\lemmaZboundedZratioZboundedZdkl*
\begin{proof}
    For every $x \in \Omega$ for which $\mu(x) \ge \nu(x)$, we can use $-\ln(1+x) \le -x + x^2$ (Lemma \ref{lemma:cheatsheet:neg-ln-1+x-le-neg-x-plus-x-sqr}), which holds for $\abs{x} \le 2/3$:
    \begin{eqnarray*}
        -\ln \frac{\nu(x)}{\mu(x)}
        = -\ln \left(1 + \frac{\nu(x) - \mu(x)}{\mu(x)}\right)
        &\le& -\frac{\nu(x) - \mu(x)}{\mu(x)} + \frac{(\nu(x) - \mu(x))^2}{(\mu(x))^2} \\
        &=& -\frac{\nu(x) - \mu(x)}{\mu(x)} + \left(\frac{\nu(x)}{\mu(x)} - 1\right)^2 \\
        \text{[Since $\nu(x) \le \mu(x) \le (1+t)\nu(x)$]} &\le& -\frac{\nu(x) - \mu(x)}{\mu(x)} + \left(\frac{1}{1+t} - 1\right)^2
        \le -\frac{\nu(x) - \mu(x)}{\mu(x)} + t^2
    \end{eqnarray*}

    For every $x \in \Omega$ for which $\mu(x) \le \nu(x)$, we can use $-\ln (1+x) \le -x + x^2/2$ (Lemma \ref{lemma:cheatsheet:neg-ln-1+x-le-neg-x-plus-x-sqr-half}):
    \begin{eqnarray*}
        -\ln \frac{\nu(x)}{\mu(x)}
        = -\ln \left(1 + \frac{\nu(x) - \mu(x)}{\mu(x)}\right)
        &\le& -\frac{\nu(x) - \mu(x)}{\mu(x)} + \frac{(\nu(x) - \mu(x))^2}{2(\mu(x))^2} \\
        &=& -\frac{\nu(x) - \mu(x)}{\mu(x)} + \frac{1}{2} \left(\frac{\nu(x)}{\mu(x)} - 1\right)^2 \\
        \text{[Since $(1-t) \nu(x) \le \mu(x) \le \nu(x)$]} &\le& -\frac{\nu(x) - \mu(x)}{\mu(x)} + \frac{1}{2} \left(\frac{1}{1-t} - 1\right)^2
        \le -\frac{\nu(x) - \mu(x)}{\mu(x)} + t^2
    \end{eqnarray*}

    Combined,
    \begin{eqnarray*}
        \ln 2 \cdot \DKL{\mu}{\nu}
        &=& -\sum_{x \in \Omega} \mu(x) \ln \frac{\nu(x)}{\mu(x)} \\
        &\le& \sum_{x \in \Omega} (-(\nu(x) - \mu(x)) + \mu(x) t^2)
        = -\sum_{x \in \Omega} (\nu(x) - \mu(x)) + t^2
        = 0 + t^2
        = t^2
    \end{eqnarray*}
\end{proof}

\lemmaZsymmetricZchiZsquareZboundedZbyZsumZdkls*
\begin{proof}
    If $\mu$ and $\nu$ are supported on different sets, then $\DKL{\mu}{\nu} + \DKL{\nu}{\mu}$ is infinite, and trivially greater than the finite left-hand expression. We proceed under the assumption that $\mu$ and $\nu$ have the same support set.

    Let $A = \{ x \in \Omega : \mu(x) > \nu(x) \}$ and $B = \{ x \in \Omega : \mu(x) < \nu(x) \}$.
    \begin{eqnarray*}
        \DKL{\mu}{\nu} + \DKL{\nu}{\mu}
        &=& \sum_{x \in \Omega} \mu(x) \log \frac{\mu(x)}{\nu(x)} + \sum_{x \in \Omega} \nu(x) \log \frac{\nu(x)}{\mu(x)} \\
        &=& -\sum_{x \in A} (\mu(x) - \nu(x)) \log \frac{\nu(x)}{\mu(x)} - \sum_{x \in B} (\nu(x) - \mu(x)) \log \frac{\mu(x)}{\nu(x)}
    \end{eqnarray*}

    For the $A$-series, we use $-\ln(1+x) \ge -x$ (Lemma \ref{lemma:cheatsheet:neg-ln-1+x-ge-neg-x}) to obtain that:
    \begin{eqnarray*}
        -\sum_{x \in A} (\mu(x) - \nu(x)) \log \frac{\nu(x)}{\mu(x)}
        &=& -\sum_{x \in A} (\mu(x) - \nu(x)) \log \left(1 + \frac{\nu(x) - \mu(x)}{\mu(x)}\right) \\
        \text{[Since $\mu(x)-\nu(x) > 0$]} &\ge& -\frac{1}{\ln 2}\sum_{x \in A} (\mu(x) - \nu(x)) \frac{\nu(x) - \mu(x)}{\mu(x)} \\
        &=& \frac{1}{\ln 2}\sum_{x \in A} \frac{(\mu(x) - \nu(x))^2}{\mu(x)}
        \ge \frac{1}{\ln 2}\sum_{x \in A} \frac{(\mu(x) - \nu(x))^2}{\mu(x) + \nu(x)}
    \end{eqnarray*}

    Analogously, for the $B$-series,
    \begin{eqnarray*}
        -\sum_{x \in B} (\nu(x) - \mu(x)) \log \frac{\mu(x)}{\nu(x)}
        &=& -\sum_{x \in B} (\nu(x) - \mu(x)) \log \left(1 + \frac{\mu(x) - \nu(x)}{\nu(x)}\right) \\
        \text{[Since $\nu(x)-\mu(x) > 0$]} &\ge& -\frac{1}{\ln 2}\sum_{x \in B} (\nu(x) - \mu(x)) \frac{\mu(x) - \nu(x)}{\nu(x)} \\
        &=& \frac{1}{\ln 2}\sum_{x \in B} \frac{(\mu(x) - \nu(x))^2}{\nu(x)}
        \ge \frac{1}{\ln 2}\sum_{x \in B} \frac{(\mu(x) - \nu(x))^2}{\mu(x) + \nu(x)}
    \end{eqnarray*}

    Combined,
    \[  \DKL{\mu}{\nu} + \DKL{\nu}{\mu}
        \ge \frac{1}{\ln 2} \sum_{x \in \Omega} \frac{(\mu(x) - \nu(x))^2}{\mu(x) + \nu(x)} \qedhere \]
\end{proof}

\lemmaZdklZofZhalfZvsZhalfZandZrZbias*
\begin{proof}
    \begin{eqnarray*}
        \DKL{\frac{1}{2}\mu + \frac{1}{2}\nu}{\frac{1+r}{2}\mu + \frac{1-r}{2}\nu}
        &=& -\sum_{x \in \Omega} \frac{1}{2}(\mu(x) + \nu(x)) \log \frac{\frac{1+r}{2}\mu(x) + \frac{1-r}{2}\nu(x)}{\frac{1}{2}\mu(x) + \frac{1}{2}\nu(x)} \\
        &=& -\sum_{x \in \Omega} \frac{1}{2}(\mu(x) + \nu(x)) \log \left(1 + r \frac{\mu(x) - \nu(x)}{\mu(x) + \nu(x)}\right)
    \end{eqnarray*}

    Since $\abs{r} < 1/2$ and $\abs{\frac{\mu(x) - \nu(x)}{\mu(x) + \nu(x)}} \le 1$, we can use the bound $-\ln (1+x) \le -x+x^2$ (Lemma \ref{lemma:cheatsheet:neg-ln-1+x-le-neg-x-plus-x-sqr}) to obtain:
    \begin{eqnarray*}
        [\cdots] &\le& \frac{1}{\ln 2}\sum_{x \in \Omega} \frac{1}{2}(\mu(x) + \nu(x)) \left(-r \frac{\mu(x) - \nu(x)}{\mu(x) + \nu(x)} + r^2 \frac{(\mu(x) - \nu(x))^2}{(\mu(x) + \nu(x))^2}\right) \\
        &=& -\frac{1}{2 \ln 2} r \underbrace{\sum_{x \in \Omega} (\mu(x) - \nu(x))} + \frac{1}{2 \ln 2}r^2 \sum_{x \in \Omega} \frac{(\mu(x) - \nu(x))^2}{\mu(x) + \nu(x)} \\
        &=& \phantom{-\frac{1}{2\ln 2}r \sum_{x \in \Omega} (\mu(x} 0 \phantom{) - \nu(x))} \!\!\!+ \frac{1}{2 \ln 2}r^2 \sum_{x \in \Omega}  \frac{(\mu(x) - \nu(x))^2}{\mu(x) + \nu(x)} \\
        \text{[Lemma \ref{lemma:symmetric-chi-square-bounded-by-sum-dkls}]} &\le& \frac{1}{2}r^2 \left(\DKL{\mu}{\nu} + \DKL{\nu}{\mu}\right)
    \end{eqnarray*}
\end{proof}

\subsection*{Proofs from Section \ref{sec:lower-bound-estimation}}

Recall the technical notations:
\defZfewZtechnicalZdefsZforZlowerZbound*

For some of our technical proofs we use Berry-Esseen theorem.

\begin{theorem}[Berry-Esseen]
    Let $X_1,\ldots,X_n$ be identically independently distributed variables with $\E[X_1] = 0$, $\Var[X_1] = \sigma^2$ and $\E[\abs{X_1}^3] = \rho$. Let $Y_n = \frac{1}{n} \sum_{i=1}^n X_i$. In this setting, for every $t \in \mathbb R$, $\abs{\Pr\left[\frac{Y_n\sqrt{n}}{\sigma} \le t\right] - \Phi(t)} \le \frac{\rho}{2\sigma^3 \sqrt{n}}$, where is the cumulative probability function of the standard normal distribution.
\end{theorem}

\begin{lemma}[Applying Berry-Esseen theorem on binomial distributions] \label{lemma:berry-esseen-modified}
    For every $\frac{1}{3} \le p \le \frac{2}{3}$ and $k \sim \Bin(n,p)$, it holds that $\Pr\left[\Bin(n,p) > np + \alpha \sqrt{n}\right] \in \Phi\left(-\alpha/\sqrt{p(1-p)}\right) \pm \frac{1}{\sqrt{n}}$ and $\Pr\left[\Bin(n,p) < np + \alpha \sqrt{n}\right] \in \Phi\left(\alpha/\sqrt{p(1-p)}\right) \pm \frac{1}{\sqrt{n}}$. In both cases, the strict inequality ($<$, $>$) can also be weak ($\le$, $\ge$).
\end{lemma}
\begin{proof}
    Let:
    \begin{itemize}
        \item $K_1,\ldots,K_n \sim \Ber(p)$ (iid).
        \item $K = \sum_{i=1}^n K_i$ (distributes like $\Bin(n,p)$).
        \item $X_i = K_i - p$.
        \item $Y_n = \frac{1}{n} X = \frac{1}{n}(K - np)$.
    \end{itemize}

    For Berry-Essen theorem, $\sigma = \sqrt{p(1-p)}$ and $\rho = p(1-p)^3 + (1-p)p^3 = \sigma^2 (p^2 + (1-p)^2)$. Hence,

    For the greater-than case,
    \begin{eqnarray*}
        \Pr\left[\Bin(np) > np + \alpha \sqrt{n} \right]
        &=& \Pr\left[K - np > \alpha \sqrt{n} \right] \\
        &=& \Pr\left[n Y_n > \alpha \sqrt{n} \right] \\
        &=& \Pr\left[\frac{Y_n\sqrt{n}}{\sigma} > \alpha/\sigma \right] \\
        &=& \Phi(\alpha/\sigma) \pm \frac{\rho}{2\sigma^3 \sqrt{n}}
    \end{eqnarray*}

    The analysis is the same for the less-than case, and analogous in the less-equals case and the greater-equals case as well. The additive error is bounded by:
    \[  \frac{\rho}{2\sigma^3 \sqrt{n}}
        = \frac{\sigma^2 (p^2 + (1-p)^2)}{2\sigma^3 \sqrt{n}}
        = \frac{p^2 + (1-p)^2}{2 \sigma \sqrt{n}}
        = \frac{p^2 + (1-p)^2}{2 \sqrt{p(1-p)}} \cdot \frac{1}{\sqrt{n}}
        \underset{1/3 \le p \le 2/3} \le \frac{1}{\sqrt{n}}
        \qedhere \]
\end{proof}

\lemmaZdivZpHZpL*
\begin{proof}
    \begin{eqnarray*}
        \frac{p_L}{p_H}
        &=& \frac{2^{-n} (1 + \delta)^{k_L} (1 - \delta)^{n - k_L}}{2^{-n} (1 + \delta)^{k_H} (1 - \delta)^{n - k_H}} \\
        &=& (1 - \delta)^{k_H - k_L} (1 + \delta)^{k_L - k_H} \\
        &=& \left(\frac{1 - \delta}{1 + \delta}\right)^{k_H - k_L} \\
        &=&  \left(1 - \frac{2\delta}{1 + \delta}\right)^{k_H - k_L} \\
        &\le& \exp\left(-2\delta(k_H - k_L)/(1+\delta)\right) \\
        &=& \exp\left(-\frac{2\sqrt{2}\eps}{\sqrt{n}} \cdot \frac{((-\sqrt{3}) - (-\sqrt{6}))\sqrt{n}}{1+\delta}\right) \\
        &=& \exp\left(-2\sqrt{2}(\sqrt{6} -\sqrt{3})\eps/(1+\delta)\right) \\
        \text{[$\delta \le \eps$]} &\le& \exp\left(-\eps \cdot 2\sqrt{2}(\sqrt{6}-\sqrt{3})/(1+\eps)\right)
        \le e^{-2.029 \eps / (1+\eps)}
    \end{eqnarray*}

    Since $\frac{1+\eps}{1-\eps} = 1 + \frac{2\eps}{1-\eps} \le e^{2\eps/(1-\eps)}$, we obtain that $\frac{(1+\eps)p_L}{(1-\eps)p_H} \le \exp\left(\left(-\frac{2.029}{1+\eps} + \frac{2}{1-\eps}\right)\eps\right) < 1$, where the last transition holds for every $\eps < 1/150$.
\end{proof}

\lemmaZmuZcloseZtoZuniform*
\begin{proof}
    When drawing $x$ bit by bit, the probability to choose $x_i=1$, given $x_1,\ldots,x_{i-1}$, is in the range $\frac{1 \pm \delta}{2}$. Therefore, $\DKL{\mu}{\mathcal U} \le n \cdot \dkl\left(\frac{1 \pm \delta}{2}, \frac{1}{2}\right) \le n \cdot \delta^2 = 2 \eps^2$, where the rightmost inequality transition is by Lemma \ref{lemma:cheatsheet:dkl-quadratic-bound}. By Pinsker's inequality, this implies that $\dtv(\mu,\mathcal U) \le \eps$.
\end{proof}

\lemmaZmuZH*
\begin{proof}
    Let $x \in \{0,1\}^n$ and $k(x)$ be the number of $\frac{1+\delta}{2}$-marginals (the number of indexes $1 \le i \le n$ for which $\mu(x_i | x_{1,\ldots,i-1}) = \frac{1+\delta}{2}$). Observe that $\mu(x)$ is fully defined by $k(x)$ and increasing monotone in $k$.

    When drawing $x$ from $\mu$, $k(x)$ is drawn from $\Bin\left(n,\frac{1+\delta}{2}\right)$, and hence:
    \begin{eqnarray*}
        \Pr_\mu[x \notin H]
        = \Pr_\mu\left[k < k_H\right]
        &=& \Pr\left[k < \E[k] - \left(\sqrt{3}+\frac{1}{2}\delta\sqrt{n}\right)\sqrt{n}\right] \\
        \text{[Lemma \ref{lemma:berry-esseen-modified}]} &\le& \Phi\left(-\frac{\sqrt{3}+\frac{1}{\sqrt{2}}\eps}{\frac{1}{2}\sqrt{1-\delta^2}}\right) + \frac{1}{\sqrt{n}} \\
        \text{[Monotonicity of $\Phi$]} &\le& \Phi(-2\sqrt{3}) + \frac{1}{\sqrt{n}} \\
        \text{[Lemma \ref{lemma:lookup:Phi(-2sqrt(3))}]} &\le& e^{-8.23} + \frac{1}{\sqrt{n}} \\
        \text{[$n \ge 2.2 \cdot 10^8$]} &\le& e^{-8}
    \end{eqnarray*}
\end{proof}

\lemmaZmuZLZpartA*
\begin{proof}
    Let $x \in \{0,1\}^n$ and $k(x)$ be the number of $\frac{1+\delta}{2}$-marginals (the number of indexes $1 \le i \le n$ for which $\mu(x_i | x_{1,\ldots,i-1}) = \frac{1+\delta}{2}$). Observe that $\mu(x)$ and $\mu'(x)$ are fully defined by $k(x)$ and that both are monotone in $k(x)$ ($\mu$ increases, $\mu'$ decreases).

    When drawing $x$ from $\mu$, $k(x)$ is drawn from $\Bin\left(n,\frac{1+\delta}{2}\right)$, and hence:
    \begin{eqnarray*}
        \Pr_\mu[x \in L]
        = \Pr_\mu\left[k \le k_L\right]
        &=&\Pr\left[k \le \E[k] - (\sqrt{6} + \frac{1}{2}\delta\sqrt{n})\sqrt{n}\right] \\
        \text{[Lemma \ref{lemma:berry-esseen-modified}]} &\ge& \Phi\left(-\frac{\sqrt{6}+\frac{1}{\sqrt{2}}\eps}{\frac{1}{2}\sqrt{1-\delta^2}}\right) - \frac{1}{\sqrt{n}} \\
        \text{[$(*)$, Monotonicity of $\Phi$]} &\ge& \Phi(-4.9) - \frac{1}{\sqrt{n}} \\
        \text{[Lemma \ref{lemma:lookup:Phi(-4.9)}]} &\ge& e^{-14.56} - \frac{1}{\sqrt{n}} \\
        \text{[$n \ge 4.5 \cdot 10^{16}$]} &\ge& e^{-14.57}
    \end{eqnarray*}
    $(*)$: for $n \ge 4.5 \cdot 10^{16}$ and $\eps < \frac{1}{2000}$, $\delta < \frac{1}{\sqrt{n}} \le \frac{1}{2000}$ and hence $-\frac{\sqrt{6} + \frac{1}{\sqrt{2}}\eps}{\frac{1}{2}\sqrt{1-\delta^2}} \ge -4.9$.
\end{proof}

\lemmaZmuZLZpartB*
\begin{proof}
    Let $x \in \{0,1\}^n$ and $k(x)$ be the number of $\frac{1+\delta}{2}$-marginals (the number of indexes $1 \le i \le n$ for which $\mu(x_i | x_{1,\ldots,i-1}) = \frac{1+\delta}{2}$). Observe that $\mu(x)$ and $\mu'(x)$ are fully defined by $k(x)$ and that both are monotone in $k(x)$ ($\mu$ increases, $\mu'$ decreases).

    For $\mu'(x)$ with $k(x) \le k_L$:
    \begin{eqnarray*}
        2^n \mu'(x) &\ge& (1 - r)^{\frac{1}{2}n - \sqrt{6}\sqrt{n}} (1 + r)^{\frac{1}{2}n + \sqrt{6} \sqrt{n}} \\
        &=& (1 - r^2)^{\frac{1}{2}n} \left(\frac{1 - r}{1 + r}\right)^{-\sqrt{6} \sqrt{n}} \\
        &=& (1 - r^2)^{\frac{1}{2}n} \left(1 - \frac{2r}{1 + r}\right)^{-\sqrt{6}\sqrt{n}} \\
        &\ge& (1 - r^2)^{\frac{1}{2}n} \exp\left(\frac{2r}{1+r} \cdot \sqrt{6}\sqrt{n}\right) \\
        &=& (1 - \paperZcoefZrZsquared/n)^{\frac{1}{2}n} \exp\left(\frac{2\cdot \paperZcoefZr/\sqrt{n}}{1+\paperZcoefZr/\sqrt{n}} \cdot \sqrt{6} \sqrt{n}\right) \\
        \text{[Lemma \ref{lemma:wolfram:(1-64/n)^(n/2)exp(16sqrt(6)/(1+8/sqrt(n)))>exp(7.19)}, $n \ge 3 \cdot 10^{10}$]} &>& e^{7.19}
    \end{eqnarray*}

    For $\mu(x)$ with $k(x) \le k_L$:
    \[  2^n \mu(x) \le (1 + \delta)^{\frac{1}{2}n - \sqrt{6} \sqrt{n}} (1 - \delta)^{\frac{1}{2}n + \sqrt{6} \sqrt{n}}
        = (1 - \delta^2)^{\frac{1}{2}n} \left(\frac{1 - \delta}{1 + \delta}\right)^{\sqrt{6} \sqrt{n}}
        < 1 \]

    Combined, $\mu'(x)/\mu(x) > e^{7.19}$ for every $x \in L_\mu$.
\end{proof}

