\vspace{3mm}
\noindent\textbf{Hessian estimation.\;}
Inspired by finite-element methods for solving high-order differential equations~\cite{XGZ19} and model-based trust-region methods for gradient-free optimization~\cite{NW06}, we estimate the Hessian $\mathbf{H}$ as the coefficient matrix $\mathbf{A}$ of a quadratic polynomial $p$ (\cref{e:quadpolymodel}) fitted to $f$ at $\bm{\theta}$. The zeroth-order term $c$ and the first-order term $\mathbf{b}$ are set to $f(\bm{\theta})$ and $\widehat{\mathbf{g}}$ (see~\cref{e:ourgradient}), respectively. Determining $\mathbf{A}$ requires at least three input points $\Theta=\{\overline{\bm{\theta}}_i\}$ with corresponding function evaluations, in addition to the two points used for computing $\widehat{\mathbf{g}}$. The process for acquiring $\Theta$ is described shortly.

Given these $f$ evaluations, the Hessian $\mathbf{A}$ is determined using standard regularized least squares approach: 
\begin{align}
\label{e:lsq}
\min_{\mathbf{h}\in \mathbb{R}^3} \sum_{i=1}^{|\Theta|}\left(q(\overline{\bm{\theta}}_i)-\phi(\overline{\bm{\theta}}_i)^\top\mathbf{h}\right)^2,
\end{align}
where $\phi(\bm{\theta})=[\frac{1}{2}\theta^1\theta^1,\theta^1\theta^2,\frac{1}{2}\theta^2\theta^2]^\top$ encodes second-order monomials with $\theta^j$ being the $j$-th element of $\bm{\theta}$, and
\begin{align}
q(\overline{\bm{\theta}}_i)=f(\overline{\bm{\theta}}_i)-\widehat{\mathbf{g}}^\top \overline{\bm{\theta}}_i-f(\bm{\theta}).
\end{align}
The minimizer $\mathbf{h}_*\in \mathbb{R}^3$ of \cref {e:lsq} is obtained as the solution of a $3\times 3$ linear system:
\begin{align}
\bm{\Phi}^\top \bm{\Phi}\mathbf{h}_*&=\bm{\Phi}^\top \mathbf{q}, \text{ where }\\
\bm{\Phi} &= \left[\phi(\overline{\bm{\theta}}_1)^\top, \ldots, \phi(\overline{\bm{\theta}}_{|\Theta|})^\top\right]^\top,\\
\mathbf{q} &= \left[q(\overline{\bm{\theta}}_1),\ldots,q(\overline{\bm{\theta}}_{|\Theta|})\right]^\top.\nonumber
\end{align}
Once the minimizer $\mathbf{h}_*\in \mathbb{R}^3$ of \cref {e:lsq} is obtained, $\mathbf{A}$ is reconstructed by appropriately arranging the elements of $\mathbf{h}_*$.

\vspace{3mm}
\noindent\textbf{Acquiring sample $f$-evaluations $\Theta$.\;}
\label{p:period} A straightforward approach to estimating the Hessian matrix $\mathbf{H}=\mathbf{A}$ is to randomly sample three input parameter combinations $\{\overline{\bm{\theta}}_i\}_{i=1}^3$ near $\bm{\theta}$ and evaluate the function $f$. However, this increases the number of function evaluations per step, potentially slowing convergence in terms of total function queries. To mitigate this, we employ a \emph{caching} mechanism that stores function evaluations for reuse in subsequent optimization steps. For this strategy to be effective, the subspaces $\mathcal{V}$ and $\{\mathcal{W}\}_{j=1}^\frac{m}{2}$ must be retained. 

To maintain this consistency, we implement a \emph{periodic subspace switching} strategy, where $\mathcal{V}$ and $\{\mathcal{W}\}_{j=1}^\frac{m}{2}$ are updated only every $T$-th optimization step. During intermediate steps $k$ (\ie $k$ mod $T \neq 0,1$), function evaluations used for gradient estimation are reused from the two preceding steps:
\begin{align}
\label{e:perturbation}
\Theta^k &= \{\bm{\theta}_1^{k-2},\bm{\theta}_2^{k-2},\bm{\theta}_1^{k-1},\bm{\theta}_2^{k-1}\}.
\end{align}
Since no function evaluations are available for reuse when $k$ mod $T = 0$, we sample three new random points and evaluate $f$ at these locations. 

\begin{algorithm}[t]
\small
\caption{Subspace-based Hessian Algorithm.}
\label{a:mainalgorithm}
\begin{algorithmic}[1]
  \State \textbf{Input:} Initial search point $\mathbf{x}^0$.
  \State \textbf{Parameters:} Step size (schedule) $\eta$, subspace switching period $T$, maximum iterations $K$.
  \State \textbf{Output:} Final solution $\mathbf{x}^K$.
  \For{$k=0$ to $K-1$}
    \If {$k \bmod T = 0$}
        \State \textbf{Select} an intermediate subspace $\mathcal{V}\subset\mathbb{R}^{m}$ from $\mathbb{R}^d$;
        \For{$j=0$ to ${\frac{m}{2}}-1$}
            \State \textbf{Sample} two indices from $\{1,\ldots,m\}$ without\\ \qquad\quad\quad replacement to define subspace $\mathcal{W}_j\subset\mathbb{R}^2$;\hspace{-0.5cm}\Comment{\CComments{\cref{s:randomsubspace}}}
        \State \textbf{Construct} projection operator $P_j$; \Comment{\CComments{\cref{e:projection}}}
        \EndFor
    \EndIf
    \State $\mathbf{v}^k \gets\mathbf{0}$;
     \For{$j =0$ to ${\frac{m}{2}}-1$}
     \State \textbf{Acquire} sample points $\Theta$ and evaluate $f$ on them;\\ 
    \Comment{\CComments{Reuse $f$ values from the previous steps\\
    \quad\quad\quad\quad\quad\quad\quad\quad\quad\: when available; \cref{s:estimgradhess}}}
    \State \textbf{Estimate} the subspace gradient $\widehat{\mathbf{g}}_j$; \Comment{\CComments{\cref{e:ourgradient}}
    }
    \State \textbf{Estimate} the subspace Hessian 
    $\widehat{\mathbf{H}}_j$; \Comment{\CComments{\cref{e:lsq}}}
    \State \textbf{Accumulate:} 
    $\mathbf{v}^k\gets \mathbf{v}^k+P^{-1}(\widehat{\mathbf{H}}_j^{-1}\widehat{\mathbf{g}}_j)$; \Comment{\CComments{\cref{e:ourupdate}}}
    \EndFor
  \State \textbf{Update:} 
  $\mathbf{x}^{k+1}\gets\mathbf{x}^k-\eta \mathbf{v}^k$;
  \EndFor
  \State \Return $\mathbf{x}^k$;
\end{algorithmic}
\end{algorithm}

\vspace{3mm}
\noindent\textbf{Optimization algorithm.\;}
\Cref{a:mainalgorithm} summarizes our main algorithm for optimizing a convex function $f$. For general non-convex functions, the Hessian matrix $\mathbf{H}$ and its estimated counterpart $\widehat{\mathbf{H}}=\mathbf{A}$ are not necessarily PD. Consequently, the resulting search direction $\mathbf{A}^{-1}\widehat{\mathbf{g}}$ may increase $f$ instead of decreasing it. To prevent this, we enforce positive definiteness by modifying the estimated Hessian $\mathbf{A}$. Specifically, we reconstruct $\mathbf{A}$ by taking the absolute values of its eigenvalues (see~\cref{e:eigendecomposition}). 

The impact of this transformation becomes clear when examining the behavior of the quadratic polynomial model function in \cref{f:quadpolymodel}. First, taking the absolute values of the eigenvalues ensures that the modified Hessian $\overline{\mathbf{A}}$ remains PD, thereby avoiding search directions that could lead to an increase in $f$. Second, the efficiency of second-order methods lies in their ability to adjust search directions based on the function's curvature. Since the elongation (curvature) of $f$ is determined by the absolute magnitudes of the Hessian eigenvalues, this transformation preserves the key benefits of second-order updates. 

When $\mathbf{A}$ contains negative eigenvalues, directly applying $\mathbf{A}^{-1}$ could generate search directions that incorrectly move along concave regions (\cref{f:quadpolymodel}(c)). By taking absolute values, we effectively reverse the movement along these eigenvectors, ensuring that the update remains well-posed for optimization (\cref{f:quadpolymodel}(e)). Following \cite{ZHJ24}, we further improve numerical stability through eigenvalue clipping, replacing each eigenvalue $\lambda_i$ with $\max(\lambda_i, \kappa)$, where the fixed positive parameter $\kappa$ is set to 0.1.

\vspace{3mm}
\noindent\textbf{Discussion.\;}
A key limitation of our approach is that each update step can only capture the joint dependence of at most two parameters. This design reflects the trade-off between incorporating second-order information and minimizing function queries in ZO optimization setting. 

In traditional optimization, the primary concerns are computational and memory complexities. Second-order methods generally incur cubic computational costs per iteration due to Hessian inversion, but they often require fewer iterations to converge to a local minimum. This balance frequently results in lower overall computational complexity. However, our preliminary experiments revealed that even for relatively low-dimensional update subspaces (\eg, $m=4$), using a full second-order approach consistently resulted in a substantially higher number of function queries.

In contrast, our two-dimensional subspace approach requires only three additional function evaluations per update step, with the periodic subspace switching strategy further enabling the complete omission of function evaluations at specific steps. This yields substantially faster overall convergence in terms of function queries while still incorporating curvature information.

An alternative approach is to approximate only the diagonal components of the Hessian~\cite{ZDY25}, offering linear scaling with respect to the function dimensionality. This method allows for the joint consideration of all parameters in each update step. However, its primary limitation is that it accurately captures curvature only when the eigenvectors of the Hessian $\mathbf{H}$ are aligned with the coordinate axes, as shown in \cref{f:quadpolymodel}(a–c). Specifically, diagonal approximations struggle with anisotropic curvature in scenarios like \cref{f:quadpolymodel}(d), where the eigenvectors are rotated by 45 degrees relative to the coordinate axes.

Our experiments demonstrate that the subspace-based approach of ZO-SAH provides substantial overall improvements over diagonal Hessian approximations.

\subsection{Convergence analysis}
\label{s:convergence}
We present the main convergence results of our method below. A complete proof is provided in \cref{s:convergence_supp}.

\begin{assumptions}[Function properties]
\label{a:assumptions1}
The objective function $f: \mathbb{R}^d \to \mathbb{R}$ is $\mu$-strongly convex, bounded below, with Lipschitz-continuous gradient (constant $C_{1}$) and Hessian (constant $C_{2}$). 
\end{assumptions}

\begin{assumptions}[Optimization steps]
\label{a:assumptions2}
Following the setup of \cite{WQY24}, we assume that the \emph{Armijo backtracking line search}~\cite{NW06} with a minimum step size is applied. Specifically, for a search direction $\mathbf{v}^{k}$, there exist bounded constants $c_{1}$, $\rho^{\min}$, and $\rho^{k}$ satisfying $\rho^{\min}\leq \rho^{k}$, such that:
\begin{align}
\label{e:armijo}
f(\mathbf{x}^{k+1}) \leq f(\mathbf{x}^{k})-c_{1} \rho^{k} \|\mathbf{v}^{k}\|^{2}.
\end{align}
We further bound the Hessian perturbation in the subspace $\mathcal{W}$ by $l$ (\ie the distance between $\bm{\theta}^k$ and elements of $\Theta^k$ is at most $l$; see~\cref{e:perturbation}). The gradient perturbation $\epsilon^k$ (\cref{e:ourgradient}) is similarly bounded by $\frac{\sqrt{2}}{dC_1} \|\nabla f(\mathbf{x}^{k})\|$. Finally, the smallest eigenvalue of $\bm{\Phi}^\top \bm{\Phi}$ is bounded below by $\gamma$.
\end{assumptions}
These assumptions, except for the last one which is specific to ZO-SAH, are commonly adopted in ZO optimization studies, and further discussions can be found in~\cite{KMR23,WQY24}.  See \Cref{s:boundhessianestim} for a discussion on $\gamma$.

\begin{proposition}\label{p:mainresult}
Under these conditions, starting from the initial search point $\mathbf{x}^0$ (\cref{e:ourupdate}), 
the sequence $(\mathbf{x}^k)$ generated by our algorithm satisfies that for all $k \geq 1$:
\begin{align}
\label{e:convergence}
\mathbb{E}_{\mathbf{P} \sim \mathcal{D}}&[f(\mathbf{x}^k) - f(\mathbf{x}^*)]
\le \frac{C_1}{2}(1-\nu)^{k}\|\Delta_{0}\|^{2},\\
\nu &= c_1 \rho^{\min} \,\frac{\mu m}{d^{2}\bigl(C_1 + E + \kappa\bigr)^{2}},
\end{align}
where $\mathbf{x}^*$ is the minimizer of $f$, $\mu$ is the strong convexity parameter of $f$, $m$ is the subspace dimension $\mathcal{V}$, 
$\Delta_0$ is the initial optimization gap ($\Delta_0=\|\mathbf{x}^{0}-\mathbf{x}^{*}\|$), and $\mathcal{D}$ is the 
distribution of projection matrices for random coordinate selection (\cref{e:projection};~\cite{GKL19}). 
The term $E$ is defined as:
\begin{align}
E:=
      \sqrt{6}\frac{s}{\gamma}\,
      \left(
         \frac{C_{1}}{d}\Delta_{0}l^{3} 
         \;+\;
         \frac{C_{2}}{6}l^{5}
      \right).
\end{align}
where $s$ is the number of perturbations, fixed at 4 ($s=|\Theta^k|$; see~\cref{e:perturbation}).
\end{proposition}

\begin{sketchofproof}
We first establish an upper bound on the difference between the estimated gradient $\widehat{\mathbf{g}}$ (\cref{e:ourgradient}) in the subspace $\mathcal{W}$ and the exact gradient $\nabla f$ projected onto $\mathcal{W}$:
\begin{align}
\label{e:gradientbound}
  \|\widehat{\mathbf{g}} - \mathbf{P}\nabla f\| \leq \frac{C_{1}\epsilon^{k}}{\sqrt{2}}.
\end{align}
Next, using \cref{e:gradientbound} and the Lipschitz continuity of the gradient and Hessian of $f$, we derive a bound on the spectral norm of the difference between the estimated subspace Hessian $\widehat{\mathbf{H}}$ and the exact Hessian $\nabla^{2} f(\mathbf{x})$ projected onto $\mathcal{W}$: 
\begin{align}
\label{e:Hessianbound}
\|\widehat{\mathbf{H}}-\mathbf{P}\nabla^{2} f(\mathbf{x})\,\mathbf{P}\| \le E.
\end{align}
Applying \cref{e:gradientbound} and \cref{e:Hessianbound} to $\mathbf{x}^k$  and combining these bounds, we obtain the following  lower bound for the update:
\begin{align}
\label{e:updatebound}
\frac{m}{2d^2(C_1+E+\kappa)^{2}} \|\nabla f(\mathbf{x}^{k})\|^{2}
\leq
\|\mathbf{v}^{k}\|^{2}.
\end{align}
Our Hessian estimate $\widehat{\mathbf{H}}$ is PD, ensuring that $-\mathbf{v}^k$ is a descent direction. Finally, substituting \cref{e:updatebound} into \cref{e:armijo}, applying the Polyak--{\L}ojasiewicz inequality~\cite{KNS16}, and telescopically summing from $0$ to $k$ yields \cref{e:convergence}.
\vspace{-2mm}
\end{sketchofproof}

