\section{Convergence analysis}
\label{s:convergence_supp}
This section presents a complete proof of Proposition~\ref{p:mainresult}. We begin by introducing assumptions commonly used in zeroth-order optimization~\cite{KMR23, WQY24}.

\begin{assumptions}[Function properties]
\label{a:assumptions1_supp}

The objective function $f: \mathbb{R}^d \to \mathbb{R}$ is $\mu$-strongly convex, bounded below, with Lipschitz-continuous gradient (constant $C_{1}$) and Hessian (constant $C_{2}$). 
\end{assumptions}

\begin{assumptions}[Optimization steps]
\label{a:assumptions2_supp}
Following the setup of \cite{WQY24}, we assume that the \emph{Armijo backtracking line search}~\cite{NW06} with a minimum step size is applied. Specifically, for a search direction $\mathbf{v}^{k}$, there exist bounded constants $c_{1}$, $\rho^{\min}$, and $\rho^{k}$ satisfying $\rho^{\min}\leq \rho^{k}$, such that:
\begin{align}
\label{e:armijo_supp}
f(\mathbf{x}^{k+1}) \leq f(\mathbf{x}^{k})-c_{1} \rho^{k} \|\mathbf{v}^{k}\|^{2}.
\end{align}
We further bound the Hessian perturbation in the subspace $\mathcal{W}$ by $l$ (\ie the distance between $\bm{\theta}^k$ and elements of $\Theta^k$ is at most $l$). The gradient perturbation $\epsilon^k$ is similarly bounded by $\frac{\sqrt{2}}{dC_1} \|\nabla f(\mathbf{x}^{k})\|$. Finally, the smallest eigenvalue of $\bm{\Phi}^\top \bm{\Phi}$ is bounded below by $\gamma$.
\end{assumptions}
\noindent Under Assumptions~\ref{a:assumptions1_supp} and \ref{a:assumptions2_supp}, we first bound the deviation between the true analytical gradient and Hessian and their respective estimates computed by our algorithm.

\begin{proposition}\label{p:mainresult_supp}
Under these conditions, starting from the initial search point $\mathbf{x}^0$, 
the sequence $(\mathbf{x}^k)$ generated by our algorithm satisfies that for all $k \geq 1$:
\begin{align}
\label{e:convergence_supp}
\mathbb{E}_{\mathbf{P} \sim \mathcal{D}}&[f(\mathbf{x}^k) - f(\mathbf{x}^*)]
\le \frac{C_1}{2}(1-\nu)^{k}\|\Delta_{0}\|^{2},\\
\nu &= c_1 \rho^{\min} \,\frac{2\mu m}{d^{2}\bigl(C_1 + E + \kappa\bigr)^{2}},
\end{align}
where $\mathbf{x}^*$ is the minimizer of $f$, $\mu$ is the strong convexity parameter of $f$, $m$ is the subspace dimension $\mathcal{V}$, 
$\Delta_0$ is the initial optimization gap ($\Delta_0=\|\mathbf{x}^{0}-\mathbf{x}^{*}\|$), and $\mathcal{D}$ is the 
distribution of projection matrices for random coordinate selection;~\cite{GKL19}). 
The term $E$ is defined as:
\begin{align}
E &=\sqrt{6}\,\frac{s}{\gamma}\left(
     \frac{C_{1}}{d}\,\Delta_0\,l^{3} 
     + \frac{C_{2}\,l^{5}}{6}\right),
\end{align}
where 
$s$ is the number of perturbations, fixed at 4 ($s=|\Theta^k|$).
\end{proposition}

\subsection{Bounds on the gradient and Hessian estimates}
\label{s:boundhessianestim}
\begin{corollary}
Let $\widehat{\mathbf{g}}$ be the gradient estimate in a given 2-dimensional subspace $\mathcal{W}$ of $\mathbb{R}^d$, and let $\mathbf{P} \nabla f(\mathbf{x}^{k})$ denote the analytical gradient projected onto $\mathcal{W}$ via the projection matrix $\mathbf{P}\in \mathbb{R}^{2\times d}$. Then, the difference between them is bounded by  
\begin{align}
\|\widehat{\mathbf{g}} - \mathbf{P} \nabla f(\mathbf{x}^{k})\| \leq \frac{C_1}{\sqrt{2}}\epsilon^{k}.
\end{align}
\label{e:corollary1}
\end{corollary}
\begin{proof}
Let $\mathbf{p}_i$ be the $i$-th row of the matrix $\mathbf{P}$, converted into a column vector. Applying the first-order Taylor expansion with the error term in Lagrange form along the direction $\mathbf{p}_i$ at $f(\mathbf{x}^{k})$, we obtain
\begin{align}
  f(\mathbf{x}^{k} + \epsilon^{k}\,\mathbf{p}_i) 
  = f(\mathbf{x}^{k}) + \epsilon^{k}\,\nabla f(\mathbf{x}^{k})^\top \mathbf{p}_i + \frac{({\epsilon^{k}})^2}{2}\,\mathbf{p}_{i}^\top  
  H f(\mathbf{x}^{k} + \epsilon^{k}\alpha\,\mathbf{p}_{i}) \mathbf{p}_i,
\end{align}
for $\alpha \in [0,1]$. Rearranging the zeroth- and first-order terms and taking absolute values, we get
\begin{align}
\left|\frac{f(\mathbf{x}^{k}+\epsilon^{k}\,\mathbf{p}_i) - f(\mathbf{x}^k)}{\epsilon^{k}} - \nabla f(\mathbf{x}^k)^{\top} \mathbf{p}_i \right| &= \left|\frac{\epsilon^{k}}{2}\,\mathbf{p}_i^{\top} 
H f\Bigl(\mathbf{x}^{k}+\epsilon^{k}\alpha\,\mathbf{p}_i\Bigr) \mathbf{p}_i\right| \leq \frac{\epsilon^{k}}{2}C_{1}.
\end{align}
\noindent Since the matrix $\mathbf{P}$ consists of two rows, it follows from~\cite{ESX22} that 
\begin{align}
\label{e:gradientbound_supp}
    \left\|\widehat{\mathbf{g}} - \mathbf{P}\nabla f(\mathbf{x}^k)\right\| \leq \frac{\epsilon^{k}}{\sqrt{2}}C_1.
\end{align}
\end{proof}
\begin{corollary}
Let $\widehat{\mathbf{H}}$ be the Hessian estimated in $\mathcal{W}$ using the least squares method (see~\cref{s:estimgradhess}). Then, the spectral norm of the difference between the analytical subspace Hessian, $\mathbf{H}=\mathbf{P}\nabla^{2} f(\mathbf{x}^{k})\mathbf{P}^{\top}$, and $\widehat{\mathbf{H}}$ is bounded by  
\begin{align}
\|\widehat{\mathbf{H}} - \mathbf{H}\|_{2} \leq \sqrt{6}\frac{s}{\gamma}\left(\frac{C_1}{\sqrt{2}}\epsilon^{k}l^{3} + \frac{C_2}{6}l^5\right).
\label{corollary2}
\end{align}
\end{corollary}
\begin{proof}
Let $\bm{\theta}^k$ be the projection of $\mathbf{x}^k$ onto $\mathcal{W}$. For simplicity of exposition, we reparameterize the coordinate variables $\bm{\theta}$ such that $\bm{\theta}^k$ is mapped to zero. 
Each perturbed parameter \(\overline{\bm{\theta}}_i \in \mathbb{R}^{2}\), satisfying \(\|\overline{\bm{\theta}}_i\| \leq l\), serves as a data point for least squares estimation. Define $\phi$ as the vector of second-order monomials:
\begin{align}
\phi(\bm{\theta})=[\tfrac{1}{2}\theta^1\theta^1,\theta^1\theta^2,\tfrac{1}{2}\theta^2\theta^2]^\top.
\end{align}
Then, the design matrix $\bm{\Phi}\in\mathbb{R}^{s\times 3}$, where $s$ is the number of such data points, is constructed as 
\begin{align}
\bm{\Phi} = \left[\phi(\overline{\bm{\theta}}_1)^\top, \ldots, \phi(\overline{\bm{\theta}}_{s})^\top\right]^\top.
\end{align}
Now, representing the symmetric Hessian matrix estimate $\widehat{\mathbf{H}}$ as a vector $\widehat{\mathbf{h}}=[\widehat{H}_{11},\widehat{H}_{12},\widehat{H}_{22}]^{\top}$, where $\widehat{H}_{ml}$ is the $(m,l)$-th element of $\widehat{\mathbf{H}}$, we can express the least square estimate $\widehat{\mathbf{h}}$ as:
\begin{align}
\label{e:lsq_supp}
\widehat{\mathbf{h}}&=\mathop{\rm arg\,min}\limits_{\mathbf{h}\in \mathbb{R}^3} \sum_{i=1}^{s}\left(q(\overline{\bm{\theta}}_i)-\phi(\overline{\bm{\theta}}_i)^\top\mathbf{h}\right)^2,\\
q(\overline{\bm{\theta}}_i)&=f(\overline{\bm{\theta}}_i)-\widehat{\mathbf{g}}^\top \overline{\bm{\theta}}_i-f(\bm{\theta}).
\end{align}
Here, we use $f(\bm{\theta})$ to denote $f(\mathbf{x}^k)$. The solution $\widehat{\mathbf{h}}$ has a closed-form expression:
\begin{align}
\widehat{\mathbf{h}}=(\bm{\Phi}^\top \bm{\Phi})^{-1}\bm{\Phi}^\top \mathbf{q}, 
\end{align}
where $\mathbf{q} =\left[q(\overline{\bm{\theta}}_1),\ldots,q(\overline{\bm{\theta}}_{s})\right]^\top$. Similarly to the estimated Hessian $\widehat{\mathbf{h}}$, let $\mathbf{h}$ represent the entries of $\mathbf{H}$. Then, their difference $\Delta \mathbf{h}$ can be expressed as
\begin{align}
\Delta\mathbf{h}
\;=\;
\widehat{\mathbf{h}} -\mathbf{h}
&
=\bigl(\bm{\Phi}^\top \bm{\Phi})^{-1}\bm{\Phi}^\top\Delta \mathbf{q},
\label{e:deltah}
\end{align}
where $\Delta\mathbf{q} = \mathbf{q} - \bm{\Phi}\mathbf{h}$.

The vector $\Delta \mathbf{q}$ captures the discrepancy between the true
function value $f(\overline{\boldsymbol{\theta}})$ and its second-order expansion, where the linear term is replaced by an estimated subspace gradient $\widehat{\mathbf{g}}$. Specifically, the $i$-th element $\Delta q_i$ of $\Delta\mathbf{q} \in \mathbb{R}^{s}$ is given by  
\begin{align}
\Delta q_i
&= f(\overline{\bm{\theta}}_{i})-f(\bm{\theta})-\widehat{\mathbf{g}}^{\top}\overline{\bm{\theta}}-\tfrac{1}{2}\,\overline{\bm{\theta}}_i^\top\,\mathbf{H}\,\overline{\bm{\theta}}_i\\
&= \left( f(\bm{\theta}) 
          + \nabla f(\mathbf{x}^k)^\top \mathbf{P}^{\top} \overline{\bm{\theta}}_{i}
          + \frac{1}{2}\,\overline{\bm{\theta}}_{i}^\top \mathbf{P} 
            \,H f(\bm{\theta}) \,\mathbf{g}^\top\,\overline{\bm{\theta}}_{i}
          + \mathcal{R}_i \right)
   \;-\;
   \left( f(\bm{\theta}) 
          + \widehat{\mathbf{g}}^{\top}\,\overline{\bm{\theta}}_i
          + \tfrac{1}{2}\,\overline{\bm{\theta}}_i^\top\,\mathbf{H}\,\overline{\bm{\theta}}_i \right)\\
&= \left(\mathbf{g}\,\nabla f(\mathbf{x}^k) - \widehat{\mathbf{g}}\right)^{\top}\,\overline{\bm{\theta}}_i + \mathcal{R}_i,
\label{e:deltaqbound}
\end{align}
where $\mathcal{R}_i$ denotes the Taylor series remainder term, accounting for the mismatch between the exact function value and its second-order approximation. By the Lipschitz continuity of the Hessian (Assumption~\ref{a:assumptions1_supp}), $\mathcal{R}_i$ is bounded 
as~\cite{NW06}:
\begin{align}
\label{e:rbound}
\mathcal{R}_i \leq \frac{C_{2}}{6}\|\mathbf{P}^{\top}\overline{\bm{\theta}}^{i}\|^{3} =  \frac{C_2}{6}\|\overline{\bm{\theta}}^{i}\|^{3} = \frac{C_2}{6}l^{3}.
\end{align}

To bound $\Delta \mathbf{h}$, we decompose it into a product of two norms:
\begin{align}
\|\Delta\mathbf{h}\| = \|(\bm{\Phi}^{\top}\bm{\Phi})^{-1}\bm{\Phi}^{\top}\Delta\mathbf{q}\| \leq \|(\bm{\Phi}^{\top}\bm{\Phi})^{-1}\|_{2}\|\bm{\Phi}^{\top}\Delta\mathbf{q}\|.
\end{align}
The square of the norm $\|\bm{\Phi}^{\top}\Delta\mathbf{q}\|$ can be explicitly written as:
\begin{align}
\bm{\Phi}^{\top} \Delta\mathbf{q} &=
\left[\sum_{i=1}^{s}\frac{1}{2} \theta_{i}^{1}\theta_{i}^{1} \Delta q_i, 
\sum_{i=1}^{s} \theta_{i}^{1}\theta_{i}^{2} \Delta q_i, 
\sum_{i=1}^{s} \frac{1}{2}\theta_{i}^{2}\theta_{i}^{2} \Delta q_i
\right]^\top,\\
\left\|\bm{\Phi}^{\top} \Delta\mathbf{q}\right\|^2 &=
\left(\sum_{i=1}^{s}\frac{1}{2} \theta_{i}^{1}\theta_{i}^{1} \Delta q_i\right)^2+\left(\sum_{i=1}^{s} \theta_{i}^{1}\theta_{i}^{2} \Delta q_i\right)^2 
+\left(\sum_{i=1}^{s} \frac{1}{2}\theta_{i}^{2}\theta_{i}^{2} \Delta q_i\right)^2.
\end{align}

To bound this term, we first bound \( \Delta q_i \) and the monomial coefficients. Using \cref{e:gradientbound}, the first summand in $\Delta q_i$ (\cref{e:deltaqbound}) is bounded as 
\begin{align}
\label{e:deltaqfirst}
 \left({\mathbf{P}}\nabla f(\mathbf{x}^{k}) -\widehat{\mathbf{g}}\right)^{\top}\overline{\boldsymbol{\theta}}_{i} &\leq \|{\mathbf{P}}\nabla f(\mathbf{x}^{k}) -\widehat{\mathbf{g}}\|\|\overline{\boldsymbol{\theta}}_{i}\| \leq \frac{C_1}{\sqrt{2}}\epsilon^{k} l.
\end{align}
Combining \cref{e:deltaqfirst} and \cref{e:rbound}, we obtain a bound on $\Delta q_{i}$:
\begin{align}
\|\Delta q_{i}\| %&= \left\| (\mbP\nabla f(\mbx^{k})-\widehat{\mbg})^{\top} \overline{\boldsymbol{\theta}}_{i} + \calR_{i} \right\| \\
&\leq \left\| \mathbf{P}^{\top} \nabla f(\mathbf{x}^{k}) - \widehat{\mathbf{g}} \right\|\left\| \overline{\boldsymbol{\theta}}_{i} \right\| + \left\| \mathcal{R}_{i} \right\| \\
&\leq \frac{C_1}{\sqrt{2}} \epsilon^{k} l + \frac{C_2}{6} l^3.
\label{e:boundqi}
\end{align}
Since the magnitude of perturbation $\overline{\bm{\theta}}_i$ is at most $l$, it follows that
\begin{align}
(\theta_{i}^{1})^2,\; (\theta_{i}^{2})^2,\; |\theta_{i}^{1}\theta_{i}^{2}|\leq l^2.
\end{align}
Using this and the bound on $\Delta q_i$ from \cref{e:boundqi}, we obtain:
\begin{align}
\left\|\bm{\Phi}^{\top} \Delta\mathbf{q}\right\|^2 
&= \left(\left(\sum_{i=1}^{s}\frac{1}{2} \theta_{i}^{1}\theta_{i}^{1}\right)^2 +\left(\sum_{i=1}^{s}\theta_{i}^{1}\theta_{i}^{2}\right)^2 +\left(\sum_{i=1}^{s}\frac{1}{2} \theta_{i}^{2}\theta_{i}^{2}\right)^2\right) \left(\sum_{i=1}^{s}\Delta q_i\right)^2\\
&\leq 3 s^2l^4 \left(\frac{C_1}{\sqrt{2}} \epsilon^{k} l + \frac{C_2}{6} l^3\right)^2\\
\Leftrightarrow \left\|\bm{\Phi}^{\top} \Delta\mathbf{q}\right\|&\leq \sqrt{3} sl^2 \left(\frac{C_1}{\sqrt{2}} \epsilon^{k} l + \frac{C_2}{6} l^3\right).
\label{e:phideltaqbound}
\end{align}

Using Assumption~\ref{a:assumptions2_supp}, $\|(\bm{\Phi}^{\top}\bm{\Phi})^{-1}\|_{2}=\frac{1}{\gamma}$. Combining this with \cref{e:phideltaqbound}, we obtain:
\begin{align}
\|\Delta\mathbf{h}\|
&\leq \|(\bm{\Phi}^{\top}\bm{\Phi})^{-1}\|_{2}\|\bm{\Phi}^{\top}\Delta\mathbf{q}\| \\
&\leq \sqrt{3}\left( \frac{s}{\gamma}\, \left( \frac{C_1}{\sqrt{2}}\epsilon^{k}\,l^3 
+ \frac{C_2}{6}\,l^5 \right) \right).
\end{align}
Since the spectral norm of a matrix is always smaller than its Frobenius norm, we can now finally bound the error between the estimated subspace Hessian and its analytical counterpart as:
\begin{align}
\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2} &\leq \sqrt{2}\|\Delta \mathbf{h}\| \\
&\leq \sqrt{6} \frac{s}{\gamma}\, \left( \frac{C_1}{\sqrt{2}}\epsilon^{k}\,l^3 
+ \frac{C_2}{6}\,l^5 \right).
\label{e:hbound}
\end{align}
\end{proof}

We assumed a lower bound $\gamma$ on the smallest eigenvalue of $\bm{\Phi}^\top \bm{\Phi}$. This assumption is not restrictive in our setting, as the radius $l$ of the sampled points $\{\overline{\bm{\theta}}_i\}_{i=1}^s$ does not need to decrease as $k$ grows. Our algorithm and the convergence proof do not require $\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2}\to 0$ as $k$, which would otherwise necessitate $l\to 0$ for more precise estimation. In applications where such precision is needed, the number of sampled points $s$ should increase toward infinity to ensure a lower-bounded eigenvalue~\cite{AT07}. While analyzing this setting would be theoretically appealing, it is not necessary for our application.

\subsection{Proof of Proposition~\ref{p:mainresult_supp}}
Here, we prove the convergence of our algorithm, which uses the \emph{Armijo backtracking line search}~\cite{NW06} with a minimum step size. We begin by explicitly representing the update vector $\mathbf{v}^k$:
\begin{align}
\mathbf{v}^k=\sum_{j=1}^{\frac{m}{2}}P^{-1}\left((\widehat{\mathbf{H}}_j^k)^{-1}\widehat{\mathbf{g}}_j^k\right),
\end{align} where $m$ is the dimension of the intermediate subspace $\mathcal{V}$.

To ensure that $\widehat{\mathbf{H}}$ remains positive definite, eigenvalue clipping is applied, replacing each eigenvalue $\lambda_i$ with $\min(\lambda_i, \kappa)$, where the positive parameter $\kappa$. As a preliminary step, we derive an upper bound for the subspace Hessian. 
\begin{align}
\label{e:hessian_bound}
\|\widehat{\mathbf{H}}\|_{2}=\|\widehat{\mathbf{H}}-\mathbf{P} H f(\mathbf{x}^k) \mathbf{P}^{\top}+\mathbf{P} H f(\mathbf{x}^k)\mathbf{P}^{\top}\|_{2} &\leq \|\widehat{\mathbf{H}}-\mathbf{P} H f(\mathbf{x}^k)\mathbf{P}^{\top}\|_{2}+\|\mathbf{P} H f(\mathbf{x}^k) \mathbf{P}^{\top}\|_{2} \\\
&\leq
\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2} +\|\mathbf{P}\|_{2} \|H f(\mathbf{x}^k)\|_{2} \|\mathbf{P}\|_{2}.
\label{e:hessian_bound2}
\end{align}
By the Lipschitz continuity of the gradient $\nabla f$ (Assumption~\ref{a:assumptions1_supp}), the Hessian $H f(\mathbf{x}^k)$ is bounded: $\|H f(\mathbf{x}^k)\|_2 \leq C_1$~\cite{Fe23}.

Using this and noting that $\|\widehat{\mathbf{H}}\widehat{\mathbf{H}}^{-1}\|_{2} \leq \|\widehat{\mathbf{H}}\|_{2}\|\widehat{\mathbf{H}}^{-1}\|_{2}$, we derive a lower bound of $\|\widehat{\mathbf{H}}^{-1}\|_{2}$ from \cref{e:hessian_bound2}:
\begin{align}
  \|\widehat{\mathbf{H}}^{-1}\|_{2} \geq \frac{1}{\|\widehat{\mathbf{H}}\|_{2}} \geq \frac{1}{\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2} + C_1+\kappa}.
\label{e:lowerbound}
\end{align}

Next, we establish a bound on the estimated subspace gradients in scenarios where $\mathcal{W}$ determined through random coordinate selection. Following the approach in~\cite{RPA25}, we take the expectation with respect to the projection matrices $\mathbf{P}$, which map onto the respective subspaces. This yields
\begin{align}
    \mathbb{E}_{\mathbf{P} \sim \mathcal{D}} [\|\mathbf{P}^{\top}\widehat{\mathbf{g}} -\nabla f(\mathbf{x}^{k})\|]  
    &= \mathbb{E}_{\mathbf{P} \sim \mathcal{D}}[\|\mathbf{P}^{\top}\widehat{\mathbf{g}}-\mathbf{P}^{\top}\mathbf{P}\nabla f(\mathbf{x}^{k})  
    + \mathbf{P}^{\top}\mathbf{P}\nabla f(\mathbf{x}^{k})-\nabla f(\mathbf{x}^{k})\|] \\
    &\leq \mathbb{E}_{\mathbf{P} \sim \mathcal{D}}[\|\mathbf{P}^{\top}\|_{2}\|\widehat{\mathbf{g}}-\mathbf{P}\nabla f(\mathbf{x}^{k})\|
    + \|\mathbf{P}^{\top}\mathbf{P}\nabla f(\mathbf{x}^{k})-\nabla f(\mathbf{x}^{k})\|] \\
    &\leq \frac{C_1\epsilon^{k}}{\sqrt{2}} + \left(1-\frac{2}{d}\right)\|\nabla
    f(\mathbf{x}^{k})\|.
\label{e:grad}
\end{align}
Given that $\epsilon^k < \frac{\sqrt{2}}{dC_1}\|\nabla f(\mathbf{x}^{k})\|$ (Assumption~\ref{a:assumptions2_supp}), there exists a constant $\tau^k$ satisfying $0< \tau^k <1$, such that~\cite{WQY24}:
\begin{align}
\label{e:tau}
    \frac{C_1\epsilon^{k}}{\sqrt{2}} + \left(1-\frac{2}{d}\right)\|\nabla f(\mathbf{x}^{k})\| &= \tau^{k} \|\nabla f(\mathbf{x}^{k})\| < \left(1-\frac{1}{d}\right)\|\nabla f(\mathbf{x}^{k})\| .
\end{align}
Combining~\cref{e:grad} and~\cref{e:tau}, we obtain
\begin{align}
\label{e:grad_inequal}
 \mathbb{E}_{\mathbf{P} \sim \mathcal{D}} [\|\mathbf{P}^{\top}\widehat{\mathbf{g}} -\nabla f(\mathbf{x}^{k})\|]  \leq \tau^{k} \|\nabla f(\mathbf{x}^{k})\|.
\end{align}
Applying the triangular inequality,
\begin{align}
\label{e:gradient_bound}
        \mathbb{E}_{\mathbf{p} \sim \mathcal{D}}[(1-\tau^k)\|\nabla f(\mathbf{x}^{k})\|] \leq \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[\|\mathbf{g}^{\top}\widehat{\mathbf{g}}\|] \leq \mathbb{E}_{\mathbf{p} \sim \mathcal{D}}[(1+\tau^k)\|\nabla f(\mathbf{x}^{k})\|].
\end{align}

Using Assumption~\ref{a:assumptions2_supp} and combining~\cref{e:hessian_bound} with~\cref{e:gradient_bound}, we obtain the iterative bound:
\begin{equation}
\label{e:iterative_gradient_inequal}
 \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k+1})] \leq \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})]-c_1\rho^{\min}\frac{m(1-\tau^k)^{2}}{2(C_{1}+\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2}+\kappa)^{2}}\|\nabla f(\mathbf{x}^{k})\|^{2}.
\end{equation}
Further, the Lipschitz continuity of the gradient provides an upper bound on $\epsilon^k$:
\begin{align}
 \epsilon^{k} < \frac{\sqrt{2}}{dC_1}\|\nabla f(\mathbf{x}^{k})\| < \frac{\sqrt{2}}{d}\Delta_{0},
\end{align}
where $\Delta_0 = \|\mathbf{x}^{0}-\mathbf{x}^{*}\|$. Substituting this bound into the upper bound of $\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2}$ in \cref{e:hbound}, we obtain

\begin{align}
\|\widehat{\mathbf{H}}-\mathbf{H}\|_{2}\leq E:=
      \sqrt{6}\frac{s}{\gamma}\,
      \left(
         \frac{C_{1}}{d}\Delta_{0}l^{3} 
         \;+\;
         \frac{C_{2}}{6}l^{5}
      \right).
\end{align}
From~\cref{e:tau}, we establish that $\tau^k<1-\frac{1}{d}$, which further implies 
\begin{align}
\frac{1}{d^2} <(1-\tau^k)^{2}.
\end{align}

By substituting the results from~\cref{e:tau} and~\cref{e:grad_inequal} into~\cref{e:iterative_gradient_inequal}, we obtain the following bound:
\begin{equation}
\label{e:iterative_expect_bound}
 \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k+1})] \leq \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})]-c_1\rho^{\min}\frac{m}{2d^{2}(C_{1}+E+\kappa)^{2}}\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[\|\nabla f(\mathbf{x}^{k})\|^{2}].
\end{equation}

\noindent Using the $\mu$-strong convexity of $f$ (Assumption~\ref{a:assumptions1_supp}) and the Polyak--{\L}ojasiewicz inequality~\cite{KNS16}, we obtain:
\begin{align}
\|\nabla f(\mathbf{x}^{k})\|^{2} \geq 2\mu(f(\mathbf{x}^{k})-f(\mathbf{x}^{*})).
\label{e:polyak}
\end{align}
Substituting~\cref{e:polyak} into~\cref{e:iterative_expect_bound}, we get
\begin{align}
\label{e:max_bound_of_expect}
 \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k+1})] \leq \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})]-c_1\rho^{\min}\frac{m\mu}{d^{2}(C_{1}+E+\kappa)^{2}}\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})-f(\mathbf{x}^{*})].
\end{align}
Subtracting $f(\mathbf{x}^{*})$ from both sides of~\cref{e:max_bound_of_expect}, we obtain
\begin{align}
\label{e:subtract_expect_bount}
 \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k+1})] - \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{*})] &\leq \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})]- \mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{*})]-c_1\rho^{\min}\frac{m\mu}{d^{2}(C_{1}+E+\kappa)^{2}}\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})-f(\mathbf{x}^{*})]\\
 &=(1-\nu)\{\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})]-\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{*})]\},
\end{align}
where
\begin{align}
 \nu &= c_1\rho^{\min}\cfrac{m\mu}{d^{2}(C_1+E+\kappa)^{2}}.
\end{align}

Performing the telescoping multiplication from $0$ to $k-1$, as in~\cite{GKL19}, we obtain
\begin{align}
\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k+1})  - f(\mathbf{x}^{*})]  \leq (1-\nu)^{k}(f(\mathbf{x}^{0})-f(\mathbf{x}^{*})).
\label{e:telemul}
\end{align}
The Lipschitz continuity of the gradient further provides the bound:
\begin{align}
f(\mathbf{x}^{0}) \leq f(\mathbf{x}^{*}) + \nabla f(\mathbf{x}^{*})^{\top}(\mathbf{x}-\mathbf{x}^{*})+\frac{C_1}{2}\|\mathbf{x}-\mathbf{x}^{*}\|^{2}.
\end{align}
\noindent Since $\nabla f(\mathbf{x}^{*}) = 0$, we have
\begin{align}
 f(\mathbf{x}^{0}) -f(\mathbf{x}^{*}) \leq \frac{C_1}{2}{\Delta_{0}}^{2}.
 \label{e:zerosum}
\end{align}

\noindent Finally, substituting~\cref{e:zerosum} to~\cref{e:telemul}, we obtain
\begin{align}
\mathbb{E}_{\mathbf{g} \sim \mathcal{D}}[f(\mathbf{x}^{k})-f(\mathbf{x}^{*})] \leq (1-\nu)^{k}\frac{C_1}{2}{\Delta_{0}}^{2}.
\end{align}

\section{Additional information}
\label{s:expdetails}

\subsection{Preliminaries for zeroth-order optimization} 
\label{s:preliminaries}
\paragraph{First- and second-order optimization.} Consider the problem of minimizing a twice-continuously differentiable function $f:\mathbb{R}^d\mapsto\mathbb{R}$. Two well-established strategies for this task are first-order and second-order iterative descent methods. At each iteration $k$, these methods update the current \emph{search point} $\mathbf{x}^k$ using the following update rules: 
\begin{align}
\label{e:firstorderopt_supp}
\mathbf{x}^{k+1}&=\mathbf{x}^k-\eta\nabla f(\mathbf{x}^k),&& \text{\small{(first-order method)}}\\
\mathbf{x}^{k+1}&=\mathbf{x}^k-\eta(\mathbf{b}^k)^{-1}\nabla f(\mathbf{x}^k),&&\text{\small{(second-order method)}}
\label{e:secondorderopt_supp}
\end{align}
where $\eta$ is the step size (or learning rate), and $\mathbf{B}^k$ is a positive definite (PD) matrix that influences the search direction and scaling. A representative example of a second-order method is Newton's method, where $\mathbf{B}^k$ corresponds to the Hessian matrix $\mathbf{H}^k:=Hf(\mathbf{x}^k)$, with $H$ denoting the Hessian operator. 

\paragraph{Zeroth-order optimization.} 
A common approach in ZO optimization is to approximate the gradient $\nabla f(\mathbf{x})$ using randomized finite difference methods while adhering to the first-order update rule (\cref{e:firstorderopt})~\cite{NS15,DJW15}:
\begin{equation}
\label{e:rge_supp}
\widehat{\nabla}f(\mathbf{x}) = \frac{1}{q}\sum_{i=1}^{q} \frac{f(\mathbf{x}+\epsilon \mathbf{u}_{i})-f(\mathbf{x})}{\epsilon}\mathbf{u}_{i},
\end{equation}
where $\epsilon$ is a small positive scalar, $q$ is the number of perturbations, and $\mathbf{u}_i\in \mathbb{R}^d$ is a random perturbation vector drawn from the normal distribution $\mathcal{N}(\mathbf{0},\mathbf{I})$.

\noindent For $q = 1$ and $\epsilon \rightarrow 0$, this approximation converges to the directional derivative of $f$ at $\mathbf{x}$ along $\mathbf{u}$~\cite{NS15}:
\begin{align}
D_\mathbf{u} f(\mathbf{x}) = \mathbf{u}^{\top}\nabla f(\mathbf{x}) = \lim_{\epsilon \rightarrow 0}\frac{f(\mathbf{x}+\epsilon\mathbf{u})-f(\mathbf{x})}{\epsilon}.
\end{align}
Multiplying by $\mathbf{u}$ and taking the expectation with respect to $\mathbf{u}$ yields:
\begin{align}
\mathbb{E}[D_\mathbf{u} (\mathbf{x})\mathbf{u}] = \mathbb{E}[(\mathbf{u}\mathbf{u}^{\top})\nabla f(\mathbf{x})] = \nabla f(\mathbf{x}).  
\end{align}
The Hessian matrix can also be approximated using finite differences~\cite{Ye23}:
\begin{align}
\label{e:hessiafd}
\widehat{\mathbf{H}} = \frac{1}{q}\sum_{i=1}^{q}\frac{f(\mathbf{x}+\epsilon\mathbf{u}_i)+f(\mathbf{x}-\epsilon\mathbf{u}_i)-2f(\mathbf{x})}{2\epsilon^2}\mathbf{u}_{i}\mathbf{u}_{i}^{\top} + \lambda \mathbf{I},
\end{align}
where $\lambda$ is a regularization parameter that ensures $\widehat{\mathbf{H}}$ remains PD. This estimated Hessian can be combined with the finite-difference gradient $\widehat{\nabla}f$ (\cref{e:rge_supp}) to enable second-order updates within the ZO setting. However, in high-dimensional settings, the query complexity $q$ required for accurate Hessian estimation scales quadratically with the dimensionality $d$, making direct second-order ZO optimization impractical.

\subsection{Baseline algorithms}
\label{sss:baseline}
To benchmark our approach, we evaluated several existing zeroth-order optimization methods. 
\begin{itemize}
\item \emph{Randomized stochastic projected gradient} (\textbf{\texttt{RSPG}}) applies standard randomized finite differences to approximate function gradients~\cite{GLZ16}. 
\item \emph{Zeroth-order sign-based stochastic gradient descent} (\textbf{\texttt{ZO-signSGD}}) improves robustness by relying only on the directional signs of the estimated partial derivatives~\cite{LCC19}. 
\item Extending the adaptive momentum method (AdaMM) to the zeroth-order domain, \emph{zeroth-order adaptive momentum method} (\textbf{\texttt{ZO-AdaMM}}) accelerates optimization by updating learning rates and descent directions based on past gradient evaluations~\cite{CLX19}. 
\item \emph{Sample reusable linear interpolation-based zeroth-order optimization} (\textbf{\texttt{ReLIZO}}) computes gradient approximations using quadratically constrained linear programming on sampled function evaluations~\cite{WQY24}. 
\item \emph{Gradient compressed sensing} (\textbf{\texttt{GraCe}}) reduces function evaluation costs by calculating sparse approximate gradients~\cite{QT24}. 
\item \emph{Hessian informed zeroth-order optimizer} (\textbf{\texttt{HiZOO}}) exploits second-order curvature information by estimating the diagonal elements of the Hessian matrix~\cite{ZDY25}. 
\item \emph{Zeroth-order Hessian-aware algorithm} (\textbf{\texttt{ZOHA}}) estimates the Hessian matrix using low-rank approximations via eigenvalue decomposition~\cite{Ye23}.  
\item \emph{Zeroth-order optimization for deep model training} (\textbf{\texttt{DeepZero}}) is designed for neural network training, selectively optimizing specific layers at each step~\cite{CZJ24}. When applied to logistic regression, interpreted as a neural network with a single layer, it simplifies to randomized block coordinate descent.
\end{itemize}

