\begin{definition}[Encounter frame and conjunction plane]
Let $\bx_{\p_1}$ be the nominal position of the main body at time of closest approach.  
We consider the orthonormal frame $(\bi, \bj, \bk)$ given by \cite{akella2000probability}:
    \begin{align}\label{eq:ijk conjunction plane}
            \bi = \frac{\bv_{\s}^{}-\bv_{\p_1}^{}}{|\bv_{\s}^{}-\bv_{\p_1}^{}|}, \quad
        \mathbf{j} = \frac{\bv_{\s} \wedge \bv_{\p_1}}{|\bv_{\s} \wedge \bv_{\p_1}|}, \quad \bk = \bi \wedge \bj.
    \end{align}
We define the \emph{local encounter frame} as $\cL = (\bx_{\p_1}; \bi, \bj, \bk)$, and 
the \emph{conjunction plane} $\cC$ as the 2D affine plane through $\bx_{\p_1}$ spanned by $(\bj, \bk)$:
\begin{align}
    \cC = \bx_{\p_1} + \mathrm{span}(\bj, \bk).
\end{align}
\end{definition}




\begin{assumption}[Information on the main body and secondary object]\label{hyp:object_info}
Throughout the encounter window, the position uncertainty of the main body (\resp{}, the secondary object) is described by a Gaussian distribution with constant covariance.
\end{assumption}
% We assume that some information is available on the states of the main body and the secondary object (e.g., drawn from a space catalog prior to the collision risk analysis).

At \tca{}, the projection of the nominal (or mean) value of the position of the main body (\resp{}, the secondary object) in the conjunction plane is denoted by $x_{\p_1}$ (\resp{} $x_{\s}$). Likewise, the projection of the (constant) covariance on the position of the main body (\resp{}, the secondary object) in the conjunction plane is denoted by $\Sigma_{\p_1}$ (\resp{} $\Sigma_{\s}$).

Given the geometries of the bodies involved in the collision event, the tether is assimilated to a line of negligible thickness. We impose little physical constraints to its shape and mechanical properties, but for its fixed length $\ell$. In order to describe the shape of the tether throughout the encounter window, we make use of the \emph{local encounter frame} $\cL$ with the tuple $(\bi, \bj, \bk)$ centered on the main body's nominal position. Then:

\begin{definition}[Tether configuration]
    \label{def:tether_shape}
    A \emph{(tether) configuration} is a continuous mapping $\bx_{\te}:~[0, 1] \mapsto \mathbb{R}^3$ such that
    \begin{align}\label{eq:tether_position}
        \bx_{\te}(0) = 0, \quad \mathrm{and} \int_0^1 \left\| \frac{\d \bx_{\te}(s)}{\d s} \right\| \d s &= \ell,
    \end{align}
    describing the shape of the tether in the local encounter frame  \(\mathcal{L}\). In particular, the tip $\bx_{\te}(0)$ coincides with the nominal position of the main body, and the tip $\bx_{\te}(1)$ coincides with the center of gravity of the small body. The set of all configurations is denoted by $\cS_{\te}$. 
\end{definition}

We also denote by $R_{\p_1}$ (\resp{} $R_{\p_2}$, $R_{\s}$) the \hbr{} of the main body (\resp{} small body, secondary object). Finally, we denote by $(\mathbf{R}_{\p}, \mathbf{T}_{\p}, \mathbf{N}_{\p})$ the local RTN frame of the main body, where $\mathbf{R}_{\p}$ (\resp{} $\mathbf{T}_{\p}$, $\mathbf{N}_{\p}$) is the radial (\resp{} tangential, out-of-plane) component.



\subsection{Problem Formulation}
A detailed modeling of tether dynamics is beyond the scope of this paper. This is further motivated by the fact that (1) the tethered system can exhibit highly complex behavior in orbit, including bounded, unbounded, or even chaotic configurations under certain energy and orbit conditions~\cite{misra2008tether_dynamics}; and (2) neither the tether nor the small body is typically observable with sufficient accuracy using ground-based sensors. For the sake of this problem, we will assume that


\begin{assumption}[Tether dynamics]
    \label{hyp:tether_dynamics}
    % Let $\Delta x_{\te}\coloneq x_{\p_2}-x_{\p_1}$ be the relative position of the tethered spacecraft's small-body
    % to main-body. 
    Throughout the collision encounter, the configuration of the tether is fixed and characterized by some unknown distribution $\rho_{\te}$ on $\cS_{\te}$.
    % $\Sigma_{\p_2}=\Sigma_{\p_1}$, which is intuitively equivalent to say that
    % the configuration $x_{\p_2}-x_{\p_1}$ remains the same when 
    % $x_{\p_1}$ varies in a high-level confidence region around its reference position.     % \begin{enumerate}[start=1,label={(\bfseries A\theassumptions.\arabic*)},itemsep=1mm, leftmargin=1.4cm]
    %     % \item \label{hyp:small_body_covariance} 
    % \end{enumerate}
\end{assumption}

Further denote by $\varphi_{\cL}^{\cC}$ the projection from the local encounter frame $\cL$ to the conjunction plane $\cC$. Then, we can formulate the collision risk assessment problem as a generalization of the classical, 2D conjunction problem \cite{akella2000probability}. Indeed, the geometry of the primary object no longer reduces to a sphere with radius $R_{\p_1}$ centered on the main body's nominal position $x_{\p_1}$: it also incorporates a sphere with radius $R_{\p_2}$ accounting for the small body, as well as the projection $x_{\te} \coloneq \varphi_{\cL}^{\cC} \circ \bx_{\te}$ representing the "footprint" of the tether in the conjunction plane (see \cref{fig_proj_cplane}).
We define the \textit{Combined Tether Hard Body} by 
\begin{align}
    \cT(x_{\te}; R_{\p_1}, R_{\p_2}, R_{\s}) \coloneq 
    \cB_2(x_{\te}(0), R_{\p_1}+R_{\s}) \cup
    \bigcup_{0\leq t \leq 1} \cB_2(x_{\te}(t), R_{\s})
    \cup \cB_2(x_{\te}(1), R_{\p_2}+R_{\s}).
\end{align}
where $\cB_2$ denotes 2-dimensional balls in the conjunction plane $\cC$, and $\bigcup_{0\leq t\leq 1} \cB_2(x_{\te}(t), R_{\s}) $ is the union of the 2-dimensional balls sweeping alongside the projection of the tether in the conjunction plane.
\begin{figure}
    \centering
    \includegraphics[width=0.7\linewidth]{figs/proj_cplane.pdf}
    \caption{\small Projection of the primary object in the conjunction plane, with the collision region depicted in red\label{fig_proj_cplane}}
\end{figure}

The PoC \cite{akella2000probability, hall2019_PoC_2D_limitations} between the tether spacecraft and the secondary is then
% \begin{align}
%     \pc_{\mathrm{ref}} =& \int \pc\left(\cB_2( x_{\p_2},R_{s,p_2}) ; ~x_{\s}, \Sigma_{\p_1}+\Sigma_{s} \right)
%     \mathcal{D}(x_{\te}) \d x_{\te}\\
%     +&  \int  
%     \pc\left(\int_0^1 \cB_2( x_{\te}(t),R_{\s}) \d t; ~x_{\s}, \Sigma_{\p_1}+\Sigma_{s} \right)
%     \mathcal{D}(x_{\te}) \d  x_{\te} 
% \end{align}
\begin{align} \label{eq_pcref}
    \pc_{\refr} =
    &  \int  
    \pc\Big( \cT(x_{\te}; R_{\p_1}, R_{\p_2}, R_{\s}); ~ x_{\s}, \Sig_{\p_1}+\Sig_{\s} \Big)\rho_{\te}(\bx_{\te}) \d\bx_{\te} ,
\end{align}
where\begin{align}
    \pc(A; \ox, \Sigma)=\frac{1}{2\pi \sqrt{|\det \Sigma|}}  \int_A 
    \exp\left(
        -\frac{1}{2}(x-\ox)^T \Sigma^{-1}(x-\ox)
    \right)\d x.
\end{align}
Unfortunately, $\rho_{\te}$ is typically unknown to the conjunction analyst, so the computation of the reference value Eq.\eqref{eq_pcref} remains out of reach in most practical situations.

\subsection{Evaluation of collision risk}

We will then consider particular cases, corresponding to various physical configurations of the tether, and draw the relevant information on the \poc{}.




\subsubsection{Maximum PoC over All Tether Configurations}

We first consider a conservative upper bound on the reference value $\pc_{\refr}$ in Eq.~\eqref{eq_pcref}, by maximizing the collision probability over all physically admissible tether configurations. Since neither the tether nor the small body is tracked, and no further dynamical assumptions are made, all configurations in $\cS_{\te}$ are considered possible.
Although tethered systems can exhibit bounded, unbounded, or even chaotic behavior~\cite{misra2008tether_dynamics}, this formulation simply reflects a lack of knowledge. We refer to the resulting worst-case estimate as the $\overline{\pc}_{\caos}$ defined by
\begin{align}\label{eq:maximum_over_configuration}
    \overline{\pc}_{\caos} = \sup_{\bx_{\te}\in \cS_{\te}}
        \pc\Big( \cT(x_{\te}; R_{\p_1}, R_{\p_2}, R_{\s}); ~ x_{\s}, \Sig_{\p_1}+\Sig_{\s} \Big).
\end{align}
The formal proof that $\overline{\pc}_{\caos}$ is an upper bound on $\pc_{\refr}$ is provided in \cref{sec:proof_PoC_caos_upper_bound}.



\subsubsection{Maximum PoC over all Planar Configurations}

An important case is when 
the small body, the tether and the main body of the tether spacecraft remain co-planar \cite{misra2008tether_dynamics},
either naturally by the dynamics or by active control.
\begin{assumption}[Tether Planar Dynamics]
    \label{hyp:planar_dynamics}
    The small body and the tether remain in the same orbital plane as the main body. Otherwise said, $\bx_{\te}(t)\cdot \mathbf{N}_{\p} = 0$, for all $0 \leq t \leq 1$. 
\end{assumption}
Define the matrices
\begin{equation}
    P =
    \begin{bmatrix}
        \mathbf{R}_{\p} \cdot \mathbf{j} & \mathbf{T}_{\p} \cdot \mathbf{j} \\
        \mathbf{R}_{\p} \cdot \mathbf{k} & \mathbf{T}_{\p} \cdot \mathbf{k}
    \end{bmatrix}
    \text{ and } Q = \ell^2 PP^{\dT}.
\end{equation}
\cref{hyp:planar_dynamics} on tether dynamics  constrains the tethered spacecraft system $\bx_{\te}$ to remain 
in a 2-dimensional ball in the plane $(\mathbf{R}_{\p}, \mathbf{T}_{\p})$, whose projection onto the conjunction plane $\cC$ is a 2-dimensional ellipse $E_2(x_{\p_1}, Q)$ defined by
the implicit equation   
% \begin{align}
%     (x_{\te}-x_{\p_1})^{\dT}Q^{-1}(x_{\te}-x_{\p_1})\leq 1.
% \end{align}
\begin{align}
    x_{\te}^{\dT}~Q^{-1} x_{\te}\leq 1.
\end{align}
Therefore, by considering the set of planar configurations 
\begin{align}
    \cS_{\plan}\coloneq \{\bx_{\te} \in \cS_{\te}~|~x_{\te}\subset E_2(x_{\p_1}, Q)\},
\end{align}
% Je dirais plutôt :
% \begin{align}
%     \cS_{\plan}\coloneq \{\bx_{\te} \in \cS_{\te}, ~\mathrm{Im}(x_{\te})\subseteq E_2(0, Q)\},
% \end{align}
% with the assumption the small-body's uncertainty \ref{hyp:small_body_covariance}
\cref{eq:maximum_over_configuration} becomes to 
% \begin{align}%\label{eq:maximum_over_configuration}
%     \overline{\pc}_{\mathrm{plan}} = \sup_{x_{\te}\in \cS_{\plan}}
%     \Bigg[
%         \pc &\Big(
%         \cB_2(x_{\p_2}, R_{s, p_2})
%     ; ~ x_{\s}, \Sig_{\p_1}+\Sig_{\s}\Big)  \\
%     +& 
%         \pc \Bigg(\bigcup_{0\leq t\leq 1}
%         \cB_2(x_{\te}(t), R_{s}) 
%     ; ~ x_{\s}, \Sig_{\p_1}+\Sig_{\s}\Bigg) 
%     \Bigg].
% \end{align}
\begin{align}%\label{eq:maximum_over_configuration}
    \overline{\pc}_{\plan} = \sup_{\bx_{\te}\in \cS_{\plan}}
        \pc\Big( \cT(x_{\te}; R_{\p_1}, R_{\p_2}, R_{\s}); ~ x_{\s}, \Sig_{\p_1}+\Sig_{\s} \Big) 
\end{align}

\subsubsection{PoC for straight configuration}
Finally, we consider the specific case where the tether is fully stretched and aligned with Earth's gravitational pull on the main body, a configuration that may occur in particular with gravity-gradient stabilized or electrodynamic tethers \cite{cosmo1997tethers}.
\begin{assumption}[Straight Earth-Pointing Tether]
    \label{hyp:straight_earth_pointing}
    The tether is fully deployed and modeled as a straight line aligned with the local radial direction pointing toward Earth. That is, the configuration of the tether in the local encounter frame $\cL$ is
    \begin{align}
    \bx_{\te, \rad}(t) = -t \, \ell \, \mathbf{R}_{\p}, \quad \text{for all } t \in [0,1].
    \end{align}
    In particular, the tether lies entirely within the orbital plane and experiences no transverse motion or deformation.
\end{assumption}
Since the tether lies along $\mathbf{R}_{\p}$, its projection onto the conjunction plane $\cC$ is given by
\begin{align}
    x_{\te, \rad}(t) = - t\ell \, u, \quad \text{where} \quad
u = 
\begin{bmatrix}
\mathbf{R}_{\p} \cdot \mathbf{j} \\
\mathbf{R}_{\p} \cdot \mathbf{k}
\end{bmatrix},
\end{align}
for all  $t \in [0,1]$. Thus, \cref{eq:maximum_over_configuration} becomes to 
\begin{align}
    \pc_{\rad} =
        \pc\Big( \cT(x_{\te, \rad}; R_{\p_1}, R_{\p_2}, R_{\s}); ~ x_{\s},
                    \Sig_{\p_1}+\Sig_{\s} \Big), 
\end{align}
that is, the analyst has now access to the value of the PoC.

\subsection{Comparison of PoC methods}
We analyze in this section the several methods presented above. We first introduce the standard operational method that spares the modeling of the tether altogether and accounts for its existence solely through an inflated \hbr{} for the primary object, namely, consider \hbr{} $\ell$ instead of $R_{\p_1}$. The corresponding PoC is then
\begin{align} \label{eq_poc_std}
    \pc_{\std} = \pc \Big(
        \cB_2(x_{\p_1}, \ell+R_{\s})
    ; ~ x_{\s}, \Sig_{\p_1}+\Sig_{\s}\Big).
\end{align}


This "standard" method is mostly advantageous due to its simplicity, since it avoids the modeling of the tether and remains within the remit of the classical 2D PoC approach \cite{akella2000probability}. It does, however, correspond to a non-physical configuration of the tether that would \emph{simultaneously fill up} the entire 3-dimensional ball of radius $\ell$ centered on the main body, at any given time throughout the encounter. Thus it (largely) overestimates the collision risk, in the general case. More precisely, it holds that:
\begin{property}[Comparison of PoC methods]
    Under chaotic motion (i.e., no further assumptions beyond \cref{hyp:tether_dynamics}),
    \begin{align}
        \pc_{\refr} \leq \overline{\pc}_{\caos} \leq 
        \pc_{\std}.
    \end{align}
    Under planar motion (see \cref{hyp:planar_dynamics}),
    \begin{align}
        \pc_{\refr} \leq \overline{\pc}_{\plan} \leq 
        \overline{\pc}_{\caos} \leq 
        \pc_{\std}.
    \end{align}
    Under Earth-pointing configuration (see \cref{hyp:straight_earth_pointing}),
     \begin{align}
        \pc_{\refr} = \pc_{\rad} \leq \overline{\pc}_{\plan} \leq 
        \overline{\pc}_{\caos} \leq 
        \pc_{\std}.
    \end{align}
\end{property}


