The goal of the generator is to generate samples similar to the real samples. Thus, its loss function should take lower values when $D_v^{real}(G_u(z))$ is higher. The loss function for the generator can be written as:
\begin{equation}
\label{eq:sgan_generator}
\calL_{G} = \calE_{z\sim \mathcal{N}^{\ell}(\mathbf{0}, \mathbf{I})}[\phi(D_{v}^{real}(G_u(z)))], 
\end{equation}


where $\phi$ is a monotone decreasing function and $\mathcal{N}^{\ell}(\mathbf{0}, \mathbf{I})$ is a $\ell$-dimensional multivariate normal distribution with zero mean and identity covariant matrix (all components of the vector are independent and follow a standard normal distribution). In our case, we use cross-entropy for the loss function, and $\phi(y) = - \log y$.

The discriminator has two goals: 1) classifying each sample as real or fake and 2) for real data, classifying the sample in one of the $K$ classes. The loss function of the discriminator is
\begin{equation}
\label{eq:sgan_discriminator}
\calL_{D} = \calL_{D,u} + \calL_{D,s},
\end{equation}
where $\calL_{D,u}$ is the \emph{unsupervised loss}, based on the fake samples and unlabeled real data, and $\calL_{D,s}$ is the \emph{supervised loss}, based on the real labeled data. These losses are
\begin{align}
\label{eq:sgan_d_unsupervised}
\calL_{D,u} &= \calE_{z\sim \mathcal{N}^{\ell}(\mathbf{0}, \mathbf{I})}\left[\phi(1-D_{v}^{real}(G_u(z)))\right]
+\calE_{x \sim p_{real, un}}\left[ \phi (D_{v}^{real}(x)) \right],\\
\label{eq:sgan_d_supervised}
\calL_{D,s} &= \calE_{(x, y) \sim p_{real, la}}\left[ \sum_{i=1}^{K} y_i \phi (D_{v,i}^{class}(x)) \right],
\end{align}

where we used $D_{v,i}^{class}(x)$ to denote the $i$-th component of the output vector $D_v^{class}(x)$ in the discriminator. 

\subsection{SSL-GAN training}
\label{sec:sslgan-method}

SSL-GAN extends the traditional unsupervised GAN by introducing an additional objective for the discriminator: classifying the real labeled images. Algorithm~\ref{alg:sslgan-training} summarizes the SSL-GAN training process.
The training proceeds over $T$ epochs, iterating through batches of labeled, $B_L$, and unlabeled, $B_U$, real samples to compute $\mathcal{L}_{D,s}$, $\mathcal{L}_{D,u}$, $\mathcal{L}_{D}$, and $\mathcal{L}_{G}$.
The two loss functions, $\mathcal{L}_{D}$ and $\mathcal{L}_{G}$, are used to update the network weights of the discriminator (Lines~\ref{alg:sa-d-training-d_ini} to~\ref{alg:sa-d-updating-d}) and the generator (Lines~\ref{alg:sa-g-training-g_ini} to~\ref{alg:sa-g-training-g_fin}), respectively, by stochastic gradient descent.

\begin{algorithm}[h!]
  \small
  \captionsetup{font=small}
  \caption{SSL-GAN training\newline
    \textbf{Input:}
    $T$: Epochs, 
    ~$p_{real,la}$: Dataset with labeled data,
    ~$p_{real,un}$: Dataset with unlabeled data,
    ~$B_s$: Batch size, 
    \hbox{$\theta_{g}$, $\theta_{d}$: Initial generator and discriminator parameters}
    \newline
    \textbf{Return:}
    $g,d$: Trained generator and discriminator
  }\label{alg:sslgan-training}
  \begin{algorithmic}[1]
    \State $g \gets$ initializeNetworks($\theta_{g}$)\Comment{Initialize the generator}
    \State $d \gets$ initializeNetworks($\theta_{d}$)\Comment{Initialize the discriminator}
    \For{$t=1$ \textbf{to} $T$}  \Comment{Loop over the $T$ training epochs}\label{alg:loop-training}
      \For{$B_L \subseteq p_{real,la}, B_U \subseteq p_{real,un}$} \Comment{Loop over the batches in the dataset}\label{alg:loop-batches}
        \State $\mathbf{z} \gets$ getRandomNoise($B_s$)\Comment{Get samples from latent space, $\mathbf{z} \sim \mathcal{N}^{\ell}(\mathbf{0}, \mathbf{I})$}\label{alg:sa-d-training-d_ini}
        \State $X_f \gets$ $g$($\mathbf{z}$)\Comment{Generate fake samples}\label{alg:sa-d-creating-g}
        \State $\mathcal{L}_{D,s} \gets$ getSupervisedLoss($d, B_L$)\Comment{Compute supervised loss}\label{alg:d-loss-d-sup}
        \State $\mathcal{L}_{D,u} \gets$ getUnsupervisedLoss($d, g, B_U, X_f$)\Comment{Compute unsupervised loss}\label{alg:d-loss-d-unsup}

        \State $\mathcal{L}_{D} \gets \mathcal{L}_{D,s}+ \mathcal{L}_{D,u}$\Comment{Compute total discriminator loss}\label{alg:sa-d-loss-total}
        \State $d \gets$ gradientDescent($d, \mathcal{L}_{D}, \theta_{d}$)\Comment{Update discriminator parameters}\label{alg:sa-d-updating-d}

        \State $\mathbf{z} \gets$ getRandomNoise($B_s$)\Comment{Get samples from latent space, $\mathbf{z} \sim \mathcal{N}^{\ell}(\mathbf{0}, \mathbf{I})$}\label{alg:sa-g-training-g_ini}
        \State $X_f \gets$ $g$($\mathbf{z}$)\Comment{Generate fake samples}\label{alg:sa-g-creating-g}
        \State $\mathcal{L}_{G} \gets$ generatorLoss($d, g, X_f$)\Comment{Compute generator loss}\label{alg:sa-g-loss-d}

        \State $g \gets$ gradientDescent($g, \mathcal{L}_{G}, \theta_{g}$)\Comment{Update generator parameters}\label{alg:sa-g-training-g_fin}
      \EndFor
    \EndFor
    \State \Return $g, d$ \Comment{Return trained $g$ and $d$}
  \end{algorithmic}
\end{algorithm}

\section{\methodLong}
\label{sec:method}


