We observe that the NN-PDE solution~$\uNhat{\theta}$ converges to the target data~$h$ as the number of neurons~$N$ in the NN~$g^N_\theta$ increases (see \Cref{fig:HeatEquation_a,fig:AllenCahnEquation_a}),
which confirms our theoretical expectations, cf.\@ \Cref{lem:lazytraining,thm:main}.
For a visualization of the target source term~$g_{\text{target}}$, the NN~$g^N_\theta$ as well as the target data~$h$ and the NN-PDE solution~$\uN{\theta}$, we refer the reader to the GitHub repository
\url{https://github.com/KonstantinRiedl/NNPDEs}.
In both experimental scenarios (i) and (ii), the loss decreases quickly from the beginning.
For small values of $N$, convergence saturates earlier at higher loss plateaus, while the error continues to decrease to very low loss plateaus even after $60.000$ epochs for larger $N$.
The spikes and oscillations present in the trajectory of the raw losses (see \Cref{fig:HeatEquation_b,fig:HeatEquation_c,fig:AllenCahnEquation_b,fig:AllenCahnEquation_c}) indicate the strong non-convexity of the underlying optimization problem for both the linear and nonlinear PDE scenario.
Only in the case of the linear heat equation, this non-convexity is expected to vanish in the infinite-width hidden layer limit due to a convexification of the optimization problem.


\section{Neural Network in the PDE Source Term}
\label{sec:infinitewidthNN}

This section is about the mathematical tools related to the neural network~(NN) $g_\theta^N$ defined in \eqref{eq:gN}, which constitutes the source term of the PDE~\eqref{eq:parabolicPDE*_plain}.

\subsection{Properties of the NN Kernel \texorpdfstring{$B$}{}}

The NN kernel~$B$, a.k.a.\@ the neural tangent kernel~(NTK) is given as in \eqref{eq:parabolicB}.
In \Cref{lem:BboundednessLinfty,lem:BboundednessL2,lem:BLipschitz} we establish some properties of the NN kernel~$B_0$ at initialization that will be useful throughout the manuscript.
First, we show that the kernel~$B_0$ is uniformly bounded,
which is a direct consequence of Assumptions~\ref{asm:NN_sigma}, \ref{asm:NN_sigma'} and \ref{asm:NN_mu0}\ref{asm:NN_mu0ii}.

\begin{lemma}[$L_\infty$-boundedness of $B_0$]
    \label{lem:BboundednessLinfty}
    The kernel $B_0=B(\mu_0)$ defined in \eqref{eq:parabolicB} is uniformly bounded in $L_\infty$, i.e., it holds
    \begin{equation}
        B_0(t,x,t',x')
        = B(t,x,t',x';\mu_0)
        \leq C^{B}_\infty
    \end{equation}
    for all $(t,x),(t',x')\in D_T$ for a constant $C^{B}_\infty=C^{B}_\infty(T,D,\sigma,\mu_0)$.
\end{lemma}

Lemma \ref{lem:BboundednessLinfty} directly implies that the kernel~$B_0$ is bounded in $L_2$.
\begin{lemma}[$L_2$-boundedness of $B_0$]
    \label{lem:BboundednessL2}
    The kernel $B_0=B(\mu_0)$ defined in \eqref{eq:parabolicB} is bounded in $L_2$, i.e., $B_0\in L_2(D_T\times D_T)$.
    We abbreviate $C^{B}_2 = \N{B_0}_{L_2(D_T\times D_T)}$.
\end{lemma}

\begin{remark}
    \label{rem:BHilbertSchmidt}
    Since the NN kernel~$B$ is symmetric, as easily verifiable by noting that $B(t,x,t',x';\mu)=B(t',x',t,x;\mu)$, and since $B_0\in L_2(D_T\times D_T)$ as establish in \Cref{lem:BboundednessL2},
    $B_0$ is a Hilbert-Schmidt kernel.
\end{remark}

We further show that the kernel~$B_0$ is Lipschitz continuous in the time and space variables.

\begin{lemma}[Lipschitz continuity of $B_0$]
    \label{lem:BLipschitz}
    The kernel $B_0=B(\mu_0)$ defined in \eqref{eq:parabolicB} is $L_B$-Lipschitz continuous, i.e., it holds
    \begin{equation}
        \abs{B(t^1,x^1,t',x';\mu_0)-B(t^2,x^2,t',x';\mu_0)}
        \leq L_B \left(\abs{t^1-t^2} + \N{x^1-x^2}\right)
    \end{equation}
    for all $(t^1,x^2),(t^2,x^2),(t',x')\in D_T$ for a constant $L_B=L_B(T,D,\sigma,\mu_0)$.
\end{lemma}

\begin{proof}
    The Lipschitzness and boundedness of $\sigma$ and $\sigma'$ via Assumptions~\ref{asm:NN_sigma} and \ref{asm:NN_sigma'} together with Jensen's inequality give
    \begin{equation}
    \begin{split}
        &\abs{B(t^1,x^1,t',x';\mu_0)-B(t^2,x^2,t',x';\mu_0)} \\
        &\qquad\,\leq \int C(1+c^2)\left((1+\absnormal{w^t})\abs{t^1-t^2} + (1+\N{w})\N{x^1-x^2}\right)d\mu_0(w^t,w,\eta,c)
    \end{split}
    \end{equation}
    for a constant $C=C(T,D,\sigma)$.
    Since $\mu_0$ is such that the marginal distribution $\mu_{0,c}$ is compactly supported and the marginal distribution $\mu_{0,(w^t,w,\eta)}$ has bounded moments according to Assumption~\ref{asm:NN_mu0}, the statement follows.
\end{proof}

To wrap up this section, let us show that $k$ is (locally) Lipschitz continuous in the NN parameters. 

\begin{lemma}[Lipschitz continuity of $k$]
    \label{lem:kLipschitz}
    The function $k$ defined in \eqref{eq:parabolick} is $L_k$-Lipschitz continuous, i.e., it holds
    \begin{equation}
    \begin{split}
        &\abs{k(t,x,t',x';c^1,w^{t,1},w^1,\eta^1)-k(t,x,t',x';c^2,w^{t,2},w^2,\eta^2)}\\
        &\qquad\,\leq L_k(c^1,c^2) \left(\abs{c^1-c^2} + \abs{w^{t,1}-w^{t,2}} + \N{w^1-w^2} + \abs{\eta^1-\eta^2}\right)
    \end{split}
    \end{equation}
    for all $(c^1,c^2),(w^{t,1},w^{t,2}),(w^1,w^2),(\eta^1,\eta^2)$ and for all $(t,x),(t',x')\in D_T$ for a constant $L_k(c^1,c^2)=L_k(T,D,\sigma,c^1,c^2)$ that is quadratic in $c^1$ and $c^2$.
\end{lemma}

\begin{proof}
    The proof follows  directly using the Lipschitzness and boundedness of $\sigma$ and $\sigma'$ via Assumptions~\ref{asm:NN_sigma}, \ref{asm:NN_sigma'}. Details are omitted.
\end{proof}

\subsection{Properties of the NN Integral Operator \texorpdfstring{$T_{B_0}$}{}}

The NN integral operator~$T_{B_0}$ is given as in \eqref{eq:parabolicT_B}.
\begin{remark}
    \label{rem:TBHilbertSchmidt}
    With the kernel $B_0$ being, as discussed in \Cref{rem:BHilbertSchmidt}, symmetric and in $L_2$, i.e., a Hilbert-Schmidt kernel,
    the associated operator $T_{B_0}:L_2(\overbar{D_T})\rightarrow L_2(\overbar{D_T})$ is a Hilbert-Schmidt integral operator.
\end{remark}

In \Cref{lem:parabolicTB,lem:TBboundednessLinfty,lem:TBLipschitz,lem:parabolicposdefTB} we establish some properties of the NN integral operator~$T_{B_0}$ that will be useful throughout the manuscript.
First, we show that the eigenfunctions of the NN integral operator~$T_{B_0}$ come with real eigenvalues and form an orthonormal basis of $L_2(D_T)$.
\begin{lemma}[Properties of $T_{B_0}$]
    \label{lem:parabolicTB}
    The operator $T_{B_0}$ defined in \eqref{eq:parabolicT_B} with $B_0=B(\mu_0)$ is a self-adjoint compact linear operator with operator norm $\N{T_{B_0}} \leq \N{T_{B_0}}_{\mathrm{HS}} = \N{B_0}_{L_2(D_T\times D_T)}\!=C^B_2$, where $\N{\dummy}_{\mathrm{HS}}$ denotes the Hilbert-Schmidt norm.
    Furthermore, the eigenfunctions $\left\{e_k(t,x)\right\}_{k=1}^\infty$ of $T_{B_0}$ have real eigenvalues~$\left\{\lambda_k\right\}_{k=1}^\infty$ and form an orthonormal basis of $L_2(D_T)$.
\end{lemma}

\begin{proof}
    Since the kernel $B_0$ is symmetric and of Hilbert-Schmidt type as verified in \Cref{lem:BboundednessL2}, see also \Cref{rem:BHilbertSchmidt},
    the operator $T_{B_0}$ is a self-adjoint, compact linear operator.
    The Hilbert-Schmidt norm is $\N{T_{B_0}}_{\mathrm{HS}} = \N{B_0}_{L_2(D_T\times D_T)}$ and provides an upper bound to the operator norm.
    Furthermore, the spectral theorem ensures the existence of an orthonormal basis of $L_2(D_T)$ consisting of eigenvectors of $T_{B_0}$ with real eigenvalue, see \cite[Theorem~6.12]{brezis2011functional}.
\end{proof}

In fact, as we show  next,
the eigenvalues of the NN integral operator $T_{B_0}$ can be shown to be strictly positive~\cite[pages 27--28]{sirignano2023pde}.
\begin{lemma}[Positive definiteness of $T_{B_0}$]
    \label{lem:parabolicposdefTB}
    The eigenvalues $\left\{\lambda_k\right\}_{k=1}^\infty$ of the operator $T_{B_0}$ defined in \eqref{eq:parabolicT_B} with $B_0=B(\mu_0)$ are strictly positive, i.e., it holds $\lambda_k>0$ for all $k$.
    Moreover, it holds  $\lambda_k\leq \N{B}_{L_2(D_T\times D_T)}$ for all $k$.
\end{lemma}
\begin{proof}
    We first prove that the eigenvalues are strictly positive, i.e., $\lambda_k>0$ for all $k$.
    Using the definition of the kernel $B_0=B(\mu_0)$ in \eqref{eq:parabolicB} we can directly compute that for any function $\widehat{u}=\widehat{u}(t,x)$ it holds
    \begin{equation}       \label{eq:proof:lem:parabolicposdefTB:1}
    \begin{split}        (\widehat{u},T_{B_0}\widehat{u})_{L_2(D_T)}
        &\geq \int \left(\int_0^T\!\!\!\int_D\sigma(w^tt+w^Tx+\eta)\widehat{u}(t,x)\,dxdt\right)^2d\mu_{0,(w^t,w,\eta)}(w^t,w,\eta)\geq0.
    \end{split}
    \end{equation}

    This verifies $\lambda_k=(e_k,T_{B_0}e_k)_{L_2(D_T)}\geq0$.
    Let us now show further that $(\widehat{u},T_{B_0}\widehat{u})_{L_2(D_T)}=0$ if and only if $\widehat{u}=0$ everywhere.
    The ``if'' direction is immediate.
    For the ``only if'' direction, we proceed by contradiction.
    Consider a function $\widehat{u}$ which is not everywhere $0$ but suppose that $(\widehat{u},T_{B_0}\widehat{u})_{L_2(D_T)}=0$.
    The latter implies due to the inequality \eqref{eq:proof:lem:parabolicposdefTB:1} that
    \begin{equation}        \label{eq:proof:lem:parabolicposdefTB:2}
        \int_0^T\!\!\!\int_D\sigma(w^tt+w^Tx+\eta)\widehat{u}(t,x)\,dxdt
        = 0
        \qquad\text{for all }
        w^t\in\bbR,
        w\in\bbR^d,
        \eta\in\bbR,
    \end{equation}
    since the marginal distribution $\mu_{0,(w^t,w,\eta)}$ assigns positive probability to every set with positive Lebesgue measure as of Assumption~\ref{asm:NN_mu0}\ref{asm:NN_mu0iv} and continuity of the integrand w.r.t.\@ the NN parameters~$w^t,w,\eta$.
    Since $\sigma$ is non-constant and bounded as of Assumption~\ref{asm:NN_sigma}, it is, according to \cite[Theorem~5]{hornik1991approximation}, discriminatory in the sense of \cite{cybenko1989approximation,hornik1991approximation}.
    This ensures (note that $\widehat{u}(t,x)\,dxdt$ is a finite signed measure since $\widehat{u}\in L_1(D_T)$ by Jensen's inequality and the fact that $\widehat{u}\in L_2(D_T)$ and $D_T$ being bounded as of Assumption~\ref{asm:Dbdd}) that \eqref{eq:proof:lem:parabolicposdefTB:2} implies that $\widehat{u}=0$ by the definition of $\sigma$ being discriminatory, see \cite{hornik1991approximation}.
    Since this is a contradiction, $(\widehat{u},T_{B_0}\widehat{u})_{L_2(D_T)}>0$ if $\widehat{u}$ is not everywhere $0$.
    In particular, for the eigenfunctions~$e_k$ it thus holds
    $\lambda_k = (e_k,T_{B_0}e_k)_{L_2(D_T)}>0$,
    which proves the first part of the statement.

    It remains to show that the eigenvalues are bounded from above, i.e., $\lambda_k<\infty$.
    For this note that by Cauchy-Schwarz inequality it holds
    \begin{equation}
    \begin{split}
        \lambda_k
        = (e_k,T_{B_0}e_k)_{L_2(D_T)}
        &\leq \N{e_k}_{L_2(D_T)}\N{T_{B_0}e_k}_{L_2(D_T)}\\
        &\leq \N{B_0}_{L_2(D_T\times D_T)}\N{e_k}_{L_2(D_T)}^2
        = \N{B_0}_{L_2(D_T\times D_T)},
    \end{split}
    \end{equation}
    where the last inequality is due to \Cref{lem:parabolicTB}.
    This concludes the statement.
\end{proof}

Next, let us show that the NN integral operator $T_{B_0}$ maps $L_2$ to $L_\infty$.
\begin{lemma}[$L_\infty$-Boundedness of $T_{B_0}\widehat{u}$]   \label{lem:TBboundednessLinfty}
    Let $\widehat{u}\in L_2(D_T)$.
    Then $T_{B_0}\widehat{u}$ defined in \eqref{eq:parabolicT_B} with $B_0=B(\mu_0)$ is uniformly bounded in $L_\infty$, i.e., it holds
    \begin{equation}        \absbig{[T_{B_0}\widehat{u}](t,x)}
        \leq C^{T_B}_\infty \N{\widehat{u}}_{L_2(D_T)}
    \end{equation}
    for all $(t,x)\in D_T$ for a constant $C^{T_B}_\infty=C^{T_B}_\infty(T,D,C^{B}_\infty)$.
\end{lemma}
\begin{proof}
    Using Cauchy-Schwarz inequality and employing \Cref{lem:BboundednessLinfty} afterwards, we bound
    \begin{equation}
    \begin{split}        \absbig{[T_{B_0}\widehat{u}](t,x)}
        &\leq\N{\widehat{u}}_{L_2(D_T)} \sqrt{\int_0^T\!\!\!\int_D \left(B_0(t,x,t',x')\right)^2 dx'dt'}\\
        &\leq \N{\widehat{u}}_{L_2(D_T)} \sqrt{T\vol{D}}C^{B}_\infty
    \end{split}
    \end{equation}    
    for each $(t,x)\in D_T$, which proves the assertion with $C^{T_B}_\infty=\sqrt{T\vol{D}}C^{B}_\infty$.
\end{proof}

To wrap up this section, we furthermore show that~$T_{B_0}\widehat{u}$ is Lipschitz continuous.
\begin{lemma}[Lipschitz continuity of $T_{B_0}\widehat{u}$]
    \label{lem:TBLipschitz}
    Let $\widehat{u}\in L_2(D_T)$.
    Then $T_{B_0}\widehat{u}$ defined in \eqref{eq:parabolicT_B} with $B_0=B(\mu_0)$ is $L_{T_B}$-Lipschitz continuous, i.e., it holds
    \begin{equation}
        \abs{[T_{B_0}\widehat{u}](t^1,x^1)-[T_{B_0}\widehat{u}](t^2,x^2)}
        \leq L_{T_B} \left(\abs{t^1-t^2} + \N{x^1-x^2}\right)
    \end{equation}
    for all $(t^1,x^2),(t^2,x^2)\in D_T$ for a constant $L_{T_B}=L_{T_B}(T,D,L_B)$.
\end{lemma}
\begin{proof}
    Using Cauchy-Schwarz inequality and employing \Cref{lem:BLipschitz} afterwards, we bound
    \begin{equation}
    \begin{split}
        &\abs{[T_{B_0}\widehat{u}](t^1,x^1)-[T_{B_0}\widehat{u}](t^2,x^2)}\\
        &\qquad\,\leq\N{\widehat{u}}_{L_2(D_T)} \sqrt{\int_0^T\!\!\!\int_D \left(B(t^1,x^1,t',x';\mu_0)-B(t^2,x^2,t',x';\mu_0)\right)^2 dx'dt'} \\
        &\qquad\,\leq \N{\widehat{u}}_{L_2(D_T)}  L_B \sqrt{T \vol{D}} \left(\abs{t^1-t^2} + \N{x^1-x^2}\right)
    \end{split}
    \end{equation}
    for $(t^1,x^2),(t^2,x^2)\in D_T$.
\end{proof}
\section{Decay of the Loss or Error Functional \texorpdfstring{$\J{\tau}$}{}}
\label{sec:decayJ}

\Cref{lem:parabolictimeevolutionJt*} in this section establishes that the loss $\J{\tau}$ defined in \eqref{eq:parabolicJtau} is monotonically non-increasing in the training time $\tau$.

We state the result for a training time interval $I$, which may be either $[0,\CT]$ or $[0,\infty)$.
\begin{proposition}[Decay of the loss $\J{\tau}$]    \label{lem:parabolictimeevolutionJt*}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in I}\in \CC\left(I,\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness} on the training time interval $I$.
    Define the error functional $\J{\tau}$ as in \eqref{eq:parabolicJtau}.
    Then, for the training time derivative $\fd{\tau}\J{\tau}$ it holds
    \begin{equation}
    \label{eq:parabolicdtJ*}
    \begin{split}
        \fd{\tau}\J{\tau}
        &= - \alpha_\tau(\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2(D_T)} \\
        &= -\alpha_\tau \int_0^T\!\!\!\int_D \uhatpp{\tau}{t,x} \int_0^T\!\!\!\int_D B(t,x,t',x';\mu_0)\uhatpp{\tau}{t',x'} \,dx'dt'dxdt
    \end{split}
    \end{equation}
    for all $\tau\in I$
    with the operator $T_{B_0}$ defined in \eqref{eq:parabolicT_B} and where the kernel $B_0=B(\mu_0)$ is as in \eqref{eq:parabolicB}.    In particular, we have $\fd{\tau}\J{\tau}\leq 0$ for all $\tau\in I$.
\end{proposition}
\begin{proof}
    Taking the training time derivative of our objective functional $\J{\tau}$, i.e., the derivative w.r.t.\@ the training time~$\tau$, 
    we obtain by chain rule and by using that $\uhatp{\tau}$ is a weak solution to the adjoint PDE~\eqref{eq:parabolicadjoint*} in the sense of \Cref{def:weak_sol_adjoint} with right-hand side $(\up{\tau}-h)$ that 
    \begin{equation}        \label{eq:proof:parabolicdtJ*1}
    \begin{split}
        \fd{\tau}\J{\tau}
        &= \fd{\tau} \frac{1}{2} \int_0^T\!\!\!\int_D (\upp{\tau}{t,x} \!-\! h(t,x))^2 \,dxdt \\
        &= \int_0^T\!\!\!\int_D (\upp{\tau}{t,x} \!-\! h(t,x)) \fd{\tau}\upp{\tau}{t,x} \, dxdt 
        = \int_0^T \!\left(\upp{\tau}{t,\dummy} \!-\! h(t,\dummy), \fd{\tau}\upp{\tau}{t,\dummy}\right)_{L_2(D)}\!dt\\
        &= \int_0^T \left\langle-\fpartial{t}\uhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB^\dagger\left[\uhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, - \left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\uhatpp{\tau}{t,\dummy}, \fd{\tau}\upp{\tau}{t,\dummy}\right)_{L_2(D)} dt \\
        &= \int_0^T \left\langle\fpartial{t}\fd{\tau}\upp{\tau}{t,\dummy},\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB\left[\fd{\tau}\upp{\tau}{t,\dummy},\uhatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, - \left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\fd{\tau}\upp{\tau}{t,\dummy},\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt \\
        &= \int_0^T \left(\fd{\tau}g^*_\tau(t,\dummy),\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt
        = \int_0^T\!\!\!\int_D \left(\fd{\tau}g^*_\tau(t,x)\right)\uhatpp{\tau}{t,x}\, dxdt.
    \end{split}
    \end{equation}

    For the weak solution property in the third line of \eqref{eq:proof:parabolicdtJ*1}, we note that $\fd{\tau}\up{\tau}$, the weak solution to the linear parabolic PDE
    \begin{alignat}{2}
        \label{eq:parabolicpI*aux}
    \begin{aligned}
        \fpartial{t}\fd{\tau}\up{\tau} + \CL\fd{\tau}\up{\tau} - q_u(\up{\tau})\fd{\tau}\up{\tau}
        &= \fd{\tau}g^*_\tau
        \qquad&&\text{in }
        D_T, \\
        \fd{\tau}\up{\tau}
        &= 0
        \qquad&&\text{on }
        [0,T]\times\partial D, \\
        \fd{\tau}\up{\tau}
        &= \fd{\tau}f = 0
        \qquad&&\text{on }
        \{0\}\times D,
    \end{aligned}
    \end{alignat}
    which is obtained by taking in \eqref{eq:parabolicPDE*} the derivative w.r.t.\@ the training time $\tau$,
    can be used as a test function in the weak formulation of \eqref{eq:parabolicadjoint*}, see \Cref{def:weak_sol_adjoint}, since $\fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    Existence, uniqueness and regularity of a weak solution to \eqref{eq:parabolicpI*aux} in a sense analogous to \Cref{def:weak_sol_adjoint} follow from classical results,
    see, e.g., \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial}, as $\fd{\tau} g^*_\tau = - \alpha_\tau T_{B_0}\uhatp{\tau} \in L_2(D_T)$ by \Cref{lem:parabolicTB}.

    For the step in the fourth line of \eqref{eq:proof:parabolicdtJ*1}
    we first recall that 
    since $\fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and since $\fpartial{t}\uhatpp{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$, the dual pairing between $H^{-1}(D)$ and $H_0^1(D)$ coincides with the $L_2(D)$ scalar product \cite[Chapter~5.9, Theorem 1(iii)]{evans2010partial}.
    This allows to compute with partial integration, which applies since $\uhatpp{\tau}{t,\dummy}, \fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$, that
    \begin{equation}       \label{eq:parabolicpI*aux_T51}
    \begin{split}
        &\int_0^T\left\langle\fpartial{t}\uhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} dt\\
        &\qquad\,= \int_0^T\left(\fpartial{t}\uhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        = \int_0^T\!\!\!\int_D \left(\fpartial{t}\uhatpp{\tau}{t,x}\right)\fd{\tau}\upp{\tau}{t,x} \, dxdt\\
        &\qquad\,= \int_D \underbrace{\uhatpp{\tau}{t,x} \fd{\tau}\upp{\tau}{t,x}\Big|_0^T}_{\substack{=0\\\text{since } \uhatp{\tau}=0 \text{ on }\{T\}\times D \text{ and}\\\text{since }\fd{\tau}\up{\tau}=0 \text{ on } \{0\}\times D}} \, dx -\int_0^T\!\!\!\int_D \uhatpp{\tau}{t,x}\fpartial{t}\fd{\tau}\upp{\tau}{t,x} \, dxdt \\
        &\qquad\,=-\int_0^T\!\!\!\int_D  \left(\fpartial{t}\fd{\tau}\upp{\tau}{t,x}\right)\uhatpp{\tau}{t,x} \, dxdt
        = -\int_0^T\left(\fpartial{t}\fd{\tau}\upp{\tau}{t,\dummy},\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)}\,dt \\
        &\qquad\,= -\int_0^T\left\langle\fpartial{t}\fd{\tau}\upp{\tau}{t,\dummy},\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} dt,
    \end{split}
    \end{equation}
    where the last step holds again since now $\uhatpp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and $\fpartial{t}\fd{\tau}\uhatp{\tau}$ is in $L_2(D)$ for a.e.\@ $t\in[0,T]$ by \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} with $p=2$.
    Those computations are analogous to the ones of \Cref{lem:parabolic_wellposedness} for the PDE \eqref{eq:parabolicpI*aux} due to its with \eqref{eq:parabolicadjoint*} identical structure and since $\fd{\tau} g^*_\tau\in L_2(D_T)$.
    Secondly, by definition of the adjoint bilinear form~$\CB^\dagger$ (see \Cref{def:weak_sol_adjoint}) it holds
    \begin{equation}
        \label{eq:parabolicpI*aux_T52}
        \CB^\dagger\left[\uhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy};t\right]
        =\CB\left[\fd{\tau}\upp{\tau}{t,\dummy},\uhatpp{\tau}{t,\dummy};t\right]
    \end{equation}
    for a.e.\@ $t\in[0,T]$ since $\uhatpp{\tau}{t,\dummy}, \fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$. 

    The penultimate step of \eqref{eq:proof:parabolicdtJ*1} holds since $\fd{\tau}\uhatp{\tau}$ is a weak solution to the PDE~\eqref{eq:parabolicpI*aux} and since $\uhatpp{\tau}{t,\dummy}$ is a suitable test function as it is in $H_0^1(D)$ for a.e.\@ $t\in[0,T]$.

    Now, recalling the definition of the right-hand side~$g^*_\tau$ from \eqref{eq:parabolicgtau} and taking its training time derivative to obtain $\fd{\tau} g^*_\tau = - \alpha_\tau T_{B_0}\uhatp{\tau}$, as well as recalling the definition of the operator $T_{B_0}$ from \eqref{eq:parabolicT_B},
    we can continue \eqref{eq:proof:parabolicdtJ*1} to obtain
    \begin{equation}
    \label{eq:proof:parabolicdtJ*2}
    \begin{split}
        \fd{\tau}\J{\tau}
        &= - \alpha_\tau \int_0^T\!\!\!\int_D \uhatpp{\tau}{t,x} \int_0^T\!\!\!\int_D B(t,x,t',x';\mu_0)\uhatpp{\tau}{t',x'} \,dx'dt'dxdt \\
        &= - \alpha_\tau (\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2(D_T)},
    \end{split}
    \end{equation}
    which concludes the first part of the proof.

    The second part now follows immediately thanks to the operator $T_{B_0}$ being positive definite as of \Cref{lem:parabolicposdefTB}.
\end{proof}

Following analogous steps we can prove \Cref{lem:grad_thetaJ}.

\begin{proof}[Proof of \Cref{lem:grad_thetaJ}]
    Taking the gradient of the objective functional $\JN{\theta}$ w.r.t.\@ the NN parameters~$\theta$, 
    we obtain by chain rule and by using that $\uNhat{\theta}$ is a weak solution to the adjoint PDE~\eqref{eq:parabolicadjoint*_plain} in the sense of \Cref{def:weak_sol_adjoint} that
    \begin{equation}        \label{eq:proof:parabolicnablaJ*1}
    \begin{split}
        \nabla_\theta\JN{\theta}
        &= \nabla_\theta \frac{1}{2} \int_0^T\!\!\!\int_D (\uNu{\theta}{t,x} \!-\! h(t,x))^2 \,dxdt \\
        &= \int_0^T\!\!\!\int_D (\uNu{\theta}{t,x} \!-\! h(t,x))\nabla_\theta \uNu{\theta}{t,x} \,dxdt 
        = \!\int_0^T \!\!\big(\uNu{\theta}{t,\dummy} \!-\! h(t,\dummy), \nabla_\theta\uNu{\theta}{t,\dummy} \big)_{L_2(D)} \, dt \\
        &= \int_0^T \big\langle\!-\!\fpartial{t}\uNhatu{\theta}{t,\dummy},\nabla_\theta\uNu{\theta}{t,\dummy}\big\rangle_{H^{-1}(D),H_0^1(D)} + \CB^\dagger[\uNhatu{\theta}{t,\dummy},\nabla_\theta\uNu{\theta}{t,\dummy};t] \\
        & \qquad\quad\, - \big(q_u(t,\dummy,\uNu{\theta}{t,\dummy})\uNhatu{\theta}{t,\dummy}, \nabla_\theta\uNu{\theta}{t,\dummy}\big)_{L_2(D)} \, dt \\
        &= \int_0^T \big\langle\fpartial{t}\nabla_\theta\uNu{\theta}{t,\dummy},\uNhatu{\theta}{t,\dummy}\big\rangle_{H^{-1}(D),H_0^1(D)} + \CB[\nabla_\theta\uNu{\theta}{t,\dummy},\uNhatu{\theta}{t,\dummy};t] \\
        & \qquad\quad\, - \big(q_u(t,\dummy,\uNu{\theta}{t,\dummy}) \nabla_\theta\uNu{\theta}{t,\dummy},\uNhatu{\theta}{t,\dummy}\big)_{L_2(D)} \, dt \\
        &= \int_0^T\big(\nabla_\theta g_\theta^N(t,\dummy),\uNhatu{\theta}{t,\dummy}\big)_{L_2(D)}\, dt
        = \int_0^T\!\!\!\int_D \left(\nabla_\theta g_\theta^N(t,x)\right)\uNhatu{\theta}{t,x}\, dxdt.
    \end{split}
    \end{equation}
    For the weak solution property in the third line of \eqref{eq:proof:parabolicnablaJ*1}, we note that $\nabla_\theta\uN{\theta}$, the weak solution to the linear parabolic PDE
    \begin{alignat}{2}
        \label{eq:parabolicpI*aux_plain}
    \begin{aligned}
        \fpartial{t}\nabla_\theta\uN{\theta} + \CL\nabla_\theta\uN{\theta} - q_u(\uN{\theta})\nabla_\theta\uN{\theta}
        &= \nabla_\theta g_\theta^N
        \qquad&&\text{in }
        D_T, \\
        \nabla_\theta\uN{\theta}
        &= 0
        \qquad&&\text{on }
        [0,T]\times\partial D, \\
        \nabla_\theta\uN{\theta}
        &= \nabla_\theta f = 0
        \qquad&&\text{on }
        \{0\}\times D,
    \end{aligned}
    \end{alignat}
    which is obtained by taking in \eqref{eq:parabolicPDE*_plain} the gradient w.r.t.\@ the NN parameters $\theta$,
    can be used as a test function in the weak formulation of \eqref{eq:parabolicadjoint*_plain}, see \Cref{def:weak_sol_adjoint}, since $\nabla_\theta\uNu{\theta}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    Existence, uniqueness and regularity of a weak solution to \eqref{eq:parabolicpI*aux_plain} in a sense analogous to \Cref{def:weak_sol_adjoint} follow from classical results as $\nabla_\theta g_\theta^N\in L_2(D_T)$,
    see, e.g., \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial}.

    For the step in the fourth line of \eqref{eq:proof:parabolicnablaJ*1} we use partial integration and the definition of the adjoint bilinear form~$\CB^\dagger$ with the same argumentation as in the proof of \Cref{lem:parabolictimeevolutionJt*}.

    The penultimate step of \eqref{eq:proof:parabolicnablaJ*1} holds since $\nabla_\theta\uN{\theta}$ is a weak solution to the PDE~\eqref{eq:parabolicpI*aux_plain} and since $\uNhatu{\theta}{t,\dummy}$ is a suitable test function as it is in $H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
\end{proof}
\section{PDE Considerations}
\label{sec:PDEconsiderations}
Leveraging that the loss $\J{\tau}$ defined in \eqref{eq:parabolicJtau} is non-increasing in the training time $\tau$ as established in \Cref{lem:parabolictimeevolutionJt*},
we provide in \Cref{sec:BoundednessSolution,sec:BoundednessAdjoint} uniform (in the training time~$\tau$) estimates for the norms of the PDE solution $\up{\tau}$ to \eqref{eq:parabolicPDE*} and its adjoint $\uhatp{\tau}$ in \eqref{eq:parabolicadjoint*}.
Those bounds are in particular independent of and thus uniform in the training time $\tau$, depending only on properties of the PDE and the NN initialization at training time~$\tau=0$.

We state the results for a training time interval $I$, which may be either $[0,\CT]$ or $[0,\infty)$.

\subsection{Boundedness of the PDE Solution \texorpdfstring{$\up{\tau}$}{} Uniformly in the Training Time}
\label{sec:BoundednessSolution}

The following uniform (in the training time $\tau$) bound on the $L_2$ norm of the PDE solution $\up{\tau}$ to \eqref{eq:parabolicPDE*}
is an immediate consequence of the error functional $\J{\tau}$ being monotonically non-increasing.

\begin{lemma}
    \label{lem:parabolic_uL2}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in I}\in \CC\left(I,\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness} on the training time interval $I$.
    Then the solution~$\up{\tau}$ is uniformly (in the training time $\tau$) bounded in $L_2(D_T)$ on that interval $I$, i.e., it holds
    \begin{equation}
        \sup_{\tau\in I}\N{\up{\tau}}_{L_2(D_T)}\leq C^{u}
    \end{equation}
    for the constant $C^{u}=4\J{0} + 2\N{h}_{L_2(D_T)}^2$.
\end{lemma}

\begin{proof}
    For the solution~$\up{\tau}$ to \eqref{eq:parabolicPDE*} we can compute with Young's inequality
    \begin{equation}
    \begin{split}
        \N{\up{\tau}}_{L_2(D_T)}^2
        &= \int_0^T\!\!\!\int_D \left(\upp{\tau}{t,x}\right)^2dxdt
        = \int_0^T\!\!\!\int_D \left(\upp{\tau}{t,x}-h(t,x)+h(t,x)\right)^2dxdt\\
        &\leq \int_0^T\!\!\!\int_D 2(\upp{\tau}{t,x}-h(t,x))^2 + 2(h(t,x))^2\,dxdt
        = 4\J{\tau} + 2\N{h}_{L_2(D_T)}^2 \\
        &\leq 4\J{0} + 2\N{h}_{L_2(D_T)}^2,
    \end{split}
    \end{equation}
    where the last step is a consequence of $\J{\tau}$ being monotonically non-increasing on the training time interval $I$ according to \Cref{lem:parabolictimeevolutionJt*}.
\end{proof}

\subsection{Boundedness of the Adjoint \texorpdfstring{$\uhatp{\tau}$}{} Uniformly in the Training Time}
\label{sec:BoundednessAdjoint}

Uniform (in the training time $\tau$) bounds on the $L_2([0,T],H^1(D))$- and $L_\infty([0,T],L_2(D))$-norms of the adjoint $\uhatp{\tau}$ in \eqref{eq:parabolicadjoint*}
are obtained via an energy estimate for the linear parabolic PDE~\eqref{eq:parabolicadjoint*} leveraging that the error functional $\J{\tau}$ is monotonically non-increasing in the training time~$\tau$.
\begin{lemma}
    \label{lem:parabolic_uhatL2}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in I}\in \CC\left(I,\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness} on the training time interval $I$.
    Then the adjoint~$\uhatp{\tau}$ in \eqref{eq:parabolicadjoint*} is uniformly (in the training time $\tau$) bounded in $L_2([0,T],H^1(D))$ and $L_\infty([0,T],L_2(D))$ on that interval $I$,
    i.e., it holds
    \begin{equation}
        \label{eq:lem:parabolic_uhatL2}
        \sup_{\tau\in I} \left(\N{\uhatp{\tau}}_{L_2([0,T],H^1(D))} + \N{\uhatp{\tau}}_{L_\infty([0,T],L_2(D))} \right)
        \leq C^{\widehat{u}}
    \end{equation}
    for a constant $C^{\widehat{u}}=C^{\widehat{u}}(T,\CL,\J{0})$.
\end{lemma}
\begin{proof}
    Let us first reverse the adjoint parabolic backward PDE \eqref{eq:parabolicadjoint*} in time to obtain with a time transformation
    for $\uhatpReverted{\tau}=\uhatppReverted{\tau}{t,x}=\uhatpp{\tau}{T-t,x}$ the parabolic forward PDE
    \begin{alignat}{2}  \label{eq:parabolicadjoint*Reversed2}
    \begin{aligned}        \fpartial{t}\uhatpReverted{\tau} + \underbar{\CL}^*\uhatpReverted{\tau} - \underbar{q}_u(\upp{\tau}{T-\dummy,\dummy})\uhatpReverted{\tau}
        &= (\upp{\tau}{T-\dummy,\dummy}-h(T-\dummy,\dummy))
        \quad&&\text{in }
        D_T, \\
        \uhatpReverted{\tau}
        &= 0
        \quad&&\text{on }
        [0,T]\times\partial D, \\
        \uhatpReverted{\tau}
        &= 0
        \quad&&\text{on }
        \{0\}\times D,
    \end{aligned}
    \end{alignat}
    where $\underbar{\CL}^*=\underbar{\CL}^*(t,x)=\CL^\dagger(T-t,x)$ and $\underbar{q}=\underbar{q}(t,x,u)=\underbar{q}(T-t,x,u)$.

    Let us now start by estimating $\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} = \int_D (\uhatppReverted{\tau}{t,x})^2 \,dx$.
    With chain rule and by using that $\uhatpReverted{\tau}$ is a weak solution to the time-reversed adjoint PDE~\eqref{eq:parabolicadjoint*Reversed2} we have
    \begin{equation}        \label{eq:proof:lem:parabolic_uhatL2:1}
    \begin{split}
        \fpartial{t}\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}
        &= 
        2\left(\uhatppReverted{\tau}{t,\dummy} ,\fpartial{t}\uhatppReverted{\tau}{t,\dummy}\right)_{L_2(D)}
        = 
        2\left\langle\fpartial{t}\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}\\
        &= - 2\underbar{\CB}^*[\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy};t] + 2(\underbar{q}_u(t,\dummy,\upp{\tau}{T-t,\dummy})\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy})_{L_2(D)}\\
        &\quad\,+ 2\left(\upp{\tau}{T-t,\dummy}-h(T-t,\dummy),\uhatppReverted{\tau}{t,\dummy}\right)_{L_2(D)},
    \end{split}
    \end{equation}
    where $\underbar{\CB}^*[\widehat{u},u;t]=\CB^\dagger[\widehat{u},u;T-t]$.
    For the second step recall that since $\uhatppReverted{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and since $\fpartial{t}\uhatppReverted{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$, the dual pairing between $H^{-1}(D)$ and $H_0^1(D)$ coincides with the $L_2(D)$ scalar product \cite[Chapter~5.9, Theorem 1(iii)]{evans2010partial}.
    For the third step, i.e., the weak solution property, note that $\uhatppReverted{\tau}{t,\dummy}$ is a valid test function since $\uhatppReverted{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    To upper bound the right-hand side of \eqref{eq:proof:lem:parabolic_uhatL2:1}, we consider each of the three terms separately.
    For the first term, by using the definition of the bilinear form $\CB$ as well as that by Assumption~\ref{asm:PDE_L_parabolicity} the PDE operator is uniformly parabolic and that by Assumption~\ref{asm:PDE_coefficients} the coefficients are in $L_\infty$, we can estimate with Cauchy-Schwarz and Young's inequality
    \begin{equation}        \label{eq:proof:lem:parabolic_uhatL2:21}
    \begin{split}
        &-\underbar{\CB}^*[\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy};t]
        =-\CB^\dagger[\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy};T-t]
        =-\CB[\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy};T-t]\\
        &\qquad\qquad\,=-\int_U \sum_{i,j=1}^d  a^{ij}(T-t,x) \fpartial{x_i} \uhatppReverted{\tau}{t,x} \fpartial{x_j} \uhatppReverted{\tau}{t,x}\\
        &\qquad\qquad\,\qquad\,+ \sum_{i=1}^d b^i(T-t,x) \fpartial{x_i} \uhatppReverted{\tau}{t,x} \uhatppReverted{\tau}{t,x} + c(T-t,x)\uhatppReverted{\tau}{t,x}\uhatppReverted{\tau}{t,x} \,dx\\
        &\qquad\qquad\,\leq\int_U -\nu \N{\nabla_x \uhatppReverted{\tau}{t,x}}^2+\frac{\nu}{2} \N{\nabla_x \uhatppReverted{\tau}{t,x}}^2\\
        &\qquad\qquad\,\qquad\,+ \frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}(\uhatppReverted{\tau}{t,x})^2 + \N{c}_{L_\infty(D_T)}(\uhatppReverted{\tau}{t,x})^2 \,dx\\
        &\qquad\qquad\,\leq -\frac{\nu}{2} \abs{\uhatppReverted{\tau}{t,\dummy}}^2_{H^1(D)} + \left(\frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}+\N{c}_{L_\infty(D_T)}\right)\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)},
    \end{split}
    \end{equation}
    where for the middle term in the next-to-last step we note that with Young's inequality it holds
    \begin{equation}
    \begin{split}
        \sum_{i=1}^d b^i(T-t,x) \fpartial{x_i} \uhatppReverted{\tau}{t,x} \uhatppReverted{\tau}{t,x}
        &\leq
        \sum_{i=1}^d \left(\frac{\nu}{2}(\fpartial{x_i} \uhatppReverted{\tau}{t,x})^2 + \frac{1}{2\nu} (b^i(T-t,x) \uhatppReverted{\tau}{t,x})^2\right)\\
        &\leq \frac{\nu}{2} \N{\nabla_x \uhatppReverted{\tau}{t,x}}^2 + \frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}(\uhatppReverted{\tau}{t,x})^2.
    \end{split}
    \end{equation}
    For the second term, by using that by Assumption~\ref{asm:PDE_nonlinearity_q_ubdd} $q_u$ is bounded, we can estimate
    \begin{equation}        \label{eq:proof:lem:parabolic_uhatL2:22}
    \begin{split}
        (\underbar{q}_u(t,\dummy,\upp{\tau}{T-t,\dummy})\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy})_{L_2(D)}
        &= (q_u(T-t,\dummy,\upp{\tau}{T-t,\dummy})\uhatppReverted{\tau}{t,\dummy},\uhatppReverted{\tau}{t,\dummy})_{L_2(D)}\\
        &\leq c_q\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}.
    \end{split}
    \end{equation}
    For the third and last term, by Cauchy-Schwarz and Young's inequality we upper bound
    \begin{equation}       \label{eq:proof:lem:parabolic_uhatL2:23}
    \begin{split}
        &\left(\upp{\tau}{T-t,\dummy}-h(T-t,\dummy),\uhatppReverted{\tau}{t,\dummy}\right)_{L_2(D)}
        \leq \N{\upp{\tau}{T-t,\dummy}-h(T-t,\dummy)}_{L_2(D)}\N{\uhatppReverted{\tau}{t,\dummy}}_{L_2(D)}\\
        &\qquad\qquad\,\leq \frac{1}{2}\left(\N{\upp{\tau}{T-t,\dummy}-h(T-t,\dummy)}^2_{L_2(D)}+\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\right).
    \end{split}
    \end{equation}

    Combining the bounds established in \eqref{eq:proof:lem:parabolic_uhatL2:21}--\eqref{eq:proof:lem:parabolic_uhatL2:23} and inserting them into \eqref{eq:proof:lem:parabolic_uhatL2:1}, we can continue bounding \eqref{eq:proof:lem:parabolic_uhatL2:1} as 
    \begin{equation}
        \label{eq:proof:lem:parabolic_uhatL2:3}
    \begin{split}
        &\fpartial{t}\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \abs{\uhatppReverted{\tau}{t,\dummy}}^2_{H^1(D)} \\
        &\qquad\,\leq \left(\frac{1}{\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}+2\N{c}_{L_\infty(D_T)}\right) \N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + 2c_q\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\\
        &\qquad\,\quad\,+ \left(\N{\upp{\tau}{T-t,\dummy}-h(T-t,\dummy)}^2_{L_2(D)}+\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\right)\\
        &\qquad\,\leq C\N{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \N{\upp{\tau}{T-t,\dummy}-h(T-t,\dummy)}^2_{L_2(D)}
    \end{split}
    \end{equation}
    for a constant $C=C(\CL,q)$.
    Defining $\widehat{N}_\tau(t) = \Nnormal{\uhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \int_0^t\absnormal{\uhatppReverted{\tau}{s,\dummy}}^2_{H^1(D)}\,ds$,    \eqref{eq:proof:lem:parabolic_uhatL2:3} translates to
    \begin{equation}           \label{eq:proof:lem:parabolic_wellposedness:NORM2_6}
        \fpartial{t} \widehat{N}_\tau(t)
        \leq C\widehat{N}_\tau(t) + \N{\upp{\tau}{T-t,\dummy}-h(T-t,\dummy)}_{L_2(D)}^2.
    \end{equation}
    We can now employ Grönwall's inequality 
    to obtain
    \begin{equation}
        \label{eq:proof:lem:parabolic_wellposedness:NORM2_8}
    \begin{split}
        \widehat{N}_\tau(t)
        &\leq \left(\widehat{N}_\tau(0)+\N{\up{\tau}-h}_{L_2(D_T)}^2\right)e^{Ct}
        \leq \left(\widehat{N}_\tau(0)+\N{\up{\tau}-h}_{L_2(D_T)}^2\right)e^{CT}.
    \end{split}
    \end{equation}
    Recalling that $\widehat{N}_\tau(0)=0$ by the initial condition in \eqref{eq:parabolicadjoint*Reversed2} shows
    \begin{equation}
        \label{eq:proof:adjointL2bounduniform}
    \begin{split}
        \N{\uhatp{\tau}}_{L_2([0,T],H^1(D))} + \N{\uhatp{\tau}}_{L_\infty([0,T],L_2(D))} 
        \leq 2\J{\tau}e^{Ct} \leq 2\J{0}e^{CT}
    \end{split}
    \end{equation}
    where the last step is a consequence of $\J{\tau}$ being monotonically non-increasing on the training time interval $I$ according to \Cref{lem:parabolictimeevolutionJt*}, which concludes the proof.
\end{proof}
\section{The Functional \texorpdfstring{$\Q{\tau} = (\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2(D_T)}$}{Q}}
\label{sec:FunctionalCQtau}

This section is dedicated to proving in \Cref{lem:CQ_Regulartiy} in \Cref{sec:RegularityCQtau}
a regularity bound for the functional
\begin{equation}
    \label{eq:CQ}
\begin{split}
    \Q{\tau}
    = (\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2(D_T)}
\end{split}
\end{equation}
of the form
\begin{equation}
    \absbig{\Q{\tau_2}-\Q{\tau_1}}
    \leq L_\CQ\int_{\tau_1}^{\tau_2} \alpha_\tau \,d\tau,
\end{equation}
which holds for all $0\leq\tau_1\leq\tau_2$,
for a constant $L_\CQ>0$ as specified after \eqref{eq:lem:CQ_Regulartiy}.
Here, the operator $T_{B_0}$ is defined in \eqref{eq:parabolicT_B} and the kernel $B_0=B(\mu_0)$ is as in \eqref{eq:parabolicB}.

In order to derive this bound, let us introduce for the functional~$\Q{\tau}$ defined in \eqref{eq:CQ} and the PDE system~\eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*}
the second-level adjoint system with variables $(\vhatp{},\whatp{})$ given by
\begin{alignat}{2}
    \label{eq:paraboliccoupledadjoint1}
\begin{aligned}
    -\fpartial{t}\vhatp{\tau} + \CL^\dagger\vhatp{\tau} - q_u(\up{\tau})\vhatp{\tau}
    &= \whatp{\tau} + q_{uu}(\up{\tau})\uhatp{\tau}\whatp{\tau}
    \qquad&&\text{in }
    D_T, \\
    \vhatp{\tau}
    &= 0
    \qquad&&\text{on }
    [0,T]\times\partial D, \\
    \vhatp{\tau}
    &= 0
    \qquad&&\text{on }
    \{T\}\times D,
\end{aligned}
\end{alignat}
and
\begin{alignat}{2}
    \label{eq:paraboliccoupledadjoint2}
\begin{aligned}
    \fpartial{t}\whatp{\tau} + \CL\whatp{\tau} - q_u(\up{\tau})\whatp{\tau}
    &= 2T_{B_0}\uhatp{\tau}
    \qquad&&\text{in }
    D_T, \\
    \whatp{\tau}
    &= 0
    \qquad&&\text{on }
    [0,T]\times\partial D, \\
    \whatp{\tau}
    &= 0
    \qquad&&\text{on }
    \{0\}\times D.
\end{aligned}
\end{alignat}

Before discussing the main statement of this section, \Cref{lem:CQ_Regulartiy},
we establish in \Cref{sec:parabolic_whatLinfty,sec:parabolic_vhatL2} uniform (in the training time~$\tau$) estimates for several norms of the second-level adjoints $\whatp{\tau}$ in \eqref{eq:paraboliccoupledadjoint1} and $\vhatp{\tau}$ in \eqref{eq:paraboliccoupledadjoint2}, respectively.

\subsection{Boundedness of the Second-Level Adjoint \texorpdfstring{$\whatp{\tau}$}{of the Adjoint} Uniformly in the Training Time}
\label{sec:parabolic_whatLinfty}

We show well-posedness of the second-level adjoint $\whatp{\tau}$ in \eqref{eq:paraboliccoupledadjoint2} and derive uniform (in the training time $\tau$) bounds on its $L_\infty(D_T)$-, $L_2(D_T)$- and $L_\infty([0,T],L_2(D))$-norms.
The uniformity of the bound in time and space is a consequence of the right-hand side of \eqref{eq:paraboliccoupledadjoint2} being in $L_\infty$ as of \Cref{lem:TBboundednessLinfty},
while the uniformity in the training time $\tau$ follows from the uniformity of the bound on the adjoint~$\uhatp{\tau}$ as of \Cref{lem:parabolic_uhatL2}.
\begin{lemma}
    \label{lem:parabolic_whatLinfty}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in I}\in \CC\left(I,\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness} on the training time interval $I$.
    Then the linear parabolic PDE~\eqref{eq:paraboliccoupledadjoint2} admits for every $\tau\in I$ a unique weak solution~$\whatp{\tau}$
    in a sense analogous to \Cref{def:weak_sol_adjoint} with right-hand side $2T_{B_0}\uhatp{\tau}$,
    which satisfies $\partial_t\whatpp{\tau}{t,\dummy} \in L_2(D)$
    for a.e.\@ $t\in[0,T]$.

    In addition, the adjoint~$\whatp{\tau}$ in \eqref{eq:paraboliccoupledadjoint2} is uniformly (in the training time $\tau$) bounded in $L_\infty(D_T)$ on that interval $I$, i.e., it holds
    \begin{equation}
        \sup_{\tau\in I}\N{\whatp{\tau}}_{L_\infty(D_T)}
        \leq C^{\widehat{w}}_\infty
    \end{equation}
    for a constant $C^{\widehat{w}}_\infty=C^{\widehat{w}}_\infty(T,\CL,q,C^B_2,C^{\widehat{u}})$.
    Furthermore, the adjoint~$\whatp{\tau}$ is uniformly (in the training time $\tau$) bounded in $L_2(D_T)$ and $L_\infty([0,T],L_2(D))$ on that interval $I$,
    i.e., it holds
    \begin{equation}
        \sup_{\tau\in I}\left(\N{\whatp{\tau}}_{L_2(D_T)} + \N{\whatp{\tau}}_{L_\infty([0,T],L_2(D))}\right)\leq C^{\widehat{w}}
    \end{equation}
    for a constant $C^{\widehat{w}}=C^{\widehat{w}}(D,C^{\widehat{w}}_\infty)$.
\end{lemma}

\begin{proof}
    \textit{Step 1a: Existence of a unique weak solution $\whatp{\tau}$.} 
    Existence and uniqueness of a weak solution to \eqref{eq:paraboliccoupledadjoint2} in a sense analogous to \Cref{def:weak_sol_adjoint} follow from classical results,
    see, e.g., \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial}, as $2T_{B_0}\uhatp{\tau}\in L_2(D_T)$ according to \Cref{lem:parabolicTB,lem:parabolic_uhatL2}.

    The remainder of the statement follows from an application of Morrey's inequality after leveraging \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} for any $p\geq2$.

    \textit{Step 1b: Existence of a unique solution $\whatp{\tau}\in W^{1,2}_{p}(D_T)$ for any $p\geq 2$.}
    We first notice that, in the notation of \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear}, the coefficients~$a_{ij}(t,x)=a^{ij}(t,x)$ of the linear PDE operator of the parabolic PDE~\eqref{eq:paraboliccoupledadjoint2} are bounded continuous functions in $D_T$ for all $i,j=1,\dots,d$,
    while the coefficients~$a_i(t,x)=b^i(t,x)-\sum_{j=1}^d\fpartial{x_j}a^{ji}(t,x)$ and $a(t,x)=c(t,x) - \sum_{i=1}^d \fpartial{x_i}b^i(t,x) - q_u(t,x,u(t,x))$ have finite norms $\N{a_i}_{L_r(D_T)}$ and $\N{a}_{L_s(D_T)}$ for any $r,s>0$.
    This is due to the uniform boundedness of the coefficients per Assumptions~\ref{asm:PDE_coefficients} and \ref{asm:PDE_nonlinearity_q_ubdd} combined with the boundedness of the domain per Assumption~\ref{asm:Dbdd}, see the subsequent computations with $T'=0$ and $\Delta T'=T$.
    Moreover, since it hold
    $\Nnormal{a_i}_{L_r(D_{T',T'+\Delta T'})} \leq \big(\Nnormal{b^i}_{L_\infty(D_T)}+\sum_{j=1}^d\Nnormal{\fpartial{x_j}a^{ji}}_{L_\infty(D_T)}\big)(\Delta T'\vol{D})^{1/r}$
    for all $i=1,\dots,d$ and
    $\Nnormal{a}_{L_s(D_{T',T'+\Delta T'})}\leq \big(\Nnormal{c}_{L_\infty(D_T)}+\sum_{i=1}^d\Nnormal{\fpartial{x_i}b^{i}}_{L_\infty(D_T)} + c_q\big)(\Delta T'\vol{D})^{1/s}$, 
    $\N{a_i}_{L_r(D_{T',T'+\Delta T'})}$ and $\N{a}_{L_s(D_{T',T'+\Delta T'})}$ tend to zero as $\Delta T'\rightarrow0$.
    Furthermore, $\partial D$ is sufficiently smooth as of Assumption~\ref{asm:D}.
    The right-hand side $f=2T_{B_0}\uhatp{\tau}\in L_p(D_T)$ for any $p\geq2$ due to being uniformly (in the training time $\tau$) bounded in $L_\infty$ as of \Cref{lem:TBboundednessLinfty}, \Cref{lem:parabolic_uhatL2} and the domain $D_T$ being bounded as of Assumption~\ref{asm:Dbdd},
    which ensures
    \begin{equation}
        \label{eq:proof:w_uniformbdd_TBubound}
    \begin{split}
        \N{2T_{B_0}\uhatp{\tau}}_{L_p(D_T)}
        &= \left(\int_0^T\!\!\!\int_D \absbig{[2T_{B}\uhatp{\tau}](t,x)}^p\,dxdt\right)^{1/p}\\
        &\leq 2C^{T_{B_0}}_\infty\N{\uhatp{\tau}}_{L_2(D_T)}(T\vol{D})^{1/p}
        \leq2C^{T_{B_0}}_\infty C^{\widehat{u}}(T\vol{D})^{1/p}.
    \end{split}
    \end{equation}
    Moreover, both the initial and the boundary conditions $\phi=0\in W^{2-2/p}_p(D)$ and $\Phi=0\in W^{1-1/(2p),2-1/p}_p(\partial D_T)$ trivially satisfy the compatibility condition $\phi|_{\partial D}=\Phi|_{t=0}$.
    Thus, \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} ensures  that $\whatp{\tau}\in W^{1,2}_{p}(D_T)$ obeys the bound
    \begin{equation}
        \label{eq:proof:w_uniformbdd_bound}
    \begin{split}
        \N{\whatp{\tau}}_{W^{1,2}_{p}(D_T)}
        &\leq C\N{2T_{B_0}\uhatp{\tau}}_{L_p(D_T)}
    \end{split}
    \end{equation}
    for a constant $C=C(T,\CL,q)$.
    With the uniform (in the training time $\tau$) bound \eqref{eq:proof:w_uniformbdd_TBubound} at our disposal,
    $\N{\whatp{\tau}}_{W^{1,2}_{p}(D_T)}$ can be controlled uniformly (in the training time $\tau$) as
    \begin{equation}
        \label{eq:proof:w_uniformbdd_bound_ctd}
    \begin{split}
        \N{\whatp{\tau}}_{W^{1,2}_{p}(D_T)}
        &\leq 2CC^{T_{B}}_\infty C^{\widehat{u}}(T\vol{D})^{1/p}.
    \end{split}
    \end{equation}
    This in particular proves that $\whatp{\tau}\in W^{1,2}_{2}(D_T)$ obeying \eqref{eq:proof:w_uniformbdd_bound_ctd} with $p=2$, concluding the first part of the statement since $\partial_t\whatpp{\tau}{t,\dummy} \in L_2(D)$ has to necessarily hold for a.e.\@ $t\in[0,T]$.

    \textit{Step 2a: Boundedness of the $L_\infty(D_T)$ norm of $\whatp{\tau}$.}
    With the conditions of \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} being fulfilled for any $p\geq2$ as we verified before, they are in particular fulfilled for $p>d+1$.
    Since we have for such $p$ the continuous embedding $W^{1,2}_{p}(D_{T})\hookrightarrow W^{1,1}_{p}(D_{T})\hookrightarrow L_{\infty}(\overbar{D}_T)$ by Morrey's inequality~\cite[Theorem 9.12]{brezis2011functional}, we have the first inequality in
    \begin{equation}
    \begin{split}
        \N{\whatp{\tau}}_{L_\infty(D_T)}
        &\leq c(d,p)\N{\whatp{\tau}}_{W^{1,2}_{p}(D_T)}
        \leq 2c(d,p)CC^{T_{B_0}}_\infty C^{\widehat{u}}(T\vol{D})^{1/p},
    \end{split}
    \end{equation}
    with the second one being due to \eqref{eq:proof:w_uniformbdd_bound_ctd}.
    As the right-hand side is bounded uniformly (in the training time $\tau$),
    and since $\whatp{\tau}\in W^{1,2}_{p}(D_{T})$ has a continuous version~\cite[Chapter~5.6, Theorem~5]{evans2010partial},
    this concludes the second part of the statement.

    \textit{Step 2b: Boundedness of the $L_2(D_T)$ and $L_\infty([0,T],L_2(D))$ norms of $\whatp{\tau}$.}
    The last part of the statement follows since
    $\N{\whatp{\tau}}_{L_\infty([0,T],L_2(D))}\leq \sqrt{\vol{D}}\N{\whatp{\tau}}_{L_\infty(D_T)}$ and $\N{\whatp{\tau}}_{L_2(D_T)}\leq \sqrt{T\vol{D}}\N{\whatp{\tau}}_{L_\infty(D_T)}$.
\end{proof}


\subsection{Boundedness of the Second-Level Adjoint \texorpdfstring{$\vhatp{\tau}$}{of the Solution} Uniformly in the Training Time}
\label{sec:parabolic_vhatL2}

We now show well-posedness of the second-level adjoint $\vhatp{\tau}$ in \eqref{eq:paraboliccoupledadjoint1} and derive uniform (in the training time $\tau$) bounds on its $L_2([0,T],H^1(D))$- and $L_\infty([0,T],L_2(D))$-norms.
\begin{lemma}
    \label{lem:parabolic_vhatL2}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in I}\in \CC\left(I,\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness}
    on the training time interval $I$.
    Then the linear parabolic PDE~\eqref{eq:paraboliccoupledadjoint1} admits for every $\tau\in I$ a unique weak solution~$\vhatp{\tau}$
    in a sense analogous to \Cref{def:weak_sol_adjoint} with right-hand side $\whatp{\tau} + q_{uu}(\up{\tau})\uhatp{\tau}\whatp{\tau}$,
    which satisfies $\partial_t\vhatpp{\tau}{t,\dummy} \in L_2(D)$
    for a.e.\@ $t\in[0,T]$.

    In addition, the adjoint~$\vhatp{\tau}$ in \eqref{eq:paraboliccoupledadjoint1} is uniformly (in the training time $\tau$) bounded in $L_2([0,T],H_1(D))$ and $L_\infty([0,T],L_2(D))$ on that interval $I$,
    i.e., it holds
    \begin{equation}
        \sup_{\tau\in I}\left(\N{\vhatp{\tau}}_{L_2([0,T],H^1(D))} + \N{\vhatp{\tau}}_{L_\infty([0,T],L_2(D))} \right)\leq C^{\widehat{v}}
    \end{equation}
    for a constant $C^{\widehat{v}}=C^{\widehat{v}}(T,\CL,q,C^{\widehat{u}},C^{\widehat{w}},C^{\widehat{w}}_\infty)$.
\end{lemma}
\begin{proof}
    Let us first reverse the adjoint parabolic backward PDE \eqref{eq:paraboliccoupledadjoint1} in time to obtain with a time transformation
    for $\vhatpReverted{\tau}=\vhatppReverted{\tau}{t,x}=\vhatpp{\tau}{T-t,x}$ the parabolic forward PDE
    \begin{alignat}{2}
    \label{eq:paraboliccoupledadjoint1*Reversed}
    \begin{aligned}
        \fpartial{t}\vhatpReverted{\tau} + \underbar{\CL}^*\vhatpReverted{\tau} - \underbar{q}_u(\upp{\tau}{T-\dummy,\dummy})\vhatpReverted{\tau}
        &= \whatpp{\tau}{T-\dummy,\dummy}+ \underbar{q}_{uu}(\upp{\tau}{T-\dummy,\dummy})\cdot\\
        &\qquad\qquad\quad\,\cdot\uhatpp{\tau}{T-\dummy,\dummy}\whatpp{\tau}{T-\dummy,\dummy}
        \quad&&\text{in }
        D_T, \\
        \vhatpReverted{\tau}
        &= 0
        \quad&&\text{on }
        [0,T]\times\partial D, \\
        \vhatpReverted{\tau}
        &= 0
        \quad&&\text{on }
        \{0\}\times D,
    \end{aligned}
    \end{alignat}
    where $\underbar{\CL}^*=\underbar{\CL}^*(t,x)=\CL^\dagger(T-t,x)$ and $\underbar{q}=\underbar{q}(t,x,u)=\underbar{q}(T-t,x,u)$.

    \textit{Step 1: Existence of a unique solution $\vhatp{\tau}$.}
    Existence, uniqueness and regulartiy of a weak solution to \eqref{eq:paraboliccoupledadjoint1} in a sense analogous to \Cref{def:weak_sol_adjoint} follow analogously to \textit{Steps 1a} and \textit{b} of the proof of \Cref{lem:parabolic_whatLinfty} from classical results, namely \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial} as well as \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} for $p=2$.
    Herefore note that $\whatp{\tau} + q_{uu}(\up{\tau})\uhatp{\tau}\whatp{\tau}\in L_2(D_T)$ by combining \Cref{lem:parabolic_whatLinfty,lem:parabolic_uhatL2} with Assumption~\ref{asm:PDE_nonlinearity_q_uubdd}. 

    \textit{Step 2: Boundedness of the $L_2([0,T],H^1(D))$ and $L_\infty([0,T],L_2(D))$ norms of $\vhatp{\tau}$.}
    Let us now estimate $\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} = \int_D (\vhatppReverted{\tau}{t,x})^2 \,dx$.
    With chain rule and by using that $\vhatpReverted{\tau}$ is a weak solution to the time-reversed adjoint PDE~\eqref{eq:paraboliccoupledadjoint1*Reversed} we have 
    \begin{equation}
        \label{eq:proof:lem:parabolic_vhatL2:1}
    \begin{split}
        &\fpartial{t}\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}
        =2\left(\vhatppReverted{\tau}{t,\dummy} ,\fpartial{t}\vhatppReverted{\tau}{t,\dummy}\right)_{L_2(D)}
        = 
        2\left\langle\fpartial{t}\vhatppReverted{\tau}{t,\dummy},\vhatppReverted{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}\\
        &\quad\,= - 2\underbar{\CB}^*[\vhatppReverted{\tau}{t,\dummy},\vhatppReverted{\tau}{t,\dummy};t] + 2(\underbar{q}_u(t,\dummy,\upp{\tau}{T\!-\!t,\dummy})\vhatppReverted{\tau}{t,\dummy},\vhatppReverted{\tau}{t,\dummy})_{L_2(D)}\\
        &\quad\,\quad\,+ 2\left(\whatpp{\tau}{T\!-\!t,\dummy} + \underbar{q}_{uu}(t,\dummy,\upp{\tau}{T\!-\!t,\dummy})\uhatpp{\tau}{T\!-\!t,\dummy}\whatpp{\tau}{T\!-\!t,\dummy},\vhatppReverted{\tau}{t,\dummy}\right)_{L_2(D)},
    \end{split}
    \end{equation}
    where $\underbar{\CB}^*[\widehat{u},u;t]=\CB^\dagger[\widehat{u},u;T-t]$ and 
    where we recall for the second step that since $\vhatppReverted{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and since $\fpartial{t}\vhatppReverted{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$, the dual pairing between $H^{-1}(D)$ and $H_0^1(D)$ coincides with the $L_2(D)$ scalar product \cite[Chapter~5.9, Theorem 1(iii)]{evans2010partial}.
    For the third step, i.e., the weak solution property, note that $\vhatppReverted{\tau}{t,\dummy}$ is a valid test function since $\vhatppReverted{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    To upper bound the right-hand side of \eqref{eq:proof:lem:parabolic_vhatL2:1}, we consider again each of the three terms separately.
    Analogously to \eqref{eq:proof:lem:parabolic_uhatL2:21} we have for the first term
    \begin{equation}
        \label{eq:proof:lem:parabolic_vhatL2:21}
    \begin{split}
        -\underbar{\CB}^*[\vhatppReverted{\tau}{t,\dummy},\vhatppReverted{\tau}{t,\dummy};t]
        \!\leq \!-\frac{\nu}{2} \abs{\vhatppReverted{\tau}{t,\dummy}}^2_{H^1(D)} \!+\! \left(\frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}\!+\!\N{c}_{L_\infty(D_T)}\!\!\right)\!\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)},
    \end{split}
    \end{equation}
    where we used the definition of the bilinear form $\CB$ as well as that by Assumption~\ref{asm:PDE_L_parabolicity} the PDE operator is uniformly parabolic and that by Assumption~\ref{asm:PDE_coefficients} the coefficients are in $L_\infty$.
    For the second term we have as in \eqref{eq:proof:lem:parabolic_uhatL2:22}  with Assumption~\ref{asm:PDE_nonlinearity_q_ubdd} that
    \begin{equation}
        \label{eq:proof:lem:parabolic_vhatL2:22}
    \begin{split}
        (\underbar{q}_u(t,\dummy,\upp{\tau}{T-t,\dummy})\vhatppReverted{\tau}{t,\dummy},\vhatppReverted{\tau}{t,\dummy})_{L_2(D)}
        &\leq c_q\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}.
    \end{split}
    \end{equation}
    For the third and last term, using Assumption~\ref{asm:PDE_nonlinearity_q_uubdd}, by Cauchy-Schwarz, Hölder's and Young's inequality we upper bound
    \begin{equation}       \label{eq:proof:lem:parabolic_vhatL2:23}
    \begin{split}
        &\left(\whatpp{\tau}{T\!-\!t,\dummy} + \underbar{q}_{uu}(T\!-\!t,\dummy,\upp{\tau}{T\!-\!t,\dummy})\uhatpp{\tau}{T\!-\!t,\dummy}\whatpp{\tau}{T\!-\!t,\dummy},\vhatppReverted{\tau}{t,\dummy}\right)_{L_2(D)}\\
        &\quad\,\leq \left(\N{\whatpp{\tau}{T\!-\!t,\dummy}}_{L_2(D)} + c_q' \N{\uhatpp{\tau}{T\!-\!t,\dummy}\whatpp{\tau}{T\!-\!t,\dummy}}_{L_2(D)}\right)\N{\vhatppReverted{\tau}{t,\dummy}}_{L_2(D)} \\
        &\quad\,\leq \left(\N{\whatpp{\tau}{T\!-\!t,\dummy}}_{L_2(D)} + c_q' \N{\uhatpp{\tau}{T\!-\!t,\dummy}}_{L_2(D)}\N{\whatpp{\tau}{T\!-\!t,\dummy}}_{L_\infty(D)}\right)\N{\vhatppReverted{\tau}{t,\dummy}}_{L_2(D)} \\
        &\quad\,\leq \frac{1}{2}\left(\left(\N{\whatpp{\tau}{T\!-\!t,\dummy}}_{L_2(D)} \!+\! c_q' \N{\uhatpp{\tau}{T\!-\!t,\dummy}}_{L_2(D)}\N{\whatpp{\tau}{T\!-\!t,\dummy}}_{L_\infty(D)}\right)^2\!+\!\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\right)\\
        &\quad\,\leq \frac{1}{2}\left(\left(C^{\widehat{w}} + c_q' C^{\widehat{u}}C^{\widehat{w}}_\infty\right)^2+\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\right),
    \end{split}
    \end{equation}
    where we employed \Cref{lem:parabolic_uhatL2} to bound the $L_2$ norm of $\uhatp{\tau}$ and \Cref{lem:parabolic_whatLinfty} to control the $L_2$ and $L_\infty$ norms of $\whatp{\tau}$.
    Combining the bounds established in \eqref{eq:proof:lem:parabolic_vhatL2:21}--\eqref{eq:proof:lem:parabolic_vhatL2:23} and inserting them into \eqref{eq:proof:lem:parabolic_vhatL2:1}, we can continue bounding \eqref{eq:proof:lem:parabolic_vhatL2:1} as
    \begin{equation}
        \label{eq:proof:lem:parabolic_vhatL2:3}
    \begin{split}
        &\fpartial{t}\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \abs{\vhatppReverted{\tau}{t,\dummy}}^2_{H^1(D)} 
        \leq \left(\frac{1}{\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}+2\N{c}_{L_\infty(D_T)}\right) \N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\\
        &\qquad\, \quad\,+ 2c_q\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \left(\left(C^{\widehat{w}} + c_q' C^{\widehat{u}}C^{\widehat{w}}_\infty\right)^2+\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)}\right)\\
        &\qquad\, \leq C\N{\vhatppReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \left(C^{\widehat{w}} + c_q' C^{\widehat{u}}C^{\widehat{w}}_\infty\right)^2
    \end{split}
    \end{equation}
    for a constant $C=C(\CL,q)$.
    Recalling that $\vhatppReverted{\tau}{0,\dummy}=0$ by the initial condition in \eqref{eq:paraboliccoupledadjoint1*Reversed}, an application of Grönwall's inequality shows
    \begin{equation}
    \begin{split}
        \N{\vhatp{\tau}}_{L_2([0,T],H^1(D))} + \N{\vhatp{\tau}}_{L_\infty([0,T],L_2(D))}
        &\leq \left(C^{\widehat{w}} + c_q' C^{\widehat{u}}C^{\widehat{w}}_\infty\right)^2Te^{CT},
    \end{split}
    \end{equation}
    which concludes the proof.
\end{proof}
\subsection{Regularity Bound for the Functional \texorpdfstring{$\Q{\tau}$}{Q} in Terms of the Learning Rate}
\label{sec:RegularityCQtau}

We now have all technical tools at hand to 
derive a regularity bound for the functional~$\Q{\tau}$ in terms of the learning rate~$\alpha_\tau$,
which is the main result of this section.

\begin{proposition}
    \label{lem:CQ_Regulartiy}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in I}\in \CC\left(I,\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness}
    on the training time interval $I$.
    Then the functional~$\Q{\tau}$ as defined in \eqref{eq:CQ} obeys the regularity bound
    \begin{equation}
        \label{eq:lem:CQ_Regulartiy}
        \absbig{\Q{\tau_2}-\Q{\tau_1}}
        \leq L_\CQ\int_{\tau_1}^{\tau_2} \alpha_\tau \,d\tau
    \end{equation}
    for all $\tau_1,\tau_2\in I$ with $0\leq\tau_1\leq\tau_2$ for a constant $L_\CQ=L_\CQ(C^{\widehat{u}},C^{\widehat{v}},C^B_2)$.
\end{proposition}

\begin{proof}
    By the fundamental theorem of calculus, it holds for all $0\leq\tau_1\leq\tau_2$ that
    \begin{equation}
        \label{eq:proof:Regularity:B1}
    \begin{split}
        \Q{\tau_2}-\Q{\tau_1}
        &= \int_{\tau_1}^{\tau_2} \fd{\tau} \Q{\tau}\,d\tau
    \end{split}
    \end{equation}
    and it thus remains to compute and estimate $\fd{\tau} \Q{\tau}$.
    Recalling that $\Q{\tau} = (\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2(D_T)}$ as defined in \eqref{eq:CQ}, we obtain for its training time derivative by chain rule and by using that $\whatp{\tau}$ and $\vhatp{\tau}$ are weak solutions (in a sense analogous to \Cref{def:weak_sol_adjoint}) to the second-level adjoint system consisting of the PDEs \eqref{eq:paraboliccoupledadjoint2} and \eqref{eq:paraboliccoupledadjoint1} that
    \begin{equation}        \label{eq:proof:Regularity:B2}
    \begin{split}
        \fd{\tau} \Q{\tau}
        &= \fd{\tau} \int_0^T\!\!\!\int_D \uhatpp{\tau}{t,x}[T_{B_0}\uhatp{\tau}](t,x)\,dxdt \\
        &= \int_0^T\!\!\!\int_D 2[T_{B_0}\uhatp{\tau}](t,x)\fd{\tau}\uhatpp{\tau}{t,x}\,dxdt
        = \int_0^T\left(2[T_{B_0}\uhatp{\tau}](t,\dummy),\fd{\tau}\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt\\
        &=\int_0^T\left\langle\fpartial{t}\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB\left[\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        \\
        &=\int_0^T\left\langle\fpartial{t}\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB\left[\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        \\
        &\quad\,+\int_0^T\left\langle-\fpartial{t}\vhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB^\dagger\left[\vhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\vhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right)_{L_2(D)}\\
        & \qquad\quad\, -\left(\whatpp{\tau}{t,\dummy} + q_{uu}(t,\dummy,\upp{\tau}{t,\dummy})\uhatpp{\tau}{t,\dummy}\whatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right)_{L_2(D)} dt.
    \end{split}
    \end{equation}
    For the weak solution property in the third line of \eqref{eq:proof:Regularity:B2}, we note that $\fd{\tau}\uhatp{\tau}$, the weak solution to the linear parabolic PDE
    \begin{alignat}{2}
        \label{eq:parabolicpII*aux}
    \begin{aligned}
        -\fpartial{t}\fd{\tau}\uhatp{\tau} + \CL^\dagger\fd{\tau}\uhatp{\tau} - q_u(\up{\tau})\fd{\tau}\uhatp{\tau}
        &= \fd{\tau}\up{\tau} + q_{uu}(\up{\tau})\uhatp{\tau}\fd{\tau}\up{\tau}
        \qquad&&\text{in }
        D_T, \\
        \fd{\tau}\uhatp{\tau}
        &= 0
        \qquad&&\text{on }
        [0,T]\times\partial D, \\
        \fd{\tau}\uhatp{\tau}
        &= 0
        \qquad&&\text{on }
        \{T\}\times D,
    \end{aligned}
    \end{alignat}
    which is obtained by taking in \eqref{eq:parabolicPDE*} the derivative w.r.t.\@ the training time $\tau$,
    can be used as a test function in the weak formulation of \eqref{eq:parabolicadjoint*}, see \Cref{def:weak_sol_adjoint}, since $\fd{\tau}\uhatpp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    Existence and uniqueness of a weak solution to \eqref{eq:parabolicpII*aux} in a sense analogous to \Cref{def:weak_sol_adjoint} follow from classical results,
    see, e.g., \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial}, as $\fd{\tau}\up{\tau} + q_{uu}(\up{\tau})\uhatp{\tau}\fd{\tau}\up{\tau}\in L_2(D_T)$.
    That the right-hand side is indeed in $L_2$ follows directly after noting that the PDE~\eqref{eq:parabolicpI*aux} for $\fd{\tau}\up{\tau}$ has a structure identical to \eqref{eq:paraboliccoupledadjoint2} with right-hand side $\fd{\tau}g^*_\tau = - \alpha_\tau T_{B_0}\uhatp{\tau}$, i.e., the same up to a constant factor.
    Following the lines of the proof of \Cref{lem:parabolic_whatLinfty} this ensures that $\fd{\tau}\up{\tau}\in L_\infty(D_T)$.
    For the weak solution property in the fifth step of \eqref{eq:proof:Regularity:B2}, we note that $\fd{\tau}\up{\tau}$, the weak solution to the linear parabolic PDE \eqref{eq:parabolicpI*aux} can be used as a test function in the weak formulation of \eqref{eq:paraboliccoupledadjoint1}, since $\fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$, see the discussion after \eqref{eq:parabolicpI*aux}.

    We now perform partial integration.
    For this purpose, first recall that 
    since $\fd{\tau}\uhatpp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and since $\fpartial{t}\whatpp{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$ according to \Cref{lem:parabolic_whatLinfty}, the dual pairing between $H^{-1}(D)$ and $H_0^1(D)$ coincides with the $L_2(D)$ scalar product \cite[Chapter~5.9, Theorem 1(iii)]{evans2010partial}.
    This allows to compute with partial integration, which applies since $\whatpp{\tau}{t,\dummy}, \fd{\tau}\uhatpp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$, that
    \begin{equation}       \label{eq:proof:Regularity:B2_a1}
    \begin{split}        &\int_0^T\left\langle\fpartial{t}\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}dt\\
        &\qquad\,= \int_0^T\left(\fpartial{t}\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        = \int_0^T\!\!\!\int_D \left(\fpartial{t}\whatpp{\tau}{t,x}\right)\fd{\tau}\uhatpp{\tau}{t,x} \, dxdt\\
        &\qquad\,= \int_D \underbrace{\whatpp{\tau}{t,x} \fd{\tau}\uhatpp{\tau}{t,x}\Big|_0^T}_{\substack{=0\\\text{since } \whatp{\tau}=0 \text{ on }\{0\}\times D \text{ and}\\\text{since }\fd{\tau}\uhatp{\tau}=0 \text{ on } \{T\}\times D}} \, dx -\int_0^T\!\!\!\int_D \whatpp{\tau}{t,x}\fpartial{t}\fd{\tau}\uhatpp{\tau}{t,x} \, dxdt \\
        &\qquad\,=-\int_0^T\!\!\!\int_D  \left(\fpartial{t}\fd{\tau}\uhatpp{\tau}{t,x}\right)\whatpp{\tau}{t,x} \, dxdt
        = -\int_0^T\left(\fpartial{t}\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)}\,dt \\
        &\qquad\,= -\int_0^T\left\langle\fpartial{t}\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}dt,
    \end{split}
    \end{equation}
    where the last step holds again since now $\whatpp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and $\fpartial{t}\fd{\tau}\uhatp{\tau}$ is in $L_2(D)$ for a.e.\@ $t\in[0,T]$, which follows again analogously to \Cref{lem:parabolic_vhatL2} for the PDE \eqref{eq:parabolicpII*aux} due to its with \eqref{eq:paraboliccoupledadjoint1} identical structure and $\fd{\tau}\up{\tau} + q_{uu}(\up{\tau})\uhatp{\tau}\fd{\tau}\up{\tau}\in L_2(D_T)$.
    Similarly, since
    $\fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ (see the discussion after \eqref{eq:parabolicpI*aux}) and since $\fpartial{t}\vhatpp{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$ according to \Cref{lem:parabolic_vhatL2}, we may compute analogously to \eqref{eq:parabolicpI*aux_T51} that
    \begin{equation}
        \label{eq:proof:Regularity:B2_a2}
    \begin{split}
        &\int_0^T\left\langle\fpartial{t}\vhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}dt
        = -\int_0^T\left\langle\fpartial{t}\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}dt
    \end{split}
    \end{equation}
    since $\vhatpp{\tau}{t,\dummy}, \fd{\tau}\upp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    Secondly, by definition of the adjoint bilinear form~$\CB^\dagger$ (see \Cref{def:weak_sol_adjoint}) it hold
    $\CB\left[\whatpp{\tau}{t,\dummy},\fd{\tau}\uhatpp{\tau}{t,\dummy};t\right]= \CB^\dagger\left[\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy};t\right]$ and $\CB^\dagger\left[\vhatpp{\tau}{t,\dummy},\fd{\tau}\upp{\tau}{t,\dummy};t\right] = \CB\left[\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy};t\right] $
    for a.e.\@ $t\in[0,T]$ since $\whatpp{\tau}{t,\dummy}$, $\fd{\tau}\uhatpp{\tau}{t,\dummy}$, $\vhatpp{\tau}{t,\dummy}$, $\fd{\tau}\upp{\tau}{t,\dummy} \in H_0^1(D)$. 
    With
    \eqref{eq:proof:Regularity:B2_a1}, \eqref{eq:proof:Regularity:B2_a2} and the former,
    we can continue \eqref{eq:proof:Regularity:B2} as
    \begin{equation}
    \begin{split}
 \label{eq:proof:Regularity:B3}
        \fd{\tau} \Q{\tau}
        &=\int_0^T\left\langle-\fpartial{t}\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB^\dagger\left[\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        \\
        &\quad\,+\int_0^T\left\langle\fpartial{t}\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB\left[\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\quad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy}\right)_{L_2(D)}\\
        & \qquad\quad\, -\left(\fd{\tau}\upp{\tau}{t,\dummy} + q_{uu}(t,\dummy,\upp{\tau}{t,\dummy})\uhatpp{\tau}{t,\dummy}\fd{\tau}\upp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt.
    \end{split}
    \end{equation}%

    A simple reordering of the terms for later convenience gives
    \begin{equation}
        \label{eq:proof:Regularity:B4}
    \begin{split}
        \fd{\tau} \Q{\tau}
        &=\int_0^T\left\langle-\fpartial{t}\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB^\dagger\left[\fd{\tau}\uhatpp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\fd{\tau}\uhatpp{\tau}{t,\dummy} + q_{uu}(t,\dummy,\upp{\tau}{t,\dummy})\uhatpp{\tau}{t,\dummy}\fd{\tau}\upp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        \\
        &\quad\,+\int_0^T\left\langle\fpartial{t}\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB\left[\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy};t\right] \\
        & \qquad\, -\left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\fd{\tau}\upp{\tau}{t,\dummy},\vhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt\\
        &\quad\,- \int_0^T\left(\fd{\tau}\upp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt.
    \end{split}
    \end{equation}

    Leveraging now in the first and second line of \eqref{eq:proof:Regularity:B4} the weak formulation of \eqref{eq:parabolicpII*aux}, with test function $\whatpp{\tau}{t,\dummy}$ (suitable due to \Cref{lem:parabolic_whatLinfty}),
    and in the third and fourth line the weak formulation of \eqref{eq:parabolicpI*aux}, with test function $\vhatpp{\tau}{t,\dummy}$ (suitable due to \Cref{lem:parabolic_vhatL2}),
    we arrive at
    \begin{equation}
        \label{eq:proof:Regularity:B5}
    \begin{split}
        \fd{\tau} \Q{\tau}
        &=\int_0^T\left(\fd{\tau}\upp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)}dt
        + \int_0^T\left(\fd{\tau}g^*_\tau(t,\dummy),\vhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt\\
        &\quad\,- \int_0^T\left(\fd{\tau}\upp{\tau}{t,\dummy},\whatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt\\
        &=\int_0^T\left(\fd{\tau}g^*_\tau(t,\dummy),\vhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt
        = \left(\fd{\tau}g^*_\tau,\vhatp{\tau}\right)_{L_2(D_T)}.
    \end{split}
    \end{equation}
    With the expression derived in \eqref{eq:proof:Regularity:B5} for $\fd{\tau}\Q{\tau}$, we can now obtain a bound on \eqref{eq:proof:Regularity:B1}. 
    Recalling that $\fd{\tau}g^*_\tau = - \alpha_\tau T_{B_0}\uhatp{\tau}$ by taking the training time derivative of $g_{\tau}$ as defined in \eqref{eq:parabolicgtau}
    and employing Cauchy-Schwarz inequality yields
    \begin{equation}
        \label{eq:proof:Regularity:B22}
    \begin{split}
        \absbig{\Q{\tau_2}\!-\!\Q{\tau_1}}
        = \abs{\int_{\tau_1}^{\tau_2} \!\fd{\tau} \Q{\tau}\,d\tau}
        &= \abs{\int_{\tau_1}^{\tau_2} \left(\fd{\tau}g^*_\tau,\vhatp{\tau}\right)_{L_2(D_T)}d\tau}
        = \abs{\int_{\tau_1}^{\tau_2} \left(\alpha_\tau T_{B_0}\uhatp{\tau},\vhatp{\tau}\right)_{L_2(D_T)}d\tau}\\
        &\leq \int_{\tau_1}^{\tau_2} \!\!\alpha_\tau\N{T_{B_0}}\N{\uhatp{\tau}}_{L_2(D_T)}\!\N{\vhatp{\tau}}_{L_2(D_T)}d\tau
        \leq C^B_2C^{\widehat{u}}C^{\widehat{v}} \!\int_{\tau_1}^{\tau_2} \!\!\alpha_\tau \,d\tau,
    \end{split}
    \end{equation}
    where the last inequality is due to
    the operator norm of $T_{B_0}$ being bounded by the $L_2$-norm of the kernel $B$ as of \Cref{lem:parabolicTB},
    $\sup_{\tau\in I}\N{\uhatp{\tau}}_{L_2(D_T)}\leq C^{\widehat{u}}$ according to \Cref{lem:parabolic_uhatL2},
    and $\sup_{\tau\in I}\N{\vhatp{\tau}}_{L_2(D_T)}\leq C^{\widehat{v}}$ according to \Cref{lem:parabolic_vhatL2}.
\end{proof}
\section{Cycle of Stopping Times Analysis}
\label{sec:cyclestoppingtimes}


Exploiting the regularity bound for the functional $\Q{\tau}$ in terms of the learning rate~$\alpha_\tau$ established in \Cref{lem:CQ_Regulartiy}
together with the fact that $\fd{\tau}\J{\tau} = - \alpha_\tau\Q{\tau}$ as shown in \Cref{lem:parabolictimeevolutionJt*},
we prove in \Cref{lem:convergenceCJCB} of this section by using a cycle of stopping times analysis as conducted in \cite{bertsekas2000gradient,sirignano2022online} that this entails $\Q{\tau}\rightarrow0$ as $\tau\rightarrow\infty$ provided that the learning rate $(\alpha_\tau)_{\tau\geq0}$ is decreasing and such that $\int_{0}^{\infty}\alpha_\tau\,d\tau=\infty$.
\begin{proposition}
    \label{lem:convergenceCJCB}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in [0,\infty)}\in \CC\left([0,\infty),\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{rem:parabolic_wellposedness}
    on the training time interval $[0,\infty)$.
    Then,
    \begin{equation}        \lim_{\tau\rightarrow\infty} \Q{\tau}
        = 0
    \end{equation}
    and thus also $\lim_{\tau\rightarrow\infty}\fd{\tau}\J{\tau}=0$.
\end{proposition}

\begin{proof}
    The proof borrows the cycle of stopping times argument from \cite[Proposition~1]{bertsekas2000gradient} and \cite[Theorem~3.1]{sirignano2022online}, which crucially depends on the regularity bound~\eqref{eq:lem:CQ_Regulartiy} for the functional $\Q{\tau}$ in terms of the learning rate as apparent in the proof of \Cref{lem:auxcontradiction}.

    \textbf{Setup.}
    Let $\varepsilon>0$ and set $A=\varepsilon/(2L_\CQ)>0$.
    We define the cycle of stopping times
    \begin{equation}
    \begin{split}
        0=\sigma_0\leq\tau_1\leq\sigma_1\leq\tau_2\leq\sigma_2\leq\tau_3\leq\dots,
    \end{split}
    \end{equation}
    where $\tau_k$ and $\sigma_k$ are defined for $k=1,2,\dots$ according to
    \begin{equation}
    \begin{split}
        \tau_k
        &= \inf\left\{\tau>\sigma_{k-1}: \Q{\tau}\geq\varepsilon\right\}\\
        \sigma_k
        &= \sup\bigg\{\tau\geq\tau_k: \frac{1}{2}\Q{\tau_k} \leq \Q{s} \leq 2\Q{\tau_k} \text{ for all }s\in[\tau_k,\tau] \text{ and }\int_{\tau_k}^{\tau}\alpha_s\,ds\leq A\bigg\}.
    \end{split}
    \end{equation}
    We further introduce the intervals $I^1_k=[\sigma_{k-1},\tau_k)$ and $I^2_k=[\tau_k,\sigma_k)$.
    It is easy to convince ourselves that by continuity (in the training time $\tau$) it holds $\Q{\tau}<\varepsilon$ for $\tau\in I^1_k$ as well as $\Q{\tau_k}/2\leq\Q{\tau}\leq2\Q{\tau_k}$ for $\tau\in I^2_k$ according to the definitions of the stopping times.

    \textbf{Main Proof.}
    We wish to show that there exists a finite time $\CT^*$ such that it holds $\Q{\tau}\leq\varepsilon$ for all $\tau>\CT^*$.
    Since $\varepsilon$ was arbitrary, the statement then follows.

    \textit{Case 1a: Finitely many $\tau_k$'s, $\tau_K=\infty$.}
    In this case, since there are only finitely many $\tau_k$'s with $\tau_K=\infty$, there indeed exists $\CT^*$ such that $\Q{\tau}\leq\varepsilon$ for all $\tau>\CT^*$.

    \textit{Case 1b: Finitely many $\tau_k$'s, $\sigma_K=\infty$.}
    This case cannot occur, since it would necessitate $\int_{\tau_k}^{\infty}\alpha_\tau\,d\tau\leq A$, which contradicts that by assumption on the learning rate $\int_{0}^{\infty}\alpha_\tau\,d\tau=\infty$.

    It thus remains to show that the case of infinitely many $\tau_k$'s cannot occur either.

    \textit{Case 2: Infinitely many $\tau_k$'s.}
    In this case, we have for sufficiently large $\widetilde{n}$ and for all $n\geq \widetilde{n}$ by a telescopic sum argument that
    \begin{equation}       \label{eq:proof:telescopicsum_aux}
    \begin{split}
        \J{\tau_{n+1}} - \J{\tau_{\widetilde{n}}}
        &= \sum_{k=\widetilde{n}}^n \big(\J{\tau_{k+1}} - \J{\tau_k}\big)
        = \sum_{k=\widetilde{n}}^n \left[\big(\J{\tau_{k+1}} - \J{\sigma_k}\big) + \big(\J{\sigma_k} - \J{\tau_k}\big)\right],
    \end{split}
    \end{equation}
    where, in the last line, the respective first term captures the behavior on the intervals $I^1_{k+1}=[\sigma_{k},\tau_{k+1})$, while the second term captures the behavior on the intervals $I^2_k=[\tau_{k},\sigma_k)$.

    On the intervals~$I^1_{k+1}=[\sigma_{k},\tau_{k+1})$ we have $\Q{\tau}\leq\varepsilon$ for $\tau\in I^1_{k+1}$.
    By the fundamental theorem of calculus it holds
    \begin{equation}        \label{eq:proof:telescopicsum_aux1}
    \begin{split}
        \J{\tau_{k+1}}-\J{\sigma_{k}}
        = \int_{\sigma_{k}}^{\tau_{k+1}} \fd{\tau}\J{\tau} \,d\tau
        =  - \int_{\sigma_{k}}^{\tau_{k+1}} \alpha_\tau\Q{\tau} \,d\tau
        \leq 0,
    \end{split}
    \end{equation}
    where we used \Cref{lem:parabolictimeevolutionJt*} to obtain the second equality and the positivity of $\Q{\tau}$, a consequence of the positive definiteness of $T_{B_0}$ from \Cref{lem:parabolicposdefTB}, for the last inequality.

    On the other hand, on the intervals~$I^2_k=[\tau_k,\sigma_k)$ we have
    \begin{equation}
        \frac{1}{2}\Q{\tau_k}\leq\Q{\tau}\leq2\Q{\tau_k}
        \qquad\text{and}\qquad
        \int_{\tau_k}^{\tau}\alpha_s\,ds\leq A
    \end{equation}
    for $\tau\in I^2_k$.
    Thus, again by the fundamental theorem of calculus and using \Cref{lem:parabolictimeevolutionJt*} in the second equality,
    it holds
    \begin{equation}        \label{eq:proof:telescopicsum_aux2}
    \begin{split}
        \J{\sigma_{k}}-\J{\tau_k}
        =\int_{\tau_k}^{\sigma_k} \fd{\tau}\J{\tau} \,d\tau
        = - \int_{\tau_k}^{\sigma_k} \alpha_\tau\Q{\tau} \,d\tau
        \leq - \frac{1}{2}\Q{\tau_k}\int_{\tau_k}^{\sigma_k} \alpha_\tau \,d\tau 
        \leq -\frac{(1-\vartheta)}{2}\varepsilon A
    \end{split}
    \end{equation}
    for any $\vartheta\in(0,1)$,
    where the third inequality is due to the property of the interval $I^2_k$, while the fourth inequality is firstly since by continuity and by definition of the stopping time~$\tau_k$ it holds $\Q{\tau_k}\geq\varepsilon$ and secondly since as of \Cref{lem:auxcontradiction} it holds $(1-\vartheta) A\leq\int_{\tau_k}^{\sigma_k} \alpha_\tau\,d\tau$.

    Inserting \eqref{eq:proof:telescopicsum_aux1} and \eqref{eq:proof:telescopicsum_aux2} into \eqref{eq:proof:telescopicsum_aux}
    yields 
    \begin{equation}
        \J{\tau_{n+1}}
        \leq \J{\tau_{\widetilde{n}}} -\sum_{k=\widetilde{n}}^n \frac{(1-\vartheta)}{2}\varepsilon A
        = \J{\tau_{\widetilde{n}}} -\sum_{k=\widetilde{n}}^n \frac{(1-\vartheta)\varepsilon^2}{4L_\CQ}.
    \end{equation}
    Letting $n\rightarrow\infty$, we would obtain that $\J{\tau_{n+1}}\rightarrow-\infty$, which contradicts the fact that $\J{\tau}\geq0$ by definition.
    By excluding that this case can occur, the proof is concluded.
\end{proof}

In the proof of \Cref{lem:convergenceCJCB} we made use of the following auxiliary result.
\begin{lemma}
    \label{lem:auxcontradiction}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in [0,\infty)}\in \CC\left([0,\infty),\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{rem:parabolic_wellposedness}
    on the training time interval $[0,\infty)$.
    For given $\varepsilon>0$, let $A=\varepsilon/(2L_\CQ)$.
    Then, for $k$ large enough and for $\eta>0$ small enough (potentially depending on $k$), one has $\int_{\tau_k}^{\sigma_k+\eta} \alpha_\tau\,d\tau>A$.
    Moreover, we also have
    $(1-\vartheta)A\leq\int_{\tau_k}^{\sigma_k} \alpha_\tau\,d\tau \leq A$ for any $\vartheta\in(0,1)$.
\end{lemma}
\begin{proof}
    The proof of the first part of the statement proceeds by contradiction.
    Let us therefore assume that $\int_{\tau_k}^{\sigma_k+\eta} \alpha_\tau\,d\tau \leq A$.
    Leveraging the regularity bound for the functional \texorpdfstring{$\Q{\tau}$}{Q} in terms of the learning rate established in \Cref{lem:CQ_Regulartiy} with $\tau_1=\tau_k$ and $\tau_2=\sigma_k+\eta$,
    we have
    \begin{equation}        \label{eq:proof:lemma:contradiction_aux1}
    \begin{split}
        \Q{\sigma_k+\eta}-\Q{\tau_k}
        \leq \absbig{\Q{\sigma_k+\eta}-\Q{\tau_k}}
        \leq L_\CQ\int_{\tau_k}^{\sigma_k+\eta}\alpha_\tau\, d\tau
        \leq L_\CQ A
        = \frac{1}{2}\varepsilon
        \leq \frac{1}{2}\Q{\tau_k},
    \end{split}
    \end{equation}
    where we used the contradiction assumption in the third step,
    the definition of $A=\varepsilon/(2L_\CQ)$ in the fourth step
    and that by definition of the stopping time~$\tau_k$ it holds $\Q{\tau_k}\geq\varepsilon$ in the last.
    The computation \eqref{eq:proof:lemma:contradiction_aux1} implies
    $\Q{\sigma_k+\eta} \leq \Q{\tau_k} + \Q{\tau_k}/2 \leq 2\Q{\tau_k}$ by simple reordering 
    as well as 
    $\Q{\tau_k} - \Q{\sigma_k+\eta} \leq \abs{\Q{\sigma_k+\eta}-\Q{\tau_k}} \leq \Q{\tau_k}/2$, or rearranged $\Q{\tau_k}/2 \leq \Q{\sigma_k+\eta}$.
    In summary, $\frac{1}{2}\Q{\tau_k} \leq \Q{\sigma_k+\eta} \leq 2\Q{\tau_k}$.
    Since the same reasoning holds for any $0<\widetilde\eta\leq\eta$, this yields a contradiction, as this would imply that $\sigma_k=\sigma_k+\eta$, contradicting $\eta>0$.
    Thus, $\int_{\tau_k}^{\sigma_k+\eta} \alpha_\tau\,d\tau > A$ holds proving the first part of the statement.

    What concerns the second part, since the learning rate $\alpha_\tau$ is decreasing in $\tau$, for large enough $k$ and small enough $\eta$ we can ensure $\int_{\sigma_k}^{\sigma_k+\eta} \alpha_\tau\,d\tau \leq \vartheta A$.
    Thus,
    \begin{equation}
        \int_{\tau_k}^{\sigma_k} \alpha_\tau\,d\tau
        = \int_{\tau_k}^{\sigma_k+\eta} \alpha_\tau\,d\tau - \int_{\sigma_k}^{\sigma_k+\eta} \alpha_\tau\,d\tau
        \geq A - \vartheta A
        = (1-\vartheta) A.
    \end{equation}
    Since by definition $\int_{\tau_k}^{\sigma_k} \alpha_\tau\,d\tau \leq A$, this concludes the proof.
\end{proof}
\section{Convergence of the Adjoint \texorpdfstring{$\uhatp{\tau}$}{} and the Solution \texorpdfstring{$\up{\tau}$}{}}
\label{sec:convergences}


Since the functional $\Q{\tau} = (\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2(D_T)}$ 
converges to zero as $\tau\rightarrow\infty$ according to \Cref{lem:convergenceCJCB} and since the NN kernel operator~$T_{B_0}$ is positive definite as of \Cref{lem:parabolicposdefTB},
we can derive in \Cref{lem:convergence_adjoint} in \Cref{sec:ConvergenceAdjoint} the weak $L_2$ convergence of the adjoint $\uhatp{\tau}$ in \eqref{eq:parabolicadjoint*} to zero as $\tau\rightarrow\infty$.
Noticing that this entails that the left-hand side of the adjoint PDE \eqref{eq:parabolicadjoint*_plain} converges to zero when evaluated against any test function,
we infer therefrom in \Cref{lem:convergence_solution} in \Cref{sec:ConvergenceSolution} the weak $L_2$ convergence of the solution $\up{\tau}$ in \eqref{eq:parabolicPDE*} to the target data $h$  by definition of the adjoint PDE.
In \Cref{sec:characterization_fixedpoint}, we provide a result of independent interest showing that (strong) limit points of the trained NN-PDE solution are global minimizers of the loss~$\J{}$ for an even more general class of second-order parabolic NN-PDEs.


\subsection{Convergence of the Adjoint \texorpdfstring{$\uhatp{\tau}$}{} as \texorpdfstring{$\tau\rightarrow\infty$}{training time goes to infinity}}
\label{sec:ConvergenceAdjoint}

Let us first infer the weak $L_2$ convergence of the adjoint $\uhatp{\tau}$ in \eqref{eq:parabolicadjoint*} to zero.

\begin{proposition}
    \label{lem:convergence_adjoint}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in [0,\infty)}\in \CC\left([0,\infty),\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{rem:parabolic_wellposedness}
    on the training time interval $[0,\infty)$.
    Then,
    \begin{equation}
        \uhatp{\tau}\rightharpoonup0
        \text{ in }
        L_2
        \quad
        \text{as }
        \tau\rightarrow\infty,
    \end{equation}
    i.e., for each test function~$\phi\in L_2(D_T)$ it holds $\lim_{\tau\rightarrow\infty} (\uhatp{\tau},\phi)_{L_2(D_T)}=0$.
\end{proposition}

\begin{proof}
    Since the eigenfunctions~$\{e_k(t,x)\}_{k=1}^\infty$ of $T_{B_0}$ form an orthonormal basis of $L_2(D_T)$ according to \Cref{lem:parabolicTB},
    we have for $\uhatp{\tau}$ the expansion $\uhatpp{\tau}{t,x} = \sum_{k=1}^\infty c_k(\tau)e_k(t,x)$.
    Using this, we can express $\Q{\tau}=\left(\uhatp{\tau},T_{B_0}\uhatp{\tau}\right)_{L_2(D_T)} = \sum_{k=1}^\infty \lambda_kc^2_k(\tau)$,
 where the last equality holds as $T_{B_0}$ is a continuous operator.
    Taking the limit $\tau\rightarrow\infty$ and leveraging \Cref{lem:convergenceCJCB} in the last step of the following display,
    this shows
    \begin{equation}
        \lim_{\tau\rightarrow\infty} \sum_{k=1}^\infty \lambda_kc^2_k(\tau)
        =\lim_{\tau\rightarrow\infty} \left(\uhatp{\tau},T_{B_0}\uhatp{\tau}\right)_{L_2(D_T)}
        =\lim_{\tau\rightarrow\infty} \Q{\tau}
        =0.
    \end{equation}
    Consequently, for $k$ fixed, it holds $\lim_{\tau\rightarrow\infty}\lambda_kc_k^2(\tau)=0$.
    Furthermore, with $\lambda_k>0$ according to \Cref{lem:parabolicposdefTB}, for $k$ fixed, it also holds $\lim_{\tau\rightarrow\infty}c_k(\tau)=0$.

    Let $\varepsilon>0$ and let $\phi\in L_2(D_T)$ denote a test function, which we can represent as $\phi(t,x) = \sum_{k=1}^\infty \varphi_k e_k(t,x)$ with $\sum_{k=1}^\infty\varphi_k^2<\infty$.
    Thus, there exists $K>0$ such that $\sum_{k=K+1}^\infty\varphi_k^2 \leq \varepsilon^2/(2C^{\widehat{u}})^2$.

   If $\varphi_k=0$ for all $k=1,\dots,K$, $\absbig{\sum_{k=1}^K \varphi_k c_k(\tau)}=0$. Otherwise, recalling that $\lim_{\tau\rightarrow\infty}c_k(\tau)=0$ for any fixed $k$, there exists $\overbar{\tau}>0$ such that $\abs{c_k(\tau)}\leq \varepsilon/(2K\max_{\tilde{k}=1,\dots,K}\absnormal{\varphi_{\tilde{k}}})$ (uniformly for $k=1,\dots,K$) for all $\tau\geq\overbar{\tau}$. This shows in particular that $\absbig{\sum_{k=1}^K \varphi_k c_k(\tau)} \leq \sum_{k=1}^K \abs{\varphi_k} \abs{c_k(\tau)} \leq \varepsilon/2$.
    We can now estimate with triangle inequality for all such $\tau\geq\overbar{\tau}$ that
    \begin{equation}
    \begin{split}
        \abs{(\phi,\uhatp{\tau})_{L_2(D_T)}}
        = \abs{\sum_{k=1}^\infty \varphi_k c_k(\tau)}
        &\leq \abs{\sum_{k=1}^K \varphi_k c_k(\tau)} + \abs{\sum_{k=K+1}^\infty \varphi_k c_k(\tau)}\\
        &\leq \frac{\varepsilon}{2} + \frac{\varepsilon}{2 C^{\widehat{u}}}\N{\uhatp{\tau}}_{L_2(D_T)}
        \leq \frac{\varepsilon}{2} + \frac{\varepsilon}{2 C^{\widehat{u}}}C^{\widehat{u}}
        \leq \varepsilon,
    \end{split}
    \end{equation}
    where we used Cauchy-Schwarz inequality and the former estimates together with \Cref{lem:parabolic_uhatL2} to obtain the bound on the tail of the series in the inequalities in the second line.
    Thus $\abs{(\phi,\uhatp{\tau})_{L_2(D_T)}}\leq\varepsilon$ for all $\tau\geq\overbar{\tau}$.
    Since $\varepsilon>0$ was arbitrary,
    this shows $\lim_{\tau \rightarrow \infty} (\phi,\uhatp{\tau})_{L_2(D_T)} = 0$ for all test functions $\phi\in L_2(D_T)$, proving the weak convergence of $\uhatp{\tau}$ to zero in $L_2$ as $\tau\rightarrow\infty$.
\end{proof}
\subsection{Convergence of the Solution \texorpdfstring{$\up{\tau}$}{} as \texorpdfstring{$\tau\rightarrow\infty$}{training time goes to infinity}}
\label{sec:ConvergenceSolution}

It remains to infer the weak $L_2$ convergence of the solution $\up{\tau}$ to \eqref{eq:parabolicPDE*} to the target data~$h$.
\begin{proposition}  \label{lem:convergence_solution}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in [0,\infty)}\in \CC\left([0,\infty),\CS\times\CS\right)$ denote the unique weak solution to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in the sense of \Cref{rem:parabolic_wellposedness}
    on the training time interval $[0,\infty)$.
    Then,
    \begin{equation}
        \up{\tau}\rightharpoonup h
        \text{ in }
        L_2
        \quad
        \text{as }
        \tau\rightarrow\infty,
    \end{equation}
    i.e., for each test function~$\phi\in L_2(D_T)$ it holds $\lim_{\tau\rightarrow\infty} (\up{\tau}-h,\phi)_{L_2(D_T)}=0$.
\end{proposition}
\begin{proof}
    Let us first show that $\lim_{\tau\rightarrow\infty} (\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}=0$ for each test function $\widetilde\phi\in C^\infty_c(D_T)$ that vanishes on the boundary.
    By using that $\uhatp{\tau}$ is a weak solution to the adjoint PDE~\eqref{eq:parabolicadjoint*} in the sense of \Cref{def:weak_sol_adjoint} with right-hand side $(\up{\tau}-h)$ we compute for the test function $\widetilde\phi\in C^\infty_c(D_T)$ that
    \begin{equation}        \label{eq:proof:lem:convergence_solution1}
    \begin{split}
        (\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}
        &= \int_0^T \left(\upp{\tau}{t,\dummy}-h(t,\dummy), \widetilde\phi(t,\dummy)\right)_{L_2(D)}dt\\
        &= \int_0^T \left\langle-\fpartial{t}\uhatpp{\tau}{t,\dummy},\widetilde\phi(t,\dummy)\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB^\dagger\left[\uhatpp{\tau}{t,\dummy},\widetilde\phi(t,\dummy);t\right] \\
        &\qquad\quad\, - \left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\uhatpp{\tau}{t,\dummy}, \widetilde\phi(t,\dummy)\right)_{L_2(D)} dt \\
        &= \int_0^T \left\langle\fpartial{t}\widetilde\phi(t,\dummy),\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)} + \CB\left[\widetilde\phi(t,\dummy),\uhatpp{\tau}{t,\dummy};t\right] \\
        &\qquad\quad\, - \left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\widetilde\phi(t,\dummy),\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt
    \end{split}
    \end{equation}
    with the last step following analogously to \eqref{eq:proof:parabolicdtJ*1}, where we justified the individual steps in detail, see \eqref{eq:parabolicpI*aux_T51}--\eqref{eq:parabolicpI*aux_T52}.
    Herefore, note that in the case here, even $\widetilde\phi\in C^\infty_c(D_T)$.

    As a consequence of the convergence $\uhatp{\tau}\rightharpoonup0$ in $L_2$ as $\tau\rightarrow\infty$, which we established in \Cref{lem:convergence_adjoint}, the right-hand side of \eqref{eq:proof:lem:convergence_solution1} converges to zero as $\tau\rightarrow\infty$.
    To be precise, let us discuss each of the three terms.
    Firstly, since $\fpartial{t}\widetilde\phi\in C^\infty_c(D_T)\subset L_2(D_T)$ and $\uhatpp{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$, the dual pairing between $H^{-1}(D)$ and $H_0^1(D)$ coincides with the $L_2(D)$ scalar product \cite[Chapter~5.9, Theorem 1(iii)]{evans2010partial} and thus
    \begin{equation}
        \label{eq:proof:lem:convergence_solution2}
    \begin{split}
        \int_0^T \left\langle\fpartial{t}\widetilde\phi(t,\dummy),\uhatpp{\tau}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}dt
        &=\int_0^T \left(\uhatpp{\tau}{t,\dummy},\fpartial{t}\widetilde\phi(t,\dummy)\right)_{L_2(D)}dt
        =\big(\uhatp{\tau},\fpartial{t}\widetilde\phi\big)_{L_2(D_T)},
    \end{split}
    \end{equation}
    which converges to zero as $\tau\rightarrow\infty$ since $\uhatp{\tau}\rightharpoonup0$ in $L_2$ according to \Cref{lem:convergence_adjoint} with test function $\fpartial{t}\widetilde\phi\in C^\infty_c(D_T)\subset L_2(D_T)$.
    Secondly, by definition of the bilinear form~$\CB$ in \eqref{eq:CB} we have
\begin{equation}
\begin{split}        \label{eq:proof:lem:convergence_solution3}
    &\int_0^T\CB\left[\widetilde\phi(t,\dummy),\uhatpp{\tau}{t,\dummy};t\right]dt 
        =\int_0^T\!\!\!\int_U \sum_{i,j=1}^d  a^{ij}(t,x) \fpartial{x_i} \widetilde\phi(t,\dummy) \fpartial{x_j} \uhatpp{\tau}{t,\dummy}\\
        &\qquad\qquad\,\qquad\,
        + \sum_{i=1}^d b^i(t,x) \fpartial{x_i} \widetilde\phi(t,\dummy) \uhatpp{\tau}{t,\dummy}
        + c(t,x)\widetilde\phi(t,\dummy)\uhatpp{\tau}{t,\dummy} \,dxdt \\
        &\qquad\qquad\,=\int_0^T\!\!\!\int_U -\sum_{i,j=1}^d  \fpartial{x_j}\left(a^{ij}(t,x) \fpartial{x_i} \widetilde\phi(t,\dummy)\right) \uhatpp{\tau}{t,\dummy}\\
        &\qquad\qquad\,\qquad\,
        + \sum_{i=1}^d b^i(t,x) \fpartial{x_i} \widetilde\phi(t,\dummy) \uhatpp{\tau}{t,\dummy}
        + c(t,x)\widetilde\phi(t,\dummy)\uhatpp{\tau}{t,\dummy} \,dxdt\\
        &\qquad\qquad\,=\int_0^T\!\!\!\int_U -\sum_{i,j=1}^d  a^{ij}(t,x) \fpartiall{x_ix_j} \widetilde\phi(t,\dummy) \uhatpp{\tau}{t,\dummy}\\
        &\qquad\qquad\,\qquad\,
        - \sum_{i,j=1}^d  \fpartial{x_j}a^{ij}(t,x) \fpartial{x_i} \widetilde\phi(t,\dummy) \uhatpp{\tau}{t,\dummy}\\
        &\qquad\qquad\,\qquad\,
        + \sum_{i=1}^d b^i(t,x) \fpartial{x_i} \widetilde\phi(t,\dummy) \uhatpp{\tau}{t,\dummy}
        + c(t,x)\widetilde\phi(t,\dummy)\uhatpp{\tau}{t,\dummy} \,dxdt\\
        &\qquad\qquad\,=\left(\uhatp{\tau},-\sum_{i,j=1}^da^{ij}\fpartiall{x_ix_j} \widetilde\phi-\sum_{i,j=1}^d\fpartial{x_j}a^{ij}\fpartial{x_i} \widetilde\phi+\sum_{i=1}^db^i\fpartial{x_i}\widetilde\phi + c\widetilde\phi\right)_{L_2(D_T)},
    \end{split}
    \end{equation}%
    where the second step is just partial integration with all boundary terms vanishing since also $\fpartial{x_i}\widetilde\phi\in C^\infty_c(D_T)$.
    Since the coefficients $a^{ij},\fpartial{x_j}a^{ij},b^i,c\in L_\infty(D_T)$ as of Assumption~\ref{asm:PDE_coefficients}, the test function in the scalar-product in the last line of \eqref{eq:proof:lem:convergence_solution3} is in $L_2(D_T)$ and thus the right-hand side of \eqref{eq:proof:lem:convergence_solution3} converges to zero as $\tau\rightarrow\infty$ since $\uhatp{\tau}\rightharpoonup0$ in $L_2$ according to \Cref{lem:convergence_adjoint}.
    Thirdly and lastly, since with $\widetilde\phi\in C^\infty_c(D_T) \subset L_2(D_T)$ and $q_u$ being uniformly bounded as of Assumption~\ref{asm:PDE_nonlinearity_q_ubdd}, also
    $q_u(\dummy,\dummy,\up{\tau})\widetilde\phi\in L_2(D_T)$,
    \begin{equation}
        \label{eq:proof:lem:convergence_solution4}
        \int_0^T \left(q_u(t,\dummy,\upp{\tau}{t,\dummy})\widetilde\phi(t,\dummy),\uhatpp{\tau}{t,\dummy}\right)_{L_2(D)} dt
        = \big(\uhatp{\tau},q_u(\up{\tau})\widetilde\phi\big)_{L_2(D_T)}
    \end{equation}
    converges to zero as $\tau\rightarrow\infty$ since $\uhatp{\tau}\rightharpoonup0$ in $L_2$ according to \Cref{lem:convergence_adjoint}.    
    With this we have shown that $(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}\rightarrow0$ for all $\widetilde\phi\in C^\infty_c(D_T)$.

    Let now $\phi\in L_2(D_T)$ and $\varepsilon>0$.
    Since $C^\infty_c(D_T)$ is dense in $L_2(D_T)$~\cite[Corollary~4.23]{brezis2011functional},
    there exists $\widetilde\phi\in C^\infty_c(D_T)$ such that $\Nbig{\phi-\widetilde\phi}_{L_2(D_T)}\leq \varepsilon/\sqrt{2\J{0}}$.
    We can thus estimate
    \begin{equation}
    \begin{split}
        \abs{(\up{\tau}-h,\phi)_{L_2(D_T)}}
        &\leq \absbig{(\up{\tau}-h,\phi-\widetilde\phi)_{L_2(D_T)}} + \absbig{(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}} \\
        &\leq \N{\up{\tau}-h}_{L_2(D_T)}\Nbig{\phi-\widetilde\phi}_{L_2(D_T)} + \absbig{(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}} \\
        &= \sqrt{2\J{\tau}}\Nbig{\phi-\widetilde\phi}_{L_2(D_T)} + \absbig{(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}} \\
        &\leq \sqrt{2\J{0}}\Nbig{\phi-\widetilde\phi}_{L_2(D_T)} + \absbig{(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}} \\
        &\leq \frac{\varepsilon}{2} + \frac{\varepsilon}{2} = \varepsilon
    \end{split}
    \end{equation}
    for sufficiently large $\tau$.
    In the next-to-last step we used that by \Cref{lem:parabolictimeevolutionJt*} the functional $\J{\tau}$ is non-increasing.
    The last step holds since $\absnormal{(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}}\rightarrow0$ for $\widetilde\phi\in C^\infty_c(D_T)$, thus $\absnormal{(\up{\tau}-h,\widetilde\phi)_{L_2(D_T)}}\leq\varepsilon/2$ for sufficiently large $\tau$.
    Consequently, $\absnormal{(\up{\tau}-h,\phi)_{L_2(D_T)}}\rightarrow0$ for all $\phi\in L_2(D_T)$, which concludes the proof.
\end{proof}

Before closing this section, let us compare \Cref{lem:convergence_solution} to prior work to indicate that we substantially strengthen the notion of convergence for a significantly wider class of PDEs and a more general loss.
\begin{remark}
\label{rem:comparisonconvergencesirignano2023pde}
    The weak convergences $\uhatp{\tau}\rightharpoonup 0$ in $L_2$ and $\up{\tau}\rightharpoonup h$ in $L_2$ as $\tau\rightarrow\infty$ established in \Cref{lem:convergence_adjoint,lem:convergence_solution}, respectively, significantly improve prior work~\cite{sirignano2023pde},
    where only convergence of the time averages has been established, cf.\@ \cite[Theorem~9.3]{sirignano2023pde}.
    In the elliptic linear PDE setting,
    the authors of \cite{sirignano2023pde} prove $\lim_{\tau\rightarrow\infty}\frac{1}{\tau}\int_0^\tau (\phi,\uhatp{s})_{L_2}^2\,ds=0$ for all $\phi\in L_2$ and $\lim_{\tau\rightarrow\infty}\frac{1}{\tau}\int_0^\tau (\psi,\uhatp{s}-h)_{L_2}^2\,ds=0$ for all $\psi\in\CA:=\{\psi\in H_0^1:\CL\psi\in L_2\}\subset L_2$.

    To see that \Cref{lem:convergence_adjoint,lem:convergence_solution} are stronger, simply observe that the time average $\frac{1}{\tau}\int_0^\tau
    f_s^2\,ds\rightarrow0$ might converge while $f_\tau\not\rightarrow0$.
    ($f_\tau$ corresponds here to either $(\phi,\uhatp{\tau})_{L_2}^2$ or $(\psi,\uhatp{\tau}-h)_{L_2}^2$.)
    A straightforward smooth example is given by 
    \begin{equation}
    f_\tau = 
    \begin{cases}
        \exp\left(1-\frac{1}{1-(\tau-2^\ell)^2}\right), & \text{for } \tau\in[2^\ell-1,2^\ell+1] \text{ for } \ell=1,2,\dots,\\
        0, & \text{else.}
    \end{cases}
    \end{equation}
    The function $\tau\mapsto f_\tau$ concatenates infinitely many bump functions centered around $2^\ell$, $\ell=1,2,\dots$, with width $2$ and maximal height $1$.
    Therefore, clearly, $u_\tau\not\rightarrow0$.
    However, since there are $\lfloor\log_2(\tau)\rfloor$ such bumps before time $\tau$,
    \begin{equation}
    \begin{split}
        \frac{1}{\tau}\int_0^\tau f_s^2\,ds
        \leq \frac{1}{\tau}\sum_{\ell=1}^{\lfloor\log_2(\tau)\rfloor}2 \leq \frac{2}{\tau}\log_2(\tau) \rightarrow0
        \quad\text{as } \tau\rightarrow\infty.
    \end{split}
    \end{equation}
    Conversely, it is immediate to see that $f_\tau\rightarrow0$ implies $\frac{1}{\tau}\int_0^\tau
    f_s^2\,ds\rightarrow0$.

    Secondly, unlike \cite{sirignano2023pde}, where the considered loss is given by 
    \begin{equation}
        \widetilde\CJ^*_\tau
        = \frac{1}{2} \sum_{\ell=1}^L  \left(\up{\tau}-h,m_\ell\right)_{L_2}^2
    \end{equation}
    for given functions $\{m_\ell\}_{\ell=1}^L$,
    we consider the stronger loss $\J{\tau}=\N{\up{\tau}-h}_{L_2}^2$ as in \eqref{eq:parabolicJtau}.

    We therefore generalize in this paper not just the class of considered PDEs substantially by allowing for nonlinear PDEs,
    but significantly improve the notion of convergence.
\end{remark}

\subsection{Limit Points of the Trained NN-PDE Solution are Global Minimizers of the Loss \texorpdfstring{$\J{}$}{}}
\label{sec:characterization_fixedpoint}

To conclude the theoretical contributions of this work,
let us provide a result about the 
limit points of the trained NN-PDE solution~$\up{\tau}$, which holds for
the even more general class of second-order parabolic NN-PDEs
\begin{alignat}{2}
\label{eq:parabolicPDE*_general}
\begin{aligned}
    \fpartial{t}\up{\tau} + \CL\up{\tau} - q(\up{\tau}, \nabla_x \up{\tau}, \mathbf{H}_{xx} \up{\tau})
    &= g^*_\tau
    \qquad&&\text{in }
    D_T, \\
    \up{\tau}
    &= 0
    \qquad&&\text{on }
    [0,T]\times\partial D, \\
    \up{\tau}
    &= f
    \qquad&&\text{on }
    \{0\}\times D,
\end{aligned}
\end{alignat}
with associated adjoint PDE
\begin{alignat}{2}
\label{eq:parabolicadjoint*_general}
\begin{aligned}
    -\fpartial{t}\uhatp{\tau} + \CL^\dagger\uhatp{\tau} - q_u(\up{\tau}, \nabla_x \up{\tau}, \mathbf{H}_{xx} \up{\tau})\uhatp{\tau}&&\\
    + \; \textstyle\sum_{i=1}^d \fpartial{x_i}\big(q_{p_i}(\up{\tau}, \nabla_x \up{\tau}, \mathbf{H}_{xx} \up{\tau}) \uhatp{\tau}\big)&&\\
    - \; \textstyle\sum_{i,j=1}^d \fpartiall{x_ix_j}\big(q_{\mathbf{H}_{ij}}(\up{\tau}, \nabla_x \up{\tau}, \mathbf{H}_{xx} \up{\tau}) \uhatp{\tau}\big)
    &= (\up{\tau}-h)
    \qquad&&\text{in }
    D_T, \\
    \uhatp{\tau}
    &= 0
    \qquad&&\text{on }
    [0,T]\times\partial D, \\
    \uhatp{\tau}
    &= 0
    \qquad&&\text{on }
    \{T\}\times D,
\end{aligned}
\end{alignat}
and coupled with the integro-differential equation~\eqref{eq:parabolicgtau} for $g^*_\tau$.

We show that any (strong) limit point of the solution of the trained NN-PDE, when using the adjoint gradient descent optimization method~\eqref{eq:GD} with the gradient being computed according to \eqref{eq:nablaJ}, is a global minimizer of the loss~$\J{}$.
\begin{theorem}
    \label{lem:stationary_point}
    Let $((\up{\tau},\uhatp{\tau}))_{\tau\in [0,\infty)}\in \CC\left([0,\infty),\CS\times\CS\right)$ denote the unique weak solution to the more general PDE system \eqref{eq:parabolicPDE*_general}--\eqref{eq:parabolicadjoint*_general} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} in a sense analogous to \Cref{lem:parabolic_wellposedness} and \Cref{rem:parabolic_wellposedness}
    on the training time interval $[0,\infty)$.
    Assume that $(\up{\tau},\uhatp{\tau})$ converges to some $(\up{\infty},\uhatp{\infty})$ in $L_2(D_T)$ as $\tau\rightarrow\infty$.
    Then $\uhatp{\infty}\equiv0$ a.e.\@ in $L_2(D_T)$ and
    \begin{equation}
        \up{\infty}\equiv h
        \text{ a.e.\@ in } L_2(D_T),
    \end{equation}
    i.e., $\up{\infty}$ is a global minimizer of $\J{}$.
\end{theorem}
\begin{proof}
    Leveraging the adjoint PDE~\eqref{eq:parabolicadjoint*_general}, we can derive analogously to \Cref{lem:parabolictimeevolutionJt*} that $\fd{\tau}\J{\tau} = - \alpha_\tau(\uhatp{\tau},T_{B_0}\uhatp{\tau})_{L_2} = - \alpha_\tau\Q{\tau}$ for all $\tau\in[0,\infty)$.
    Moreover, by following the computations of \Cref{lem:parabolic_uhatL2}, we can derive a uniform (in the training time~$\tau$) estimate of the form \eqref{eq:lem:parabolic_uhatL2} for the adjoint~$\uhatp{\tau}$.

    \textbf{Step 1: $\uhatp{\infty}\equiv0$ a.e.\@ in $L_2(D_T)$.}
    Since the eigenfunctions~$\{e_k(t,x)\}_{k=1}^\infty$ of $T_{B_0}$ form an orthonormal basis of $L_2(D_T)$ according to \Cref{lem:parabolicTB},
    $\uhatp{\infty}$ has the expansion $\uhatpp{\infty}{t,x} = \sum_{k=1}^\infty c_ke_k(t,x)$.
    We now proceed by contradiction and suppose that $\uhatp{\infty}$ is not $0$ a.e.\@ in $L_2(D_T)$.
    Then there exists at least one $\tilde{k}\in\bbN$ with $c_{\tilde{k}}\neq0$.
    Using this, we can lower bound $\Q{\infty}=\left(\uhatp{\infty},T_{B_0}\uhatp{\infty}\right)_{L_2(D_T)} = \sum_{k=1}^\infty \lambda_kc^2_k \geq \lambda_{\tilde{k}}c_{\tilde{k}}^2>0$ after recalling that $\lambda_{\tilde{k}}>0$ according to \Cref{lem:parabolicposdefTB}.
    We furthermore have
    \begin{equation}
    \begin{split}
        \Q{\tau} &= \left(\uhatp{\tau},T_{B_0}\uhatp{\tau}\right)_{L_2(D_T)} \\
        &= \left(\uhatp{\tau}-\uhatp{\infty},T_{B_0}\uhatp{\tau}\right)_{L_2(D_T)} + \left(\uhatp{\infty},T_{B_0}(\uhatp{\tau}-\uhatp{\infty})\right)_{L_2(D_T)} + \left(\uhatp{\infty},T_{B_0}\uhatp{\infty}\right)_{L_2(D_T)} \\
        &\geq - 2C^B_2C^{\widehat{u}}\N{\uhatp{\tau}-\uhatp{\infty}}_{L_2(D_T)} + \left(\uhatp{\infty},T_{B_0}\uhatp{\infty}\right)_{L_2(D_T)},
    \end{split}
    \end{equation}
    where we used Cauchy-Schwarz inequality together with \Cref{lem:parabolicTB} in the last step.
    Since $\uhatp{\tau}$ converges to $\uhatp{\infty}$ in $L_2(D_T)$ by assumption as $\tau\rightarrow\infty$, there exists $\overbar{\tau}>0$ such that $\N{\uhatp{\tau}-\uhatp{\infty}}_{L_2(D_T)} \leq \lambda_{\tilde{k}}c_{\tilde{k}}^2/(4C^B_2C^{\widehat{u}})$ for all $\tau>\overbar{\tau}$.
    Thus, $\Q{\tau}\geq \lambda_{\tilde{k}}c_{\tilde{k}}^2/2$ for all $\tau>\overbar{\tau}$.
    With the fundamental theorem of calculus it then holds
    \begin{equation}
        \J{\tau} = \J{\overbarscript{\tau}} - \int_{\overbarscript{\tau}}^\tau \alpha_s \Q{s} \,ds \leq \J{\overbarscript{\tau}} - \frac{\lambda_{\tilde{k}}c_{\tilde{k}}^2}{2}\int_{\overbarscript{\tau}}^\tau \alpha_s \,ds \rightarrow - \infty
    \end{equation}
    as $\tau\rightarrow\infty$ due to condition~\eqref{eq:learning_rate} on the learning rate $\alpha_\tau$.
    This contradicts the positivity of the functional~$\J{}$.
    Therefore, $\uhatp{\infty}\equiv0$ a.e.\@ in $L_2(D_T)$.

    \textbf{Step 2: $\up{\infty}\equiv h$ a.e.\@ in $L_2(D_T)$.}
    By using that $\uhatp{\infty}$ is a weak solution to the adjoint PDE~\eqref{eq:parabolicadjoint*_general} in a sense analogous to \Cref{def:weak_sol_adjoint} with right-hand side $(\up{\infty}-h)$,
    we infer that the left-hand side vanishes for all test functions $\phi\in L_2(D_T)$ as in \Cref{lem:convergence_solution}.
    Thus, $\up{\infty}\equiv h$ a.e.\@ in $L_2(D_T)$.
\end{proof}

