\section{Well-Posedness of the NN-PDE Training Dynamics}
\label{sec:well-posedness}

In this appendix, we show the well-posedness of the NN-PDE training dynamics,
i.e., the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} for $g^*_\tau$, by proving \Cref{lem:parabolic_wellposedness}.

Recall that $\CS = L_2([0,T],H^1(D)) \cap L_\infty([0,T],L_2(D))$.
\begin{proof}[Proof of \Cref{lem:parabolic_wellposedness}]
    \textbf{Existence.}
    The existence proof is based on a fixed-point argument employing the Banach fixed point theorem.
    For a given training time horizon $\CT>0$, let us denote by $\CV_\CT=\CC\left([0,\CT],\CS\right)$ the Banach space consisting of elements with finite norm
    \begin{equation}
        \N{u}_{\CV_\CT}
        = \sup_{\tau\in[0,\CT]} \left(\N{u_\tau}_{L_2([0,T],H^1(D))} + \N{u_\tau}_{L_\infty([0,T],L_2(D))}\right).
    \end{equation}
    A solution $((\up{\tau},\uhatp{\tau}))_{\tau\in[0,\CT]}$ to the PDE system \eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} is to be shown in what follows an element of the space $\CC\left([0,\CT],\CS\times\CS\right)$ (which we identify with the space $\CV_\CT\times\CV_\CT$) with additional regularity.

    \textit{Step~1: Existence and regularity for given right-hand side $\widetilde{g}_\tau= - \int_0^\tau \alpha_s b_s\,ds$.}
    For given $\CT>0$, let $b:[0,\CT] \rightarrow L_2(D_T)$ be a given function with $b_\tau$ being Lipschitz continuous on $\overbar{D_T}$ for each $\tau\in[0,\CT]$ and such that $\sup_{\tau\in[0,\CT]} \N{b_\tau}_{L_\infty(D_T)}\leq C_b$, where $C_b$ may depend in particular on $\CT$.
    Consider the auxiliary PDE system
    \begin{alignat}{2}
   \label{eq:parabolicPDE*_tilde}
    \begin{aligned}
        \fpartial{t}\upt{\tau} + \CL\upt{\tau} - q(\upt{\tau})
        &= \widetilde{g}_\tau = - \int_0^\tau \alpha_s b_s\,ds
        \qquad&&\text{in }
        D_T, \\
        \upt{\tau}
        &= 0
        \qquad&&\text{on }
        [0,T]\times\partial D, \\
        \upt{\tau}
        &= f
        \qquad&&\text{on }
        \{0\}\times D
    \end{aligned}
    \end{alignat}
    and
    \begin{alignat}{2}
    \label{eq:parabolicadjoint*_tilde}
    \begin{aligned}
        -\fpartial{t}\uhatpt{\tau} + \CL^\dagger\uhatpt{\tau} - q_u(\upt{\tau})\uhatpt{\tau}
        &= (\upt{\tau}-h)
        \qquad&&\text{in }
        D_T, \\
        \uhatpt{\tau}
        &= 0
        \qquad&&\text{on }
        [0,T]\times\partial D, \\
        \uhatpt{\tau}
        &= 0
        \qquad&&\text{on }
        \{T\}\times D.
    \end{aligned}
    \end{alignat}
    We first prove that there exists a solution~$(\upt{\tau},\uhatpt{\tau})\in \CS\times\CS$ to the system~\eqref{eq:parabolicPDE*_tilde}--\eqref{eq:parabolicadjoint*_tilde} for all $\tau\in[0,\CT]$ using classical existence results from \cite{ladyzhenskaia1968linear}.
    Such solution, as we show, enjoys the property that for all $\tau\in[0,\CT]$ it holds $(\partial_t\uppt{\tau}{t,\dummy},\partial_t\uhatppt{\tau}{t,\dummy})\in L_2(D)\times L_2(D)$ for a.e.\@ $t\in[0,T]$.

    \textit{Step~1a: Existence of solution to PDE \eqref{eq:parabolicPDE*_tilde}.}
    For the existence of a solution to the nonlinear PDE \eqref{eq:parabolicPDE*_tilde}, we invoke \cite[Chapter V, Theorem 6.2]{ladyzhenskaia1968linear}.
    To begin with,
    we notice that, in the notation of \cite[Chapter V, Theorem 6.2]{ladyzhenskaia1968linear}, the coefficients of the nonlinear PDE operator of the parabolic PDE~\eqref{eq:parabolicPDE*_tilde} are $a_{i}(t,x,u,p)=\sum_{j=1}^d a^{ji}(t,x)p_j$ and $a(t,x,u,p)=\sum_{i=1}^d b^i(t,x) p_i + c(t,x)u - q(t,x,u) + \int_0^\tau \alpha_s b_s(t,x)\,ds$, and thus also $A(t,x,u,p) = \sum_{i=1}^d b^i(t,x) p_i + c(t,x)u - q(t,x,u) + \int_0^\tau \alpha_s b_s(t,x)\,ds - \sum_{j=1}^d \fpartial{x_i}a^{ji}(t,x)p_j$.
    Clearly, for $(t,x)\in\overbar{D_T}$ and arbitrary $u$ it holds $\sum_{i,j=1}^d\fpartial{p_j} a_i(t,x,u,p)\xi_i\xi_j\big|_{p=0} = \sum_{i,j=1}^d a^{ji}(t,x)\xi_i\xi_j \geq \nu \N{\xi}^2\geq 0$
    by uniform parabolicity of $\fpartial{t}+\CL$, i.e., Assumption~\ref{asm:PDE_L_parabolicity},
    and it holds with Young's inequality 
    \begin{equation}
    \begin{split}
        &A(t,x,u,0)u
        = \left(c(t,x)u - q(t,x,u) + \int_0^\tau \alpha_s b_s(t,x)\,ds\right)u\\
        &\qquad\,\geq  -\!\N{c}_{L_\infty(D_T)}u^2 - C_q(1+\abs{u})\abs{u} + \frac{1}{2}\left(\int_0^\tau\! \alpha_s b_s(t,x)\,ds\right)^2 \!-\frac{1}{2}u^2
        \geq -b_1u^2-b_2\!\!
    \end{split}
    \end{equation}
    by Assumptions~\ref{asm:PDE_coefficients} and \ref{asm:WP_coefficients} for the first term, by Assumption~\ref{asm:WP_nonlinearity_q_growth} for the second term, and, for the last term, due to $\alpha_\tau$ being bounded from above together with $\sup_{\tau\in[0,\CT]} \N{b_\tau}_{L_\infty(D_T)}\leq C_b$ by assumption on $b$.
    Moreover, by Assumptions~\ref{asm:WP_coefficients} and \ref{asm:WP_nonlinearity_q_growth} the functions $a_{i}$ and $a$ are continuous w.r.t.\@ $t,x,u,p$ since again $b_\tau$ is continuous for every $\tau\in[0,\CT]$.
    Interchanging limits in the term $\int_0^\tau \alpha_s b_s(t,x)\,ds$ is warranted by the dominated convergence theorem since $\alpha_\tau$ is bounded from above and $\sup_{\tau\in[0,\CT]} \N{b_\tau}_{L_\infty(D_T)}\leq C_b$.
    In addition, the functions $a_{i}$ are differentiable w.r.t.\@ $x,u,p$ by Assumption~\ref{asm:WP_coefficients}.
    For $(t,x)\in\overbar{D_T}$, $\abs{u}\leq M$ and arbitrary $p$ we furthermore have
    \begin{equation}
    \begin{split}
        &\sum_{i=1}^d \left(\abs{a_i} + \abs{\fpartial{u}a_i}\right)(1+\N{p}) + \sum_{i,j=1}^d \abs{\fpartial{x_j} a_i} + \abs{a} \\
        &\qquad\,= \sum_{i=1}^d \abs{\sum_{j=1}^d a^{ji}(t,x)p_j} (1+\N{p}) + \sum_{i,j=1}^d \abs{\fpartial{x_j}\sum_{k=1}^d a^{ki}(t,x)p_k}\\
        &\qquad\,\quad\, + \abs{\sum_{i=1}^d b^i(t,x) p_i + c(t,x)u - q(t,x,u) + \int_0^\tau \alpha_s b_s(t,x)\,ds}
        \leq \mu (1+\N{p})^2,
    \end{split}
    \end{equation}
    where the last inequality holds due to Assumptions~\ref{asm:PDE_coefficients} and  \ref{asm:WP_nonlinearity_q_growth}, and due to the last term being uniformly bounded with the same arguments as above.
    Furthermore, for $(t,x)\in\overbar{D_T}$, $\abs{u}\leq M$ and $\N{p}\leq \widetilde{M}$, we have the following Hölder continuity properties in $(t,x,u,p)$ (we denote by $\star$ the exponent if the respective function does not depend on the variable, thus being Hölder continuous with any exponent):
    the functions $a_i$ are $(\gamma_1/2,\gamma_1,\star,1)$-Hölder continuous, 
    the functions $\partial_{p_j}a_i$ are $(\gamma_1/2,\gamma_1,\star,\star)$-Hölder continuous,
    the functions $\partial_{u}a_i$ are $(\star,\star,\star,\star)$-Hölder continuous,
    the functions $\partial_{x_i}a_i$ are $(\gamma_1/2,\gamma_1,\star,\star)$-Hölder continuous,
    and the function $a$ is $(\min\{\gamma_1/2,1\},\min\{\gamma_1,1\},1,1)$-Hölder continuous.
    The Hölder properties of all those functions are due to Assumption~\ref{asm:WP_coefficients}, except
    for the last function, where we further used that firstly $q$ is $(\gamma_1/2,\gamma_1,1)$-Hölder continuous in $(t,x,u)$ by Assumption~\ref{asm:WP_nonlinearity_q_growth} for $t,x$ and the mean-value theorem together with Assumption~\ref{asm:PDE_nonlinearity_q_ubdd} for $u$, and secondly that $b_\tau$ is $(1,1)$-Hölder continuous for every $\tau\in[0,\CT]$ by assumption together with $\alpha_\tau$ being bounded from above.
    Lastly, the boundary $\partial D$ and the initial condition~$f$ and boundary condition satisfy the assumptions due to Assumptions~\ref{asm:D} and \ref{asm:WP_initialcondition}, respectively. 
    Thus, \cite[Chapter V, Theorem 6.2]{ladyzhenskaia1968linear} ensures the existence of a solution~$\upt{\tau}\in H^{\gamma'/2,\gamma'}(\overbar{D_T})$ to \eqref{eq:parabolicPDE*_tilde} with $\partial_{x_i}\upt{\tau}$ being bounded in $\overbar{D_T}$.
    Since we are on a compact domain as of Assumptions~\ref{asm:WP_coefficients}, where Hölder continuity implies uniform boundedness, we proved $\upt{\tau}\in \CS$.
    \cite[Chapter V, Theorem 6.2]{ladyzhenskaia1968linear} further ensures that $\partial_t \upt{\tau} \in H^{\gamma'/2,\gamma'}(D_T)$, and thus also $\partial_t\uppt{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$ is proven.

    \textit{Step~1b: Existence of solution to adjoint PDE \eqref{eq:parabolicadjoint*_tilde}.}
    For the existence of a solution to the linear adjoint PDE \eqref{eq:parabolicadjoint*_tilde}, 
    we invoke the classical results \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial} as well as \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} with $p=2$.
    To this end, let us first reverse the adjoint parabolic backward PDE \eqref{eq:parabolicadjoint*_tilde} in time to obtain with a time transformation
    for $\uhatptReverted{\tau}=\uhatpptReverted{\tau}{t,x}=\uhatppt{\tau}{T-t,x}$ the parabolic forward PDE
    \begin{alignat}{2}
\label{eq:parabolicadjoint*_tildereverted}
    \begin{aligned}
     \fpartial{t}\uhatptReverted{\tau} + \underbar{\CL}^*\uhatptReverted{\tau} \!-\! \underbar{q}_u(\uppt{\tau}{T\!-\!\dummy,\dummy})\uhatptReverted{\tau}
        &= (\uppt{\tau}{T\!-\!\dummy,\dummy} \!-\! h(T\!-\!\dummy,\dummy))
        \qquad&&\text{in }
        D_T, \\
        \uhatptReverted{\tau}
        &= 0
        \qquad&&\text{on }
        [0,T]\times\partial D, \\
        \uhatptReverted{\tau}
        &= 0
        \qquad&&\text{on }
        \{0\}\times D, 
    \end{aligned}
    \end{alignat}
    where $\underbar{\CL}^*=\underbar{\CL}^*(t,x)=\CL^\dagger(T-t,x)$ (analogously for the individual coefficients of the operator $\underbar{\CL}^*$) and $\underbar{q}=\underbar{q}(t,x,\widehat{u})=q(T-t,x,\widehat{u})$.
    Since the parabolic PDE \eqref{eq:parabolicadjoint*_tildereverted} is linear,
    existence and uniqueness of a weak solution of \eqref{eq:parabolicadjoint*_tildereverted} in the sense of \Cref{def:weak_sol_adjoint} follow from classical results,
    see, e.g., \cite[Chapter~7.1, Theorem~3]{evans2010partial} and \cite[Chapter~7.1, Theorem~4]{evans2010partial} for existence and uniqueness, respectively.
    To apply those results, note that the term $\underbar{q}_u(\uppt{\tau}{T-\dummy,\dummy})\uhatptReverted{\tau}$ can be absorbed into a parabolic PDE operator ${\widetilde{\underbar{\CL}}}^*$ with $\widetilde{\underbar{c}} = \underbar{c} - \sum_{i=1}^d \fpartial{x_i}\underbar{b}^i-\underbar{q}_u(\uppt{\tau}{T-\dummy,\dummy})\in L_\infty(D_T)$ due to Assumptions~\ref{asm:PDE_coefficients} and \ref{asm:PDE_nonlinearity_q_ubdd}.
    Moreover, since $\upt{\tau}\in L_2(D_T)$ by the former statement and since $h\in L_2(D_T)$ by assumption, the right-hand side~$(\uppt{\tau}{T-\dummy,\dummy}-h(T-\dummy,\dummy))\in L_2(D_T)$.
    With this, we proved $\uhatpt{\tau}\in L_2([0,T],H^1(D)) \cap L_\infty([0,T],L_2(D))$.
    To prove additional regularity, we invoke \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} with $p=2$.
    We now notice that, in the notation of \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear}, the coefficients~$a_{ij}=\underbar{a}^{ij}$ of the linear PDE operator of the parabolic PDE~\eqref{eq:parabolicadjoint*_tildereverted} are bounded continuous functions in $D_T$ for all $i,j=1,\dots,d$ due to Assumptions~\ref{asm:PDE_coefficients} and \ref{asm:WP_coefficients},
    while the coefficients~$a_i=\underbar{b}^i-\sum_{j=1}^d\fpartial{x_j}\underbar{a}^{ji}$ and $a=\underbar{c} - \sum_{i=1}^d \fpartial{x_i}\underbar{b}^i - \underbar{q}_u(\uppt{\tau}{T-\dummy,\dummy})$ have finite norms $\N{a_i}_{L_r(D_T)}$ and $\N{a}_{L_s(D_T)}$ for any $r,s>0$.
    This is due to the uniform boundedness of the coefficients per Assumptions~\ref{asm:PDE_coefficients} and \ref{asm:PDE_nonlinearity_q_ubdd} combined with the boundedness of the domain per Assumption~\ref{asm:Dbdd}, see the subsequent computations with $T'=0$ and $\Delta T'=T$.
    Moreover, since it hold $\N{a_i}_{L_r(D_{T',T'+\Delta T'})} \leq \big(\Nnormal{b^i}_{L_\infty(D_T)}+\sum_{j=1}^d\Nnormal{\fpartial{x_j}a^{ji}}_{L_\infty(D_T)}\big)(\Delta T'\vol{D})^{1/r}$
    for all $i=1,\dots,d$ and
    $\Nnormal{a}_{L_s(D_{T',T'+\Delta T'})}\leq \big(\Nnormal{c}_{L_\infty(D_T)}+\sum_{i=1}^d\Nnormal{\fpartial{x_i}b^{i}}_{L_\infty(D_T)} + c_q\big)(\Delta T'\vol{D})^{1/s}$,
    $\N{a_i}_{L_r(D_{T',T'+\Delta T'})}$ and $\N{a}_{L_s(D_{T',T'+\Delta T'})}$ tend to zero as $\Delta T'\rightarrow0$.
    Furthermore, $\partial D$ is sufficiently smooth as of Assumption~\ref{asm:D}.
    The right-hand side $f=(\uppt{\tau}{T-\dummy,\dummy}-h(T-\dummy,\dummy))\in L_2(D_T)$ as argued before.
    Lastly, the initial and boundary conditions $\phi=0\in W^{1}_2(D)$ and $\Phi=0\in W^{3/4,3/2}_2(\partial D_T)$ satisfy the compatibility condition $\phi|_{\partial D}=\Phi|_{t=0}$.
    Thus, \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} ensures the existence of a unique solution~$\uhatptReverted{\tau}\in W^{1,2}_{2}(D_T)$ to \eqref{eq:parabolicadjoint*_tildereverted} and thus also a unique solution~$\uhatpt{\tau}\in W^{1,2}_{2}(D_T)$ to the parabolic backward PDE \eqref{eq:parabolicadjoint*_tilde}.
    We moreover have the bound
    \begin{equation}
        \Nbig{\uhatpt{\tau}}_{W^{1,2}_{2}(D_T)}
        = \Nbig{\uhatptReverted{\tau}}_{W^{1,2}_{2}(D_T)}
        \lesssim \N{\upt{\tau}}_{L_2(D_T)} + \N{h}_{L_2(D_T)}.
    \end{equation}

    In particular, since $\uhatpt{\tau}\in W^{1,2}_{2}(D_T)$, also $\partial_t\uhatppt{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$ is proven.

    \textit{Step~1c: Explicit norm bound for the solution to PDE system \eqref{eq:parabolicPDE*_tilde}--\eqref{eq:parabolicadjoint*_tilde}.}
    In this step, we compute explicit bounds on the norms $\N{\upt{\tau}}_{L_2([0,T],H^1(D))} + \N{\upt{\tau}}_{L_\infty([0,T],L_2(D))}$ as well as $\Nnormal{\uhatpt{\tau}}_{L_2([0,T],H^1(D))} + \Nnormal{\uhatpt{\tau}}_{L_\infty([0,T],L_2(D))}$, respectively.

    \textit{Step~1c(i): Energy estimate for solution to \eqref{eq:parabolicPDE*_tilde}.}
    For the norm of a solution to the nonlinear PDE \eqref{eq:parabolicPDE*_tilde} we conduct the following computations.
    We obtain by chain rule and by using that $\upt{\tau}$ is a weak solution to \eqref{eq:parabolicPDE*_tilde} in the sense of \Cref{def:weak_sol} that
    \begin{equation}
        \label{eq:proof:lem:parabolic_wellposedness:NORM_0}
    \begin{split}
        \fpartial{t}\Nbig{\uppt{\tau}{t,\dummy}}^2_{L_2(D)}
        &=2\big(\uppt{\tau}{t,\dummy},\fpartial{t}\uppt{\tau}{t,\dummy}\big)_{L_2(D)}
        = 
        2\big\langle\fpartial{t}\uppt{\tau}{t,\dummy},\uppt{\tau}{t,\dummy}\big\rangle_{H^{-1}(D),H_0^1(D)}\\
        &= - 2\CB\big[\uppt{\tau}{t,\dummy},\uppt{\tau}{t,\dummy};t\big]
        + 2\big(q(t,\dummy,\uppt{\tau}{t,\dummy}),\uppt{\tau}{t,\dummy}\big)_{L_2(D)}\\
        &\quad\,+ 2\big(\widetilde{g}_\tau(t,\dummy),\uppt{\tau}{t,\dummy}\big)_{L_2(D)},
    \end{split}
    \end{equation}
    where the second step is due to the dual pairing between $H^{-1}(D)$ and $H_0^1(D)$ coinciding with the $L_2(D)$ scalar product \cite[Chapter~5.9, Theorem 1(iii)]{evans2010partial} since $\uppt{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and since $\fpartial{t}\uppt{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$.
    For the weak solution property in the third step of \eqref{eq:proof:lem:parabolic_wellposedness:NORM_0} to hold, we note that $\upt{\tau}$ can be used as a test function in the weak formulation of~\eqref{eq:parabolicPDE*_tilde}, see \Cref{def:weak_sol}, since $\uppt{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$.
    To estimate the right-hand side of \eqref{eq:proof:lem:parabolic_wellposedness:NORM_0} from above,
    we consider each of the three terms separately.
    For the first term of \eqref{eq:proof:lem:parabolic_wellposedness:NORM_0}, by using the definition of the bilinear form $\CB$ as well as that by Assumption~\ref{asm:PDE_L_parabolicity} the PDE operator is uniformly parabolic and that by Assumption~\ref{asm:PDE_coefficients} the coefficients are in $L_\infty$, we can estimate with Cauchy-Schwarz and Young's inequality analogously to \eqref{eq:proof:lem:parabolic_uhatL2:21}
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_2}
    \begin{split}
        -\CB[\uppt{\tau}{t,\dummy},\uppt{\tau}{t,\dummy};t]
        &\!\leq\!
        -\frac{\nu}{2}\! \abs{\uppt{\tau}{t,\dummy}}^2_{H^1(D)}\!+\! \left(\frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}\!\!+\!\N{c}_{L_\infty(D_T)}\!\right)\!\N{\uppt{\tau}{t,\dummy}}^2_{L_2(D)}.
    \end{split}
    \end{equation}
    For the second term of \eqref{eq:proof:lem:parabolic_wellposedness:NORM_0}
    we can estimate with Assumption~\ref{asm:WP_nonlinearity_q_growth} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_3}
    \begin{split}
        \left(q(t,\dummy,\uppt{\tau}{t,\dummy}),\uppt{\tau}{t,\dummy}\right)_{L_2(D)}
        &\leq\N{q(t,\dummy,\uppt{\tau}{t,\dummy})}_{L_2(D)}\N{\uppt{\tau}{t,\dummy}}_{L_2(D)}\\
        &\leq C_q(1+\N{\uppt{\tau}{t,\dummy}}_{L_2(D)})\N{\uppt{\tau}{t,\dummy}}_{L_2(D)}\\
        & = C_q\left(\frac{1}{2} + \frac{3}{2}\N{\uppt{\tau}{t,\dummy}}_{L_2(D)}^2\right).
    \end{split}
    \end{equation}
    For the third and last term of \eqref{eq:proof:lem:parabolic_wellposedness:NORM_0}, by Cauchy-Schwarz and Young’s inequality we upper bound
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_4}
    \begin{split}
        \left(\widetilde{g}_\tau(t,\dummy),\uppt{\tau}{t,\dummy}\right)_{L_2(D)}
        &\leq \N{\widetilde{g}_\tau(t,\dummy)}_{L_2(D)}\N{\uppt{\tau}{t,\dummy}}_{L_2(D)}\\
        &\leq \frac{1}{2}\left(\N{\widetilde{g}_\tau(t,\dummy)}_{L_2(D)}^2 + \N{\uppt{\tau}{t,\dummy}}_{L_2(D)}^2\right).
    \end{split}
    \end{equation}
    Combining the bounds established in \eqref{eq:proof:lem:parabolic_wellposedness:NORM_2}--\eqref{eq:proof:lem:parabolic_wellposedness:NORM_4} and inserting them into \eqref{eq:proof:lem:parabolic_wellposedness:NORM_0}, we arrive after reordering at
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_5}
    \begin{split}        &\fpartial{t}\N{\uppt{\tau}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \abs{\uppt{\tau}{t,\dummy}}^2_{H^1(D)}
        \leq C\N{\uppt{\tau}{t,\dummy}}^2_{L_2(D)} + \N{\widetilde{g}_\tau(t,\dummy)}_{L_2(D)}^2 + C,
    \end{split}
    \end{equation}
    for a constant $C=C(\CL,q)$.
    An application of Grönwall's inequality shows
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_utilde}
        \N{\upt{\tau}}_{L_2([0,T],H^1(D))} + \N{\upt{\tau}}_{L_\infty([0,T],L_2(D))}
        \leq C\left(\N{f}_{L_2(D)} + \N{\widetilde{g}_\tau}_{L_2(D_T)} + 1\right)
    \end{equation}
    for some other, potentially larger, constant $C=C(T,\CL,q)$.
    Thus, in particular,
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_utilde_UNIFORM}
        \N{\upt{\tau}}_{\CV_\CT}
        \leq C\left(\N{f}_{L_2(D)} + \sup_{\tau\in[0,\CT]}\N{\widetilde{g}_\tau}_{L_2(D_T)} + 1\right).
    \end{equation}

    \textit{Step~1c(ii): Energy estimate for solution to \eqref{eq:parabolicadjoint*_tilde}.}
    For the norm of a solution to the PDE \eqref{eq:parabolicadjoint*_tilde} we proceed as follows using the time-reversed formulation \eqref{eq:parabolicadjoint*_tildereverted}.
    We obtain again by chain rule and by using that $\uhatptReverted{\tau}$ is a weak solution to \eqref{eq:parabolicPDE*_tilde} in the sense of \Cref{def:weak_sol_adjoint} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM2_1}
    \begin{split}        \fpartial{t}\Nnormal{\uhatpptReverted{\tau}{t,\dummy}}^2_{L_2(D)}        &=2\big(\uhatpptReverted{\tau}{t,\dummy},\fpartial{t}\uhatpptReverted{\tau}{t,\dummy}\big)_{L_2(D)}
        =         2\big\langle\fpartial{t}\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy}\big\rangle_{H^{-1}(D),H_0^1(D)}\\
        &= - 2\underbar{\CB}^*\big[\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy};t\big]
        + 2\big(\underbar{q}_u(t,\dummy,\uppt{\tau}{T-t,\dummy})\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy}\big)_{L_2(D)}\\
        &\quad\,+ 2\big(\uppt{\tau}{T-t,\dummy}-h(T-t,\dummy),\uhatpptReverted{\tau}{t,\dummy}\big)_{L_2(D)},
    \end{split}
    \end{equation}
    where the individual steps hold as before since $\uhatpptReverted{\tau}{t,\dummy}\in H_0^1(D)$ for a.e.\@ $t\in[0,T]$ and since $\fpartial{t}\uhatpptReverted{\tau}{t,\dummy}\in L_2(D)$ for a.e.\@ $t\in[0,T]$.
    To estimate the right-hand side of \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_1} from above,
    we consider each of the three terms separately.
    For the first term of \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_1}, by using the definition of the bilinear form $\CB^\dagger$ as well as that by Assumption~\ref{asm:PDE_L_parabolicity} the PDE operator is uniformly parabolic and that by Assumption~\ref{asm:PDE_coefficients} the coefficients are in $L_\infty$, we can estimate as in \eqref{eq:proof:lem:parabolic_wellposedness:NORM_2} that 
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM2_2}
    \begin{split}
        &-\underbar{\CB}^*\big[\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy};t\big]
        =-\CB^\dagger\big[\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy};T-t\big]
        =-\CB\big[\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy};T-t\big]\\
        &\qquad\qquad\,\leq -\frac{\nu}{2} \absnormal{\uhatpptReverted{\tau}{t,\dummy}}^2_{H^1(D)}+ \left(\frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}+\N{c}_{L_\infty(D_T)}\right)\Nnormal{\uhatpptReverted{\tau}{t,\dummy}}^2_{L_2(D)}.
    \end{split}
    \end{equation}
    For the second term of \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_1}
    we can estimate with Assumption~\ref{asm:PDE_nonlinearity_q_ubdd} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM2_3}
    \begin{split}
        \big(\underbar{q}_u(t,\dummy,\uppt{\tau}{T-t,\dummy})\uhatpptReverted{\tau}{t,\dummy},\uhatpptReverted{\tau}{t,\dummy}\big)_{L_2(D)}
        &\leq c_q\Nnormal{\uhatpptReverted{\tau}{t,\dummy}}_{L_2(D)}^2.
    \end{split}
    \end{equation}
    For the third and last term of \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_1}, by Cauchy-Schwarz and Young’s inequality we upper bound
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM2_4}
    \begin{split}
        &\big(\uppt{\tau}{T-t,\dummy}-h(T-t,\dummy),\uhatpptReverted{\tau}{t,\dummy}\big)_{L_2(D)}
        \leq \N{\uppt{\tau}{T-t,\dummy}-h(T-t,\dummy)}_{L_2(D)}\Nnormal{\uhatpptReverted{\tau}{t,\dummy}}_{L_2(D)}\\
        &\qquad\qquad\,\leq \frac{1}{2}\left(\N{\uppt{\tau}{T-t,\dummy}-h(T-t,\dummy)}_{L_2(D)}^2 + \Nnormal{\uhatpptReverted{\tau}{t,\dummy}}_{L_2(D)}^2\right).
    \end{split}
    \end{equation}
    Combining the bounds established in \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_2}--\eqref{eq:proof:lem:parabolic_wellposedness:NORM2_4} and inserting them into \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_1}, we arrive after reordering at
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM2_5}
    \begin{split}        &\fpartial{t}\Nnormal{\uhatpptReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \absnormal{\uhatpptReverted{\tau}{t,\dummy}}^2_{H^1(D)}
        \leq C\Nnormal{\uhatpptReverted{\tau}{t,\dummy}}^2_{L_2(D)} + \N{\uppt{\tau}{T-t,\dummy}-h(T-t,\dummy)}_{L_2(D)}^2,
    \end{split}
    \end{equation}
    for a constant $C=C(\CL,q)$.
    Recalling that $\Nnormal{\uhatpptReverted{\tau}{0,\dummy}}^2_{L_2(D)} =0$, an application of Grönwall's inequality shows
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:NORM_uhattilde}
    \begin{split}
        \Nnormal{\uhatpt{\tau}}_{L_2([0,T],H^1(D))} + \Nnormal{\uhatpt{\tau}}_{L_\infty([0,T],L_2(D))}
        &= \Nnormal{\uhatptReverted{\tau}}_{L_2([0,T],H^1(D))} + \Nnormal{\uhatptReverted{\tau}}_{L_\infty([0,T],L_2(D))} \\
        &\leq C\N{\upt{\tau}-h}_{L_2(D_T)}
        \leq C\left(\N{\upt{\tau}}_{L_2(D_T)} + \N{h}_{L_2(D_T)}\right)
    \end{split}
    \end{equation}
    for some other, potentially larger, constant $C=C(T,\CL,q)$.
    Thus, in particular,
    \begin{equation}       \label{eq:proof:lem:parabolic_wellposedness:NORM_uhattilde_UNIFORM}
        \Nnormal{\uhatpt{\tau}}_{\CV_\CT}
        \leq C\left(\N{\upt{\tau}}_{\CV_\CT} + \N{h}_{L_2(D_T)}\right).
    \end{equation}

    \textit{Step~1d: Existence of solution to PDE system \eqref{eq:parabolicPDE*_tilde}--\eqref{eq:parabolicadjoint*_tilde}.}
    Summarizing the former results from \textit{Steps~1a, 1b} and \textit{1c}
    we thus proved that for each $\tau\in[0,\CT]$ there exists a solution $(\upt{\tau},\uhatpt{\tau})\in \CS\times\CS$ to \eqref{eq:parabolicPDE*_tilde}--\eqref{eq:parabolicadjoint*_tilde}.
    As $\widetilde{g}_{\tau}$ is Lipschitz continuous in $\tau$ by the dominated convergence theorem, which can be seen since
    \begin{equation}
        \N{\widetilde{g}_{\tau_2} - \widetilde{g}_{\tau_1}}_{L_2(D_T)}
        = \N{\int_{\tau_1}^{\tau_2} \alpha_s b_s\,ds}_{L_2(D_T)}
        \leq C \int_{\tau_1}^{\tau_2} \N{b_s}_{L_\infty(D_T)} ds
        \leq C\abs{\tau_2-\tau_1}
    \end{equation}
    for a constant $C=C(\alpha,T,D,C_b)$,
    the solution $(\upt{},\uhatpt{})$ is in particular continuous in the training time $\tau$, i.e., $(\upt{},\uhatpt{})\in \CV_\CT\times\CV_\CT$.
    As we further showed, for each $\tau\in[0,\CT]$ such solution satisfies $(\partial_t\uppt{\tau}{t,\dummy},\partial_t\uhatppt{\tau}{t,\dummy})\in L_2(D) \times L_2(D)$
    for a.e.\@ $t\in[0,T]$.

    \textit{Step~2: Existence for specific right-hand side $\widetilde{g}_\tau = g^*_\tau= - \int_0^\tau \alpha_s T_{B_0}\uhatp{s}\,ds$.}
    We now make a specific choice for the functions $b_\tau$.

    \textit{Step~2a: Choice of right-hand side $\widetilde{g}_\tau = g^*_\tau= - \int_0^\tau \alpha_s T_{B_0}\uhatp{s}\,ds$.}
    For an arbitrarily given $\uhatp{\tau}\in \CS$, $\tau\in[0,\CT]$, with $\sup_{\tau\in[0,\CT]} \N{\uhatp{\tau}}_{L_2(D_T)}\leq M$ ($M$ may depend on $\CT$) 
    we set $b_\tau = T_{B_0}\uhatp{\tau}$ for all $\tau\in[0,\CT]$.
    It holds with \Cref{lem:parabolicTB} that
    \begin{equation}
    \begin{split}
        \N{b_\tau}_{L_2(D_T)}
        &= \N{T_{B_0}\uhatp{\tau}}_{L_2(D_T)}\leq C^B_2 \N{\uhatp{\tau}}_{L_2(D_T)} 
        \leq C^B_2 M,
    \end{split}
    \end{equation}
    which is a uniform bound in $\tau$.
    In fact, a more careful estimate employing \Cref{lem:TBboundednessLinfty} shows
    \begin{equation}
    \begin{split}
        \N{b_\tau}_{L_\infty(D_T)}
        &= \N{T_{B_0}\uhatp{\tau}}_{L_\infty(D_T)}
        =\sup_{(t,x)\in D_T}\absbig{[T_{B_0}\uhatp{\tau}](t,x)}
        \leq C^{T_B}_\infty \N{\uhatp{\tau}}_{L_2(D_T)}
        \leq C^{T_B}_\infty M.
    \end{split}
    \end{equation}
    Since the right-hand side is uniform in $\tau$, $\sup_{\tau\in[0,\CT]} \N{b_\tau}_{L_\infty(D_T)} \leq C$, where $C$ may depend on $\CT$.
    Furthermore, it is immediate to see, that using the definition of $T_{B_0}$ in \eqref{eq:parabolicT_B} and that the kernel $B$ as given in \eqref{eq:parabolicB} is continuous in $t,x$ on $\overbar{D_T}$, the function $b_\tau=T_{B_0}\uhatp{\tau}$ is continuous on $\overbar{D_T}$ for each $\tau\in[0,\CT]$ by the dominated convergence theorem.
    In fact, the function $b_\tau=T_{B_0}\uhatp{\tau}$ is Lipschitz continuous on $\overbar{D_T}$ since it holds by \Cref{lem:TBLipschitz} that
    \begin{equation}
    \begin{split}
        \abs{b_\tau(t^1,x^1)\!-\!b_\tau(t^2,x^2)}
        &= \abs{[T_{B_0}\uhatp{\tau}](t^1,x^1)\!-\![T_{B_0}\uhatp{\tau}](t^2,x^2)} 
        \leq L_{T_B}\! \left(\abs{t^1\!-\!t^2} \!+\! \N{x^1\!-\!x^2}\right)\!\!
    \end{split}
    \end{equation}
    for all $(t^1,x^1),(t^2,x^2)\in\overbar{D_T}$.

    \textit{Step~2b: Definition of fixed point mapping.}
    Let us consider the fixed point map
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:F}
        F: \CV_\CT\times\CV_\CT \rightarrow \CV_\CT\times\CV_\CT,\quad
        (\up{},\uhatp{})\mapsto(\upt{},\uhatpt{})
    \end{equation}
    and define for given $M<\infty$ and $\CT<\infty$ the function space $\CV_\CT(M)=\{u\in\CV_\CT\!:\!\N{u}_{\CV_\CT}\leq M\}$.

    We will first show in \textit{Step~2d} existence locally in the training time by proving that there exist $M_0>0$ and $\CT_0>0$ such that $F$ is a fixed point mapping on $\CV_{\CT_0}(M_0)\times\CV_{\CT_0}(M_0)$, which allows to apply the Banach fixed point theorem.
    In \textit{Step~2e} we will then extend the proof by a bootstrapping argument to any given (arbitrarily large) time horizon~$\CT$.

    \textit{Step~2c: Preliminary computations.}
    Let us start by conducting some preliminary computations on a generic space $\CV_{\widetilde{\CT}}(\widetilde{M})\times \CV_{\widetilde{\CT}}(\widetilde{M})$.

    \textit{Step~2c(i): Preliminary computations for self-mapping property of $F$.}
    Consider $(\upt{},\uhatpt{})$ together with its corresponding $(\up{},\uhatp{}) \in \CV_{\widetilde{\CT}}(\widetilde{M})\times \CV_{\widetilde{\CT}}(\widetilde{M})$.
    Using \eqref{eq:proof:lem:parabolic_wellposedness:NORM_utilde_UNIFORM} and \eqref{eq:proof:lem:parabolic_wellposedness:NORM_uhattilde_UNIFORM} in the first inequality and \Cref{lem:parabolicTB} in the last step, we establish
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:SELFMAPPING}
    \begin{split}
        &\N{\upt{}}_{\CV_{\widetilde{\CT}}(\widetilde{M})} + \Nnormal{\uhatpt{}}_{\CV_{\widetilde{\CT}}(\widetilde{M})}
        \leq C\sup_{\tau\in[0,\widetilde{\CT}]} \N{\widetilde{g}_\tau}_{L_2(D_T)} + C\left(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1\right)\\ 
        &\qquad\,\leq C\sup_{\tau\in[0,\widetilde{\CT}]} \N{\int_0^\tau \alpha_s T_{B_0}\uhatp{s}\,ds}_{L_2(D_T)} + C\left(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1\right)\\
        &\qquad\,\leq C \int_0^{\widetilde{\CT}} \N{\alpha_s T_{B_0}\uhatp{s}}_{L_2(D_T)}ds + C\left(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1\right)\\
        &\qquad\,\leq C_1 \int_0^{\widetilde{\CT}} \N{\uhatp{s}}_{L_2(D_T)}ds + C_1\left(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1\right)
    \end{split}
    \end{equation}
    for a constant $C_1=C_1(\alpha,\CL,q,C^B_2)$ (to be precise, $C_1=C\max\{\alpha_0C^B_2,1\}$).

    \textit{Step~2c(ii): Preliminary computations for contractivity of $F$.}
    Consider two pairs $(\uptu{}{1},\uhatptu{}{1})$, $(\uptu{}{2},\uhatptu{}{2})$ with their corresponding $(\upu{}{1},\uhatpu{}{1}), (\upu{}{2},\uhatpu{}{2}) \in \CV_{\widetilde{\CT}}(\widetilde{M})\times \CV_{\widetilde{\CT}}(\widetilde{M})$.

    \textit{A bound for $\Nnormal{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_2([0,T],H^1(D))} + \Nnormal{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty([0,T],L_2(D))}$.}
    Since both $\uptu{\tau}{1}$ and $\uptu{\tau}{2}$ weakly satisfy \eqref{eq:parabolicPDE*_tilde} in the sense of \Cref{def:weak_sol},
    it weakly holds
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1}        \fpartial{t}\left(\uptu{\tau}{1}-\uptu{\tau}{2}\right) + \CL\left(\uptu{\tau}{1}-\uptu{\tau}{2}\right) - \left(q(\uptu{\tau}{1})-q(\uptu{\tau}{2})\right) = \widetilde{g}_\tau^1-\widetilde{g}_\tau^2
    \end{equation}
    with zero initial and zero boundary conditions.
    We obtain by chain rule and by using that $\uptu{\tau}{1}-\uptu{\tau}{2}$ is a weak solution to \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1} in the sense of \Cref{def:weak_sol} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu2}
    \begin{split}        &\fpartial{t}\N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}^2_{L_2(D)}\\        &\qquad\,=2\left(\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy},\fpartial{t}\left(\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right)\right)_{L_2(D)}\\
        &\qquad\,= 
        2\left\langle\fpartial{t}\left(\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right),\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right\rangle_{H^{-1}(D),H_0^1(D)}\\
        &\qquad\,= - 2\CB[\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy},\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy};t]\\
        &\qquad\,\quad\,+ 2\left(q(t,\dummy,\upptu{\tau}{1}{t,\dummy})-q(t,\dummy,\upptu{\tau}{2}{t,\dummy}),\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right)_{L_2(D)}\\
        &\qquad\,\quad\,+ 2\left(\widetilde{g}_\tau^1(t,\dummy)-\widetilde{g}_\tau^2(t,\dummy),\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right)_{L_2(D)},
    \end{split}
    \end{equation}
    where the individual steps hold as previously described.
    To estimate the right-hand side of \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu2} from above,
    we consider each of the three terms separately.
    For the first term, by using the definition of the bilinear form $\CB$ as well as that by Assumption~\ref{asm:PDE_L_parabolicity} the PDE operator is uniformly parabolic and that by Assumption~\ref{asm:PDE_coefficients} the coefficients are in $L_\infty$, we can estimate as in \eqref{eq:proof:lem:parabolic_wellposedness:NORM_2} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu3}
    \begin{split}
        &-\CB[\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy},\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy};t]\\
        &\qquad\,\leq -\frac{\nu}{2} \abs{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}^2_{H^1(D)}\\
        &\qquad\,\quad\,+ \left(\frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}+\N{c}_{L_\infty(D_T)}\right)\N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}^2_{L_2(D)}.
    \end{split}
    \end{equation}
    For the second term, we first note that by the mean-value theorem, for any $(t,x)\in D_T$ there exists a $\xi(t,x)$ such that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu4aux}
    \begin{split}
        q(t,x,\upptu{\tau}{1}{t,x})-q(t,x,\upptu{\tau}{2}{t,x})
        = q_u(t,x,\xi(t,x))\left(\upptu{\tau}{1}{t,x}-\upptu{\tau}{2}{t,x}\right).
    \end{split}
    \end{equation}
    Leveraging this while using that by Assumption~\ref{asm:PDE_nonlinearity_q_ubdd}  $q_u$ is bounded,
    we can estimate
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu4}
    \begin{split}
        &\left(q(t,\dummy,\upptu{\tau}{1}{t,\dummy})-q(t,\dummy,\upptu{\tau}{2}{t,\dummy}),\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right)_{L_2(D)}\\
        &\qquad\,= \int_D \left(q_u(t,x,\xi(t,x))\left(\upptu{\tau}{1}{t,x}-\upptu{\tau}{2}{t,x}\right)\right)\left(\upptu{\tau}{1}{t,x}-\uppu{\tau}{2}{t,x}\right) dx\\
        &\qquad\,\leq c_q\int_D \left(\upptu{\tau}{1}{t,x}-\uppu{\tau}{2}{t,x}\right)^2 dx
        = c_q \N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}_{L_2(D)}^2.
    \end{split}
    \end{equation}
    For the third and last term, by Cauchy-Schwarz and Young’s inequality we upper bound
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu5}
    \begin{split}
        &\left(\widetilde{g}_\tau^1(t,\dummy)-\widetilde{g}_\tau^2(t,\dummy),\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}\right)_{L_2(D)} \\
        &\qquad\,\leq \N{\widetilde{g}_\tau^1(t,\dummy)-\widetilde{g}_\tau^2(t,\dummy)}_{L_2(D)}\N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}_{L_2(D)}\\
        &\qquad\,\leq \frac{1}{2}\left(\N{\widetilde{g}_\tau^1(t,\dummy)-\widetilde{g}_\tau^2(t,\dummy)}_{L_2(D)}^2 + \N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}_{L_2(D)}^2\right).
    \end{split}
    \end{equation}
    Combining the bounds established in \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu3}--\eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu5} and inserting them into \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu2},
    we arrive after reordering at
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu6}
    \begin{split}        &\fpartial{t}\N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \abs{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}^2_{H^1(D)}\\
        &\qquad\,\leq C\N{\upptu{\tau}{1}{t,\dummy}-\upptu{\tau}{2}{t,\dummy}}^2_{L_2(D)} + \N{\widetilde{g}_\tau^1(t,\dummy)-\widetilde{g}_\tau^2(t,\dummy)}_{L_2(D)}^2,
    \end{split}
    \end{equation}
    for a constant $C=C(\CL,q)$.
    Recalling that $\upptu{\tau}{1}{0,\dummy}=\upptu{\tau}{2}{0,\dummy}$, an application of Grönwall's inequality shows
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_utilde}
        \N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_2([0,T],H^1(D))} + \N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty([0,T],L_2(D))}
        \leq C\N{\widetilde{g}_\tau^1-\widetilde{g}_\tau^2}_{L_2(D_T)}
    \end{equation}
    for some other, potentially larger, constant $C=C(T,\CL,q)$.
    Thus, in particular,
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_utilde_UNIFORM}
        \N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{\CV_\CT}
        \leq C\sup_{\tau\in[0,\CT]}\N{\widetilde{g}_\tau^1-\widetilde{g}_\tau^2}_{L_2(D_T)}.
    \end{equation}

    \textit{A bound for $\Nnormal{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty(D_T)}$.}
    For later use, let us further provide an $L_\infty$ bound for the weak solution to \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1} by employing Morrey's inequality after leveraging \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} for any $p>1$.
    Therefore notice, that by the mean-value theorem, for any $(t,x)\in D_T$ there exists a $\xi(t,x)$ such that, in place of \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1}, it weakly holds
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1_aux}        \fpartial{t}\left(\uptu{\tau}{1}-\uptu{\tau}{2}\right) + \CL\left(\uptu{\tau}{1}-\uptu{\tau}{2}\right) - q_u(\xi)\left(\uptu{\tau}{1}-\uptu{\tau}{2}\right) = \widetilde{g}_\tau^1-\widetilde{g}_\tau^2
    \end{equation}
    with zero initial and zero boundary conditions.
    We now notice that, in the notation of \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear}, the coefficients~$a_{ij}(t,x)=a^{ij}(t,x)$ of the linear PDE operator of the parabolic PDE~\eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1_aux} are bounded continuous functions in $D_T$ for all $i,j=1,\dots,d$,
    while the coefficients~$a_i(t,x)=b^i(t,x)-\sum_{j=1}^d\fpartial{x_j}a^{ji}(t,x)$ and $a(t,x)=c(t,x) - \sum_{i=1}^d \fpartial{x_i}b^i(t,x) - q_u(t,x,\xi(t,x))$ have finite norms $\N{a_i}_{L_r(D_T)}$ and $\N{a}_{L_s(D_T)}$ for any $r,s>0$.
    This is due to the uniform boundedness of the coefficients per Assumptions~\ref{asm:PDE_coefficients} and \ref{asm:PDE_nonlinearity_q_ubdd} combined with the boundedness of the domain per Assumption~\ref{asm:Dbdd}, see the subsequent computations with $T'=0$ and $\Delta T'=T$.
    Moreover, since it hold
    $\Nnormal{a_i}_{L_r(D_{T',T'+\Delta T'})}\leq \big(\Nnormal{b^i}_{L_\infty(D_T)}+\sum_{j=1}^d\Nnormal{\fpartial{x_j}a^{ji}}_{L_\infty(D_T)}\big)(\Delta T'\vol{D})^{1/r}$
    for all $i=1,\dots,d$ and
    $\Nnormal{a}_{L_s(D_{T',T'+\Delta T'})}\leq \big(\Nnormal{c}_{L_\infty(D_T)}+\sum_{i=1}^d\Nnormal{\fpartial{x_i}b^{i}}_{L_\infty(D_T)} + c_q\big)(\Delta T'\vol{D})^{1/s}$,
    $\N{a_i}_{L_r(D_{T',T'+\Delta T'})}$ and $\N{a}_{L_s(D_{T',T'+\Delta T'})}$ tend to zero as $\Delta T'\rightarrow0$.
    Furthermore, $\partial D$ is sufficiently smooth as of Assumption~\ref{asm:D}.
    The right-hand side $f=\widetilde{g}_\tau^1-\widetilde{g}_\tau^2\in L_p(D_T)$ for any $p\geq2$ since
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty3}
    \begin{split}
        &\N{\widetilde{g}_\tau^1-\widetilde{g}_\tau^2}_{L_p(D_T)}
        = \N{\int_0^\tau \alpha_s T_{B_0}(\uhatpu{s}{1}-\uhatpu{s}{2})\,ds}_{L_p(D_T)} \\
        &\quad\,\leq \alpha_0 \int_0^\tau \!\N{T_{B_0}(\uhatpu{s}{1}\!-\!\uhatpu{s}{2})}_{L_p(D_T)}ds 
        = \alpha_0 \int_0^\tau\! \left(\int_0^T\!\!\!\int_D \absbig{[T_{B_0}(\uhatpu{s}{1}\!-\!\uhatpu{s}{2})](t,x)}^p\,dxdt\right)^{1/p} \!ds \\
        &\quad\,\leq \alpha_0C_\infty^{T_B} \int_0^\tau \left(\int_0^T\!\!\!\int_D \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)}^p\,dxdt\right)^{1/p} ds \\
        &\quad\,= \alpha_0C_\infty^{T_B}(T\vol{D})^{1/p} \int_0^\tau \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds\\
        &\quad\,\leq \alpha_0\CT C_\infty^{T_B}(T\vol{D})^{1/p} \sup_{\tau\in[0,\CT]}\N{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_2(D_T)} ds,
    \end{split}
    \end{equation}
    where we used \Cref{lem:TBboundednessLinfty} in the third line.
    Moreover, the initial and boundary conditions $\phi=0\in W^{2-2/p}_p(D)$ and $\Phi=0\in W^{1-1/(2p),2-1/p}_p(\partial D_T)$ satisfy the compatibility condition $\phi|_{\partial D}=\Phi|_{t=0}$.
    Thus, \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} ensures that the unique solution~$(\uptu{\tau}{1}-\uptu{\tau}{2})\in W^{1,2}_{p}(D_T)$ to    \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1_aux} and thus \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYu1} obeys the bound
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty4}
    \begin{split}
        \N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{W^{1,2}_{p}(D_T)}
        &\leq C\N{\widetilde{g}_\tau^1-\widetilde{g}_\tau^2}_{L_p(D_T)} 
    \end{split}
    \end{equation}
    for a constant $C=C(T,\CL,q)$.

    With the conditions of \cite[Chapter IV, Theorem 9.1]{ladyzhenskaia1968linear} being fulfilled for any $p\geq2$ as we verified before, they are in particular fulfilled for $p>d+1$.
    Since we have for such $p$ the continuous embedding $W^{1,2}_{p}(D_{T})\hookrightarrow W^{1,1}_{p}(D_{T})\hookrightarrow L_{\infty}(\overbar{D}_T)$ by Morrey's inequality~\cite[Theorem 9.12]{brezis2011functional}, we have the first inequality in
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty5}
    \begin{split}
        \N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty(D_T)}
        &\leq c(d,p)\N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{W^{1,2}_{p}(D_T)}
        \leq c(d,p)C\N{\widetilde{g}_\tau^1-\widetilde{g}_\tau^2}_{L_p(D_T)},
    \end{split}
    \end{equation}
    with the second one being due to \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty4}.
    Hence, using the last two lines of \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty3}, we have 
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty6}
    \begin{split}
        \N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty(D_T)}
        &\leq C \int_0^\tau \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds \\
        &\leq C \CT \sup_{\tau\in[0,\CT]}\N{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_2(D_T)} ds,
    \end{split}
    \end{equation}
    for a constant $C=C(\alpha,T,D,\CL,q,C^{T_B}_\infty)$.

    \textit{A bound for $\Nnormal{\uhatptu{\tau}{1}-\uhatptu{\tau}{2}}_{L_2([0,T],H^1(D))} + \Nnormal{\uhatptu{\tau}{1}-\uhatptu{\tau}{2}}_{L_\infty([0,T],L_2(D))}$.}
    Since both $\uhatptu{\tau}{1}$ and $\uhatptu{\tau}{2}$ weakly satisfy \eqref{eq:parabolicadjoint*_tilde} in the sense of \Cref{def:weak_sol_adjoint},
    it weakly holds
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat1'}
        -\fpartial{t}\big(\uhatptu{\tau}{1}-\uhatptu{\tau}{2}\big) + \CL^\dagger\big(\uhatptu{\tau}{1}-\uhatptu{\tau}{2}\big) - \big(q_u(\uptu{\tau}{1})\uhatptu{\tau}{1}-q_u(\uptu{\tau}{2})\uhatptu{\tau}{2}\big)
        = \uptu{\tau}{1}-\uptu{\tau}{2}
    \end{equation}
    with zero terminal and zero boundary conditions,
    or equivalently
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat1}
    \begin{split}
        -&\fpartial{t}\big(\uhatptu{\tau}{1}-\uhatptu{\tau}{2}\big) + \CL^\dagger\big(\uhatptu{\tau}{1}-\uhatptu{\tau}{2}\big) - \big(q_u(\uptu{\tau}{1})\big(\uhatptu{\tau}{1}-\uhatptu{\tau}{2}\big)\big)\\
        &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\;\;= (\uptu{\tau}{1}-\uptu{\tau}{2}) + \big(q_u(\uptu{\tau}{1})-q_u(\uptu{\tau}{2})\big)\uhatptu{\tau}{2}.
    \end{split}
    \end{equation}
    Let us now first reverse \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat1} in time to obtain with a time transformation
    for $\uhatptuReverted{\tau}{k}=\uhatpptuReverted{\tau}{k}{t,x}=\uhatpptu{\tau}{k}{T-t,x}$ for $k=1,2$ the parabolic forward PDE
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat1reverted}
    \begin{split}        &\fpartial{t}\big(\uhatptuReverted{\tau}{1}-\uhatptuReverted{\tau}{2}\big) + \underbar{\CL}^*\big(\uhatptuReverted{\tau}{1}-\uhatptuReverted{\tau}{2}\big) - \big(\underbar{q}_u(\upptu{\tau}{1}{T-\dummy,\dummy})\big(\uhatptuReverted{\tau}{1}-\uhatptuReverted{\tau}{2}\big)\big)\\
        &\quad\,= (\upptu{\tau}{1}{T-\dummy,\dummy}-\upptu{\tau}{2}{T-\dummy,\dummy}) + \big(\underbar{q}_u(\upptu{\tau}{1}{T-\dummy,\dummy})-\underbar{q}_u(\upptu{\tau}{2}{T-\dummy,\dummy})\big)\uhatptuReverted{\tau}{2}
    \end{split}
    \end{equation}
    with zero initial and zero boundary conditions.
    We obtain by chain rule and by using that $\uhatptuReverted{\tau}{1}-\uhatptuReverted{\tau}{2}$ is a weak solution to \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat1reverted} in the sense of \Cref{def:weak_sol_adjoint} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat2}
    \begin{split}        &\fpartial{t}\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}^2_{L_2(D)}\\       &\quad\,=2\big(\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy},\fpartial{t}\big(\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big)\big)_{L_2(D)}\\
        &\quad\,=        2\big\langle\fpartial{t}\big(\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big),\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big\rangle_{H^{-1}(D),H_0^1(D)}\\
        &\quad\,= - 2\underbar{\CB}^*\big[\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy},\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy};t\big]\\
        &\quad\,\quad\,+ 2\big(\underbar{q}_u(t,\dummy,\upptu{\tau}{1}{T\!-\!t,\dummy})\big(\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big),\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big)_{L_2(D)}\\
        &\quad\,\quad\,+ 2\big(\upptu{\tau}{1}{T\!-\!t,\dummy}-\upptu{\tau}{2}{T\!-\!t,\dummy},\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big)_{L_2(D)}\\
        &\quad\,\quad\,+ 2\big(\big(\underbar{q}_u(t,\dummy,\upptu{\tau}{1}{T\!-\!t,\dummy})-\underbar{q}_u(t,\dummy,\upptu{\tau}{2}{T\!-\!t,\dummy})\big)\uhatpptuReverted{\tau}{2}{t,\dummy},\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big)_{L_2(D)},\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!
    \end{split}
    \end{equation}
    where the individual steps hold as previously described.
    To estimate the right-hand side of \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat2} from above,
    we consider each of the four terms separately.
    For the first term, by using the definition of the bilinear form $\CB$ as well as that by Assumption~\ref{asm:PDE_L_parabolicity} the PDE operator is uniformly parabolic and that by Assumption~\ref{asm:PDE_coefficients} the coefficients are in $L_\infty$, we can estimate as in \eqref{eq:proof:lem:parabolic_wellposedness:NORM2_2} that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat3}
    \begin{split}
        &-\underbar{\CB}^*\big[\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy},\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy};t\big]\\
        &\qquad\,\leq -\frac{\nu}{2} \absbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}^2_{H^1(D)}\\
        &\qquad\,\quad\,+ \left(\frac{1}{2\nu} \sum_{i=1}^d\N{b^i}_{L_\infty(D_T)}+\N{c}_{L_\infty(D_T)}\right)\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}^2_{L_2(D)}.
    \end{split}
    \end{equation}
    For the second term, using that by Assumption~\ref{asm:PDE_nonlinearity_q_ubdd}  $q_u$ is bounded,
    we can estimate directly
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat4}
    \begin{split}
        &\big(\underbar{q}_u(t,\dummy,\upptu{\tau}{1}{T-t,\dummy})\big(\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big),\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big)_{L_2(D)}\\
        &\qquad\, \leq c_q \Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2.
    \end{split}
    \end{equation}

    For the third term, by Cauchy-Schwarz and Young’s inequality we upper bound
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat5}
    \begin{split}
        &\big(\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy},\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}\big)_{L_2(D)} \\
        &\qquad\,\leq \N{\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy}}_{L_2(D)}\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\\
        &\qquad\,\leq \frac{1}{2}\left(\N{\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy}}_{L_2(D)}^2 + \Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2\right).
    \end{split}
    \end{equation}

    For the fourth and final term, we first note that by the mean-value theorem, for any $(t,x)\in D_T$ there exists a $\xi(t,x)$ such that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat6aux}
    \begin{split}
        \underbar{q}_u(t,x,\upptu{\tau}{1}{T\!-\!t,x})\!-\!\underbar{q}_u(t,x,\upptu{\tau}{2}{T\!-\!t,x})
        = \underbar{q}_{uu}(t,x,\xi(t,x))\left(\upptu{\tau}{1}{T\!-\!t,x}\!-\!\upptu{\tau}{2}{T\!-\!t,x}\right).
    \end{split}
    \end{equation}

    Leveraging this while using that by Assumption~\ref{asm:PDE_nonlinearity_q_uubdd}  $q_{uu}$ is bounded,
    we can estimate by Cauchy-Schwarz and Young’s inequality
    \begin{equation}       \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat6}
    \begin{split}
        &\big(\big(\underbar{q}_u(t,\dummy,\upptu{\tau}{1}{T\!-\!t,\dummy})\!-\!\underbar{q}_u(t,\dummy,\upptu{\tau}{2}{T\!-\!t,\dummy})\big)\uhatpptuReverted{\tau}{2}{t,\dummy},\uhatpptuReverted{\tau}{1}{t,\dummy}\!-\!\uhatpptuReverted{\tau}{2}{t,\dummy}\big)_{L_2(D)} \\
        &\,\leq \Nbig{\big(\underbar{q}_u(t,\dummy,\upptu{\tau}{1}{T\!-\!t,\dummy})\!-\!\underbar{q}_u(t,\dummy,\upptu{\tau}{2}{T\!-\!t,\dummy})\big)\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}\!-\!\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\\
        &\,\leq \Nbig{\underbar{q}_u(t,\dummy,\upptu{\tau}{1}{T\!-\!t,\dummy})\!-\!\underbar{q}_u(t,\dummy,\upptu{\tau}{2}{T\!-\!t,\dummy})}_{L_\infty(D)}\Nbig{\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}\!-\!\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\\
        &\,\leq c_q'\Nbig{\upptu{\tau}{1}{T\!-\!t,\dummy}\!-\!\upptu{\tau}{2}{T\!-\!t,\dummy}}_{L_\infty(D)}\Nbig{\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}\!-\!\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}\\
        &\,\leq \frac{1}{2} \left(\Nbig{\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2\Nbig{\upptu{\tau}{1}{T\!-\!t,\dummy}\!-\!\upptu{\tau}{2}{T\!-\!t,\dummy}}_{L_\infty(D)}^2 \!+\! (c_q')^2\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}\!-\!\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2\right).
    \end{split}
    \end{equation}

    Combining the bounds established in \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat3}--\eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat6} and inserting them into \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat2},
    we arrive after reordering at
    \begin{equation}       \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuhat7}
    \begin{split}        &\fpartial{t}\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}^2_{L_2(D)} + \frac{\nu}{2} \absbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}^2_{H^1(D)}\\
        &\qquad\,\leq C\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2 + \N{\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy}}_{L_2(D)}^2 \\
        &\qquad\,\qquad\, + \Nbig{\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2 \N{\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy}}_{L_\infty(D)}^2\\
        &\qquad\,\leq C\Nbig{\uhatpptuReverted{\tau}{1}{t,\dummy}-\uhatpptuReverted{\tau}{2}{t,\dummy}}_{L_2(D)}^2 + \N{\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy}}_{L_2(D)}^2 \\
        &\qquad\,\qquad\, + \Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))}^2 \N{\upptu{\tau}{1}{T-t,\dummy}-\upptu{\tau}{2}{T-t,\dummy}}_{L_\infty(D)}^2
    \end{split}
    \end{equation}
    for a constant $C=C(\CL,q)$.
    Recalling that $\uhatpptu{\tau}{1}{0,\dummy}=\uhatpptu{\tau}{2}{0,\dummy}$, an application of Grönwall's inequality shows
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_uhattilde}
    \begin{split}
        &\Nbig{\uhatptu{\tau}{1}-\uhatptu{\tau}{2}}_{L_2([0,T],H^1(D))} + \Nbig{\uhatptu{\tau}{1}-\uhatptu{\tau}{2}}_{L_\infty([0,T],L_2(D))} \\
        &\qquad\,\leq C\left(\N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_2(D_T)} + \Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))}\N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty(D_T)}\right)
    \end{split}
    \end{equation}
    for some other, potentially larger, constant $C=C(T,\CL,q)$.
    Thus, in particular,
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_uhattilde_UNIFORM}
    \begin{split}
        &\Nbig{\uhatptu{}{1}\!-\!\uhatptu{}{2}}_{\CV_\CT}\\
        &\qquad\,\leq C\left(\sup_{\tau\in[0,\CT]}\!\N{\uptu{\tau}{1}\!-\!\uptu{\tau}{2}}_{L_2(D_T)} \!+\!\!\! \sup_{\tau\in[0,\CT]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))}\!\sup_{\tau\in[0,\CT]}\!\N{\uptu{\tau}{1}\!-\!\uptu{\tau}{2}}_{L_\infty(D_T)}\right).
    \end{split}
    \end{equation}

    Using \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_utilde_UNIFORM} and \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_uhattilde_UNIFORM} in the first inequality together with the first step of \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty6} in the second inequality and \Cref{lem:parabolicTB} in the next-to-last step, we have
    \begin{equation}
    \begin{split}    \label{eq:proof:lem:parabolic_wellposedness:CONTRACTION}
        &\N{\uptu{}{1}-\uptu{}{2}}_{\CV_{\widetilde{\CT}}(\widetilde{M})} + \Nbig{\uhatptu{}{1}-\uhatptu{}{2}}_{\CV_{\widetilde{\CT}}(\widetilde{M})}\\
        &\qquad\,\leq C\sup_{\tau\in[0,\widetilde{\CT}]} \N{\widetilde{g}_\tau^1-\widetilde{g}_\tau^2}_{L_2(D_T)} + C\sup_{\tau\in[0,\widetilde{\CT}]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))} \sup_{\tau\in[0,\widetilde{\CT}]}\N{\uptu{\tau}{1}-\uptu{\tau}{2}}_{L_\infty(D_T)} \!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\\ 
        &\qquad\,\leq C\sup_{\tau\in[0,\widetilde{\CT}]} \N{\int_0^\tau \alpha_s T_{B_0}[\uhatpu{s}{1}-\uhatpu{s}{2}]\,ds}_{L_2(D_T)} \\
        &\qquad\,\quad\,+ C\sup_{\tau\in[0,\widetilde{\CT}]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))} \sup_{\tau\in[0,\widetilde{\CT}]}\int_0^\tau \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds \\
        &\qquad\,\leq C \int_0^{\widetilde{\CT}} \N{\alpha_s T_{B_0}[\uhatpu{s}{1}-\uhatpu{s}{2}]}_{L_2(D_T)}ds \\
        &\qquad\,\quad\,+  C\sup_{\tau\in[0,\widetilde{\CT}]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))} \int_0^{\widetilde{\CT}} \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds \\
        &\qquad\,\leq C_2 \left(1+\sup_{\tau\in[0,\widetilde{\CT}]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))}\right) \int_0^{\widetilde{\CT}} \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds
    \end{split}
     \end{equation}%
    for a constant $C_2=C_2(\alpha,\CL,q,C^B_2)$ (to be precise, $C_2=C\max\{\alpha_0C_2^B,1\}$).

    \textit{Step~2d: Existence locally in training time.}
    Let us choose
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:M0CT0}
        M_0
        = 2C_1\!\left(\N{h}_{L_2(D_T)} \!+\! \N{f}_{L_2(D)} \!+\! 1\right)
        \quad\text{and}\quad
        \CT_0
        = \min\left\{\frac{1}{4C_1},\frac{1}{2C_2(1+M_0)}\right\}
    \end{equation}
    where the constants $C_1$ and $C_2$ are as given implicitly in \eqref{eq:proof:lem:parabolic_wellposedness:SELFMAPPING} and \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTION}, respectively.
    We show in what follows that there exists a unique solution $(\up{},\uhatp{})\in \CV_{\CT_0}(M_0)\times\CV_{\CT_0}(M_0)$.

    \textit{Step~2d(i): Self-mapping property of $F$.}
    Consider $(\upt{},\uhatpt{})$ together with its corresponding $(\up{},\uhatp{}) \in \CV_{\CT_0}(M_0)\times \CV_{\CT_0}(M_0)$.
    Using the definitions of $M_0$ and $\CT_0$ in \eqref{eq:proof:lem:parabolic_wellposedness:M0CT0}, respectively, we can derive from \eqref{eq:proof:lem:parabolic_wellposedness:SELFMAPPING} that
    \begin{equation}
    \begin{split}
        &\N{\upt{}}_{\CV_{\CT_0}(M_0)} \!+\! \Nnormal{\uhatpt{}}_{\CV_{\CT_0}(M_0)}
        \leq C_1 \int_0^{\CT_0} \N{\uhatp{s}}_{L_2(D_T)}ds \!+\! C_1\left(\N{h}_{L_2(D_T)} \!+\! \N{f}_{L_2(D)} \!+\! 1\right)\\
        &\qquad\qquad\,\leq C_1 \CT_0 \N{\uhatp{}}_{\CV_{\CT_0}(M_0)} + \frac{M_0}{2}
        \leq C_1 \CT_0 M_0 + \frac{M_0}{2}
        \leq \frac{M_0}{4} + \frac{M_0}{2} \leq M_0.
    \end{split}
    \end{equation}
    Thus, $(\upt{},\uhatpt{}) \in \CV_{\CT_0}(M_0)\times \CV_{\CT_0}(M_0)$.

    \textit{Step~2d(ii): Contractivity of $F$.}
    Consider two pairs $(\uptu{}{1},\uhatptu{}{1})$, $(\uptu{}{2},\uhatptu{}{2})$ together with their corresponding $(\upu{}{1},\uhatpu{}{1}), (\upu{}{2},\uhatpu{}{2}) \in \CV_{\CT_0}(M_0)\times \CV_{\CT_0}(M_0)$.
    According to \textit{Step~2d(i)}, $(\uptu{}{1},\uhatptu{}{1}),(\uptu{}{2},\uhatptu{}{2}) \in \CV_{\CT_0}(M_0)\times \CV_{\CT_0}(M_0)$.
    Using the definitions of $M_0$ and $\CT_0$ in \eqref{eq:proof:lem:parabolic_wellposedness:M0CT0}, we can derive from \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTION} that
    \begin{equation}
    \begin{split}
        &\N{\uptu{}{1}-\uptu{}{2}}_{\CV_{\CT_0}(M_0)} + \Nbig{\uhatptu{}{1}-\uhatptu{}{2}}_{\CV_{\CT_0}(M_0)}\\
        &\quad\,\leq C_2 \left(1+\sup_{\tau\in[0,\CT_0]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T], L_2(D))}\right) \int_0^{\CT_0} \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds \\
        &\quad\,\leq C_2 \left(1+M_0\right) \int_0^{\CT_0} \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds
        \leq C_2 \left(1+M_0\right)\CT_0 \Nbig{\uhatpu{}{1}-\uhatpu{}{2}}_{\CV_{\CT_0}(M_0)} \\
        &\quad\,\leq \frac{1}{2} \Nbig{\uhatpu{}{1}-\uhatpu{}{2}}_{\CV_{\CT_0}(M_0)}
        \leq \frac{1}{2} \left(\N{\upu{}{1}-\upu{}{2}}_{\CV_{\CT_0}(M_0)} + \Nbig{\uhatpu{}{1}-\uhatpu{}{2}}_{\CV_{\CT_0}(M_0)}\right),
    \end{split}
    \end{equation}
    showing that the map $F$ is a contraction.

    \textit{Step~2d(iii): Banach fixed-point theorem.}
    Hence, the Banach fixed-point theorem guarantees that there exists a unique solution $(\up{},\uhatp{})\in \CV_{\CT_0}(M_0)\times\CV_{\CT_0}(M_0)$,
    which satisfies $(\up{},\uhatp{}) = F(\up{},\uhatp{})$.
    We have thus established the existence of a unique local-in-training-time solution to the PDE system~\eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} for $\widetilde{g}_\tau = g^*_\tau$ on the training time domain $[0,\CT_0]$.
    In particular, $(\up{\tau},\uhatp{\tau})\in \CS\times \CS$ for every $\tau\in[0,\CT_0]$.
    Reapplying the classical existence and regularity results from \textit{Steps 1a}, \textit{1b} and \textit{1c} further shows that for each $\tau\in[0,\CT]$ such solution satisfies $(\partial_t\uppt{\tau}{t,\dummy},\partial_t\uhatppt{\tau}{t,\dummy})\in L_2(D) \times L_2(D)$
    for a.e.\@ $t\in[0,T]$.

    \textit{Step~2e: Existence globally in training time.}
    Leveraging a bootstrapping argument, we now extend this argument to obtain a solution on a training time domain $[0,\CT]$ for an arbitrary $\CT<\infty$.
    To do so, we proceed inductively.
    Suppose we have a solution $(\up{},\uhatp{})\in \CV_{\CT_{k-1}}(M_{k-1})\times\CV_{\CT_{k-1}}(M_{k-1})$ which is such that for each $\tau\in[0,\CT_{k-1}]$ it satisfies $(\partial_t\upp{\tau}{t,\dummy},\partial_t\uhatpp{\tau}{t,\dummy})\in L_2(D) \times L_2(D)$
    for a.e.\@ $t\in[0,T]$. (We showed in \textit{Step~2d} before that this is the case for the induction start $k=1$.)

    On the training time interval $I = [0,\CT_{k-1}]$ we can now employ \Cref{lem:parabolictimeevolutionJt*} which ensures that $\fd{\tau}\J{\tau}\leq0$ for all $\tau\in I=[0,\CT_{k-1}]$.
    Thanks to this, \Cref{lem:parabolic_uhatL2} (applied in the setting $I=[0,\CT_{k-1}]$) provides a uniform (in the training time $\tau$ and on the training time interval $[0,\CT_{k-1}]$) bound $\sup_{\tau\in[0,\CT_{k-1}]}\N{\uhatp{\tau}}_{L_2(D_T)}\leq C^{\widehat{u}}$, where $C^{\widehat{u}}$ does not depend on $\CT_{k-1}$ but only on $\J{0}$.  
    Let us now choose 
    \begin{equation}
\label{eq:proof:lem:parabolic_wellposedness:MkCTk}
        M_k
        = k C^{\widehat{u}} + 2C_1\!\left(\N{h}_{L_2(D_T)} \!+\! \N{f}_{L_2(D)} \!+\! 1\right)
        \quad\text{and}\quad
        \CT_k
        = \CT_{k-1} + \min\left\{\frac{1}{4C_1},\frac{1}{2C_2(1+M_k)}\right\}.
    \end{equation}
    We show in what follows that there exists a unique solution $(\up{},\uhatp{})\in \CV_{\CT_{k}}(M_{k})\times\CV_{\CT_{k}}(M_{k})$.

    \textit{Step~2e(i): Self-mapping property of $F$.}
    Consider $(\upt{},\uhatpt{})$ together with its corresponding $(\up{},\uhatp{}) \in \CV_{\CT_k}(M_k)\times \CV_{\CT_k}(M_k)$.
    Using the definitions of $M_k$ and $\CT_k$ in \eqref{eq:proof:lem:parabolic_wellposedness:MkCTk}, we can derive from \eqref{eq:proof:lem:parabolic_wellposedness:SELFMAPPING} that
    \begin{equation}
    \begin{split}
        &\N{\upt{}}_{\CV_{\CT_k}(M_k)} + \Nnormal{\uhatpt{}}_{\CV_{\CT_k}(M_k)} \leq C_1 \int_0^{\CT_k} \N{\uhatp{s}}_{L_2(D_T)}ds + C_1\left(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1\right)\\
        &\qquad\,\leq C_1 \int_0^{\CT_{k-1}} \N{\uhatp{s}}_{L_2(D_T)}ds + C_1 \int_{\CT_{k-1}}^{\CT_k} \N{\uhatp{s}}_{L_2(D_T)}ds + C_1\left(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1\right)\\
        &\qquad\,\leq C_1 \CT_{k-1} C^{\widehat{u}} + C_1 (\CT_k-\CT_{k-1}) \N{\uhatp{}}_{\CV_{\CT_k}(M_k)} + \frac{M_k}{2}\\
        &\qquad\,\leq C_1 \CT_{k-1} C^{\widehat{u}} + C_1 (\CT_k-\CT_{k-1}) M_k + \frac{M_k}{2}
        \leq \frac{M_k}{4} + \frac{M_k}{4} + \frac{M_k}{2} \leq M_k,
    \end{split}
    \end{equation}%
    where we used in the last step that (with $\CT_{-1}:=0$) according to the definition of $\CT_k$ in \eqref{eq:proof:lem:parabolic_wellposedness:MkCTk} it holds
    $C_1 \CT_{k-1} C^{\widehat{u}}= C_1 \sum_{\ell=0}^{k-1} (\CT_{\ell}-\CT_{\ell-1}) C^{\widehat{u}}\leq \frac{1}{4} k C^{\widehat{u}}\leq \frac{M_k}{4}.$
    Thus, $(\upt{},\uhatpt{}) \in \CV_{\CT_k}(M_k)\times \CV_{\CT_k}(M_k)$.

    \textit{Step~2e(ii): Contractivity of $F$.}
    Consider two pairs $(\uptu{}{1},\uhatptu{}{1})$, $(\uptu{}{2},\uhatptu{}{2})$ together with their corresponding $(\upu{}{1},\uhatpu{}{1}), (\upu{}{2},\uhatpu{}{2}) \in \CV_{\CT_k}(M_k)\times \CV_{\CT_k}(M_k)$.
    Using the definitions of $M_k$ and $\CT_k$ in \eqref{eq:proof:lem:parabolic_wellposedness:MkCTk}, we can derive from \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTION} that
    \begin{equation}
    \begin{split}
        &\N{\uptu{}{1}-\uptu{}{2}}_{\CV_{\CT_k}(M_k)} + \Nbig{\uhatptu{}{1}-\uhatptu{}{2}}_{\CV_{\CT_k}(M_k)}\\
        &\qquad\,\leq C_2 \left(1+\sup_{\tau\in[0,\CT_k]}\Nbig{\uhatptu{\tau}{2}}_{L_\infty([0,T],L_2(D))}\right) \int_0^{\CT_k} \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds \\
        &\qquad\,\leq C_2 \left(1\!+\!M_k\right) \int_0^{\CT_k} \N{\uhatpu{s}{1}-\uhatpu{s}{2}}_{L_2(D_T)} ds \\
        &\qquad\,\leq C_2 \left(1\!+\!M_k\right) \int_{\CT_{k-1}}^{\CT_k} \N{\uhatpu{s}{1}\!-\!\uhatpu{s}{2}}_{L_2(D_T)} ds 
        \leq C_2 \left(1\!+\!M_k\right)(\CT_k\!-\!\CT_{k-1}) \Nbig{\uhatpu{}{1}\!-\!\uhatpu{}{2}}_{\CV_{\CT_k}(M_k)} \\
        &\qquad\,\leq \frac{1}{2} \Nbig{\uhatpu{}{1}-\uhatpu{}{2}}_{\CV_{\CT_k}(M_k)}
        \leq \frac{1}{2} \left(\N{\upu{}{1}-\upu{}{2}}_{\CV_{\CT_k}(M_k)} + \Nbig{\uhatpu{}{1}-\uhatpu{}{2}}_{\CV_{\CT_k}(M_k)}\right),
    \end{split}
    \end{equation}
    where the third step is due to the uniqueness of the solution on the training time interval $[0,\CT_{k-1}]$.
    Thus, the map $F$ is a contraction.

    \textit{Step~2e(iii): Banach fixed-point theorem.}
    Hence, the Banach fixed-point theorem guarantees that there exists a unique solution $(\up{},\uhatp{})\in \CV_{\CT_k}(M_k)\times\CV_{\CT_k}(M_k)$,
    which satisfies $(\up{},\uhatp{}) = F(\up{},\uhatp{})$.
    We have thus established the existence of a unique solution to the PDE system~\eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} for $\widetilde{g}_\tau = g^*_\tau$ on the training time domain $[0,\CT_k]$.
    In particular, $(\up{\tau},\uhatp{\tau})\in \CS\times \CS$ for every $\tau\in[0,\CT_k]$.
    Reapplying the classical existence and regularity results from \textit{Steps 1a}, \textit{1b} and \textit{1c} further shows that for each $\tau\in[0,\CT_k]$ such solution satisfies $(\partial_t\uppt{\tau}{t,\dummy},\partial_t\uhatppt{\tau}{t,\dummy})\in L_2(D) \times L_2(D)$
    for a.e.\@ $t\in[0,T]$.

    \textit{Step~2e(iv): Globality of the construction in training time.}
    It remains to notice that, due to the definition of the times~$\CT_k$ in \eqref{eq:proof:lem:parabolic_wellposedness:MkCTk}, the telescopic sum
    \begin{equation}
        \label{eq:proof:lem:parabolic_wellposedness:harmonicseries}
    \begin{split}
        \sum_{k=1}^\infty (\CT_k-\CT_{k-1})
        &= \sum_{k=1}^\infty \min\left\{\frac{1}{4C_1},\frac{1}{2C_2(1+M_k)}\right\}
        \geq \sum_{k=K}^\infty \frac{1}{2C_2(1+M_k)}\\
        &= \sum_{k=K}^\infty \frac{1}{2C_2(1+k C^{\widehat{u}} + 2C_1(\N{h}_{L_2(D_T)} + \N{f}_{L_2(D)} + 1))}
    \end{split}
    \end{equation}
    diverges.
    To see this, simply note that the definition of the bounds~$M_k$ in \eqref{eq:proof:lem:parabolic_wellposedness:MkCTk} grows linearly in $k$, thus the last term in \eqref{eq:proof:lem:parabolic_wellposedness:harmonicseries} being a harmonic series for some sufficiently large integer $K$.
    This ensures that the above construction in \textit{Step~2d} and \textit{2e} gives a solution in $\CV_{\CT}(M)\times\CV_{\CT}(M)$ for any given $\CT<\infty$ and suitable associated $M>0$.

    \textbf{Uniqueness.}
    It remains to prove the uniqueness of a solution $(\up{\tau},\uhatp{\tau})$ to the PDE system~\eqref{eq:parabolicPDE*}--\eqref{eq:parabolicadjoint*} coupled with the integro-differential equation~\eqref{eq:parabolicgtau} for $g^*_\tau$.
    For this purpose, suppose that there are two weak solutions $(\upu{}{1},\uhatpu{}{1}),(\upu{}{2},\uhatpu{}{2})\in \CV_\CT(M)\times \CV_\CT(M)$.
    This means we have $(\upu{\tau}{1},\uhatpu{\tau}{1}),(\upu{\tau}{2},\uhatpu{\tau}{2})\in \CS\times \CS$ with satisfy $(\fpartial{t}\upu{\tau}{1},\fpartial{t}\uhatpu{\tau}{1}),(\fpartial{t}\upu{\tau}{2},\fpartial{t}\uhatpu{\tau}{2})\in L_2(D)\times L_2(D)$ for a.e.\@ $t\in[0,T]$ and where $g^{*,1}_\tau,g^{*,2}_\tau\in L_2(D_T)$ denote the corresponding integral terms \eqref{eq:parabolicgtau} for each $\tau\in[0,\CT]$.
    By repeating the computations of the existence proof in \textit{Step 2b(ii)} we obtain analogously to \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_utilde} and \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty5} that
    \begin{equation}       \label{eq:proof:lem:parabolic_wellposedness:UNIQUENESS1}
        \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_\infty([0,T],H^1(D))} + \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_2([0,T],L_2(D))}
        \leq C\N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_2(D_T)}
    \end{equation}
    and for some $p>d+1$ that
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:UNIQUENESS2}
    \begin{split}
        \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_\infty(D_T)}
        &\leq C\N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_p(D_T)},
    \end{split}
    \end{equation}
    as well as analogously to \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITY_uhattilde} that 
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:UNIQUENESS3}
    \begin{split}
        &\Nbig{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_2([0,T],H^1(D))} + \Nbig{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_\infty([0,T],L_2(D))}\\
        &\qquad\,\leq C\left(\N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_2(D_T)} + M\N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_\infty(D_T)}\right),
    \end{split}
    \end{equation}
    where we used directly that $\upu{\tau}{2}\in\CV_\CT(M)$.
    Since it holds
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:UNIQUENESS4}
    \begin{split}
        \N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_p(D_T)}
        &\leq C \int_0^\tau \N{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_2(D_T)} ds,
    \end{split}
    \end{equation}
    according to the next-to-last step in \eqref{eq:proof:lem:parabolic_wellposedness:CONTRACTIVITYuinfty3},
    we get
    \begin{equation}        \label{eq:proof:lem:parabolic_wellposedness:UNIQUENESS5}
    \begin{split}
        &\N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_2(D_T)} + \N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_p(D_T)}
        \leq C \int_0^\tau \N{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_2(D_T)} ds \\
        &\qquad\,\leq C \int_0^\tau \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_2(D_T)} + \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_\infty(D_T)} ds \\
        &\qquad\,\leq C \int_0^\tau \N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_2(D_T)} + \N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_p(D_T)} ds.
    \end{split}
    \end{equation}
    Recalling that $g_0^1=g_0^2=0$, we can now employ Grönwall's inequality in its integral form to obtain
    \begin{equation}       \label{eq:proof:lem:parabolic_wellposedness:UNIQUENESS6}
        \N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_2(D_T)} + \N{g^{*,1}_\tau-g^{*,2}_\tau}_{L_p(D_T)}
        = 0
    \end{equation}
    for every $\tau\in[0,\CT]$.

    Recalling \eqref{eq:proof:lem:parabolic_wellposedness:UNIQUENESS1} and \eqref{eq:proof:lem:parabolic_wellposedness:UNIQUENESS3},
    we hence conclude that for every $\tau\in[0,\CT]$ it hold
    \begin{equation}
        \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_2([0,T],H^1(D))} + \N{\upu{\tau}{1}-\upu{\tau}{2}}_{L_\infty([0,T],L_2(D))}
        =0
    \end{equation}
    and
    \begin{equation}
        \N{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_2([0,T],H^1(D))} + \N{\uhatpu{\tau}{1}-\uhatpu{\tau}{2}}_{L_\infty([0,T],L_2(D))}
        =0.
    \end{equation}
    Thus $\Nbig{\upu{}{1}-\upu{}{2}}_{\CV_\CT(M)}=0$ and $\Nbig{\uhatpu{}{1}-\uhatpu{}{2}}_{\CV_\CT(M)}=0$, proving uniqueness in $\CV_\CT(M)$.
\end{proof}




