\subsection{Temperature Threshold} \label{subsec:temp_threshold}
% In this section, the goal is to use the structural algorithm described in Section \ref{sec:structure_alg} as a subroutine to prove that Gibbs sampling is classically easy when $\beta \leq \frac{1}{50\mathcal{R}d^2}$. 
In the sampling setting, the bound on the inverse temperature $\beta$ changes from the structural algorithm by a factor of $\frac{24}{25}d^{-1}$. 
The reason for the factor of $\frac{24}{25}$ is the following variant of Lemma \ref{lem:alpha_bound}:
\begin{lemma}\label{lem:alpha_bound_sampling}
For $\beta \leq \frac{1}{50\mathcal{R}d^2}$ and for the structural algorithm with $N = 25$, $\alpha_j \leq \frac{24}{25}$, for any $j$.
\end{lemma}
\begin{proof}
Since $\beta \leq \frac{1}{50 \mathcal{R}d^2} \leq \frac{1}{50 \mathcal{R}d} = \frac{1}{2N\mathcal{R}d}$, Lemma \ref{lem:alpha_bound} implies that 
\[\alpha_j \leq \frac{24}{N}\left(1 - \frac{1}{\mathcal{R}}\right)^{|T_j| - b_j}\]
Note that since $b_j = |T_j - S_j|$, $|T_j| - b_j \geq 0$. It follows that $\alpha_j \leq \frac{24}{25}$.
\end{proof}

To use the structural algorithm as a subroutine for sampling, it will be necessary that $\alpha_j$ is bounded away from 1, which is why the choice of a slightly larger temperature bound ensures that $\alpha_j \leq 1-\frac{1}{25}$.

The additional factor of $d^{-1}$ allows for the efficient approximation of the partition function of the Hamiltonians $H^{S}$ for any $S \subseteq [n]$.
To do so, we cite Theorem 3.7 from \cite{bakshi2024high}. We remark that this theorem, although originally proved for the spin setting, can be applied without modification to the fermionic setting because the terms in the fermionic Hamiltonian, having even parity, are still ``bosonic'' in the sense that non-overlapping terms commute with each other.

\begin{lemma}\label{lem:eff_partition}
Say $H$ is an $n$-mode fermionic Hamiltonian with fixed locality $\mathcal{R}$ and degree $d$. For $\beta < \frac{1}{e(e+1)(1+e(d - 1))d}$, the partition function $\text{tr}(e^{-\beta H})$ may be estimated to multiplicative precision $\epsilon$ in time $\text{poly}(n, \epsilon^{-1})$. 
\end{lemma}

\begin{corollary}\label{cor:partition_estimate}
When $\beta \leq \frac{1}{50\mathcal{R}d^2}$, the partition function of an $n$-mode fermionic Hamiltonian $H$ with fixed locality $\mathcal{R}$ and degree $d$ as well as the quantity $\text{tr}(e^{-\beta H })$ can be estimated to multiplicative precision $\epsilon$ in time $\text{poly}(n, \epsilon^{-1})$. 
\end{corollary}
\begin{proof}
For $\mathcal{R} \geq 2$, 
\begin{equation}
\frac{1}{50\mathcal{R}d^2} \leq \frac{1}{100d^2} < \frac{1}{e(e+1)(1+e(d-1))d}
\end{equation}
for any $d \geq 1$. 
\end{proof}

For this choice of $\beta$, therefore, we may use the partition function and the structural algorithm together to implement a Gibbs sampling algorithm. 
In particular, we will make use of a subroutine of the algorithm, which is essentially just one of the $2n$ steps in Section \ref{subsec:struc_alg_description} with $N=25$:
\begin{algorithm}[Pinning one site]
\label{alg:pinning_subroutine}
\mbox{}\\

\textbf{Input:} Subset of terms $S \subseteq [2n]$ for unpinned sites and iteration $j$. Pinned unnormalized Gaussian states $\sigma$ and unpinned state $I + \alpha \Gamma.$

\textbf{Output:} $(j', S', \sigma', \Gamma', \alpha')$, representing the pinned version of the input states at the next iteration.
\begin{enumerate}
    % \item Choose $i$ to be the minimal index in the support of $\Gamma$; if $\Gamma$ has empty support, choose the minimal $i$ in $S$. Define $S' = S - \{i\}$. 
    \item If $\text{supp}(\Gamma) \cap S$ is nonempty, set $i$ as the minimal index in $\text{supp}(\Gamma) \cap S$. Otherwise, let $i$ be the minimal index in $S$.
    Define $S' = S - \{i\}$. 
    Define $$M = e^{\beta H^{S'/2}}e^{-\beta H^{S/2}}.$$
    \item Sample $I + \beta_1 \Lambda_1$ for $\beta_1 = (25\mathcal{R})^{-t_1}$ from the probability distribution in Lemma \ref{lem:fermion_convexcomb}, so that
    \[
    \mathbb{E}\left[I + \beta_1 \Lambda_1\right] = M =  e^{\beta H^{S'/2}}e^{-\beta H^{S/2}}.
    \]
    \item Sample $I + \beta_2 \Lambda_2$ for $\beta_2 = (25\mathcal{R})^{-t_2}$ independently, so that
    \[
    \mathbb{E}\left[I + \beta_2 \Lambda_2\right] = M^\dag.
    \]
    \item Set $\sigma' \gets \sigma$ and $(\Gamma', \alpha')$ as:
        \begin{enumerate}
            \item $\bigl(\Gamma, (1-\frac{1}{\mathcal{R}})^{-1}\alpha_{j}
            \bigl)$ with probability $1 - \frac{1}{\mathcal{R}}$
            \item $\left(\Lambda_1, (6\mathcal{R})\beta_1\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_2, (6\mathcal{R})\beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_1\Gamma, (6\mathcal{R})\beta_1\alpha_{j}\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Gamma\Lambda_2, (6\mathcal{R})\alpha_{j} \beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_1\Lambda_2, (6\mathcal{R})\beta_1 \beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_1\Gamma\Lambda_2, (6\mathcal{R})\beta_1\alpha_{j}  \beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
        \end{enumerate}
    \item If $\Gamma'$ is not Hermitian:
    \begin{itemize}
        \item $\Gamma' \leftarrow 0, \alpha' \leftarrow 0$.
    \end{itemize}
    \item  If there are two indices $k, l \in S_j^c$ such that $k, l \in \text{supp}\left(\Gamma'\right)$, i.e. $\Gamma' =\Gamma^- \cdot (i\gamma_k \gamma_l)$: 
    \begin{enumerate}
        \item $\Gamma' \leftarrow \Gamma^-$, $\sigma' \leftarrow (I + i\gamma_k\gamma_l) \cdot \sigma'$ with probability $\frac{1}{2}$
        \item $\Gamma' \leftarrow -\Gamma^-$, $\sigma' \leftarrow (I - i\gamma_k\gamma_l) \cdot \sigma'$ with probability $\frac{1}{2}$
    \end{enumerate}
    \item If $\Gamma' \in \{\pm I\}$:
        \begin{itemize}
            \item $\sigma' \leftarrow (I + \alpha' \Gamma')\sigma'$, $\Gamma' \leftarrow 0$,  and $\alpha' \leftarrow 0$. 
        \end{itemize}
    \item $j \gets j + 1$.
\end{enumerate}
\end{algorithm}
Recall that the structural algorithm samples unnormalized Gaussian states $\sigma_i$ with probability $p_i$ such  that 
\[\sum_i p_i\sigma_i = e^{-\beta H}.\]
As discussed in the overview, a classical sampling algorithm must sample the operators $\rho_i=\frac{\sigma_i}{\text{tr}(\sigma_i)}$ according to the distribution 
\[q_i = \frac{p_i\text{tr}(\sigma_i)}{\text{tr}(e^{-\beta H})}.\]
Preparing the operators $\rho_i$ with respect to the distribution $p_i$ is easy, because the classical description of $\sigma_i$ can easily be renormalized to obtain a classical description of $\rho_i$. 
Thus, the main obstacle is converting this naive sampler to one that can sample $\rho_i$ with the correct probabilities, $q_i$, yielding a classical algorithm that can prepare 
\[\sum_{i} q_i \rho_i = \frac{e^{-\beta H}}{\text{tr}(e^{-\beta H})}.\]

\subsection{Sample Tree}\label{subsec:sample_tree}
In general, reducing a sampler for a distribution $q$ to a sampler for a distribution $p$ is a daunting task. 
However, there is a natural tree structure, $\mathcal{T}$, associated with these distributions. 
The tree has a root node with associated data $(0, S_0, \sigma_0, \Gamma_0,\alpha_0) = (0, [2n], I, 0, 0)$, and the children of a given node correspond to all possible random choices in the Algorithm \ref{alg:pinning_subroutine}, with the algorithm's output $(j+1, S_{j+1}, \sigma_{j+1}, \Gamma_{j+1}, \alpha_{j+1})$ as the associated data.
For a node $v$, we will denote its associated quantities by $j_v, S_v, \sigma_v, \Gamma_v$, and $\alpha_v$. 
For any internal node $v$ and any (potentially unnormalized) distribution on the leaves $r$, we use the notation $\mathcal{L}_\mathcal{T}(v)$ to denote the leaves below a given node $v$, and $r_v = \sum_{w\in \mathcal{L}_T(v)}r_w$.
% $r_v = \sum_{w \text{ leaf of }v}r_w$.
% Letting $\mathcal{L}_\mathcal{T}(v)$ be the leaves below a given node $v$, $r_v = \sum_{w\in \mathcal{L}_T(v)}r_w$. \YT{$r_v$ is doubly defined}
Our structural algorithm is a walk down this tree from $j = 0$ to $j = 2n$, by repeated application of Algorithm \ref{alg:pinning_subroutine}, and the probability distribution $p$ on the leaves is the probability of reaching a given leaf applying this algorithm.
$p_v$ for a general internal node is therefore the probability of reaching the node $v$. 
One final piece of notation is that $\mathcal{C}_\mathcal{T}(v)$ will be used to denote the set of children of a given node $v$. 

A reduction between sampling algorithms of two distributions on the leaves of a tree is possible when additional conditions are satisfied on the internal nodes of the tree. 
In particular, to convert a sampling algorithm for $p_i$ to a sampling algorithm for $q_i$, we make use of Theorem 5.8 in \cite{bakshi2024high}.
We replace a certain approximation ratio in their formulation, 10, with an arbitrary constant $\gamma$. 
We note that proof of the theorem in \cite{bakshi2024high} generalizes to this case as well.
\begin{theorem}\label{thm:simulate_distr}
Assume that $p$ and $q$ are two probability distributions on the leaves of a tree $\mathcal{T}$ of depth $d$, where each node has at most $k$ children. 
Let $\hat{p}$ and $\hat{q}$ be any unnormalized distributions that are equal to $p$ and $q$ up to some constant, i.e. $\hat{p}_v = Cp_v$ and $\hat{q}_v = Dq_v$ for any node $v$ and some constants $C, D \neq 0$. 
Assume also the following four conditions:
\begin{enumerate}
\item For any internal node $v$, the values $\frac{\hat{q}_v}{\hat{p}_v}$ can be calculated efficiently up to constant multiplicative error.
\item For any leaf $v$, the values $\frac{\hat{q}_v}{\hat{p}_v}$ can be efficiently calculated exactly.
\item For any internal node $v$, the leaves $v_k$ of $v$ can be sampled efficiently according to the distribution $\frac{p_{v_k}}{p_v}$.
\item Finally, for any node $v$ and its child $w$,
\[\left|\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)-\log\left(\frac{\hat{q}_w}{\hat{p}_w}\right)\right | \leq \log(\gamma)\]
for some constant $\gamma > 1$. 
\end{enumerate}


Then, there exists a $\text{poly}\left(d, \log(k), \log\left(\epsilon^{-1}\right)\right)$ algorithm to sample from $q$ up to total variation distance $\epsilon$. 
\end{theorem}

Theorem \ref{thm:simulate_distr} works by performing a carefully chosen random walk on the tree $\mathcal{T}$. 
This walk is designed so that its marginal distribution on the leaves of the tree converges to the target distribution $q$, using only local information about the ratios $\hat{q}_v/\hat{p}_v$.
At each node of the tree, the walk chooses to move up, down, or stay in place based on local comparisons of these unnormalized probabilities. 
The assumption that the log-ratio $\log(\hat{q}_v/\hat{p}_v)$ varies slowly across parent-child pairs is crucial: if the changes were large, they could prevent the walk from effectively concentrating around the parts of the tree where $q$ is most dense. 
We refer readers to Algorithm 5.9 in \cite{bakshi2024high} for the technical details of the walk as well as its mixing time analysis. 

We will first establish that almost all of the conditions of Theorem \ref{thm:simulate_distr} can be satisfied for the sampling tree $\mathcal{T}$ of Algorithm \ref{alg:pinning_subroutine}. 
The analysis requires an estimate of how the trace of a positive semidefinite matrix is affected by perturbations. 
\begin{lemma}\label{lem:matrix_perturbation}
Assume that $P$ is a positive semidefinite operator, and $A$ is some operator such that $\lVert A \rVert_\infty \leq 1 - \epsilon$ for $0<\epsilon \leq 1$. 
Then \[\left|\log(\text{tr}(P(1+A))) - \log(\text{tr}(P))\right| \leq \text{log}\left(\epsilon^{-1}\right)\]
\end{lemma}
\begin{proof}
We may use Hölder's inequality to say that 
\begin{equation}
\begin{aligned}
|\text{tr}(PA)|&\leq \lVert PA\rVert_1 \\&\leq \lVert P\rVert_1  \lVert A\rVert_\infty\\&= \text{tr}(P)\lVert A\rVert_\infty
\end{aligned}
\end{equation}
using the property that the $1$-norm is the sum of the absolute values of the eigenvalues of an operator. 
From this, we deduce that 
\begin{equation}
\text{tr}(P)(I-\lVert A\rVert_\infty) \leq \text{tr}(P(1+A))  \leq \text{tr}(P)(I+\lVert A\rVert_\infty),
\end{equation}
and in particular by the bound on $\lVert A \rVert_\infty$:
\begin{equation}
\epsilon \text{tr}(P)  \leq \text{tr}(P(1+A))  \leq (2-\epsilon)\text{tr}(P).
\end{equation}
It follows that 
\begin{equation}
\left|\log(\text{tr}(P(1+A))) - \log(\text{tr}(P))\right| \leq \max(\log(\epsilon^{-1}), \log(2-\epsilon)) = \log(\epsilon^{-1}),
\end{equation}
where the last equality holds since $(2-\epsilon)\epsilon \leq 1$ for $0 < \epsilon \leq 1$. 
\end{proof}

To prove condition (1), it will also be important to track the expectation of the output of Algorithm \ref{alg:structural_alg} conditioned on reaching a given internal node of $\mathcal{T}$.
\begin{lemma}\label{lem:gen_expectation}
Let $A_v$ be the event of reaching an internal node $v$ in the structural algorithm. Then $\mathbb{E}[\sigma_{2n} |A_v] = e^{-\beta H ^{S_v}/2}(I + \alpha_v \Gamma_v)\sigma_ve^{-\beta H ^{S_v}/2}$. 
\end{lemma}
\begin{proof}
Say that the node $v$ corresponds to the $j$th step of the algorithm.
As in Lemma \ref{lem:fermion_expectation}, we can use Equation \ref{eq:rewritteninductiveexpectation}, along with the law of total expectations and properties of $\mathcal{F}$-measurable random variables:
\begin{align*}
&\mathbb{E}\left[M_j^{-1}\dots M_{2n}^{-1}(I+\alpha_{2n}\Gamma_{2n})\sigma_{2n}(M_{2n}^{\dag})^{-1} \dots (M_{j}^{\dag})^{-1}| \mathcal{F}_j\right] \\
&= \mathbb{E}\left[\mathbb{E}\left[M_j^{-1}\dots M_{2n-1}^{-1}M_{2n}^{-1}(I+\alpha_{2n}\Gamma_{2n})\sigma_{2n}(M_{2n}^{\dag})^{-1} (M_{2n-1}^{\dagger})^{-1}\dots (M_{j}^{\dag})^{-1}| \mathcal{F}_{2n-1}\right]| \mathcal{F}_j\right]
\\
&= \mathbb{E}\left[M_j^{-1}\dots M_{2n-1}^{-1}\mathbb{E}\left[M_{2n}^{-1}(I+\alpha_{2n}\Gamma_{2n})\sigma_{2n}(M_{2n}^{\dag})^{-1} | \mathcal{F}_{2n-1}\right](M_{2n-1}^{\dagger})^{-1}\dots (M_{j}^{\dag})^{-1}| \mathcal{F}_j\right]\\
&= \mathbb{E}\left[M_j^{-1}\dots (I+\alpha_{2n-1}\Gamma_{2n-1})\sigma_{2n-1}\dots (M_{j}^{\dag})^{-1}| \mathcal{F}_j\right]
\\
&= \dots = \mathbb{E}\left[(I + \alpha_j \Gamma_j)\sigma_j | \mathcal{F}_j\right]\\\
&= (I + \alpha_j \Gamma_j)\sigma_j. 
\end{align*}
Note that $M_{2n} \dots M_j = e^{-\beta H^{S_j}/2}$ and $\alpha_{2n} = 0$, the left hand side of the above expression is 
\begin{equation}
\mathbb{E}\left[e^{\beta H^{S_j}/2}(I + \alpha_{2n}\Gamma_{2n})\sigma_{2n}e^{\beta H^{S_j}/2} | \mathcal{F}_j\right] = e^{\beta H^{S_j}/2}\mathbb{E}\left[\sigma_{2n}| \mathcal{F}_j\right]e^{\beta H^{S_j}/2},
\end{equation}
since $S_j$ depends only on randomness up until step $j$. 
We conclude that
\begin{equation}
\mathbb{E}\left[\sigma_{2n}| \mathcal{F}_j\right] = e^{-\beta H ^{S_j}/2}(I + \alpha_j \Gamma_j)\sigma_je^{-\beta H ^{S_j}/2}
\end{equation}
Since $A_v$ is an event based only on random choices up to the $j$th step, it is true that
\[\mathbb{E}[\cdot | A_v] = \mathbb{E}[\mathbb{E}[\cdot | \mathcal{F}_j] | A_v],\]
from which it follows that
\[\mathbb{E}[\sigma_{2n} | A_v] = e^{-\beta H ^{S_v}/2}(I + \alpha_v \Gamma_v)\sigma_ve^{-\beta H ^{S_v}/2}.\]
\end{proof}

\begin{lemma} \label{lem:cond_1_2_satisfied}
Let $\mathcal{T}$ be the tree associated with Algorithm \ref{alg:pinning_subroutine} with the associated distributions $p$ and $q$, and let $\hat{p}_v = p_v$, $\hat{q}_v = \text{tr}(e^{-\beta H})q_v = \text{tr}(\sigma_v)p_v$ be the corresponding unnormalized distributions for any leaf $v$. 
Then conditions (1) and (2) of Theorem \ref{thm:simulate_distr} are satisfied. 
\end{lemma}
\begin{proof}
See that
\begin{align}
\frac{\hat{q}_v}{\hat{p}_v} &= \frac{\sum_{w\in \mathcal{L}_T(v)}\hat{q}_w}{\sum_{w\in \mathcal{L}_T(v)}p_w}\\
&= \frac{\sum_{w\in \mathcal{L}_T(v)}\text{tr}(\sigma_w)p_w}{\sum_{w\in \mathcal{L}_T(v)} p_w }\\
&= \mathbb{E}[\text{tr}(\sigma_w) \,|\, \text{structural algorithm \ref{alg:structural_alg} reaches }v]\\
&= \text{tr}(\mathbb{E}[\sigma_w \,|\, \text{structural algorithm \ref{alg:structural_alg} reaches }v])\\
&=\text{tr}(e^{-\beta H^{S_v}/2}(I+\alpha_{v}\Gamma_v)\sigma_v e^{-\beta H^{S_v}/2}) \label{eq:cond_exp}\\
&= \text{tr}(\sigma_ve^{-\beta H^{S_v}}(I+\alpha_v \Gamma_v))
\end{align}
where Eq. ~(\ref{eq:cond_exp}) uses Lemma \ref{lem:gen_expectation}. 
The state $\sigma$ acts on different modes than $e^{-\beta H^{S_v}}$, as we have established its suppport is contained in $S_v^c$. 
As a consequence,
\begin{equation}
\text{tr}\left(\sigma_v e^{-\beta H^{S_v}}\right) = \text{tr}(\sigma_v)\text{tr}\left(e^{-\beta H^{S_v}}\right).
\end{equation}
% \YT{This seems to be assuming that $\sigma_v$ is normalized, which does not seem to be true from Step 7 on Page 24? Though $\text{tr}(\sigma_v)$ can still be computed so we can let $P=\sigma_v e^{-\beta H^{S_v}}$ below.}
For the same reason, $\sigma_v e^{-\beta H^{S_v}}$ is positive semidefinite. 
Setting $P = \sigma_ve^{-\beta H^{S_v}}$ and $A = \alpha_v \Gamma_v$, note that $\lVert A \rVert_\infty = \alpha_v$. 
Applying Lemma \ref{lem:matrix_perturbation}, 
\begin{align*}
\left\lvert\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right) - \log(\text{tr}(P))\right\rvert &= \left\lvert\log\left(\text{tr}(P(I+A))\right) - \log(\text{tr}(P))\right\rvert\\
&\leq \log((1-\alpha_v)^{-1}) \\
&\leq \log(25),
\end{align*}
where the last inequality holds by Lemma \ref{lem:alpha_bound_sampling}. 
We note that $\text{tr}(P) = \text{tr}(\sigma_v)\text{tr}\left(e^{-\beta H^{S_v}}\right)$, and $\text{tr}(\sigma_v)$ is known exactly. Since $H^{S_v}$ has locality and degree bounded by the constant locality $\mathcal{R}$ and degree $d$ of $H$, Corollary \ref{cor:partition_estimate} may therefore be applied to calculate its $\frac{\hat{q}_v}{\hat{p}_v}$ up to multiplicative error $25$. 
This establishes condition (1).

For condition (2), note that associated to any leaf $v$ is the state $\sigma_v$, whose classical representation includes the trace $\text{tr}(\sigma_v)$. 
It follows that $\frac{\hat{q}_v}{\hat{p}_v} = \text{tr}(\sigma_v)$ can be calculated exactly for any leaf $v$. 
Thus, condition (2) can be satisfied as well. 
\end{proof}

Condition (3) does not hold true for the tree $\mathcal{T}$. 
One simple way to see this is that in every application of Algorithm \ref{alg:pinning_subroutine}, there are infinite possible outcomes of the random choices, due to the sampling from probability distributions with infinite support in steps 2 and 3.  
Furthermore, 
Condition (4) is satisfiable, using the following lemma. 
After establishing this condition, we will design a subtree $\mathcal{T}'$ of $\mathcal{T}$ for which all four conditions may be attained, and ensure that the parameter $k$ in Theorem \ref{thm:simulate_distr} is such that $\log(k) \in \text{poly}(n)$. 
\begin{lemma}\label{lem:gen_decomp}
For any $S_i$ and $S_{i-1}$ as in Lemma \ref{lem:fermion_taylordecomp}, if $\beta \leq \frac{1}{2Cd}$ for some value $C > 1$, then $e^{-\beta H^{S_{i}}}e^{\beta H^{S_{i-1}}}= I + A$ where $\lVert A \rVert_\infty \leq \frac{1}{C-1}$.
\end{lemma}
\begin{proof}
Lemma \ref{lem:fermion_taylordecomp} decomposes $M_i$ as $I + \sum_{t>0}\sum_j c_{j, t} \Gamma_{j,t}$ such that $\sum_j c_{j, t} \leq C^{-t} $. 
Defining $A = \sum_{t>0} \sum_j c_{j, t} \Gamma_{j,t}$, we find that
\begin{equation}
\lVert A\rVert_\infty \leq \sum_{t > 0}\sum_j c_{j, t} \leq \sum_{t>0}C^{-t} = \frac{1}{C-1}. 
\end{equation}
\end{proof}
\begin{lemma} \label{lem:cond_4_satisfied}
Let $\mathcal{T}$ be the tree associated with Algorithm \ref{alg:pinning_subroutine} with the associated distributions $p$ and $q$, and let $\hat{p}_v = p_v$, $\hat{q}_v = \text{tr}(e^{-\beta H})q_v = \text{tr}(\sigma_v)p_v$ be the corresponding unnormalized distributions for any leaf $v$. 
Then condition (4) of Theorem \ref{thm:simulate_distr} is satisfied, with constant $\gamma_\mathcal{T} = 16000$. 
\end{lemma}

Next, we verify condition (4) of Theorem \ref{thm:simulate_distr}, that 
\[\left|\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)-\log\left(\frac{\hat{q}_w}{\hat{p}_w}\right)\right | \leq \log(\gammat),\]
for the constant $\gammat = 16000$.
Given that $\frac{\hat{q}_v}{\hat{p}_v} = \text{tr}(e^{-\beta H^{S_v}} (I + \alpha_v \Gamma_v) \sigma_v)$, from the proof of Lemma~\ref{lem:cond_1_2_satisfied},
we need only show that
\begin{equation}
    \left|\log\left(\text{tr}(e^{-\beta H^{S_v}}(I+\alpha_v \Gamma_v)\sigma_v)\right) - \log\left(\text{tr}(e^{-\beta H^{S_w}}(I+\alpha_w \Gamma_w)\sigma_w)\right)\right| = O(1).
\end{equation}
By an application of the triangle inequality, the following three relations suffices:
\[\left|\log\left(\text{tr}(\sigma_ve^{-\beta H^{S_v}}(I+\alpha_v \Gamma_v))\right) - \log\left(\text{tr}(\sigma_ve^{-\beta H^{S_v}})\right)\right| = O(1),\]
\[\left|\log\left(\text{tr}(\sigma_we^{-\beta H^{S_w}}(I+\alpha_w \Gamma_w))\right) - \log\left(\text{tr}(\sigma_we^{-\beta H^{S_w}})\right)\right| = O(1),\]
\[\left|\log\left(\text{tr}(\sigma_v)\text{tr}( e^{-\beta H^{S_v}})\right) - \log\left(\text{tr}(\sigma_w)\text{tr}(e^{-\beta H^{S_w}})\right)\right| = O(1).\]
The first two have already been shown in Lemma \ref{lem:cond_1_2_satisfied} in the proof of condition (1), each with the bound $25 = O(1)$. 

For the third relation, applying Lemma \ref{lem:gen_decomp} to $S_v$ and $S_w$ and using the triangle inequality, we may rewrite the inequality as
\[\left|\log\left(\text{tr}(e^{-\beta H^{S_w}}(I+A))\right) - \log\left(\text{tr}(e^{-\beta H^{S_w}})\right)\right| + \left|\log\left(\text{tr}(\sigma_v)\right) - \log\left(\text{tr}(\sigma_w)\right)\right| =O(1)\]
for some $A$. 
The second summand is at most $\log(25)$, since in any step $\sigma_v$ is multiplied by a commuting operator with trace 1 or trace $1 \pm \alpha_v$. 
This latter value lies in $[\frac{1}{25}, 1 + \frac{24}{25}]$, and therefore the logarithm is bounded in absolute value by $\log(25)$. 
Since $\beta \leq \frac{1}{50\mathcal{R}d^2} \leq \frac{1}{100d}$, we can take $C=25$, so $\lVert A \rVert_\infty \leq \frac{1}{49}$. 
Lemma \ref{lem:matrix_perturbation} applies again since $e^{-\beta H S_w}$ is positive, yielding an upper bound of $\log(25 \cdot 49 \cdot 48^{-1})$, including the second summand. 

In particular, we have shown that 
\begin{equation}
    \begin{aligned}
        &\left|\log\left(\text{tr}(e^{-\beta H^{S_v}}(I+\alpha_v \Gamma_v))\right) - \log\left(\text{tr}(e^{-\beta H^{S_w}}(I+\alpha_w \Gamma_w))\right)\right| \\&\leq \log\left(\left(\frac{1}{25}\right)^{-3}\cdot \left(\frac{48}{49}\right)^{-1}\right) \\
        &\leq \log(\gammat),
    \end{aligned}
\end{equation}
as desired.

\subsection{Truncated Sample Tree}\label{subsec:truncated_sample_tree}
\begin{theorem}[efficient algorithm]\label{thm:efficient_gibbs_sampling}
Assume that $H$ has locality $\mathcal{R}$ and has degree $d$, and $\beta \leq \frac{1}{50\mathcal{R}d^2}$. 
Then there exists a classical algorithm that can sample the Gibbs state to trace distance $\epsilon$ in time $\text{poly}(n, \log(\epsilon^{-1}))$.
\end{theorem}
To prove this theorem, we will create an approximate version of Algorithm \ref{alg:pinning_subroutine}, such that the corresponding tree $\mathcal{T}'$ will satisfy the conditions of Theorem \ref{thm:simulate_distr}. 
The following lemmas yields an approximate version of a sampling step in the algorithm. 

\begin{lemma}\label{lem:eff_sampl}
    There exists a $\text{poly}\left(\delta^{-1}\right)$-time algorithm that samples from a distribution $\mu'$ of outcomes $(t_k, I + (25\mathcal{R})^{-t_k}\Gamma_k)$ of Lemma \ref{lem:fermion_convexcomb}, which is precisely the distribution $\mu$ from Lemma \ref{lem:fermion_convexcomb} conditioned on an event $A$ with $\mathbb{P}_\mu[A] \geq 1 - \delta$, i.e. 
    \begin{equation}
    \mu'_X = \begin{cases}
    \displaystyle \frac{\mu_X}{\mathbb{P}_\mu[A]} & \text{if } X \in A \\
    0 & \text{if } X \notin A
    \end{cases}.
    \end{equation}
    Specifically, $A$ is the event that $t_k \leq t_\text{max}$ for threshold $t_\text{max} = \lceil \log_2\left(\delta^{-1}\right)\rceil$. 
    Moreover, the distribution $\mu'$ has support with size $\text{exp}(\text{polylog}\left(\delta^{-1}\right))$.
\end{lemma}
\begin{proof}
% \YT{what even $A$ is should be stated in the theorem} 
%Let the event $A$ be the event that $t_k \leq t_\text{max}$ for threshold $t_\text{max} = \lceil \log_2\left(\delta^{-1}\right)\rceil$. 
The distribution $\mu$ corresponds to the probabilities in the convex combination
\begin{equation}
M_i =   \sum_{t>0}\left(\left(2^{-t} - c_t(N\mathcal{R})^t\right)I + \sum_j c_{j,t}(N\mathcal{R})^t(I+ (N\mathcal{R})^{-t} \Gamma_{j,t})\right),
\end{equation}
where $\Gamma_{j,t}$ are $\mathcal{R}t$-local Majorana operators and $c_{j,t} \in \mathbb{R}^+.$
We will show that the probabilities in the convex combination
\begin{equation}
\sum_{t=1}^{t_{\text{max}}}\left(\frac{\left(2^{-t} - c_t(N\mathcal{R})^t\right)}{1-2^{-t_\text{max}}}I + \sum_j \frac{c_{j,t}(N\mathcal{R})^t}{1-2^{-t_\text{max}}}(I+ (N\mathcal{R})^{-t} \Gamma_{j,t})\right)
\end{equation}
can be sampled efficiently, and this is precisely the original distribution conditioned on the event $t_k \leq t_\text{max}$, which occurs with probability $1-2^{-t_\text{max}} \geq 1 - \delta$. 

This algorithm to perform this sampling will proceed in two steps. 
Firstly, it samples a value of $t = 1 , \dots, t_\text{max}$ from the distribution $\frac{2^{-t}}{1 - 2^{-t_\text{max}}}$, which may be done exactly and efficiently. 
Then, given the sampled $t$, it must sample $I$ with probability $1 - c_t(2N\mathcal{R})^t$ and each $I + (N\mathcal{R})^{-t}\Gamma_{j,t}$ with probability $c_{j, t}(2N\mathcal{R})^t$.
However, Corollary \ref{cor:sampl_cjt} is able to sample each $\Gamma_{j,t}$ with probabilities $p_{j,t} \geq c_{j,t}(2N\mathcal{R})^t$, in time. 
After sampling an operator $\Gamma_{j,t}$, the algorithm can further sample from $\{0, \Gamma_{j,t}\}$ with probabilities $1 - \frac{p_{j,t}}{(2N\mathcal{R})^{-t}}$ and $\frac{p_{j,t}}{c_{j, t}(2N\mathcal{R})^{-t}}$. We are now sampling each $\Gamma_{j,t}$ with probability $c_{j, t}(2N\mathcal{R})^{-t}$ and $0$ with the remaining probability.
Returning $I + (2N\mathcal{R})^{-t}\Gamma_{j,t}$ or $I$ correspondingly gives the desired algorithm.

The above algorithm chooses a value for $t \leq t_\text{max}$, and then applies Corollary \ref{cor:sampl_cjt} for $t$, which is efficient in $\log\delta^{-1}$ and $n$. 
Furthermore, Corollary \ref{cor:sampl_cjt} guarantees that the number of possible terms $(c_{j,t}, \Gamma_{j,t})$ for a given $t$ is at most $(t+1)! \cdot (d + 1)^t.$
Since we truncate the expansion at $t_{\text{max}} = \lceil \log_2 (\delta^{-1})\rceil$, the total number of possible sampling outcomes is at most 
\begin{equation}
\sum_{t = 0}^{t_{\text{max}}} (t+1)! \cdot (d+1)^t \leq (t_{\text{max}} +1)\cdot (t_{\text{max}} + 1)! \cdot (d+1)^{t_{\text{max}}}.
\end{equation}
Because $\log(\delta^{-1})!$ is quasipolynomial in $\delta^{-1}$, $(t_\text{max}+1)! = \text{exp}(\text{polylog}(\delta^{-1}))$.
Likewise, $(d+1)^{t_\text{max}} = O(\delta^{-\log(d+1)}) = \text{poly}(\delta^{-1})$. 
We conclude that the support of the sampling distribution is $\text{exp}(\text{polylog}(\delta^{-1}))$. 


