Using the above lemma, we can adapt Algorithm \ref{alg:pinning_subroutine} to make it efficient to implement, stated below:

\begin{algorithm}[Pinning one site, efficient]
\label{alg:pinning_subroutine_rounded}
\mbox{}\\

\textbf{Input:} Subset of terms $S \subseteq [2n]$ for unpinned sites and iteration $j$. Pinned unnormalized Gaussian states $\sigma$ and unpinned state $I + \alpha \Gamma.$ Desired trace distance $\epsilon$ between the sampled state and the Gibbs state, for $\epsilon \geq 0.$

\textbf{Output:} $(j', S', \sigma', \Gamma', \alpha')$, representing the pinned version of the input states at the next iteration.
\begin{enumerate}
    % \item Choose $i$ to be the minimal index in the support of $\Gamma$; if $\Gamma$ has empty support, choose the minimal $i$ in $S$. Define $S' = S - \{i\}$. 
    \item If $\text{supp}(\Gamma) \cap S$ is nonempty, set $i$ as the minimal index in $\text{supp}(\Gamma) \cap S$. Otherwise, let $i$ be the minimal index in $S$.
    Define $S' = S - \{i\}$. 
    Define $$M = e^{\beta H^{S'/2}}e^{-\beta H^{S/2}}.$$
    \item Sample $I + \beta_1 \Lambda_1$ for $\beta_1 = (25\mathcal{R})^{-t_1}$ from the probability distribution in Lemma \ref{lem:eff_sampl} with $\delta = \frac{\epsilon}{16n(\gammat+2)}$ for $\gammat$ as defined in Lemma~\ref{lem:cond_4_satisfied}, so that
    \[
    \mathbb{E}\left[I + \beta_1 \Lambda_1\right] = M =  e^{\beta H^{S'/2}}e^{-\beta H^{S/2}}.
    \]
    \item Sample $I + \beta_2 \Lambda_2$ for $\beta_2 = (25\mathcal{R})^{-t_2}$ independently from the same distribution, so that
    \[
    \mathbb{E}\left[I + \beta_2 \Lambda_2\right] = M^\dag.
    \]
    \item Set $\sigma' \gets \sigma$ and $(\Gamma', \alpha')$ as:
        \begin{enumerate}
            \item $\bigl(\Gamma, (1-\frac{1}{\mathcal{R}})^{-1}\alpha_{j}
            \bigl)$ with probability $1 - \frac{1}{\mathcal{R}}$
            \item $\left(\Lambda_1, (6\mathcal{R})\beta_1\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_2, (6\mathcal{R})\beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_1\Gamma, (6\mathcal{R})\beta_1\alpha_{j}\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Gamma\Lambda_2, (6\mathcal{R})\alpha_{j} \beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_1\Lambda_2, (6\mathcal{R})\beta_1 \beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
            \item $\left(\Lambda_1\Gamma\Lambda_2, (6\mathcal{R})\beta_1\alpha_{j}  \beta_2\right)$ with probability $\frac{1}{6\mathcal{R}}$
        \end{enumerate}
    \item If $\Gamma'$ is not Hermitian:
    \begin{itemize}
        \item $\Gamma' \leftarrow 0, \alpha' \leftarrow 0$.
    \end{itemize}
    \item  If there are two indices $k, l \in S_j^c$ such that $k, l \in \text{supp}\left(\Gamma'\right)$, i.e. $\Gamma' =\Gamma^- \cdot (i\gamma_k \gamma_l)$: 
    \begin{enumerate}
        \item $\Gamma' \leftarrow \Gamma^-$, $\sigma' \leftarrow (I + i\gamma_k\gamma_l) \cdot \sigma'$ with probability $\frac{1}{2}$
        \item $\Gamma' \leftarrow -\Gamma^-$, $\sigma' \leftarrow (I - i\gamma_k\gamma_l) \cdot \sigma'$ with probability $\frac{1}{2}$
    \end{enumerate}
    \item If $\Gamma' \in \{\pm I\}$:
        \begin{itemize}
            \item $\sigma' \leftarrow (I + \alpha' \Gamma')\sigma'$, $\Gamma' \leftarrow 0$,  and $\alpha' \leftarrow 0$. 
        \end{itemize}
    \item $j \gets j + 1$.
\end{enumerate}
\end{algorithm}
Indeed, the rest of the algorithm consists of products of scalars and Majorana strings, which can be encoded efficiently. 
For this new algorithm, we may now define a new tree $\mathcal{T}'$, where again the root node is $(0, S_0, \sigma_0, \Gamma_0, \alpha_0)$, and the children of a given node are obtained by an application of Algorithm \ref{alg:pinning_subroutine_rounded}. 
Note that $\mathcal{T}'$ can be naturally identified as a subtree of $\mathcal{T}$, because the two algorithms are identical except that the sampling distribution in Lemma \ref{lem:eff_sampl} has support contained in that of Lemma \ref{lem:fermion_convexcomb}. 
With this algorithm, we may define a distribution $p'$ on the leaves, where $p'_w$ is the probability of reaching the node $w$ from the root with a repeated application of Algorithm \ref{alg:pinning_subroutine_rounded}. 
Let $\hat{p}'_w = p'_w$ for any leaf. 
We may also define an unnormalized distribution $\hat{q}'$ on the leaves by 
\begin{equation}
\hat{q}'_w = \text{tr}(\sigma_w)\hat{p}'_w.
\end{equation}
Here, $\hat{q}'$ is being defined in direct analogy to $\hat{q}$.
Then, $q'$ is simply its normalization, i.e. 
\begin{equation}
q'_v = \frac{\hat{q}'_v}{\sum_{w\in \mathcal{L}_{\mathcal{T}'}(r)} \hat{q}'_v}= \frac{\hat{q}'_v}{\hat{q}'_r},
\end{equation}
where $r$ denotes the root node. 

Using Lemma \ref{lem:eff_sampl}, we can establish a relationship between $p_v$ and $p_v'$. 
In particular, for any vertex $v$ in the tree $\mathcal{T}'$, their difference is at most $Cp_v'$ for an appropriate constant that is determined by our choice of $\delta$. 
This bound is obtained by using a similar bound on the conditional distributions of the children of $v$, specifically $\frac{p_w'}{p_v'}$ and $\frac{p_w}{p_v}$. 
\begin{lemma}\label{lem:p_p'_relationship}
For the distribution $p'$ obtained from Algorithm ~\ref{alg:pinning_subroutine_rounded}, and for any node $v$ and child $w$ in the tree $\mathcal{T}'$, $\left|\frac{p_w'}{p_v'} - \frac{p_w}{p_v}\right| \leq \frac{\epsilon}{8n(\gammat+2)}\left(\frac{p_w'}{p_v'}\right)$. 
Moreover, for any leaf node $v \in \mathcal{L}_{\mathcal{T}'}(r)$, $|p_v - p_v'| \leq \frac{\epsilon}{4(\gammat+2)}p_v'$. 
% \YT{need to introduce $\epsilon$ and $\gamma_\tau$. Maybe say $p'$ is the distribution obtained from Algorithm~\ref{alg:pinning_subroutine_rounded}.}
\end{lemma}
\begin{proof}
The only difference between Algorithm \ref{alg:pinning_subroutine} and Algorithm \ref{alg:pinning_subroutine_rounded} is that the sampling in steps 2 and 3 are from different distributions. By Lemma \ref{lem:eff_sampl}, the distribution in Algorithm \ref{alg:pinning_subroutine_rounded} is simply the distribution in Algorithm \ref{alg:pinning_subroutine} conditioned on an event of probability at least $1 - \delta$. 

There are two such events $A_1, A_2$ that occur in each application of Algorithm \ref{alg:pinning_subroutine_rounded}, more specifically in steps 2 and 3. 
As such, the conditional distribution $\frac{p_w'}{p_v'}$ for $w$, i.e. the children of a fixed node $v$, is precisely $\frac{p_w}{p_v}$ conditioned on the joint event $A_1 \cap A_2$, which happens as an event of probability at least $1-2\delta$ by a union bound.
We choose $\delta = \frac{\epsilon}{16n(\gammat+2)}.$
It follows that
\[\left|\frac{p_w}{p_v} - \frac{p_w'}{p_v'}\right| = \frac{p_w'}{p_v'} - \frac{p_w}{p_v} \leq \frac{p_w'}{p_v'}-\left(1-\frac{\epsilon}{8n(\gammat+2)}\right)\frac{p_w'}{p_v'} = \frac{\epsilon}{8n(\gammat+2)}\left(\frac{p_w'}{p_v'}\right), \]
where the first inequality holds since $\frac{p_w'}{p_v'} = \frac{p_w/p_v}{\mathbb{P}_{p}[A_1 \cap A_2]} \leq \frac{p_w/p_v}{1-\epsilon/8n(\gammat+2)}$. 

To traverse the entire tree to a leaf, there are $2n$ steps, which means we iteratively apply Algorithm \ref{alg:pinning_subroutine_rounded} $2n$ times.
Thus, the distribution $p_v'$ over the leaves $v$ is $p_v$ conditioned on an event of probability at least $1 - 2n \cdot 2\delta = 1 - \frac{\epsilon}{4(\gammat+2)}$ by a union bound as well.
For any leaf node $v \in \mathcal{L}_{\mathcal{T}'}(r)$, it follows by the same reasoning as the above that  
\[|p_v - p_v'| \leq  \frac{\epsilon}{4(\gammat+2)}p_v'. \]
\end{proof}

For our new tree $\mathcal{T}'$, there is also a natural bound on the number of children of any node. 
\begin{lemma}\label{lem:tree_bound}
The number of children of any node in $\mathcal{T}'$ is at most $k$ for $\log(k) = \text{poly}(n, \log(\epsilon^{-1}))$. 
\end{lemma}
\begin{proof}
The sampling algorithm in Algorithm \ref{alg:pinning_subroutine} involves three random choices. 
The first two are calls to the efficient sampling algorithm from Lemma \ref{lem:eff_sampl}, in step 2 and 3 of the algorithm respectively, which has support with size $\text{exp}(\text{poly}(\log (\delta^{-1})))$.
We will use a more crude bound of $\text{exp}(\text{poly}(\delta^{-1}))$ for the support to simplify the choice of $\delta$ below.
We choose $\delta = \frac{\epsilon}{16n(\gammat+2)}$, from which we get the number of possible outcomes in the form of $(t_i, I + \beta_{t_i} \Lambda_{t_i})$ for each of these two calls is bounded by $\text{exp}(\text{poly}(n, \log (\epsilon^{-1}))).$
% The algorithm's random choice involves a choice of what degree to sample from, from zero to $\lceil \delta^{-1} \rceil$.
% Up to this degree, at each step some local term of $H$ 
% Each of these choices involves 
The next two calls are random choices from seven choices of $(\Gamma, \sigma, \alpha)$ in step 4 and two options of $(\Gamma, \sigma, \alpha)$ in step 6, giving an additional factor of 14, which is constant. 
This gives us the final number of children of at most $k = \text{exp}(\text{poly}(n, \log (\epsilon^{-1}))).$
\end{proof}

We will now establish two important results that relate distributions on $\mathcal{T}$ to those on $\mathcal{T}'$, presented in Lemma \ref{lem:approximate_expectation} and Lemma \ref{lem:q_approx} below, which will each be important in the proof of Theorem~\ref{thm:efficient_gibbs_sampling}.
Lemma \ref{lem:approximate_expectation} is the most technical, bounding the difference between $\frac{\hat{q}_v}{\hat{p}_v}$ and $\frac{\hat{q}'_v}{\hat{p}'_v}$. 
We have previously seen $\frac{\hat{q}_v}{\hat{p}_v}$ to be the expected value of $\text{tr}(\sigma_w)$ for leaves $w$ below $v$ under the distribution $p_w$, so intuitively the lemma establishes how well the primed distribution approximates these conditional expectations. 
It has two roles: it will allow us to relate $\hat{q}_r$ to $\hat{q}'_r$, and bound the multiplicative distance between $\frac{\hat{q}_v'}{\hat{p}_v'}$ and $\frac{\hat{q}_w'}{\hat{p}_w'}$ for a node $v$ and its child $w$ (to satisfy condition (1)) . 


\begin{lemma}\label{lem:approximate_expectation}
For any node $v \in \mathcal{T}'$,
\[\left|\frac{\hat{q}'_v}{\hat{p}'_v}- \frac{\hat{q}_v}{\hat{p}_v}\right| \leq \frac{ (2n-j_v)(\gammat+1)\epsilon}{8n(\gammat + 2) }\max\left(\frac{\hat{q}_v'}{\hat{p}_v'} , \frac{\hat{q}_v}{\hat{p}_v}\right). \]
In particular, 
\[\left|\log\left(\frac{\hat{q}'_v}{\hat{p}'_v}\right)- \log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)\right| \leq \log\left(1+\frac{ (2n-j_v)(\gammat+1)\epsilon}{4n (\gammat+2)}\right).\]
\end{lemma}
\begin{proof}
We will prove this reduction by descending strong induction on the depth of $v$, with the base case of $j_v = 2n$.
In this case, by definition $\frac{\hat{q}_v'}{\hat{p}_v'} = \frac{\hat{q}_v}{\hat{p}_v} = \text{tr}(\sigma_v)$, so the result is immediate.
Now see that we may write $\frac{\hat{q}'_v}{\hat{p}'_v}$ as 
\[\frac{\hat{q}'_v}{\hat{p}'_v} = \sum_{w\in \mathcal{C}_{\mathcal{T}'}(v)} \left(\frac{\hat{q}'_w}{\hat{p}'_w}\right) \cdot \left( \frac{\hat{p}'_w}{\hat{p}'_v}\right) = \sum_{w\in \mathcal{C}_{\mathcal{T}'}(v)} \left(\frac{\hat{q}'_w}{\hat{p}'_w}\right) \cdot \left( \frac{\hat{p}_w}{\hat{p}_v}\right)+\sum_{w\in \mathcal{C}_{\mathcal{T}'}(v)} \left(\frac{\hat{q}'_w}{\hat{p}'_w}\right)  \left( \frac{\hat{p}'_w}{\hat{p}'_v}-\frac{\hat{p}_w}{\hat{p}_v}\right),\]
Likewise,  
\[\frac{\hat{q}_v}{\hat{p}_v} = \sum_{w\in \mathcal{C}_{\mathcal{T}}(v)} \left(\frac{\hat{q}_w}{\hat{p}_w}\right) \cdot \left( \frac{\hat{p}_w}{\hat{p}_v}\right).\]
The proof of Lemma \ref{lem:p_p'_relationship} states that the distribution $\frac{p'_w}{p'_v}$ is the distribution $\frac{p_w}{p_v}$ conditioned on an event with probability at least $1 - \frac{\epsilon}{8n(\gammat+2)}$.

By induction, we assume that for all children nodes $w \in \mathcal{C}_{\mathcal{T}'}(v)$ (which necessarily satisfy
$j_w = j_v + 1$), the following holds: 
\[\left|\frac{\hat{q}_w'}{\hat{p}_w'} - \frac{\hat{q}_w}{\hat{p}_w} \right| \leq \left(\frac{ (2n-j_w )(\gammat+1)\epsilon}{8n(\gammat+2)}\right)\max\left(\frac{\hat{q}_v'}{\hat{p}_v'} , \frac{\hat{q}_v}{\hat{p}_v}\right).\]
The base case for leaf nodes is clear because they are precisely equal, both $\text{tr}(\sigma_w)$. 
Now see that
\begin{align*}
&\left|\frac{\hat{q}_v'}{\hat{p}_v'} - \frac{\hat{q}_v}{\hat{p}_v} \right| \\&= 
\left| \sum_{w \in \mathcal{C}_{\mathcal{T}'}(v)} \left(\frac{\hat{q}_w'}{\hat{p}_w'} - \frac{\hat{q}_w}{\hat{p}_w}\right)\cdot \left(\frac{\hat{p}_w}{\hat{p}_v}\right) + \sum_{w\in \mathcal{C}_{\mathcal{T}'}(v)} \left(\frac{\hat{q}'_w}{\hat{p}'_w}\right)  \left( \frac{\hat{p}'_w}{\hat{p}'_v}-\frac{\hat{p}_w}{\hat{p}_v}\right) - \sum_{w \in \mathcal{C}_{\mathcal{T}}(v) \backslash \mathcal{C}_{\mathcal{T}'}(v)} \left(\frac{\hat{q}_w}{\hat{p}_w}\right)\cdot \left(\frac{\hat{p}_w}{\hat{p}_v}\right)\right|\\
&\leq \sum_{w \in \mathcal{C}_\mathcal{T}'(v)} \left|\frac{\hat{q}_w'}{\hat{p}_w'} - \frac{\hat{q}_w}{\hat{p}_w}\right|\cdot \left(\frac{\hat{p}_w}{\hat{p}_v}\right) + \frac{\epsilon}{8n(\gammat+2)} \left(\frac{\hat{q}_v'}{\hat{p}_v'}\right) + \frac{\gammat \epsilon}{8n(\gammat+2)}\left(\frac{\hat{q}_v}{\hat{p}_v    }\right)\\
&\leq \frac{(2n - j_v - 1)(\gammat+1)\epsilon}{8n(\gammat+2)}\max\left(\frac{\hat{q}_v'}{\hat{p}_v'} , \frac{\hat{q}_v}{\hat{p}_v}\right) + \frac{\epsilon}{8n(\gammat+2)}\left(\frac{\hat{q}_v'}{\hat{p}_v'}\right) + \frac{\gammat \epsilon}{8n(\gammat+2)}\left(\frac{\hat{q}_v}{\hat{p}_v} \right)\\
&\leq \frac{(2n - j_v)(\gammat+1)\epsilon}{8n(\gammat+2)}\max\left(\frac{\hat{q}_v'}{\hat{p}_v'} , \frac{\hat{q}_v}{\hat{p}_v}\right),
\end{align*}
where we use Lemma \ref{lem:p_p'_relationship} in the first inequality, as well as the fact that $\frac{\hat{q}_w}{\hat{p}_w} \leq \gammat \frac{\hat{q}_v}{\hat{p}_v}$ for any child $w$ of $v$. To obtain the second statement, note that since $\frac{\epsilon(\gammat+1)}{4(\gammat+2)} \leq \frac{\epsilon}{4} \leq \frac{1}{2}$, explicit calculation shows us that the first statement implies that
\[\left|\log\left(\frac{\hat{q}'_v}{\hat{p}'_v}\right)-\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)\right | \leq \log\left( 1+ 2\left(\frac{\epsilon(\gammat+1)}{4(\gammat+2)}\right)\right) = \log\left(1 + \frac{\epsilon(\gammat+1)}{2(\gammat+2)}\right).\]
\end{proof}

