We are now ready to prove that sampling from $q'_v$ amount to sampling from $q_v$, up to a total variation distance of $\frac{\epsilon}{2}$. 
The proof of this lemma reduces to the previous bound on $|p_v - p_v'|$, and the technical result of Lemma \ref{lem:approximate_expectation} that can bound the difference of $\hat{q}_r'$ and $\hat{q}_r$. 
The constant $\delta$ was chosen precisely to obtain the following bound. 
\begin{lemma}\label{lem:q_approx}
The total variation distance of the distributions $q_v$ and $q'_v$ is bounded by $\frac{\epsilon}{2}$. 
\end{lemma}
\begin{proof}
The total variation distance of the two distributions may be written as
\begin{align*}
\text{TV}(q, q')&=\frac{1}{2}\sum_{v \in \mathcal{L}_{\mathcal{T}(r)}} |q_v - q_v'| \\&= \frac{1}{2}\sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} |q_v - q_v'| + \frac{1}{2}\sum_{v \in \mathcal{L}_{\mathcal{T}(r)} \backslash \mathcal{L}_{\mathcal{T'}(r)}} |q_v - q_v'|\\
&= \frac{1}{2}\sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} |q_v - q_v'| + \frac{1}{2}\sum_{v \in \mathcal{L}_{\mathcal{T}(r)} \backslash \mathcal{L}_{\mathcal{T'}(r)}} q_v \\
&\leq \sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} |q_v - q_v'|,
\end{align*}
where the second equality holds since $\hat{q}'_v=0$ for nodes $v \notin \mathcal{L}_{\mathcal{T}'}(r)$, and the inequality holds because 
\[\sum_{v \in \mathcal{L}_{\mathcal{T}(r)} \backslash \mathcal{L}_{\mathcal{T'}(r)}} q_v = 1 - \sum_{v \in \mathcal{L}_{\mathcal{T}'}(r) } q_v = \sum_{v \in \mathcal{L}_{\mathcal{T}'}(r) } q'_v - q_v \leq \sum_{v \in \mathcal{L}_{\mathcal{T}'}(r) } |q_v - q'_v|. \]
Now, it follows that, denoting the root of $\mathcal{T}'$ by $r$,
\begin{align*}
\text{TV}(q, q')&\leq\sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} |q_v - q_v'| 
\\ &= \sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \left|\frac{\hat{q}_v}{\hat{q}_r}  - \frac{\hat{q}_v'}{\hat{q}_r'} \right|
\\&\leq \frac{1}{\hat{q}_r'}\sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \left|\hat{q}_v  - \hat{q}_v' \right| + \sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \left|\frac{\hat{q}_v}{\hat{q}_r}  - \frac{\hat{q}_v}{\hat{q}_r'}\right|
\\&= \frac{1}{\hat{q}_r'}\sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \text{tr}(\sigma_v)|p_v-p_v'| + \sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \frac{\hat{q}_v}{\hat{q}_r\hat{q}_r'}\left|\hat{q}_r'  - \hat{q}_r\right|
\\ &\leq \frac{1}{\hat{q}_r'}\sum_{v \in \mathcal{L}_{\mathcal{T}'}(r)} \text{tr}(\sigma_v)|p_v-p_v'|+ \sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \frac{\hat{q}_v}{\hat{q}_r}\left(\frac{\epsilon(\gammat+1)}{2(\gammat+2)} \right) \\ &\leq \frac{\epsilon}{4(\gammat+2) \hat{q}_r'} \sum_{v \in \mathcal{L}_{\mathcal{T}'}(r)} p'_v \text{tr}(\sigma_v) + \frac{\epsilon(\gammat+1)}{2(\gammat+2) }\\&= \frac{\epsilon}{4(\gammat+2)\hat{q}_r'} \sum_{v \in \mathcal{L}_{\mathcal{T}'}(r)}\hat{q}'_v+ \frac{\epsilon(\gammat+1)}{2(\gammat+2) } \\&< \frac{\epsilon}{2}
\end{align*}
as desired.
Here, the second inequality comes from applying a direct triangle inequality, and the third inequality comes from Lemma \ref{lem:approximate_expectation}, applied to the root node $r$. 
In particular, since $\hat{p}_r= \hat{p}_r'=1$, we have that $\left |\log(\hat{q}'_r)- \log(\hat{q}_r) \right| \leq \log(1 + \frac{\epsilon(\gammat+1)}{2(\gammat+2)})$, which implies that $|\hat{q}_r - \hat{q}'_r| \leq \frac{\epsilon(\gammat+1)}{2(\gammat+2)}\hat{q}'_r$.
The last inequality comes from applying Lemma \ref{lem:p_p'_relationship} and the fact that $\sum_{v \in \mathcal{L}_{\mathcal{T}'(r)}} \frac{\hat{q}_v}{\hat{q}_r} \leq 1.$
We further note that $\sum_{v \in \mathcal{L}_{\mathcal{T}'}(r)}\hat{q}'_v = \hat{q}'_r$ to arrive at the final expression. 
\end{proof}

Having developed approximate analogs of the original distributions on $\mathcal{T}$, we can prove Theorem~\ref{thm:efficient_gibbs_sampling}. 
\\
\begin{proof}[Theorem~\ref{thm:efficient_gibbs_sampling}]
This proof will proceed in two steps. 
Firstly, we will show that all four conditions of Theorem~\ref{thm:simulate_distr} are satisfied for the distributions $p'$ and $q'$. 
Then, we will show that the ability to sample from $q'$ yields the desired Gibbs sampling algorithm. 

We will establish each condition of $p'$ and $q'$ necessary for Theorem \ref{thm:simulate_distr}. 
We also have that condition (2) is easily satisfied. 
Indeed, by definition, for any leaf node $v \in \mathcal{T}'$
\[\frac{\hat{q}_v'}{\hat{p}'_v} = \text{tr}(\sigma_v),\]
which can be exactly calculated given $v$. 
Condition (3) is also satisfied. 
Indeed, for any internal node $v$ and a child $v_k$, $\frac{p'_{v_k}}{p'_v}$ is the conditional probability of reaching $v_k$ by repeated application of Algorithm \ref{alg:pinning_subroutine_rounded} given that the algorithm reaches $v$. 
A single application of Algorithm 22 therefore suffices to sample the children of $v$ according to this probability distribution. 
Now notice that both conditions (1) and (4) follow from the statement of Lemma \ref{lem:approximate_expectation}, which implies that
\[\left|\log\left(\frac{\hat{q}'_v}{\hat{p}'_v}\right)-\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)\right | \leq \log\left( 1+ \frac{\epsilon}{2}\right).\]
As we have already demonstrated an efficient algorithm to calculate $\frac{\hat{q}_v}{\hat{p}_v}$ up to constant multiplicative error, this statement shows that the same algorithm calculates $\frac{\hat{q}_v'}{\hat{p}_v'}$ up to constant multiplicative error. Condition (1) is therefore satisfied. 
Meanwhile, condition (4) can be obtained from the triangle inequality, since for a node $v$ and a child $w$, 
\begin{equation*}
\begin{aligned}
\left|\log\left(\frac{\hat{q}'_v}{\hat{p}'_v}\right)-\log\left(\frac{\hat{q}'_w}{\hat{p}'_w}\right)\right |
&\leq \left|\log\left(\frac{\hat{q}'_v}{\hat{p}'_v}\right)-\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)\right | + \left|\log\left(\frac{\hat{q}_v}{\hat{p}_v}\right)-\log\left(\frac{\hat{q}_w}{\hat{p}_w}\right)\right | \\
& + \left|\log\left(\frac{\hat{q}'_w}{\hat{p}'_w}\right)-\log\left(\frac{\hat{q}_w}{\hat{p}_w}\right)\right | \\
&\leq 2 \log \left(1 + \frac{ \epsilon}{2}\right) + \log (\gammat), 
\end{aligned}
\end{equation*}
where the middle term is at most $\log(\gammat)$ since condition (4) is satisfied for $\hat{p}$ and $\hat{q}$. 
We may therefore apply Theorem \ref{thm:simulate_distr} and obtain a $\text{poly}(n, \log(\epsilon^{-1}), \log(k))$ algorithm to sample a distribution $q''$ that is $q'$ up to $\frac{\epsilon}{2}$ total variation distance.
The number of children of each node was bounded in Lemma \ref{lem:tree_bound} so that $\log(k)$ is polynomial in $n$.
By Lemma \ref{lem:q_approx}, the total variation distance between $q''$ and $q$ is at most $\epsilon$.
It follows that
\begin{align*}
\left\lVert \sum_{v \in \mathcal{L}_\mathcal{T}(r)} q''_v \frac{\sigma_v}{\text{tr}(\sigma_v)}- \rho_\beta\right\rVert_{\text{tr}} &= \frac{1}{2}\left\lVert \sum_{v \in \mathcal{L}_\mathcal{T}(r)} q''_v \frac{\sigma_v}{\text{tr}(\sigma_v)}- \rho_\beta\right\rVert_1 \\
&= \frac{1}{2}\left\lVert \sum_{v \in \mathcal{L}_\mathcal{T}(r)} q''_v \frac{\sigma_v}{\text{tr}(\sigma_v)}- \sum_{v \in \mathcal{L}_\mathcal{T}(r)} q_v \frac{\sigma_v}{\text{tr}(\sigma_v)}\right\rVert_1 \\&\leq \frac{1}{2} \sum_{v \in \mathcal{L}_\mathcal{T}(r)}| q''_v-q_v|\\
&\leq \epsilon,
\end{align*}
giving the desired trace distance bound. 

\end{proof}

