\section{Notation and Preliminaries}\label{notation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
For $k\in N^+$ and $1\leq p\leq +\infty$, we denote $L^p(\Omega)$ and $W^{k, p}(\Omega)$ as the classical Lebesgue space and Sobolev space, respectively. The norms of these spaces are denoted by
\begin{align*}
	||u||_{L^p(\Omega)}&=\left(\int_{\Omega}|u(\mathbf{x})|^p\diff \mathbf{x}\right)^\frac{1}{p},\\
	||u||_{W^{k,p}(\Omega)}&=\left(\sum\limits_{|j|\leq k}||D^ju||_{L^p(\Omega)}^p\right)^\frac{1}{p}.
\end{align*}
within this context, $W^{k, 2}(\Omega)$ is also known as the Hilbert space and can be expressed as $H^k(\Omega)$.  $||\cdot||_{L^\infty}$ represents the norm of the space  $L^\infty(\Omega)$ which is defined as
\begin{equation*}
	||u||_{L^\infty(\Omega)}=ess\sup\limits_{\mathbf{x}\in \Omega}|u(\mathbf{x})|.
\end{equation*}

For simplicity, we denote the inner products of both
$L^2(\Omega)$ and $\textbf{L}^2(\Omega)$
by $(\cdot,\cdot)$, and use $\langle \cdot,\cdot \rangle$ to denote the dual product of $H^{-1}(\Omega) \times H^1_0(\Omega)$. namely,
\begin{align*}
	\begin{split}
		&(u,v)=\int_\varOmega u(x)v(x) d x \quad \forall  \, u,v\in L^2(\Omega),\\
		&({\bf u},{\bf v})=\int_\Omega {\bf u}(x)\cdot {\bf v}(x) dx \quad \forall \, {\bf u},{\bf v}\in {\bf L}^2(\Omega) .\\
	\end{split}
\end{align*}
