		B(\textbf{u},\textbf{v},\textbf{w}) &= \int_\Omega (\u \cdot \nabla \textbf{v}) \cdot\textbf{w} dx + \frac{1}{2} \int_{\Omega} (\nabla \cdot \u) \v \cdot \w dx \\
		&=   \frac{1}{2}\int_\Omega (\u \cdot \nabla \textbf{v}) \cdot\textbf{w} dx -  \frac{1}{2} \int_{\Omega} (\u \cdot \nabla) \w \cdot\v dx  \quad \forall ~\u,\v,\w\in\textbf{V},\\
		b(\u,c,r) &=  \int_\Omega (\u \cdot \nabla c)r dx+ \frac{1}{2} \int_{\Omega} (\nabla \cdot \u) crdx, \\
		&=\frac{1}{2}\int_\Omega (\u \cdot \nabla c) r dx -  \frac{1}{2} \int_{\Omega} (\u \cdot \nabla r) c dx \quad \forall ~\u \in \V, \,  \forall c,r \in X.
