which has the following properties \cite{heyinnian2005,heyinnian2022}
\begin{align}
	& B(\textbf{u},\textbf{v},\textbf{v})=0, \quad b(\u,r,r)=0,\label{biobdf-2}\\
	&B(\textbf{u},\textbf{v},\textbf{w}) = - b(\textbf{u},\textbf{w},\textbf{v}),\quad b(\textbf{u},c,r) = - b(\textbf{u},r,c),\label{biobdf-17}\\
	&B(\textbf{u},\textbf{v},\textbf{w}) \leq C \| \nabla \textbf{u} \|_{L^2} \| \nabla \textbf{v} \| _{L^2} \| \nabla \textbf{w} \|_{L^2},\quad b(\textbf{u},c,r) \leq C \| \nabla \textbf{u} \|_{L^2} \| \nabla c \| _{L^2} \| \nabla r \|_{L^2},\\
	&B(\textbf{u},\textbf{v},\textbf{w})  \leq C \| \textbf{u} \| ^{\frac{1}{2}}_{L^2} \| \nabla \textbf{u}\| ^{\frac{1}{2}}_{L^2} \| \nabla \textbf{v} \| _{L^2} \| \nabla \textbf{w} \|_{L^2}, \quad  b(\textbf{u},c,r)  \leq C \| \textbf{u} \| ^{\frac{1}{2}}_{L^2} \| \nabla \textbf{u}\| ^{\frac{1}{2}}_{L^2} \| \nabla c \| _{L^2} \| \nabla r \|_{L^2}.
\end{align}

If $\nabla \cdot \u=0$, there holds $B(\textbf{u},\textbf{v},\textbf{w}) = (\textbf{u} \cdot \nabla \textbf{v},\textbf{w})= \int_\Omega (\u \cdot \nabla \textbf{v}) \cdot\textbf{w} dx $ and $b(\u,c,r) = (\textbf{u} \cdot \nabla c,r) = \int_\Omega (\u \cdot \nabla c)r dx$.

Set $m_0 = \frac{1}{| \Omega|} \int_{\Omega} \eta_0 dx >0$, and take  $\tilde{\eta} = \eta-m_0$ as  the new variable, then the original problem  (\ref{cfmodel}) can be written by the following forms.
\begin{align}\label{recfmodel}
	\begin{cases}
		\tilde{\eta}_t- \alpha_\eta \Delta \tilde{\eta} + \beta \, \text{div} ((\tilde{\eta}+m_0) \nabla c) + u \cdot \nabla \tilde{\eta} = 0, & \quad \text{in } \Omega \times (0, T], \\
		c_t - \alpha_c \Delta c + u \cdot \nabla c + \gamma (\tilde{\eta}+m_0) c = 0, &\quad \text{in } \Omega \times (0, T], \\
		u_t + (u \cdot \nabla) u - \nu \Delta u + \nabla p = (\tilde{\eta}+m_0) \nabla \phi, & \quad\text{in } \Omega \times (0, T], \\
		\text{div} \, u = 0, & \quad\text{in } \Omega \times (0, T], \\
		\frac{\partial \tilde{\eta}}{\partial n} = 0, \, \frac{\partial c}{\partial n} = 0, \, u = 0, &\quad \text{on } \partial \Omega \times (0, T], \\
		\tilde{\eta}(\cdot, 0) =\tilde{\eta}_0, \, c(\cdot, 0) = c_0, \, u(\cdot, 0) = u_0, &\quad \text{in } \Omega.
	\end{cases}
\end{align}

We present the main error estimate of $ ( \u,p,\eta,c)$ under the following regularity assumptions.

\textbf{Assumption A1}: Assume the exact solutions $ ( \u,p,\eta,c)$  satisfy
\begin{align}\label{cf-regularity}
	\begin{cases}
	\| \phi \|_{H^2} \leq C,\\
	\u \in L^\infty (0,T; W^{2,4}), \quad  \u_t \in L^{2}(0,T;H^2), \quad \u_{tt} \in L^2(0,T;H^{-1}(\Omega)),\\
	p \in L^{\infty}(0,T;H^1), \quad p_t \in L^2(0,T; H^1),\\
	\tilde{\eta} \in L^{\infty}({0,T; W^{2,4}}), \quad \tilde{\eta}_t \in L^{2}(0,T;H^2), \quad \tilde{\eta}_{tt} \in L^2(0,T;L^2),\\
	c\in L^{\infty} (0,T;W^{2,4}), \quad   c_t \in L^{2}(0,T;H^2), \quad c_{tt }\in L^2(0,T;L^2).
			\end{cases}
\end{align}

The following discrete Gronwall inequality established in \cite{evance2022,heywood1990} will be used frequently.
\begin{lemma} (Discirete Gronwall's inequality ) Let $a_k , b_k$ and $y_k$ be the nonnegative numbers such that \label{biobdf-11}
	\begin{align}\label{growninequality-discrete}
		a_n+ \tau \sum \limits^n \limits_{k=0}  b_k\leq \tau \sum \limits^n \limits_{k=0} \gamma _k a_k + B \quad \text{for} \,\, n \geq 1,
	\end{align}
	Suppose $\tau \gamma _k \leq 1$ and set $\sigma_k = (1-\tau \gamma_k) ^{-1}$. Then there holds
	\begin{align}\label{grown2}
		a_n + \tau \sum \limits^n \limits_{k=0} b_k \leq exp(\tau \sum \limits^n \limits_{k=0} \gamma_k \sigma_k) B \quad  \text{for} \,\, n\geq 1.
	\end{align}
	\begin{remark}
		If the sum on the right-hand side of (\ref{growninequality-discrete}) extends only up to $n-1$, then the estimate (\ref{grown2}) still holds for all $k \geq 1$ with $\sigma_k=1$.
	\end{remark}

\end{lemma}

The following Sobolev inequalities in 2D will be used frequently. \cite{evance2022}
\begin{align}\label{cf-inequality}
