		&W^{2,4}(\Omega)  \hookrightarrow W^{1,\infty}(\Omega),\\ 
		&H^2(\Omega) \hookrightarrow W^{1,q}(\Omega), \quad 2 \leq q < \infty,\\
		&H^2(\Omega) \hookrightarrow L^{\infty}(\Omega).
	\end{cases}
\end{align}

