%Let $\{t_n= n\tau\}^N_n=0$ denote a uniform partition of the time interval $[0,T]$, with a step size $\tau=T/ N$, and $v^n=v(x,t_n)$. by defining $D_{\tau} v^{n+1}= \frac{v^{n+1} -v^n}{\tau}$ and starting with $ (\u^0_h,p^0_h,\tilde{\eta}^0_h,c^0_h)$, the fully discrete pressure-correction projection method for the Chemotaxis-Fluid system (\ref{recfmodel}) is formulated as: 

\textbf{The pressure-correction projection finite element method:}

\textbf{Step 1: } For given $(\u^{n}_h, p^n_h, \tilde{\eta}^n_h)$, we find $\u^{n+1}_h$ by 
\begin{align}\label{cf-scheme1}
	( \frac{\tilde{\u}^{n+1} -\u^n  }{\tau},\v_h   ) + \mu (\nabla \tilde{\u}^{n+1}_h,\v_h)+ B(\u^n_h, \tilde{\u}^{n+1}_h,\v_h) + (\nabla p^n_h, \v_h) \\
	= ( ( \tilde{\eta}^n_h+m_0) \nabla \phi^{n+1},\v_h  ), \quad \forall \v_h \in \V_h.\notag
\end{align}

\textbf{Step 2:}
Find $p^{n+1}_h \in M_h$ by 
\begin{align}\label{cf-scheme2}
	(\nabla p^{n+1}_h,\nabla q_h) =(\nabla p^n_h,\nabla q_h) - \frac{1}{2\tau} (\nabla \tilde{\u}^{n+1}_h,q_h), \quad \forall q_h \in M_h.
\end{align}

\textbf{Step 3:} 
Then we update $\u^{n+1}_h$ by 

\begin{align}\label{cf-scheme3}
	\u^{n+1}_h =\tilde{\u}^{n+1}_h-2 \tau ( \nabla p^{n+1}_h - \nabla p^n_h  )
\end{align}

\textbf{Step 4:} For given $(\u^n_h, \tilde{\eta}^n_h)$, we can get $\tilde{\eta}^{n+1}_h$ by

\begin{align}\label{cf-scheme4}
	(\frac{\tilde{\eta}^{n+1}_h - \tilde{\eta}^n_h}{\tau} , w_h) + a_\eta ( \nabla \tilde{\eta}^{n+1}_h, \nabla w) - \beta ( (\tilde{\eta}^n_h+m_0) \nabla c^{n+1}_h, \nabla w_h   )\\
	 +
	b(\u^n_h,  \tilde{\eta}^{n+1}_h , w_h)=0, \quad \forall w_h \in X_{0h}. \notag
\end{align}

\textbf{Step 5 :} Then we update $\eta^{n+1}_h$ by 

\begin{align}\label{cf-scheme5}
	\eta^{n+1}_h = \tilde{\eta}^{n+1}_h +m_0.
\end{align}

\textbf{Step 6:} For given $(\u^n_h,\tilde{\eta}^n_h)$, $c^{n+1}_h$ can be derived by

\begin{align}\label{cf-scheme6}
	(  \frac{c^{n+1}_h - c^n_h}{\tau},\psi_h   )+ a_c (\nabla c^{n+1}_h,\nabla \psi_h)+b(\u^n_h, c^{n+1}_h,\psi_h) \\
	+ \gamma ( (\tilde{\eta}^n+m_0) c^{n+1}_h,\psi_h )=0, \quad \forall \psi_h \in X_h.\notag
\end{align}

\begin{remark}
	From \textbf{Step 5}, it follows that the finite element approximation $\eta_h^{n+1}$ preserves the global mass conservation property, i.e., 
	\begin{align}
		\int_{\Omega} \eta_h^{n+1} \, dx = m_0 |\Omega|.
	\end{align}
	This conservation property is fundamental in ensuring the physical fidelity of the numerical solution over time.
\end{remark}
We introduce error function as follows:
\begin{align}
	\u^n-\tilde{\u}^n_h&=\u^n-R_h \u^n +R_h \u^n -\tilde{\u}^n_h := \theta^n_u +\tilde{e}_{\u}^n,\\
		\u^n-\u^n_h&=\u^n-R_h \u^n +R_h \u^n -\u^n_h := \theta^n_u +e_{\u}^n,\\
			p^n-p^n_h&=p^n-K_h p^n +K_h p^n -p^n_h := \theta^n_p +e_{p}^n,\\
			\tilde{\eta}^n-\tilde{\eta}^n_h&=\tilde{\eta}^n-T_h  \tilde{\eta}^n_h +T_h  \tilde{\eta}^n_h -\tilde{\eta}^n_h := \theta^n_{\eta} +\tilde{e}_{\eta}^n,\\	c^n-c^n_h&=c^n-\Pi_h c^n +\Pi_h c^n -c^n_h := \theta^n_c +e_{c}^n,
\end{align}
where $(R_h,K_h) : \V \times M \rightarrow \V_h \times M_h$ are the Stokes projection operators defined by 
\begin{align}
	( \nabla (\u-R_h \u ), \nabla \v_h)-(\nabla \cdot \v_h, p-K_h p)+(\nabla \cdot ( \u-R_h \u ),q_h)=0, \quad \forall (\v_h, q_h) \in (\V_h \times M_h).
\end{align}
and the Ritz projection operators defined by 
\begin{align}
	( \nabla (\tilde{\eta} -T_h \tilde{\eta}),  \nabla w_h)&=0, \quad \forall  w_h \in X_{0h},\\
	( \nabla (c -\Pi_h c),  \nabla \psi_h)&=0, \quad \forall  \psi_h \in X_{h}.
\end{align}

By the regularity assumption \textbf{A1}, we can have the following approximation  properties:
\begin{align}
	\| \u^n - R_h \u^n \|_{L^2}+h \| p^n-K_h p^n\|_{L^2} &\leq C h^2(\| \u^n\|_{H^2}  +\| p^n\|_{H^1}),\label{cf-uprojection}\\
	\| \tilde{\eta}^n-T_h \tilde{\eta}^n\|_{L^2} &\leq C h^2 \| \tilde{\eta}^n\|_{H^2},\label{cf-etaprojection}\\
\| c^n-\Pi_h c^n \|_{L^2}+	h \| \nabla (c^n-\Pi_h c^n) \|_{L^2} &\leq C h^3 \| c^n\|_{H^3}\label{cf-cprojection}.
\end{align}

We define the iteration initial value $\u^0_h=I_{1h} \u^0, \, p^0_h = I_{2h} p^0, \, \eta^0_h = I_{3h}\eta_0,\,  \c^0_h = I_{4h}c^0$, where $(I_{1h}, I_{2h},I_{3h},I_{4h})$ are the interpolation operators into $(\V_h \times M_h \times X_{0h}, X_h)$, respectively, then we have the following approximation error:
\begin{align}
\| \u^0 - I_{1h}\u^0 \|_{L^2} + h \| \nabla (\u^0- I_{1h}\u^0)\|_{L^2} \leq C h^2 \| \u^0\|_{H^2},\label{cf-uinterpolation}\\
\| p^0 - I_{2h}p^0 \|_{L^2}\leq C h \| p^0\|_{H^1},\\
\| \tilde{\eta}^0 - I_{3h}{\eta}^0\|_{L^2} \leq C h^2 \| \tilde{\eta}^0\|_{H^2},\label{cf-etainterpolation}\\
\| c^0 - I_{4h}c^0 \|_{L^2}+ \| \nabla ( c^0 - I_{4h}c^0)\|_{L^2} \leq C h^2 \| c^0\|_{H^3}.\label{cf-cinterpolation}
\end{align}

Next, we will give the main theorem in this paper.
\begin{theorem}\label{cf-therror}
	Let $(\u^i,p^i, \eta^i,c^i)$ and $(\u^i_h,p^i_h, \eta^i_h,c^i_h)$ are the solutions of the continuous model (\ref{cfmodel}) and the finite element discrete scheme (\ref{cf-scheme1})-(\ref{cf-scheme6}),under the regularity assumption (\ref{cf-regularity}), there exists some $C >0$ independent of $\tau$ and $h$ such that
	\begin{align}\label{cf-errorresult}
		\underset{0\leq i \leq N}{\max} (\| \u^i-\u^i_h\|_{L^2}^2 + \| \eta^i-\eta^i_h\|_{L^2}^2 +\| c^i-c^i_h\|_{L^2}^2 )\leq C (\tau^2+h^4).
	\end{align}
\end{theorem}
