\section{Error estimate for the pressure-correction projection finite element methods}\label{erroranalysis}
In this section, we will derive the convergent analysis for the fully discrete pressure-correction projection method. Firstly, we need to derive the error equation,
for $0\leq n \leq N-1$, the exact solutions $(\u^{n+1},p^{n+1}, \tilde{\eta}^{n+1},c^{n+1})$ to (\ref{recfmodel}) satisfies
\begin{align}
	D_{\tau} \u^{n+1}- \mu \Delta \u^{n+1} + \u^n\cdot \u^{n+1} + \nabla p^n &= (\tilde{\eta}^n +m_0) \nabla \phi^{n+1}+ R_{\u}^{n+1},\label{cf-exact1}\\
	D_{\tau} \tilde{\eta}^{n+1} -a_\eta \Delta \tilde{\eta}^{n+1} + \u^n\cdot \nabla \tilde{\eta}^{n+1}-\beta \div( (\tilde{\eta}^{n+1}+m_0)\nabla c^{n+1}  ) &=R^{n+1}_c,\label{cf-exact2}\\
	D_{\tau}c^{n+1}-a_c \Delta c^{n+1} + \u^n\cdot \nabla c^{n+1} + \gamma (\tilde{\eta}^n+m_0) c^{n+1} &= R^{n+1}_c,\label{cf-exact3}
\end{align}
where the trunction error $R^{n+1}_{\u}, R^{n+1}_{\tilde{\eta}},R^{n+1}_c$ are given by
\begin{align}
	R^{n+1}_{\u} &= D_{\tau} \u^{n+1} -\u_t(t^{n+1}) + \u^n \cdot \u^{n+1}- \u^{n+1} \cdot \u^{n+1} + \nabla p^n-\nabla p^{n+1} \notag\\
	&+ (\tilde{\eta}^{n+1}+m_0)\nabla \phi^{n+1} - (\tilde{\eta}^{n}+m_0)\nabla \phi^{n+1},\notag\\
	R^{n+1}_{\eta }  &= D_{\tau} \tilde{\eta}^{n+1} -\tilde{\eta}_t(t^{n+1})+ \u^n \cdot \nabla \tilde{\eta}^{n+1} -  \u^{n+1} \cdot \nabla \tilde{\eta}^{n+1},\notag \\
	R^{n+1}_c &=  D_{\tau} c^{n+1} -c_t(t^{n+1})+ \u^n \cdot \nabla c^{n+1}-\u^{n+1} \cdot \nabla c^{n+1}\notag\\
	&+ \gamma(  \tilde{\eta}^n+m_0)c^{n+1}-\gamma(  \tilde{\eta}^{n+1}+m_0)c^{n+1}.\notag
\end{align}
Next, we give the error estimate  for $R^{n+1}_{\u}, R^{n+1}_{\tilde{\eta}},R^{n+1}_c$ by the following lemma.
\begin{lemma}\label{cf-trunction-error}
Under the regularity assumption \textbf{A1}, there holds
\begin{align}\label{cf-12}
	\tau \sum_{n=0}^{N-1} ( \| R^{n+1}_{\u}\|_{H^{-1}}^2 +\| R^{n+1}_{\tilde{\eta}}\|_{L^2}^2 + \| R^{n+1}_c\|_{L^2}^2  ) \leq C \tau ^2. 
\end{align}
\begin{proof}
	In terms of Taylor formula
	\begin{align}
	D_{\tau} \u^{n+1} - u_t(t^{n+1}) = - \frac{1}{\tau } \int^{t^{n+1}}_{t^{n}} (t-t^n)\u_{tt}dt,
 		\end{align}
we have
\begin{align}
<R^{n+1}_\u,\v>&= - <\frac{1}{\tau}  \int^{t^{n+1}}_{t^n} (t-t^n) \u_{tt}dt,\v   >- b( \int^{t^{n+1}}_{t^n}  \u_t dt, \u^{n+1},\v  ) \notag\\
&-(\int^{t^{n+1}}_{t^n} p_t dt, \div \v ) + ( \int^{t^{n+1}}_{t^n} \tilde{\eta}_tdt \nabla \phi^{n+1},\v  ),
\end{align} 
from the regularity assumptions, we can have 
\begin{align}\label{cf-1}
	\| R^{n+1}_{\u} \|_{H^{-1}} =&\underset{\v \in \V}{\sup} \frac{ <R^{n+1}_\u,\v>}{\| \nabla \v \|_{L^2}} \notag\\
	\leq& \frac{C}{\tau} \int^{t^{n+1}}_{t^n} (t-t^n) \| \u_{tt}\|_{H^{-1}}dt + C \| \nabla \u^{n+1} \|_{L^3} \int^{t^{n+1}}_{t^n} \| \u_t\|_{L^2}dt\notag\\
	&+C \int^{t^{n+1}}_{t^n} \|p_t \|_{L^2}dt + C \| \phi^{n+1} \|_{W^{1,3}} \int^{t^{n+1}}_{t^n} \| \tilde{\eta}_t\|_{L^2}dt  \\
	\leq& C \tau^{\frac{1}{2}} (     \int^{t^{n+1}}_{t^n} \| \u_{tt}\| _{H^{-1}}^2dt  +  \int^{t^{n+1}}_{t^n}\| \u_t\|_{L^2}^2dt + \int^{t^{n+1}}_{t^n} \| p_t \|_{L^2}^2dt + \int^{t^{n+1}}_{t^n}\| \tilde{\eta}_t\|_{L^2}^2 dt)^{\frac{1}{2}}.\notag
\end{align}

For $R^{n+1}_{\tilde{\eta}}$, we can get
\begin{align}\label{cf-2}
	\|  R^{n+1}_{\tilde{\eta}}\|_{L^2} 
	\leq 
	&
	\frac{1}{\tau} \int^{t^{n+1}}_{t^n} (t-t^n)\|\tilde{\eta}_{tt}\|_{L^2}dt
	+ \int^{t^{n+1}}_{t^n} \| \u_{t}\|_{L^2}dt \| \nabla \tilde{\eta}^{n+1}\|_{L^{\infty}}\notag\\
	\leq & C \tau^{\frac{1}{2}} (  \int^{t^{n+1}}_{t^n}\| \tilde{\eta}_{tt}\|_{L^2}^2 dt
	+ \int^{t^{n+1}}_{t^n}\| \u_t\|_{L^2}^2 dt )^{\frac{1}{2}}.
\end{align}

Similarly, 
\begin{align}\label{cf-3}
		\|  R^{n+1}_{c}\| _{L^2}\leq &\frac{1}{\tau} \int^{t^{n+1}}_{t^n} (t-t^n)\|c_{tt}\|_{L^2}dt+ \int^{t^{n+1}}_{t^n} \|\u_{t}\|_{L^2} dt \|  c^{n+1}\|_{W^{1,\infty}} +C \int^{t^{n+1}}_{t^n}\| \tilde{\eta}_t\| _{L^2}dt \| c^{n+1}\|_{L^{\infty}} \notag\\
		\leq & C \tau^{\frac{1}{2}} (  \int^{t^{n+1}}_{t^n}\| c_{tt}\|_{L^2}^2 dt+ \int^{t^{n+1}}_{t^n}\| u_t\|_{L^2}^2 dt+ \int^{t^{n+1}}_{t^n}\| \tilde{\eta}_t\|_{L^2}^2 dt )^{\frac{1}{2}}.
\end{align}

Thus,  from (\ref{cf-1}), (\ref{cf-2}), (\ref{cf-3}), we complete the proof of Lemma  \ref{cf-trunction-error}.

\end{proof}
\end{lemma}
Secondly, we will give the error equation, testing (\ref{cf-exact1}) - (\ref{cf-exact3}) by $ (\v_h,q_h,w_h,\psi_h) \in  \V_h \times M_h \times X_{0h} \times X_h$ and subtracting them from (\ref{cf-scheme1}), (\ref{cf-scheme4}), (\ref{cf-scheme6}), we get
\begin{align}
	&(\frac{\tilde{e}^{n+1}_\u - e^n_\u}{\tau},\v_h) + \mu (\nabla \tilde{e}^{n+1}_\u, \nabla \v_h) - (\nabla \cdot \v_h,e^n_p)\notag\\
	=&(\frac{\theta^{n+1}_\u - \theta^n_\u}{\tau},\v_h)+<R^{n+1}_\u,\v_h>-B(e_{\u}^n,\tilde{\u}^{n+1},\v_h)-B(\theta^n_\u,\tilde{\u}^{n+1},\v_h)\label{cf-errorequation1}\\
	&-B(\u^n_h,\tilde{e}^{n+1}_\u,\v_h) -B(\u^n_h,\theta^{n+1}_\u,\v_h)+((\tilde{e}^n_\eta+ \tilde{\theta}^n_\eta) \nabla \phi^{n+1} ,\v_h) .\notag\\%%%%%%%%%%%%%%%%%%%%%%%%%%%%
&	(\frac{\tilde{e}^{n+1}_\eta- \tilde{e}^n_\eta}{\tau},w_h)+a_\eta ( \nabla \tilde{e}^{n+1}_\eta,\nabla w_h)\notag\\
	=&(\frac{\theta^{n+1}_\eta - \theta^n_\eta}{\tau},w_h)+ (R^{n+1}_\eta,w_h)
	-b(e^n_\u,\tilde{\eta}^{n+1},w_h)-b(\theta^n_\u,\tilde{\eta}^{n+1},w_h) \label{cf-errorequation2}\\
	&-b(\u^n_h,\tilde{e}^{n+1}_\eta,w_h) 
	-b(\u^n_h, \tilde{\theta}_\eta^{n+1},w_h)
	+\beta(\tilde{e}^n_\eta \nabla c^{n+1},\nabla w_h)+ \beta(\theta_\eta^n \nabla c^{n+1},\nabla w_h) \notag\\
	&+\beta(  (\tilde{\eta}^n+m_0) \nabla (e^{n+1}_c +\theta^{n+1}_c) , \nabla w_h) + \beta(  (\tilde{e}^n_\eta+\theta^n_\eta) \nabla (e^{n+1}_c +\theta^{n+1}_c), \nabla w_h)	+\beta (  (\tilde{\eta}^{n+1}-\tilde{\eta}^n) \nabla c^{n+1}, \nabla w_h  ).\notag\\%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	&	(\frac{e^{n+1}_c- e^n_c}{\tau},w_h)+a_\eta ( \nabla e^{n+1}_c,\nabla \psi_h)\notag\\
	=&(\frac{\theta^{n+1}_c - \theta^n_c}{\tau},\psi_h) + (R^{n+1}_c,\psi_h) -b(e^n_\u,c^{n+1},\psi_h)-b(\theta^n_\u, c^{n+1},\psi_h)\label{errorequation3}\\
	&-b(\u^n_h,e^{n+1}_c,\psi_h)-b(\u^n_h,\theta^{n+1}_c,\psi_h)-\gamma(\tilde{e}^n_\eta c^{n+1},\psi_h)-\gamma(\theta^n_\eta c^{n+1},\psi_h)\notag\\
	&-\gamma( (\tilde{\eta}^n+m_0) (e^{n+1}_c+\theta^{n+1}_c),\psi_h )
	-\gamma( (  \tilde{e}^n_\eta+\theta^n_\eta) (e^{n+1}_c+\theta^{n+1}_c),\psi_h)\notag.
 \end{align}

From (\ref{cf-scheme3}), we have 
\begin{align}
	\u^{n+1}_h -R^{n+1}_h \u^{n+1} +R^{n+1}_h \u^{n+1} -\tilde{\u}^{n+1}_h+ 2 \tau (  \nabla (p^{n+1}_h- K_hp^{n+1}   -    \nabla (p^{n}_h- K_hp^{n} )) = - 2 \tau ( \nabla K_h ( p^{n+1}-p^{n})),
\end{align}
furthermore
\begin{align}\label{cf-errorequation4}
	e^{n+1}_\u-\tilde{e}^{n+1}_\u + 2\tau ( \nabla e^{n+1}_p- \nabla e^n_p) =  - 2 \tau ( \nabla K_h ( p^{n+1}-p^{n})).
\end{align}

\begin{lemma}\label{cf-therror2}
Under the regularity assumption (\ref{cf-regularity}), there exists some $C_1 >0$ independent of $\tau$ and $h$ such that
	\begin{align}\label{cf-errorresult2}
	\| e^{i}_\u \|^2_{L^2}+\| \tilde{e}^{i}_\eta \|^{2}_{L^2}+\| e^{i}_c \|^{2}_{L^2} \leq C_1 (\tau^2+h^4), \quad \forall 0\leq i \leq N.
		\end{align}
\end{lemma}
\begin{proof}
It's easy to see that the proof of Theorem \ref{cf-therror} can be done from the Lemma \ref{cf-therror2} and the projection error (\ref{cf-uprojection}) - (\ref{cf-cprojection}), we just need to proof the Lemma \ref{cf-therror2} by the mathematical induction method. So we firstly prove (\ref{cf-errorresult2}) is valid for $i=1$, taking $n=0$ in the error equations (\ref{cf-errorequation1}) - (\ref{cf-errorequation4}), we have 
\begin{align}
	&(\frac{\tilde{e}^{1}_\u - e^0_\u}{\tau},\v_h) + \mu (\nabla \tilde{e}^{1}_\u, \nabla \v_h) - (\nabla \cdot \v_h,e^0_p)\notag\\
	=&(\frac{\theta^{1}_\u - \theta^0_\u}{\tau},\v_h)+<R^{1}_\u,\v_h>-B(e_{\u}^0,\tilde{\u}^{1},\v_h)-B(\theta^0_\u,\tilde{\u}^{1},\v_h)\label{cf-uerror00}\\
	&-B(\u^0_h,\tilde{e}^{1}_\u,\v_h) -B(\u^0_h,\theta^{1}_\u,\v_h)+((\tilde{e}^0_\eta+ \theta^0_\eta) \nabla \phi^{1} ,\v_h) .\notag\\%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	&	(\frac{\tilde{e}^{1}_\eta- \tilde{e}^0_\eta}{\tau},w_h)+a_\eta ( \nabla \tilde{e}^{1}_\eta,\nabla w_h)\notag\\
	=&(\frac{\theta^{1}_\eta - \theta^0_\eta}{\tau},w_h)+ (R^{1}_\eta,w_h)-b(\tilde{e}^0_\u,\tilde{\eta}^{1},w_h)-b(\theta^0_\u,\tilde{\eta}^{1},w_h) \label{cf-etaerror00}\\
	&-b(\u^0_h,\tilde{e}^{1}_\eta,w_h) -b(\u^0_h, \tilde{\theta}_\eta^{1},w_h)+\beta(\tilde{e}^0_\eta \nabla c^{1},\nabla w_h)+ \beta(\theta_\eta^0 \nabla c^{1},\nabla w_h) \notag\\
	&+\beta(  (\tilde{\eta}^0+m_0) \nabla (e^{1}_c +\theta^{1}_c) ,\nabla  w_h) + \beta(  (\tilde{e}^0_\eta+\theta^0_\eta) \nabla (e^{1}_c +\theta^{1}_c), \nabla w_h)+\beta (  (\tilde{\eta}^{1}-\tilde{\eta}^0) \nabla c^{1}, \nabla w_h  ).\notag\\%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	&	(\frac{e^{1}_c- e^0_c}{\tau},w_h)+a_\eta ( \nabla e^{1}_c,\nabla \psi_h)\notag\\
	=&(\frac{\theta^{1}_c - \theta^0_c}{\tau},\psi_h) + (R^{1}_c,\psi_h) -b(e^0_\u,c^{1},\psi_h)-b(\theta^0_\u,c^{1},\psi_h)\label{cf-cerror00}\\
	&-b(\u^0_h,e^{1}_c,\psi_h)-b(\u^0_h,\theta^{1}_c,\psi_h)-\gamma(\tilde{e}^0_\eta c^{1},\psi_h)-\gamma(\tilde{\theta}^0_\eta c^{1},\psi_h)\notag\\
	&-\gamma( (\tilde{\eta}^0+m_0) (e^{1}_c+\theta^{1}_c),\psi_h )
	-\gamma( (  \tilde{e}^0_\eta+e^0_\eta) (e^{1}_c+\theta^{1}_c),\psi_h)\notag.
\end{align}


\subsection{Convergent analysis}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%
%\subsection{Estimate of $ e^{1}_\u$}
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Setting $ \v_h=\tau \tilde{e}^1_\u$ in (\ref{cf-uerror00}) and noticing that $ e^0_\u=e^0_p=0$, we have
\begin{align}
	\| \tilde{e}^{1}_\u\|_{L^2}^2+\mu \tau \| \nabla \tilde{e}^{1}_\u\|_{L^2}^2
	=&\tau(\frac{\theta^{1}_\u - \theta^0_\u}{\tau},\v_h)+ \tau  <R^{1}_\u,\tilde{e}^{1}_\u>- \tau  B(\theta_{\u}^0,\tilde{\u}^{1},\tilde{e}^{1}_\u) \label{cf-1uerror}\\
	%- \tau B(e^0_\u,\tilde{\u}^{1},\tilde{e}^{1}_\u)\\
	&- \tau B(\u^0_h,\tilde{e}^{1}_\u,\tilde{e}^{1}_\u) - \tau B(\u^0_h,\theta^{1}_\u,\tilde{e}^{1}_\u)
	+\tau( \theta^0_\eta \nabla \phi^{1} ,\tilde{e}^{1}_\u).\notag
\end{align}


Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-uinterpolation}),  H\"{o}lder inequality and Young inequality, we have
\begin{align}
	\tau(\frac{\theta^{1}_\u - \theta^0_\u}{\tau},\v_h)
	\leq & \nu_1 \| \tilde{e}^1_\u\|^2_{L^2}+C (\| \theta^1_\u\|^2_{L^2}+\| \theta^0_\u\|^2_{L^2})\\
	\leq &\nu_1 \| \tilde{e}^1_\u\|^2_{L^2}+C h^4.\notag\\
	\tau( \tilde{\theta}^0_\eta \nabla \phi^{1} ,\tilde{e}^{1}_\u) \leq &C \| \theta^0_\eta\|_{L^2}\| \nabla \phi^{1}\|_{L^3} \|\tilde{e}^{1}_\u\|_{L^6}\\
	\leq &C h^4  + \nu_4  \tau \|  \nabla \tilde{e}^1_\u\|^2_{L^2}.\notag
\end{align}

Similarly, by using (\ref{cf-12}), one has
\begin{align}
 \tau    <R^{1}_\u,\tilde{e}^{1}_\u>
 \leq & \nu_4 \tau  \| \nabla  \tilde{e}^1_\u\|^2_{L^2}+ C \tau  \|R^{1}_\u\|^2_{H^{-1}}  \\
 \leq &  \nu_4 \tau \| \nabla  \tilde{e}^1_\u\|^2_{L^2}+C\tau^2. \notag
 \end{align}

Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), (\ref{cf-uinterpolation}), we can derive 
\begin{align}
	 \tau  B(\theta_{\u}^0,\tilde{\u}^{1},\tilde{e}^{1}_\u)
	 \leq &C\tau \| \theta^0_\u\|_{L^2} \| \nabla \tilde{\u}^1\|_{L^3} \| \tilde{e}^1_\u\|_{L^6}  \notag\\
	 \leq & C   h^4+ \nu_4 \tau \| \nabla \tilde{e}^1_\u\|^2_{L^2}. \notag
\end{align}

In terms of (\ref{biobdf-2}), (\ref{biobdf-17}) and inverse inequalities (\ref{biobdf-16}), we can get 
\begin{align}
	&|-\tau B(\u^0_h,\tilde{e}^{1}_\u,\tilde{e}^{1}_\u) -\tau B(\u^0_h,\theta^{1}_\u,\tilde{e}^{1}_\u)|\notag\\
	\leq& | \tau B(\e^0_\u+\theta^0_\u,\theta^{1}_\u,\tilde{e}^{1}_\u)+ \tau B(\u^0,\tilde{e}^{1}_\u,\theta^{1}_\u)\notag\\
	\leq & 2\tau \| \theta^0_\u\|_{L^3} \| \nabla  \theta^{1}_\u \|_{L^2}\| \tilde{e}^{1}_\u\|_{L^6} 
	+ 2\tau \| \u^0\|_{L^{\infty}} \| \nabla \tilde{e}^{1}_\u\|_{L^2} \| \theta^{1}_\u\|_{L^2} \\
	\leq & C \tau h^{-\frac{3}{2}} \| \theta^0_\u\|_{L^2}  \| \theta^{1}_\u \|_{L^2} \| \nabla  \tilde{e}^{1}_\u\|_{L^2}  + C  \tau h^4 + \nu_4 \tau \| \nabla  \tilde{e}^{1}_\u\|_{L^2}\notag\\
	\leq & \nu_4 \tau  \| \nabla  \tilde{e}^{1}_\u\|_{L^2}+C  \tau h^4+C \tau h^5.\notag
\end{align}

Substituting the above inequalities into (\ref{cf-1uerror}), for sufficiently small $\nu_1, \nu_4$, and sufficiently small $ \tau , h$ such that $C\tau \leq C_1$ and $C \tau h \leq C_1$, we can derive
\begin{align}\label{cf-1uerrorresult}
		\| \tilde{e}^{1}_\u\|_{L^2}^2+\mu \tau \| \nabla \tilde{e}^{1}_\u\|_{L^2}^2 \leq C_1 (\tau^2+h^4).
\end{align}

Let $n=0$ in (\ref{cf-errorequation4}), we have 
\begin{align}\label{cf-1errorequation4}
	e^{1}_\u-\tilde{e}^{1}_\u + 2\tau  \nabla e^{1}_p =  - 2 \tau ( \nabla K_h ( p^{1}-p^{0})).
\end{align}

Testing (\ref{cf-1errorequation4}) by $2 \e^1_\u$ and noticing that (\ref{divergence-free}), we can derive 
\begin{align}
	\| \e^1_\u \|^2_{L^2} - \| \tilde{e}^1_\u\|^2_{L^2} + \| \tilde{e}^1_\u - \tilde{e}^1_\u\|^2_{L^2}=0.
\end{align}

Associating with (\ref{cf-1uerrorresult}) yield
\begin{align}\label{cf-uerrorreulst}
	\| \e^1_\u \|^2_{L^2}+\mu \tau \| \nabla \tilde{e}^{1}_\u\|_{L^2}^2 \leq C_1 (\tau^2+h^4).
\end{align}
