	&+2 \tau \beta (  (\tilde{\eta}^{1}-\tilde{\eta}^0) \nabla c^{1},  \nabla \tilde{e}^1_\eta ).\notag
\end{align}


Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-etainterpolation}),  H\"{o}lder inequality and Young inequality, we have
\begin{align}
	\tau(\frac{\tilde{e}^{1}_\eta- \tilde{e}^0_\eta}{\tau},w_h) 
	\leq&\nu_2 \| \tilde{e}^1_\eta\|^2_{L^2}+ C (\| \theta^1_\eta\|^2_{L^2}+\| \theta^0_\eta\|^2_{L^2})\notag\\
	\leq &\nu_2 \| \tilde{e}^1_\eta\|^2_{L^2}+C h^4.\notag
\end{align}

Similarly, by using (\ref{cf-12}), one has
\begin{align}
 \tau(R^{1}_\eta,\tilde{e}^{1}_\eta)
	\leq & \nu_2 \| \tilde{e}^1_\eta\|^2_{L^2}+ C \tau  \|R^{1}_\eta\|^2_{L^2} \notag\\
	\leq &\nu_2 \| \tilde{e}^1_\eta\|^2_{L^2}+C\tau^2. \notag
\end{align}

Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}),  (\ref{cf-etainterpolation}), we can derive 
\begin{align}
	\tau b(\theta^0_\u,\tilde{\eta}^{1},\tilde{e}^{1}_\eta)
	\leq &C\tau \| \theta^0_\u\|_{L^2} \| \nabla \tilde{\eta}^1\|_{L^3} \|\| \tilde{e}^1_\eta\|_{L^6} \notag\\
	\leq & C  \tau h^4+ \nu_5 \tau \| \nabla \tilde{e}^1_\eta\|^2_{L^2}. \notag
\end{align}


In terms of (\ref{biobdf-2}), (\ref{biobdf-17}) and inverse inequalities (\ref{biobdf-16}), we can get 
\begin{align}
	-\tau b(\u^0_h,\tilde{e}^{1}_\eta,\tilde{e}^{1}_\eta) - \tau b(\u^0_h,\theta^{1}_\eta,\tilde{e}^{1}_\eta)
	\leq& |\tau b(\theta^0_\u,\theta^{1}_\eta,\tilde{e}^{1}_\eta)+ \tau b(\u^0,\tilde{e}^{1}_\eta, \theta^{1}_\eta)|\\
	\leq & \tau \|\theta^0_\u\|_{L^3} \| \nabla  \theta^{1}_\eta \|_{L^2}\| \tilde{e}^{1}_\eta\|_{L^6} 
	+ \tau \| \u^0\|_{L^{\infty}} \| \nabla \tilde{e}^{1}_\eta\|_{L^2} \| \theta^{1}_\eta\|_{L^2} \notag\\
	\leq & C \tau h^{-\frac{3}{2}} \|\theta^0_\u\|_{L^2}  \| \theta^{1}_\eta \|_{L^2} \| \nabla  \tilde{e}^{1}_\eta\|_{L^2}  + C \tau h^4 + \nu_5 \tau \| \nabla  \tilde{e}^{1}_\eta\|_{L^2}\notag\\
	\leq & \nu_5\tau \| \nabla  \tilde{e}^{1}_\eta\|_{L^2}+C \tau h^4+C\tau h^5.\notag
\end{align}

By using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), H\"{o}lder inequality and Young inequality, we have
\begin{align}
	\tau \beta(\tilde{\theta}_\eta^0 \nabla c^{1}, \nabla \tilde{e}^{1}_\eta)\leq
	&C\tau \| \tilde{\theta}^0_\eta\|_{L^2} \| \nabla c^{1}\|_{L^\infty} \|  \nabla \tilde{e}^{1}_\eta\|_{L^2}\\
	\leq & C \tau h^4+\nu_5 \tau \| \nabla  \tilde{e}^{1}_\eta\|^2_{L^2}.\notag
\end{align}



Applying (\ref{cf-cprojection}), H\"{o}lder inequality and Young inequality, we can derive
\begin{align}
 \tau\beta(  (\tilde{\eta}^0+m_0) \nabla (e^{1}_c +\theta^{1}_c) , \nabla \tilde{e}^{1}_\eta) \leq
	& 2 \tau \| \tilde{\eta}^0+m_0\|_{L^{\infty}} (\| \nabla e^{1}_c\|_{L^2} + \| \nabla \theta^{1}_c\|_{L^2} ) \| \nabla \tilde{e}^{1}_\eta\|_{L^2}\\
	\leq &\nu_5 \tau \| \nabla  \tilde{e}^{1}_\eta\|^2_{L^2}+ C \tau \| \nabla e^{1}_c\|^2_{L^2} + C \tau h^4.\nonumber
\end{align}

Utilizing  the regularity assumption (\ref{cf-regularity}), (\ref{cf-cprojection}), inverse inequality (\ref{biobdf-21}), $\tau=h$, we have 
\begin{align}
 \tau \beta(  \theta^0_\eta \nabla (e^{1}_c +\theta^{1}_c), \nabla  \tilde{e}^{1}_\eta)\leq
	&C \tau \| \tilde{e}_\eta^0+\theta^0_\eta\|_{L^\infty} (\| \nabla \theta^{1}_c\|_{L^2} + \| \nabla e^{1}_c\|_{L^2})\| \nabla \tilde{e}^{1}_\eta\|_{L^2}\\
	\leq & C\tau h^{-1} (\tau+h^2)
	(\| \nabla \theta^{1}_c\|_{L^2} + \| \nabla e^{1}_c\|_{L^2})
	\| \nabla \tilde{e}^{1}_\eta\|_{L^2}\notag\\
	\leq & C \tau h^4  +\nu_5 \tau \|  \nabla \tilde{e}^{1}_\eta\|^2_{L^2}+C\tau \| \nabla e^{1}_c\|^2_{L^2} .\notag
\end{align}
