Setting $\psi_h=\tau \e^1_c$ in (\ref{cf-cerror00}) and noticing that $ e^0_c=0$, we have 
\begin{align}\label{cf-1cerrorequation}
	%%%%%%%%%%%%%%%%%%%%
	\| e^{1}_c\|_{L^2}^2+a_c \tau \| \nabla e^{1}_c\|_{L^2}^2
	= & \tau(\frac{\theta^{1}_c - \theta^0_c}{\tau},\psi_h)
	+ \tau (R^{1}_c,e^{1}_c)
	% - \tau b(e^0_\u,c^{1},e^{1}_c)
	-\tau b(\theta^0_\u.c^{1},e^{1}_c)\\
	&
	-\tau b(\u^0_h,e^{1}_c,e^{1}_c)
	- \tau b(\u^0_h,\theta^{1}_c,e^{1}_c)
	%-\tau \gamma(\tilde{e}^0_\eta c^{1},e^{1}_c)
	-\tau\gamma(\theta^0_\eta c^{1},e^{1}_c)\notag\\
	&- \tau\gamma( (\tilde{\eta}^0+m_0) (e^{1}_c+\theta^{1}_c),e^{1}_c )
	- \tau\gamma( \theta^0_\eta (e^{1}_c+\theta^{1}_c),e^{1}_c ).\notag
\end{align}




Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-cinterpolation}),  H\"{o}lder inequality and Young inequality, we have
\begin{align}
	\tau(\frac{\theta^{1}_c - \theta^0_c}{\tau},\psi_h) 
	\leq&\nu_3 \| \tilde{e}^1_c\|^2_{L^2}+C (\| \theta^1_c\|^2_{L^2}+\| \theta^0_c\|^2_{L^2})\notag\\
	\leq &\nu_3 \| \tilde{e}^1_c\|^2_{L^2}+C h^4.\notag
\end{align}

Similarly, by using (\ref{cf-12}), one has
\begin{align}
	\tau (R^{1}_c,e^{1}_c)
	\leq & \nu_3 \| \tilde{e}^1_c\|^2_{L^2} + C \tau  \|R^{1}_c\|^2_{L^2}\notag\\
	\leq &\nu_3 \| \tilde{e}^1_c\|^2_{L^2}  +C\tau^2. \notag
\end{align}


Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), (\ref{cf-cinterpolation}) we can derive 
\begin{align}
	\tau b(\theta^0_\u,c^{1},e^{1}_c)
	\leq &C\tau \| \theta^0_\u\|_{L^2} \| \nabla c^1\|_{L^3} \|\| e^1_c\|_{L^6} \notag \notag\\
	\leq & C  \tau  h^4+ \nu_6 \tau \| \nabla e^1_c\|^2_{L^2}. \notag
\end{align}


In terms of (\ref{biobdf-2}), (\ref{biobdf-17}) and inverse inequalities (\ref{biobdf-16}), we can get 
\begin{align}
	-\tau b(\u^0_h,e^{1}_c,e^{1}_c)
	- \tau b(\u^0_h,\theta^{1}_c,e^{1}_c)\leq
	&|-\tau b(\u^0_h,e^{1}_c,e^{1}_c) - \tau b(\u^0_h,\theta^{1}_c,e^{1}_c)|\notag\\
	\leq& | \tau b(\theta^0_\u,\theta^{1}_c,e^{1}_c)+ 2 \tau b(\u^0,e^{1}_c, \theta^{1}_c)\notag\\
	\leq &\tau \| \theta^0_\u\|_{L^3} \| \nabla  \theta^{1}_c \|_{L^2}\| e^{1}_c\|_{L^6} 
	+ \tau \| \u^0\|_{L^{\infty}} \| \nabla e^{1}_c\|_{L^2} \| \theta^{1}_c\|_{L^2} \\
	\leq & C \tau h^{-\frac{3}{2}}\| \theta^0_\u\|_{L^2}  \| \theta^{1}_c \|_{L^2} \| \nabla  e^{1}_c\|_{L^2}  + C \tau h^4 + \nu_6 \tau  \| \nabla  e^{1}_c\|_{L^2}\notag\\
	\leq & \nu_6 \tau \| \nabla  \tilde{e}^{1}_c\|_{L^2}+C \tau h^4+C \tau h^5.\notag
\end{align}

By using H\"{o}lder inequality and Young inequality, we have
\begin{align}
	\tau\gamma(\tilde{\theta}^0_\eta c^{1},e^{1}_c)\leq&
	C\tau   \| \theta^0_\eta\|_{L^2}\| c^{1}\|_{L^{3}} \| e^{1}_c\|_{L^6} \\
	\leq &C \tau h^4 +\nu_6 \tau \| \nabla e^{1}_c\|_{L^2}^2.\notag\\
- \tau\gamma( (\tilde{\eta}^0+m_0) (e^{1}_c+\theta^{1}_c),e^{1}_c ) \leq&
	|- \tau\gamma( (\tilde{\eta}^0+m_0) (e^{1}_c+\theta^{1}_c),e^{1}_c )|\\
	\leq & C\tau \| \tilde{\eta}^0+m_0\|_{L^{3}}  \| e^{1}_c+\theta^{1}_c\|_{L^2} \|e^{1}_c\|_{L^6}. \notag\\
	\leq & C \tau h^4 + \nu_3 \tau \| e^{1}_c\|^2_{L^2}+\nu_6 \tau\| \nabla  e^{1}_c\|^2_{L^2}.\notag
\end{align}

Utilizing  the regularity assumption (\ref{cf-regularity}), inverse inequality (\ref{biobdf-21}), we have 
\begin{align}
- \tau\gamma( \theta^0_\eta (e^{1}_c+\theta^{1}_c),e^{1}_c ) \leq&
	|- \tau\gamma(  \theta^0_\eta (e^{1}_c+\theta^{1}_c),e^{1}_c )|\\
	\leq &  C \tau \| \theta^0_\eta\|_{L^4}  \| e^{1}_c+\theta^{1}_c\|_{L^2} \| e^{1}_c\|_{L^4}\notag\\
	\leq& C \tau h^{-\frac{1}{2}} \| \theta^0_\eta\|_{L^2} \| e^{1}_c\|_{L^2} \| \nabla e^{1}_c\|_{L^2} 
	+ C \tau h^{-\frac{1}{2}} \| \theta^0_\eta\|_{L^2} \| \theta^{1}_c\|_{L^2} \| \nabla e^{1}_c\|_{L^2}  \notag\\
	\leq &\nu_6\tau \| \nabla  \tilde{e}^{1}_c\|_{L^2} +C\tau h^{-1}\| \theta^0_\eta\|_{L^2}^2 \|e^{1}_c\|^2_{L^2} + C\tau h^3 \|\theta^0_\eta\|_{L^2}^2.\notag\\
	\leq &\nu_6\tau \| \nabla  \tilde{e}^{1}_c\|_{L^2}+C \tau h^3 \|e^{1}_c\|^2_{L^2} +C \tau h^7. \notag
\end{align}

Substituting the above estimates into (\ref{cf-1cerrorequation}), for sufficiently small $\nu_3, \nu_6,\tau,h$ we can derive
\begin{align}
	\| e^{1}_c\|_{L^2}^2+a_c \tau \| \nabla e^{1}_c\|_{L^2}^2\leq C_1 (\tau^2+h^4) +C \tau h^3 \|e^{1}_c\|^2_{L^2} 
\end{align}


Combining with  (\ref{cf-etaerrorresult}), for sufficiently small $ \tau, h $ such that $C \tau h^3$ sufficiently small, we can derive 


\begin{align}\label{cf-etacerror}
	\| e^{1}_c\|_{L^2}^2+\| \tilde{e}^{1}_\eta\|_{L^2}^2+a_\eta \tau \| \nabla \tilde{e}^{1}_\eta\|_{L^2}^2 +a_c \tau \| \nabla e^{1}_c\|_{L^2}^2  	 \leq C(\tau^2+h^4).
\end{align}

According to (\ref{cf-uerrorreulst}) and (\ref{cf-etacerror}), we have proved  (\ref{cf-errorresult2}) is valid for  $i=1$.
By assuming that (\ref{cf-errorresult2}) is valid for  $i=n$, i.e.
	\begin{align}\label{cf-infuctionerror}
	\| e^{n}_\u \|^2_{L^2}+\| \tilde{e}^{n}_\eta \|^{2}_{L^2}+\| e^{n}_c \|^{2}_{L^2} \leq C(\tau^2+h^4).
\end{align}
We will prove  (\ref{cf-errorresult2}) is valid for $i=n+1$.
