Setting $\v_h=2\tau \tilde{e}_\u^{n+1}$ in (\ref{cf-errorequation1}) and applying $a(a-b)=\frac{1}{2} \big(a^2-b^2+(a-b)^2 \big) $, one has 
\begin{align}\label{cf-uerror}
&\| \tilde{e}^{n+1}_\u\|_{L^2}^2-\| e^{n}_\u\|_{L^2}^2+\| \tilde{e}^{n+1}_\u-e^{n}_\u\|_{L^2}^2 +2 \mu \tau \| \nabla \tilde{e}^{n+1}_\u\|_{L^2}^2+2\tau(\nabla e^n_p,\tilde{e}^{n+1}_\u)\notag\\
=&2 \tau (\frac{\theta^{n+1}_\u - \theta^n_\u}{\tau},\tilde{e}^{n+1}_\u)+2 \tau 		 <R^{n+1}_\u,\tilde{e}^{n+1}_\u>-2 \tau  B(\theta_{\u}^n,\tilde{\u}^{n+1},\tilde{e}^{n+1}_\u)-2 \tau B(e^n_\u,\tilde{\u}^{n+1},\tilde{e}^{n+1}_\u)\\
&-2 \tau B(\u^n_h,\tilde{e}^{n+1}_\u,\tilde{e}^{n+1}_\u) -2 \tau B(\u^n_h,\theta^{n+1}_\u,\tilde{e}^{n+1}_\u)
+2\tau((\tilde{e}^n_\eta+ \theta^n_\eta) \nabla \phi^{n+1} ,\tilde{e}^{n+1}_\u)	.\notag
\end{align}

By using H\"{o}lder inequality and Young inequality, one has
\begin{align}
|2 \tau (\frac{\theta^{n+1}_\u - \theta^n_\u}{\tau},\tilde{e}^{n+1}_\u) |\leq&\epsilon_1  \tau \| \tilde{e}^{n+1}_\u\|_{L^2}^2 +C \tau \| \frac{\theta^{n+1}_\u - \theta^n_\u}{\tau} \|^2_{L^2}\notag\\
\leq & \epsilon_1  \tau \| \tilde{e}^{n+1}_\u\|_{L^2}^2 + C \tau h^4 \|  \frac{\u^{n+1}-\u^n}{\tau} \|_{H^2}^2 \notag\\
\leq &  \epsilon_1 \tau \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}+C\tau h^4 \|  \u_t(\xi)\|_{H^2}^2 \quad \xi\in(t^n,t^{n+1})\\
\leq & \epsilon_1 \tau \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}+C\tau h^4.\notag\\
|2 \tau  <R^{n+1}_\u,\tilde{e}^{n+1}_\u>|\leq & \tau \| R^{n+1}_\u\|_{H^{-1}}^2+ \epsilon_1 \tau \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}.
\end{align}

Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), H\"{o}lder inequality and Young inequality, we have
\begin{align}
	2\tau((\tilde{e}^n_\eta+ \theta^n_\eta) \nabla \phi^{n+1} ,\tilde{e}^{n+1}_\u)
	\leq & C\tau \|\tilde{e}^n_\eta\|^2_{L^2} + \epsilon_1 \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}+C \tau h^4.\\
&|-2 \tau  B(\theta_{\u}^n,\tilde{\u}^{n+1},\tilde{e}^{n+1}_\u)-2 \tau B(e^n_\u,\tilde{\u}^{n+1},\tilde{e}^{n+1}_\u)| \notag \\
\leq & 2 \tau \| \theta^n_\u\|_{L^2} \| \nabla \tilde{\u}^{n+1}\|_{L^3} \|\tilde{e}^{n+1}_\u \|_{L^6}+2 \tau \| e^n_\u \|_{L^2}  \| \nabla \tilde{\u}^{n+1}\|_{L^3} \|\tilde{e}^{n+1}_\u \|_{L^6} \\
\leq &  \epsilon_1  \tau \| \nabla \tilde{e}^{n+1}_\u \|_{L^2}^2 + C\tau  \| e^n_\u\|_{L^2}^2 +C\tau h^4.\notag
\end{align}
In terms of (\ref{biobdf-2}), (\ref{biobdf-17}), (\ref{cf-uprojection}) and inverse inequalities (\ref{biobdf-16}), we can get 
\begin{align}
	&|-2 \tau B(\u^n_h,\tilde{e}^{n+1}_\u,\tilde{e}^{n+1}_\u) -2 \tau B(\u^n_h,\theta^{n+1}_\u,\tilde{e}^{n+1}_\u)|\notag\\
	\leq& |2 \tau B(\e^n_\u+\theta^n_\u,\theta^{n+1}_\u,\tilde{e}^{n+1}_\u)+ 2 \tau B(\u^n,\tilde{e}^{n+1}_\u,\theta^{n+1}_\u)\notag\\
	\leq & 2\tau \| \e^n_\u+\theta^n_\u\|_{L^3} \| \nabla  \theta^{n+1}_\u \|_{L^2}\| \tilde{e}^{n+1}_\u\|_{L^6} 
	+ 2\tau \| \u^n\|_{L^{\infty}} \| \nabla \tilde{e}^{n+1}_\u\|_{L^2} \| \theta^{n+1}_\u\|_{L^2} \\
	\leq & C \tau \| \e^n_\u+\theta^n_\u\|_{H^1} h^{-1} \| \theta^{n+1}_\u \|_{L^2} \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}  + C \tau h^4 + \epsilon_1 \tau \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}\notag\\
	\leq & C \tau \| \e^n_\u+\theta^n_\u\|_{L^2} h^{-2} \| \theta^{n+1}_\u \|_{L^2} \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}  + C \tau h^4 + \epsilon_1 \tau \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}\notag\\
	\leq & \epsilon_1 \tau \| \nabla  \tilde{e}^{n+1}_\u\|_{L^2}+ C\tau \| \e^n_\u\|_{L^2}^2+C \tau h^4.\notag
\end{align}

Substituting the above estimates into (\ref{cf-uerror}), choosing $\epsilon_1$ sufficiently small, we have 
\begin{align}\label{cf-uerrorresult}
	&\| \tilde{e}^{n+1}_\u\|_{L^2}^2-\| e^{n}_\u\|_{L^2}^2+\| \tilde{e}^{n+1}_\u-e^{n}_\u\|_{L^2}^2 +2 \mu \tau \| \nabla \tilde{e}^{n+1}_\u\|_{L^2}^2\notag\\
	\leq & \tau \| R^{n+1}_\u\|_{L^2}^2+C\tau h^4+C\tau ( \| e^n_\u\|_{L^2}^2+ \|\tilde{e}^n_\eta\|^2_{L^2}).
\end{align}

Testing (\ref{cf-errorequation4}) by $e^{n+1}_\u$ and $\frac{1}{2} ( e^{n+1}_\u+ \tilde{e}^{n+1}_\u)$, we have 
\begin{align}
	\frac{1}{2} (   \| e^{n+1}_\u \|_{L^2}^2- \| \tilde{e}^{n+1}_\u\|_{L^2}^2+ \|  e^{n+1}_\u - \tilde{e}^{n+1}_\u\|_{L^2}^2)=&0,\label{cf-7}\\
	\frac{1}{2} (\| \e^{n+1}_u\|_{L^2}^2- \| \tilde{e}^{n+1}_\u\|_{L^2}^2  ) + \tau ( \nabla e^{n+1}_p- \nabla e^n_p,\tilde{e}^{n+1}_\u ) =&   \tau ( \nabla K_h ( p^{n+1}-p^{n}),\tilde{e}^{n+1}_\u).\label{cf-8}
\end{align}
where we use  $(\nabla q_h ,\u^{n+1}_h) = -(\nabla \cdot \u^{n+1}_h, q_h)=0$.

By using H\"{o}lder inequality and Young inequality, one has
\begin{align}\label{cf-4}
	\tau (\nabla K_h(p^{n+1}-p^n),\tilde{e}^{n+1}_\u   ) \leq& C \tau \| K_h (p^{n+1}-p^n)\|_{L^2} \| \nabla \tilde{e}^{n+1}_\u\|_{L^2}\notag\\
	\leq & \epsilon_1 \tau | \nabla \tilde{e}^{n+1}_\u\|_{L^2}^2+ C \tau^2 \int_{t^{n}}^{t^{n+1}} \| p_t\|^2_{L^2} dt.
\end{align}

From (\ref{cf-errorequation4}), one has 
\begin{align}
\tilde{e}^{n+1}_\u =	e^{n+1}_\u + 2\tau ( \nabla e^{n+1}_p- \nabla e^n_p)  - 2 \tau ( \nabla K_h ( p^{n+1}-p^{n})).
\end{align}

Thus 
\begin{align}\label{cf-5}
&\tau ( \nabla e^{n+1}_p+ \nabla e^n_p,\tilde{e}^{n+1}_\u ) \\
=& 2 \tau^2( \| \nabla e^{n+1}_p \|^2_{L^2}-\| \nabla e^{n}_p \|^2_{L^2} ) - 2 \tau^2 (\nabla (e^{n+1}_p +e^{n}_p ) ,  \nabla K_h ( p^{n+1}-p^{n}) ) \notag
\end{align}
where
\begin{align}\label{cf-6}
	&2 \tau^2 (\nabla (e^{n+1}_p +e^{n}_p ) ,  \nabla K_h ( p^{n+1}-p^{n}) ) \notag \\
	\leq & 2\tau^2 \|\nabla (e^{n+1}_p+e^{n}_p)\|_{L^2}\| \nabla K_h ( p^{n+1}-p^{n})\|_{L^2}\\
	\leq &C \tau^{\frac{3}{2}} \|\nabla (e^{n+1}_p+e^{n}_p)\|_{L^2} \tau^{\frac{1}{2}}\| \nabla K_h ( p^{n+1}-p^{n})\|_{L^2} \notag\\
	\leq & C \tau^3 ( \|\nabla (e^{n+1}_p\|^2_{L^2} +\|\nabla e^{n}_p\|^2_{L^2}  ) + C\tau^2 \int_{t^{n}}^{t^{n+1}} \|  \nabla p_t\|^2_{L^2} dt.\notag
\end{align}

Summing up (\ref{cf-uerrorresult}), (\ref{cf-7}), (\ref{cf-8}) and considering (\ref{cf-4}), (\ref{cf-5}), (\ref{cf-6}), for sufficiently small $\epsilon_1$, we have 
\begin{align}\label{cf-9}
	&\| e^{n+1}_\u\|_{L^2}^2-\| e^{n}_\u\|_{L^2}^2+ 2 \mu \tau \| \nabla \tilde{e}^{n+1}_\u\|_{L^2}^2 + \tau^2( \| \nabla e^{n+1}_p \|^2_{L^2}-\| \nabla e^{n}_p \|^2_{L^2} ) \notag\\
	\leq &C \tau^3 ( \|\nabla (e^{n+1}_p\|^2_{L^2}+\|\nabla e^{n}_p\|^2_{L^2}  ) +C\tau ( \| e^n_\u\|_{L^2}^2+ \|\tilde{e}^n_\eta\|^2_{L^2})\notag\\
	&+C \tau^2 \int_{t^{n}}^{t^{n+1}} \| p_t\|^2_{L^2} dt + C\tau^2 \int_{t^{n}}^{t^{n+1}} \|  \nabla p_t\|^2_{L^2} dt+ \tau \| R^{n+1}_\u\|_{L^2}^2+C\tau h^4.
\end{align}
