%\subsection{Estimate of $ \tilde{e}^{n+1}_\eta$}
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Setting $w_h= 2 \tau  \tilde{e}^{n+1}_\eta $ in (\ref{cf-errorequation2}), we have 
\begin{align}\label{cf-etaerror}
	&\| \tilde{e}^{n+1}_\eta\|_{L^2}^2-\| e^{n}_\eta\|_{L^2}^2+\| \tilde{e}^{n+1}_\eta-e^{n}_\eta\|_{L^2}^2 +2a_\eta \tau \| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}^2\notag\\
	=&2\tau(\frac{\theta^{n+1}_\eta - \theta^n_\eta}{\tau},\tilde{e}^{n+1}_\eta)
	+2\tau(R^{n+1}_\eta,\tilde{e}^{n+1}_\eta)
	-2\tau b(\tilde{e}^n_\u,\tilde{\eta}^{n+1},\tilde{e}^{n+1}_\eta)
	-2\tau b(\theta^n_\u,\tilde{\eta}^{n+1},\tilde{e}^{n+1}_\eta) \\
	&-2\tau b(\u^n_h,\tilde{e}^{n+1}_\eta,\tilde{e}^{n+1}_\eta) 
	-2\tau b(\u^n_h, \theta_\eta^{n+1},\tilde{e}^{n+1}_\eta)
	+2\tau \beta(\tilde{e}^n_\eta \nabla c^{n+1},\nabla \tilde{e}^{n+1}_\eta)
	+2\tau \beta(\theta_\eta^n \nabla c^{n+1},\nabla \tilde{e}^{n+1}_\eta) \notag\\
	&+ 2 \tau\beta(  (\tilde{\eta}^n+m_0) \nabla (e^{n+1}_c +\theta^{n+1}_c) ,\nabla  \tilde{e}^{n+1}_\eta) 
	+ 2 \tau \beta(  (\tilde{e}^n_\eta+\theta^n_\eta) \nabla (e^{n+1}_c +\theta^{n+1}_c),  \nabla \tilde{e}^{n+1}_\eta)\notag\\
		&+2\tau\beta (  (\tilde{\eta}^{n+1}-\tilde{\eta}^n) \nabla c^{n+1}, \nabla \tilde{e}^{n+1}_\eta ).\notag\\
	:=& \sum_{i=1}^{11}2\tau (Y_i ,\tilde{e}^{n+1}_\eta).\notag
\end{align}

By using $ab \leq \frac{1}{2}(a^2+b^2)$, one has
\begin{align}
	2\tau (Y_1 ,\tilde{e}^{n+1}_\eta) \leq&|2 \tau (\frac{\theta^{n+1}_\eta - \theta^n_\eta}{\tau},\tilde{e}^{n+1}_\eta) |\notag\\
	\leq&  \tau \| \tilde{e}^{n+1}_\eta\|_{L^2}^2 + \tau h^4 \|  \frac{\eta^{n+1}-\eta^n}{\tau} \|_{H^2}^2 \notag\\
	\leq &  \tau \|  \tilde{e}^{n+1}_\eta\|_{L^2}+C\tau h^4 \|  \eta_t(\xi)\|_{H^2}^2\quad \xi\in(t^n,t^{n+1})\\
	\leq & \tau \|  \tilde{e}^{n+1}_\eta\|_{L^2}+C\tau h^4.\notag\\
		2\tau (Y_1 ,\tilde{e}^{n+1}_\eta)\leq&|2 \tau  (R^{n+1}_\eta,\tilde{e}^{n+1}_\eta)\notag\\
		\leq & \tau \| R^{n+1}_\eta\|_{L^2}^2+  \tau \| \tilde{e}^{n+1}_\eta\|_{L^2}.
\end{align}

Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), H\"{o}lder inequality and Young inequality, we have
\begin{align}
		2\tau (Y_3+Y_4 ,\tilde{e}^{n+1}_\eta)\leq
	&|-2 \tau  b(e^n_\u,\tilde{\eta}^{n+1},\tilde{e}^{n+1}_\eta)-2 \tau b(\theta_{\u}^n,\tilde{\eta}^{n+1},\tilde{e}^{n+1}_\eta)| \notag \\
	\leq & 2 \tau \| e^n_\u\|_{L^2} \|  \| \nabla \tilde{\eta}^{n+1}\|_{L^3} \|\tilde{e}^{n+1}_\eta \|_{L^6}
	+2 \tau \| \theta^n_\u\| _{L^2} \| \nabla \tilde{\eta}^{n+1}\|_{L^3} \|\tilde{e}^{n+1}_\eta \|_{L^6} \\
	\leq &  \epsilon_2  \tau \| \nabla \tilde{e}^{n+1}_\eta \|_{L^2}^2 + C\tau  \| e^n_\u\|_{L^2}^2 +C\tau h^4.\notag
\end{align}

In terms of (\ref{biobdf-2}), (\ref{biobdf-17}) and inverse inequalities (\ref{biobdf-16}), we can get 
\begin{align}
		2\tau (Y_5+Y_6 ,\tilde{e}^{n+1}_\eta)\leq
	&|-2 \tau b(\u^n_h,\tilde{e}^{n+1}_\eta,\tilde{e}^{n+1}_\eta) -2 \tau b(\u^n_h,\theta^{n+1}_\eta,\tilde{e}^{n+1}_\eta)|\notag\\
	\leq& |2 \tau b(\e^n_\u+\theta^n_\u,\theta^{n+1}_\eta,\tilde{e}^{n+1}_\eta)+ 2 \tau b(\u^n,\tilde{e}^{n+1}_\eta, \theta^{n+1}_\eta)|\notag\\
	\leq & 2\tau \| \e^n_\u+\theta^n_\u\|_{L^3} \| \nabla  \theta^{n+1}_\eta \|_{L^2}\| \tilde{e}^{n+1}_\eta\|_{L^6} 
	+ 2\tau \| \u^n\|_{L^{\infty}} \| \nabla \tilde{e}^{n+1}_\eta\|_{L^2} \| \theta^{n+1}_\eta\|_{L^2} \\
	\leq & C \tau \| \e^n_\u+\theta^n_\u\|_{H^1} h^{-1} \| \theta^{n+1}_\eta \|_{L^2} \| \nabla  \tilde{e}^{n+1}_\eta\|_{L^2}  + C \tau h^4 + \epsilon_2 \| \nabla  \tilde{e}^{n+1}_\eta\|_{L^2}\notag\\
	\leq & C \tau \| \e^n_\u+\theta^n_\u\|_{L^2} h^{-2} \| \theta^{n+1}_\eta \|_{L^2} \| \nabla  \tilde{e}^{n+1}_\eta\|_{L^2}  + C \tau h^4 + \epsilon_2 \| \nabla  \tilde{e}^{n+1}_\eta\|_{L^2}\notag\\
	\leq & \epsilon_2 \tau \| \nabla  \tilde{e}^{n+1}_\eta\|_{L^2}+ C\tau \| \e^n_\u\|_{L^2}^2+C \tau h^4.\notag
\end{align}

By using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), H\"{o}lder inequality and Young inequality,  we have
\begin{align}
	2\tau (Y_7+Y_8 ,\tilde{e}^{n+1}_\eta)\leq
	&C\tau \| \tilde{e}^n_\eta+\tilde{\theta}^n_\eta\|_{L^2} \| \nabla c^{n+1}\|_{L^\infty} \| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}\\
	\leq & C \tau  \| \tilde{e}^n_\eta\|_{L^2}^2+C \tau h^4+\epsilon_2 \tau \| \nabla  \tilde{e}^{n+1}_\eta\|_{L^2}.\notag
\end{align}
Applying (\ref{cf-cprojection}), H\"{o}lder inequality and Young inequality, we can derive
\begin{align}
		2\tau (Y_9 ,\tilde{e}^{n+1}_\eta)\leq
		& 2 \tau \| \tilde{\eta}^n+m_0\|_{L^{\infty}} (\| \nabla e^{n+1}_c\|_{L^2} + \| \nabla \theta^{n+1}_c\|_{L^2} ) \|\nabla \tilde{e}^{n+1}_\eta\|_{L^2}\\
		\leq &  \epsilon_2  \tau \| \tilde{e}^{n+1}_\eta\|^2_{L^2}+ C\tau \| \nabla e^{n+1}_c\|^2_{L^2} + C \tau h^4.\nonumber
\end{align}
Utilizing  the regularity assumption (\ref{cf-regularity}), (\ref{cf-cprojection}), inverse inequality (\ref{biobdf-21}), (\ref{cf-infuctionerror}), $\tau=h$, we have 
\begin{align}
	2\tau (Y_{10} ,\tilde{e}^{n+1}_\eta)\leq
	&C \tau \| \tilde{e}_\eta^n+\theta^n_\eta\|_{L^\infty} (\| \nabla \theta^{n+1}_c\|_{L^2} + \| \nabla e^{n+1}_c\|_{L^2})\| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}\\
	\leq & C\tau h^{-1} (\tau+h^2)
	(\| \nabla \theta^{n+1}_c\|_{L^2} + \| \nabla e^{n+1}_c\|_{L^2})
	\| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}\notag\\
	\leq & C \tau h^4  +\epsilon_2 \tau \|  \nabla \tilde{e}^{n+1}_\eta\|^2_{L^2}+C\tau \| \nabla e^{n+1}_c\|^2_{L^2} .\notag
	\end{align}
For the last term, we have 
	\begin{align}
	2\tau (Y_{11} ,\tilde{e}^{n+1}_\eta)\leq
	&2 \tau\beta (  (\tilde{\eta}^{n+1}-\tilde{\eta}^n) \nabla c^{n+1}, \nabla \tilde{e}^{n+1}_\eta ) \notag \\
	\leq &C \tau \| \tilde{\eta}^{n+1}-\tilde{\eta}^n\|_{L^2} \| \nabla c^{n+1}\|_{L^\infty} \| \nabla \tilde{e}^{n+1}_\eta \|_{L^2}\notag \\
	\leq &  \epsilon_2 \tau \| \nabla \tilde{e}^{n+1}_\eta \|_{L^2} + C\tau^2 \int_{t_{n}}^{t_{n+1}} \| \tilde{\eta}_t\|^2_{L^2}ds.
\end{align}
	Substituting the above estimates into (\ref{cf-etaerror}), we can derive
\begin{align}\label{cf-10}
	&\| \tilde{e}^{n+1}_\eta\|_{L^2}^2-\| e^{n}_\eta\|_{L^2}^2+\| \tilde{e}^{n+1}_\eta-e^{n}_\eta\|_{L^2}^2 +2a_\eta \tau \| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}^2\\
	\leq & C\tau h^4 +C \tau\| \tilde{e}^{n+1}_\eta\|^2_{L^2}  + \tau \| R^{n+1}_\eta\|_{L^2}^2 + \epsilon_2  \tau \| \nabla \tilde{e}^{n+1}_\eta \|_{L^2}^2 + C\tau ( \| e^n_\u\|_{L^2}^2+ \| \tilde{e}^n_\eta\|_{L^2}^2) \notag\\
	&+\epsilon_3 \tau \| \nabla e^{n+1}_c\|^2_{L^2} 
	+C\tau^2 \int_{t_{n}}^{t_{n+1}} \| \tilde{\eta}_t\|^2_{L^2}+C\tau \| \nabla e^{n+1}_c\|^2_{L^2} .\notag
\end{align}
