%\subsection{Estimate of $e^{n+1}_c $}
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Setting $\psi_h=2\tau e^{n+1}_c$ in (\ref{errorequation3}), we have
\begin{align}\label{cf-cerror}
	&\| e^{n+1}_c\|_{L^2}^2-\| e^{n}_c\|_{L^2}^2+\| e^{n+1}_c-e^{n}_c\|_{L^2}^2 +2a_c \tau \| \nabla e^{n+1}_c\|_{L^2}^2\\
	\leq & 2 \tau(\frac{\theta^{n+1}_c - \theta^n_c}{\tau},e^{n+1}_c) 
	+2 \tau (R^{n+1}_c,e^{n+1}_c) -2 \tau b(e^n_\u,c^{n+1},e^{n+1}_c)
	-2 \tau b(\theta^n_\u.c^{n+1},e^{n+1}_c)\notag\\
	&
	-2 \tau b(\u^n_h,e^{n+1}_c,e^{n+1}_c)
	-2 \tau b(\u^n_h,\theta^{n+1}_c,e^{n+1}_c)
	-2 \tau \gamma(\tilde{e}^n_\eta c^{n+1},e^{n+1}_c)
	-2 \tau\gamma(\theta^n_\eta c^{n+1},e^{n+1}_c)\notag\\
	&-2 \tau\gamma( (\tilde{\eta}^n+m_0) (e^{n+1}_c+\theta^{n+1}_c),e^{n+1}_c )
	-2 \tau\gamma( (  \tilde{e}^n_\eta+\theta^n_\eta) (e^{n+1}_c+\theta^{n+1}_c),e^{n+1}_c )\notag\\
	:=& \sum_{i=1}^{10} 2\tau (M_i,e^{n+1}_c).\notag
	\end{align}

By using $ab \leq \frac{1}{2}(a^2+b^2)$, one has
\begin{align}
	2\tau (M_1 ,e^{n+1}_c) \leq&|2 \tau (\frac{\theta^{n+1}_c - \theta^n_c}{\tau},e^{n+1}_c) |\notag\\
	\leq&  \tau \| e^{n+1}_c\|_{L^2}^2 + \tau h^4 \|  \frac{c^{n+1}-c^n}{\tau} \|_{H^2}^2 \notag\\
	\leq &  \tau \|  e^{n+1}_c\|_{L^2}+C\tau h^4 \|  c_t(\xi)\|_{H^2}^2 \quad \xi\in(t^n,t^{n+1})\\
	\leq & \tau \|  e^{n+1}_c\|_{L^2}+C\tau h^4.\notag\\
	2\tau (M_1 ,e^{n+1}_c)\leq&|2 \tau  (R^{n+1}_c,e^{n+1}_c)\notag\\
	\leq & \tau \| R^{n+1}_c\|_{L^2}^2+  \tau \| e^{n+1}_c\|_{L^2}.
\end{align}

Using the regularity assumption (\ref{cf-regularity}), (\ref{cf-inequality}), H\"{o}lder inequality and Young inequality, we have
\begin{align}
	2\tau (M_3+Y_4 ,e^{n+1}_c)\leq
	&|-2 \tau  b(e^n_\u,c^{n+1},e^{n+1}_c)-2 \tau b(\theta_{\u}^n,c^{n+1},e^{n+1}_c)| \notag \\
	\leq & 2 \tau \| e^n_\u\|_{L^2} \|  \| \nabla c^{n+1}\|_{L^3} \|e^{n+1}_c \|_{L^3}
	+2 \tau \| \theta^n_\u\|_{L^2}  \| \nabla c^{n+1}\|_{L^3} \|e^{n+1}_c \|_{L^6} \\
	\leq &  \epsilon_3  \tau \| \nabla e^{n+1}_c \|_{L^2}^2 + C\tau  \| e^n_\u\|_{L^2}^2 +C\tau h^4.\notag
\end{align}


In terms of (\ref{biobdf-2}), (\ref{biobdf-17}) and inverse inequalities (\ref{biobdf-16}), we can get 
\begin{align}
	2\tau (M_5+M_6 ,e^{n+1}_c)\leq
	&|-2 \tau b(\u^n_h,e^{n+1}_c,e^{n+1}_c) -2 \tau b(\u^n_h,\theta^{n+1}_c,e^{n+1}_c)|\notag\\
	\leq& |2 \tau b(\e^n_\u+\theta^n_\u,\theta^{n+1}_c,e^{n+1}_c)+ 2 \tau b(\u^n,e^{n+1}_c, \theta^{n+1}_c)\notag\\
	\leq & 2\tau \| \e^n_\u+\theta^n_\u\|_{L^3} \| \nabla  \theta^{n+1}_c \|_{L^2}\| e^{n+1}_c\|_{L^6} 
	+ 2\tau \| \u^n\|_{L^{\infty}} \| \nabla e^{n+1}_c\|_{L^2} \| \theta^{n+1}_c\|_{L^2} \\
	\leq & C \tau \| \e^n_\u+\theta^n_\u\|_{H^1} h^{-1} \| \theta^{n+1}_c \|_{L^2} \| \nabla  e^{n+1}_c\|_{L^2}  + C \tau h^4 + \epsilon_3 \tau \| \nabla  e^{n+1}_c\|_{L^2}\notag\\
	\leq & C \tau \| \e^n_\u+\theta^n_\u\|_{L^2} h^{-2} \| \theta^{n+1}_c \|_{L^2} \| \nabla  e^{n+1}_c\|_{L^2}  + C \tau h^4 + \epsilon_3 \tau \| \nabla  e^{n+1}_c\|_{L^2}\notag\\
	\leq & \epsilon_3 \tau \| \nabla  \tilde{e}^{n+1}_c\|_{L^2}+ C\tau \| \e^n_\u\|_{L^2}^2+C \tau h^4.\notag
\end{align}

By using H\"{o}lder inequality and Young inequality, we have
\begin{align}
	2\tau (M_7+M_8 ,e^{n+1}_c)\leq&
	C\tau ( \| \tilde{e}^n_\eta \|_{L^2} + \| \theta^n_\eta\|_{L^2}) \| c^{n+1}\|_{L^{3}} \| e^{n+1}_c\|_{L^6} \\
	\leq &C \tau h^4 +C\tau \| \tilde{e}^n_\eta \|_{L^2}^2+\epsilon_3  \tau \| \nabla e^{n+1}_c\|_{L^2}^2.\notag\\
	2\tau (M_9 ,e^{n+1}_c)\leq&
|-2 \tau\gamma( (\tilde{\eta}^n+m_0) (e^{n+1}_c+\theta^{n+1}_c),e^{n+1}_c )|\\
\leq & C\tau \| \tilde{\eta}^n+m_0\|_{L^{3}}  \| e^{n+1}_c+\theta^{n+1}_c\|_{L^2} \|e^{n+1}_c\|_{L^6}. \notag\\
\leq & C \tau h^4 + C \tau \| e^{n+1}_c\|^2_{L^2}+\epsilon_3  \tau \| \nabla  e^{n+1}_c\|^2_{L^2}.\notag
\end{align}

Utilizing  the regularity assumption (\ref{cf-regularity}), inverse inequality (\ref{biobdf-21}), we have 
\begin{align}
	2\tau (M_{10} ,e^{n+1}_c)\leq&
	|2 \tau\gamma( (  \tilde{e}^n_\eta+\theta^n_\eta) (e^{n+1}_c+\theta^{n+1}_c),e^{n+1}_c )|\\
	\leq &  C \tau \| \tilde{e}^n_\eta+\theta^n_\eta\|_{L^4}  \| e^{n+1}_c+\theta^{n+1}_c\|_{L^2} \| e^{n+1}_c\|_{L^4}\notag\\
	\leq& C \tau h^{-\frac{1}{2}} \| \tilde{e}^n_\eta+\theta^n_\eta\|_{L^2} \| e^{n+1}_c\|_{L^2} \| \nabla e^{n+1}_c\|_{L^2} 
	+ C \tau h^{-\frac{1}{2}} \| \tilde{e}^n_\eta+\theta^n_\eta\|_{L^2} \| \theta^{n+1}_c\|_{L^2} \| \nabla e^{n+1}_c\|_{L^2}  \notag\\
	\leq &\epsilon_3\tau \| \nabla  \tilde{e}^{n+1}_c\|_{L^2} +C\tau h^{-1}\| \tilde{e}^n_\eta+\theta^n_\eta\|_{L^2}^2 \|e^{n+1}_c\|^2_{L^2} + C\tau h^3 \|\tilde{e}^n_\eta+\theta^n_\eta\|_{L^2}^2.\notag
\end{align}

Substituting the above estimates into (\ref{cf-cerror}), we can derive
\begin{align}\label{cf-11}
		&\| e^{n+1}_c\|_{L^2}^2-\| e^{n}_c\|_{L^2}^2+\| e^{n+1}_c-e^{n}_c\|_{L^2}^2 +2a_c \tau \| \nabla e^{n+1}_c\|_{L^2}^2\\
		\leq& C \tau \| e^{n+1}_c\|_{L^2}^2+ \epsilon_3 \tau \| \nabla e^{n+1}_c\|_{L^2}^2+ C\tau h^4 + C\tau (\| e^n_\u\|^2_{L^2} + \| \tilde{e}^n_\eta\|^2_{L^2})\notag\\
		&+C\tau h^{-1}\| \tilde{e}^n_\eta+e^n_\eta\|_{L^2}^2 \|e^{n+1}_c\|^2_{L^2} + C\tau h^3 \|\tilde{e}^n_\eta+\theta^n_\eta\|_{L^2}^2.\notag
\end{align}

Thus, from (\ref{cf-9}), (\ref{cf-10}), (\ref{cf-11}), for sufficiently small $\epsilon_1,\epsilon_2,\epsilon_3$, we have
\begin{align}
	&\| e^{n+1}_\u\|_{L^2}^2-\| e^{n}_\u\|_{L^2}^2+ 2 \mu \tau \| \nabla \tilde{e}^{n+1}_\u\|_{L^2}^2 + \tau^2( \| \nabla e^{n+1}_p \|^2_{L^2}-\| \nabla e^{n}_p \|^2_{L^2} ) \\
	&+\| \tilde{e}^{n+1}_\eta\|_{L^2}^2-\| e^{n}_\eta\|_{L^2}^2+\| \tilde{e}^{n+1}_\eta-e^{n}_\eta\|_{L^2}^2 +2a_\eta \tau \| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}^2\nonumber\\
	&+\| e^{n+1}_c\|_{L^2}^2-\| e^{n}_c\|_{L^2}^2+\| e^{n+1}_c-e^{n}_c\|_{L^2}^2 +2a_c \tau \| \nabla e^{n+1}_c\|_{L^2}^2\notag\\
	\leq &C \tau^3 ( \|\nabla (e^{n+1}_p\|^2_{L^2}+\|\nabla e^{n}_p\|^2_{L^2}  ) + C\tau(  \| \tilde{e}^{n+1}_\eta\|^2_{L^2} +\tau \| e^{n+1}_c\|_{L^2}^2+\| e^n_\u\|_{L^2}^2+ \|\tilde{e}^n_\eta\|^2_{L^2} )\nonumber \\
	&+C \tau^2 \int_{t^{n}}^{t^{n+1}} \| p_t\|^2_{L^2} dt + C\tau^2 \int_{t^{n}}^{t^{n+1}} \|  \nabla p_t\|^2_{L^2} dt+ C\tau ( \| R^{n+1}_\u\|_{H^{-1}}^2+ \| R^{n+1}_\eta\|_{L^2}^2+ \| R^{n+1}_c\|_{L^2}^2)+C\tau h^4\nonumber\\
	& +C\tau h^{-1}\| \tilde{e}^n_\eta+\theta^n_\eta\|_{L^2}^2 \|e^{n+1}_c\|^2_{L^2} + C\tau h^3 \|\tilde{e}^n_\eta+\theta^n_\eta\|_{L^2}^2+ C\tau^2 \int_{t_{n}}^{t_{n+1}} \| \tilde{\eta}_t\|^2_{L^2}ds.\nonumber
\end{align}
Summing up from 0 to $N-1$,
in terms of mathematical induction method (\ref{cf-infuctionerror}), regularity assumptions (\ref{cf-regularity}), (\ref{cf-12}), for sufficiently small $h$ such that 
\begin{align}
	&\| e^{N}_\u\|_{L^2}^2+\| e^{N}_\eta\|_{L^2}^2+ \| e^{N}_c\|_{L^2}^2+2 \mu \tau \sum_{n=0}^{N-1}(\| \nabla \tilde{e}^{n+1}_\u\|_{L^2}^2 +\| \nabla \tilde{e}^{n+1}_\eta\|_{L^2}^2 + \| \nabla e^{n+1}_c\|_{L^2}^2)+\tau^2\| \nabla e^{N}_p \|^2_{L^2}  \\
	\leq & C(\tau^2 +h^4) +C \tau^3 ( \|\nabla e^{n+1}_p\|^2_{L^2}+\|\nabla e^{n}_p\|^2_{L^2}  ) + C\tau(  \| \tilde{e}^{n+1}_\eta\|^2_{L^2} +\tau \| e^{n+1}_c\|_{L^2}^2+\| e^n_\u\|_{L^2}^2+ \|\tilde{e}^n_\eta\|^2_{L^2} )\nonumber
	\end{align}

Application of Gronwall's inequality in Lemma \ref{biobdf-11} yields (\ref{cf-errorresult2}). The proof of Lemma \ref{cf-therror2} is completed.
	\end{proof}

\subsection{The proof of Theorem \ref{cf-therror}}
\begin{proof}
	According the projection error (\ref{cf-uprojection}), (\ref{cf-etaprojection}), (\ref{cf-cprojection}) and Lemma \ref{cf-therror2}, we can derive 
	\begin{align}\label{cf-uiresult}
		\| \u^i-\u^i_h\|_{L^2} =\| \u^i-R_h \u^i + R_h \u^i -\u^i_h\|_{L^2} \leq \| \u^i-R_h \u^i \|_{L^2} + \| e^i_\u\|_{L^2} \leq C(\tau^2+h^4).
	\end{align}

Similarly 

	\begin{align}
	\| \eta^i-\eta^i_h\|_{L^2} = &	\| (\tilde{\eta}^i+m_0)-(\tilde{\eta}^i_h+m_0)\|_{L^2}\label{cf-etairesult}\\
	 =&	\| \tilde{\eta}^i-\tilde{\eta}^i_h\|_{L^2}\notag\\
	 =&\| \eta^i-T_h \eta^i + T_h \eta^i -\eta^i_h\|_{L^2}\notag\\
	  \leq &\| \eta^i-T_h \eta^i \|_{L^2} + \| e^i_\eta\|_{L^2} \notag\\
	  \leq &C(\tau^2+h^4),\notag\\
	\| c^i-c^i_h\|_{L^2} =&\| c^i-\Pi_h c^i + \Pi_h c^i -c^i_h\|_{L^2}\notag\\
	 \leq &\| c^i-\Pi_h c^i \|_{L^2} + \| e^i_c\|_{L^2}\notag\\
	  \leq &C(\tau^2+h^4).\label{cf-ciresult}
\end{align}

Thus, we complete the proof of Theorem \ref{cf-therror}.
\end{proof}

Now the convergence analysis by the pressure-correction projection finite element method is done. Using the error estimates (\ref{cf-uiresult}), (\ref{cf-etairesult}), (\ref{cf-ciresult}) and the regularity assumption (\ref{cf-regularity}), we can deduce the unconditional stability for the fully discrete scheme as follows:
\begin{theorem}
Under the regularity assumption (\ref{cf-regularity}), for sufficiently small $\tau$ and $h$, the following unconditional stability results satisfy
\begin{align}
	\| \u^i_h\|_{L^2}^2 + 	\| \eta^i_h\|_{L^2}^2+	\| c^i_h\|_{L^2}^2 + \tau \sum_{i=1}^{N} \| \nabla \u^i_h\|^2_{L^2}+\tau \sum_{i=1}^{N} \| \nabla \eta^i_h\|^2_{L^2}+\tau \sum_{i=1}^{N} \| \nabla c^i_h\|^2_{L^2} \leq C.
\end{align}
for $1 \leq i \leq N$, which is difficult to derive by using the energy analysis method due to the nonlinear term $\beta \div(\eta \nabla c)$ in (\ref{cfmodel}).
\end{theorem}
