\subsection{Update Rule}

Agents revise their strategy by maximizing their payoff function jointly with respect to their two decision variables (actions and opinions), as proposed in~\cite{aghbolagh2023coevolutionary}. %{\color{blue}As we will see below, $\mathcal{B}_i(f_i(\cdot,\vect{z_{-i}}(t)))$ will be such that $z_i \in B$ is unique. }
At each time $t$, each agent is either activated or inactive. An agent $i$ that is activated updates their opinion and action simultaneously according to the best-response update rule:
\begin{equation}\label{eq:async_update}
 z_i(t+1) = \mathcal{B}_i(f_i(\cdot,\vect{z_{-i}}(t))).
% z_i(t+1) \in \mathcal{B}_i(z_{-i}).
\end{equation}
where $\mathcal{B}_i$ is the best-response strategy defined in \eqref{eq:best_response} and
$f_i(\cdot,\vect{z_{-i}}(t))$ is the payoff from \eqref{def:payoff_func_coo_anti}, with the convention that, if $\mathcal{B}_i(f_i(\cdot,\vect{z_{-i}}(t)))$ comprises multiple elements, then it is chosen the one with $x_i(t+1)=x_i(t)$, which is unique for $\beta_i>0$ (see~\cite{aghbolagh2023coevolutionary}), to account for social inertia in human decision-making~\cite{ye2021nat}. For all other agents who are inactive, their strategies are unchanged: $z_k(t+1) = z_k(t)$. In other words, active agents tend to maximize their current payoff, based on the current action of others, as supported by empirical evidence~\cite{mas2016behavioral}. 
Following~\cite{aghbolagh2023coevolutionary}, we derive a closed-form expression for the update rule of the coevolutionary dynamics by explicitly writing the maximizers of~\eqref{def:payoff_func_coo_anti}.
\begin{proposition}\label{prop:dyn}
Given a state $\vect{z}=(\vect{x},\vect{y})\in \gA$ and an agent $i\in\mathcal{V},$ let us define the discriminant 
\begin{equation}\label{delta_i(z)}
 \begin{aligned}
  \delta_i(\vect{z}(t)) & = \frac{\varepsilon_i\lambda_i(1-\beta_i)}{2}\sum_{j\in \mathcal V}a_{ij}\left[2x_j(t)+\alpha(1+x_j(t))\right]\\
   &+2(1-\lambda_i)\lambda_i\beta_i\sum\nolimits_{j \in \mathcal V}w_{ij}y_j(t).
               % &+2(1-\lambda_i)\lambda_i\beta_i[(1-\gamma_i)\sum_{j \in \mathcal V}w_{ij}y_j(t)+\gamma_iu_i].
 \end{aligned} 
\end{equation} 
If $i\in\mathcal V$ is activated at time $t$, the state is updated to
\begin{subequations}\label{update_rule_coo_xy}
\begin{align}
    x_i(t+1)&=\mathcal{S}(\delta_i(\vect{z}(t)))\label{action_update}\\ 
    y_i(t+1)&=(1-\lambda_i)\sum\nolimits_{j\in\mathcal{V}}\hspace{-.2cm}w_{ij}y_j(t)\label{opinion_update}%\\
    %(1-\lambda_i)[(1-\gamma_i)\sum_{j\in\mathcal{V}}w_{ij}y_j(t)+\gamma_iu_i\label{opinion_update}\\
            %& \qquad 
            +\lambda_i\mathcal{S}(\delta_i(\vect{z}(t))),%\notag
\end{align}
\end{subequations}
where 
\begin{equation}
     \mathcal{S}(\delta_i(\vect{z}(t)))=
     \begin{cases}
     +1 & \text{if} \ \delta_i(\vect{z}(t))>0,\\    
     x_i(t) & \text{if} \ \delta_i(\vect{z}(t))=0,\\
     -1 & \text{if} \ \delta_i(\vect{z}(t))<0.
     \end{cases}
\end{equation}
\end{proposition}
\begin{proof}
    Case $\varepsilon=+1$ is proved in \cite{aghbolagh2023coevolutionary}. The proof for $\varepsilon=-1$ follows the same arguments, and is thus omitted.
\end{proof}
%===== two standing assumptions====================%%%%%%%%%%%%%%%%%%%%%%%%%&======================================================================================================================
Next, we formalize two standing assumptions that will be enforced for the rest of the paper. First, we assume that the population is homogeneous, second, we pose some mild constraints on the activation sequence, which are quite standard in the related literature~\cite{xiao2006state,zino2020two}.

\begin{assumption}[Homogeneous population]\label{as:uniform}
The parameters are homogeneous, i.e., for all $i\in\mathcal V$, there holds  $\lambda_i=\lambda \in (0,1),\beta_i=\beta\in(0,1)$, and $\varepsilon_i=\varepsilon\in\{-1,+1\}$. Moreover, 
the two graphs are undirected, i.e., $W=W^{\top}$ and $A=A^{\top}$.
\end{assumption}

\begin{assumption}[Activation sequence]\label{as:activation}
There exists a finite positive integer $T$ such that, for any $t \geq 0$, every agent activates at least once in the interval $t,t+1,\ldots,t+T-1$.
\end{assumption}

Under Assumption~\ref{as:uniform}, all agents have the same $\varepsilon$. Hence, we can identify two scenarios of interest: i) Networks of \emph{coordinating agents}, where $\varepsilon=+1$; and ii) Networks of \emph{anti-coordinating agents}, where $\varepsilon=-1$. In the rest of this paper, we present results on these two scenarios. First, in Section~\ref{sec: results_coo}, we consider a population of coordinating agents, where \cite{aghbolagh2023coevolutionary} guarantees convergence to an equilibrium, and we focus on characterizing conditions under which the system converges to a consensus. Second, in Section~\ref{sec: results_anti_coord}, we consider a population of anti-coordinating agents and, after proving convergence to an equilibrium, we investigate consensus and polarized equilibria and their basins of attraction. 


%=====Coordination Game%%%%%%%%%%%%%%%%%%%%%%%%%&===================================================================================
\section{Results for Coordinating Agents}\label{sec: results_coo}
In the presence of only coordinating agents $(\varepsilon_i=+1,\,\forall\,i\in\mathcal V)$, the  results from~\cite{aghbolagh2023coevolutionary} guarantee that the coevolutionary dynamics under Assumptions~\ref{as:uniform}--\ref{as:activation} converges to a NE. However, in general, multiple equilibria may be present. In~\cite{aghbolagh2023coevolutionary}, some conditions have been established under which polarized equilibria exist and are stable. Here, instead, we focus on consensus equilibria, which are defined as follows.

\begin{definition}[Consensus configuration]\label{def_NE_consensus}
   We say that the vector $\vect{z}(t)=[\vect{x}(t), \vect{y}(t)]$ is a  consensus configuration at time $t$ if $\vect{x}(t)= \vect{y}(t)=\vect{1}_n$ or $\vect{x}(t)=\vect{y}(t)=-\vect{1}_n.$ 
\end{definition}

We now prove that consensus configurations are always NEs of the game when all players are coordinating agents.  

\begin{theorem}\label{thm:NE_consesus}
Consider the coevolutionary model in \eqref{update_rule_coo_xy}.
Suppose that Assumption~\ref{as:uniform}  holds and $\varepsilon=1$.
%Then the game has pure strategy Nash equilibria of the form $z^{*}= [\vect{1}_n,\vect{1}_n]$ or $[-\vect{1}_{n},-\vect{1}_{n}].$
Then the consensus configurations $\vect{z}^{*}= [\vect{1}_n,\vect{1}_n]$ and $[-\vect{1}_{n},-\vect{1}_{n}]$
%or $[-\vect{1}_{n},-\vect{1}_{n}]$ 
are NE.
\end{theorem}
\begin{proof}The proof is reported in Appendix~\ref{app:thm:NE_consesus}. 
\end{proof}

In the following, we establish conditions under which the dynamics converge to such a consensus configuration. 


\subsection{Basin of Attraction of Consensus Configuration}
%With this notion of a partition in place, w
%We introduce the following definitions of sets in the network. The superscript of the set represents the sign of the opinion, while the subscript represents the sign of the action. 
Given a time instant $t\in \mathbb Z_+$, and $\vect z(t) = (\vect x(t), \vect y(t))$, we define the following mutually exclusive sets
\begin{align*}
    \mathcal{V}_{1}^{+}(t) & :=\{j:\sgn(y_j(t))\geq 0, x_j(t)=+1\}, \\
    \mathcal{V}_{-1}^{+}(t)& :=\{j:\sgn(y_j(t))>0, x_j(t)=-1\}, \\
    \mathcal{V}_{1}^{-}(t)& :=\{j:\sgn(y_j(t))<0, x_j(t)=+1\},\\
    \mathcal{V}_{-1}^{-}(t)& :=\{j:\sgn(y_j(t))\leq 0, x_j(t)=-1\}.
\end{align*}
with $\sgn(0) = 0$.
% : $\mathcal{V}_{1}^{+}(t):=\{j:\sgn(y_j(t))\geq0, x_j(t)=+1\}$,  $\mathcal{V}_{-1}^{+}(t):=\{j:\sgn(y_j(t))>0, x_j(t)=-1\}$, $\mathcal{V}_{1}^{-}(t):=\{j:\sgn(y_j(t))<0, x_j(t)=+1\}$, and $\mathcal{V}_{-1}^{-}(t):=\{j:\sgn(y_j(t))\leq0, x_j(t)=-1\}$. 
Intuitively, $\mathcal{V}_{1}^{+}(t)$ and $\mathcal{V}_{-1}^{-}(t)$ are the sets of agents whose actions and opinions are aligned (the agent's opinion indicates a preference for their current action). On the contrary, $\mathcal{V}_{-1}^{+}(t)$ and $\mathcal{V}_{1}^{-}(t)$ are the sets of agents who are misaligned, i.e., the sign of their opinion differs from their action. Before presenting our results, we report two graph-theoretic definitions.

\begin{definition}[Cohesive set]\label{def:cohesive set}
Let $\mathcal{G}[M]=(\mathcal{V},\mathcal{E}_M,M)$ be a graph with associated adjacency matrix $M$. Then, for a given constant $q\in (0,1)$, a set $S\subset$ $\mathcal{V}$ is called $q$-cohesive if 
\begin{equation}
\frac{\sum_{j \in S} m_{ij}}{\sum_{j \in \mathcal{V}}m_{ij}}\geq q,\;\forall\,i \in S.
\end{equation}
Conversely, a set $S\subset$ $\mathcal{V}$ is called $q$-diffusive if 
\begin{equation}
\frac{\sum_{j \in S} m_{ij}}{\sum_{j \in \mathcal{V}}m_{ij}}<q,\;\forall\,i \in S.
\end{equation}
% where $q\in (0,1),\forall i \in S.$
\end{definition}

