\section{Results for Anti-coordinating Agents}\label{sec: results_anti_coord}

%We consider the coevolutionary dynamics with anti-coordinating agents. Such anti-coordination behavior exists in social communities in different scenarios, local public goods provision, information gathering, and firms interacting in competitive markets, as described above. 

\subsection{Convergence}

We start the analysis of the coevolutionary model with anti-coordinating agents $(\varepsilon_i=-1,\,\forall i\in\mathcal V)$ by proving the following convergence result.

\begin{theorem}\label{thm:anti_convergence_all}
Consider the coevolutionary model in \eqref{update_rule_coo_xy}.
Suppose that Assumptions~\ref{as:uniform} and \ref{as:activation} hold and $\varepsilon=-1$. Then, the state of the system $\vect{z}(t)$ converges to a steady state $\vect{z}^* = (\vect x^*, \vect y^*)$. Specifically, the action vector $\vect{x}(t)$ converges to $\vect{x^*}$ in finite time, while the opinion vector $\vect{y}(t)$ converges to $\vect{y^*}$ asymptotically.
\end{theorem}

\begin{proof}
The proof is reported in Appendix~\ref{app:thm:anti_convergence_all}.  
\end{proof}

% \begin{remark}
%     The result in Theorem~\ref{thm:anti_convergence_all} can be readily extended to the scenario in which agents have prejudices, adding the fourth term to \eqref{def:payoff_func_coo_anti} and, consequently, to the potential function in \eqref{mixed_Phi(z)}. 
% \end{remark}

After having established convergence in the presence of anti-coordinating agents, we start analyzing some equilibria of interest, namely, consensus and polarized configurations.

\subsection{Consensus Equilibria}
We start by analyzing whether a consensus equilibrium exists,  establishing the following result.
\begin{theorem}\label{thm:consensus_ equilibrium_anti} Consider the coevolutionary model in \eqref{update_rule_coo_xy}.
Suppose that Assumptions~\ref{as:uniform}--\ref{as:activation} hold and $\varepsilon=-1$. Then, $\vect{z}^*=[\vect{1}_n,\vect{1}_n]$  
is an equilibrium of the coevolutionary model on the two-layer network $\gG$ iff, for any $i\in\mathcal{V}$, it holds  
\begin{equation}\label{eq:condition_A}\sum\nolimits_{j\in\mathcal{V}}a_{ij}<\frac{2(1-\lambda)\beta}{(1-\beta)(1+\alpha)}.
\end{equation}
\end{theorem}

\begin{proof}The proof is reported in Appendix~\ref{app:consensus_ equilibrium_anti}.
\end{proof}

