\subsection{Polarized Equilibria}

%Studying polarized equilibria in social networks helps uncover the mechanisms that reinforce or mitigate divisions within communities, providing insights that are essential for addressing issues related to misinformation, political polarization, and group dynamics. 
Here, we discuss how our model may lead to the emergence of stable polarized configurations (see Definition~\ref{def_polar}). 
%Given the set of agents $\mathcal{V}$, we denote by $(\mathcal{V}_p, \mathcal{V}_n)$ a partitioning of the agents into two disjoint sets satisfying $\gV_p\bigcap\gV_n=\emptyset$, $\gV_p\bigcup\gV_n=\gV$ and $\mathcal{V}_p \neq \emptyset$ and $\mathcal{V}_n \neq \emptyset$. With this notion of a partition in place, we introduce the following definitions of polarization in the network.We adopt the same definition of the polarized state as Definition 3 in \cite{aghbolagh2023coevolutionary}. To better understand the following theorem, we briefly reiterate it here. Given a state of the system $\vect z=(\vect{x},\vect{y})\in\{-1,1\}^n\times [-1,1]^n$, we say that the action vector $\vect x$ is \emph{polarized} if there exists a partition of the agents ($\gV_p$, $\gV_n$) such that $x_j=+1$, for all $j\in\gV_p$ and $x_i=-1$, for all $i\in\gV_n$. The opinion vector $\vect y$ is \emph{polarized} if there exists a partition of the agents ($\gV_p$, $\gV_n$) such that $y_j>0$, for all $j\in\gV_p$ and $y_i<0$, for all $i\in\gV_n$. The state $\vect{z}$ is \emph{polarized} if there exists a partition of the agents ($\gV_p$, $\gV_n$) such that $x_i=-1$ and $y_i<0$, for all $i\in\gV_n$, and $x_j=1$ and $y_j>0$, for all $j\in\gV_p$. The state $\vect{z^*}$ is a \emph{polarized equilibrium} if it is a polarized state, and it is an equilibrium of the coevolutionary model in Eqs.~(\ref{action_update})--(\ref{opinion_update}). 
In particular, the following result provides a sufficient condition for the existence of a polarized equilibrium in the presence of anti-coordinating agents, and complements a similar result for coordinating agents in \cite[Theorem~2]{aghbolagh2023coevolutionary}.
\begin{theorem}\label{thm:polarized_anti}
Consider the coevolutionary model in \eqref{update_rule_coo_xy}.
Suppose that Assumptions~\ref{as:uniform}--\ref{as:polarization} hold and $\varepsilon=-1$. Suppose there exists a partitioning of the agents $(\mathcal{V}_p,\mathcal{V}_n)$ with 
\begin{equation}\label{eq:dp_dn_anti}
 \begin{aligned}
   \underline{d}_p:=\min_{i\in\mathcal{V}_p} \sum\nolimits_{j\in\mathcal{V}_p} w_{ij},  
   \bar{d}_p:=\max_{i\in\mathcal{V}_p} \sum\nolimits_{j\in\mathcal{V}_p} w_{ij},\\
   \underline{d}_n:=\min_{i\in\mathcal{V}_n } \sum\nolimits_{j\in\mathcal{V}_n }w_{ij}, 
  \bar{d}_n:=\max_{i\in\mathcal{V}_n } \sum\nolimits_{j\in\mathcal{V}_n }w_{ij}, 
\end{aligned}
\end{equation}
such that the following three conditions are satisfied:
\begin{subequations}
\begin{equation}\label{eq:pol_y_cond_anti}
   \lambda>\max \Big(\frac{\underline{d}_p-\bar{d}_n }{1+\underline{d}_p-\underline{d}_n}, \frac{\bar d_n-\underline d_p}{1+\bar d_n-\underline d_p}\Big),
\end{equation}
\begin{equation}\label{eq:pol_xp_cond_anti}
    \frac{\lambda (\underline{d}_p +\bar{d}_n - 1) + \underline{d}_p -\bar{d}_n}{1-(1-\lambda)(\bar{d}_p +\bar{d}_n-1)}+\frac{(1-\beta)(1-2\bar{d}_p)}{2 \beta  (1-\lambda )}>0,
    %- \frac{(1-\beta)(2\bar{d}_p -1)}{2 \beta  (1-\lambda )} > 0
\end{equation}
\begin{equation}\label{eq:pol_xn_cond_anti}
 \frac{\lambda (\underline{d}_n + \bar{d}_p - 1) + \underline{d}_n - \bar{d}_p}{1-(1-\lambda)(\bar{d}_n+\bar{d}_p -1)}-\frac{(1-\beta)(1-2\bar{d}_n)}{2 \beta  (1-\lambda )}>0.
\end{equation}\end{subequations}
Then, the coevolutionary model in \eqref{update_rule_coo_xy} has a polarized equilibrium with respect to the partition $(\mathcal{V}_p,\mathcal{V}_n)$.
\end{theorem}
\begin{proof}
The proof is reported in Appendix~\ref{app:thm:polarized_anti}.    
\end{proof}

Theorem~\ref{thm:polarized_anti} establishes three conditions for the existence of a polarized equilibrium. Although the last two conditions may not be intuitive, all three are easy to check. Below, we study the stability of such equilibrium, establishing a more conservative sufficient condition.

%%%%%%%%%%%%---Th7-----===================================================================================================
\begin{theorem}\label{thm:polarized_convergence_anti}
Consider the coevolutionary model in \eqref{update_rule_coo_xy}. Suppose that Assumptions~\ref{as:uniform}--\ref{as:polarization} hold, $\beta<1/(2-\lambda)$, and $\varepsilon=-1$. 
Suppose $\vect{z}(0)$ is a polarized configuration with respect to a partition $(\mathcal{V}_{1}^{+}(0),\mathcal{V}_{-1}^{-}(0))=:(\mathcal{V}_p,\mathcal{V}_n)$.  
If
\begin{equation}\label{eq:condition_polarized_anti}
    \frac{1-2\lambda}{1-\lambda}<\sum\nolimits_{j\in  \mathcal S}w_{ij}<\frac12\Big(1+\frac{\beta(1-\lambda)}{2\beta-\beta\lambda-1}\Big), \forall\, i\in \mathcal S,
\end{equation}
holds separately for $\mathcal S=\mathcal V_p$ and $\mathcal S=\mathcal V_n$, then $\vect{z}(t)$ is polarized for any $t$ with respect to the same partition $(\mathcal{V}_p,\mathcal{V}_n)$. Moreover, $\lim_{t\to\infty} \vect{z}(t) = \vect{z}^*$, where $\vect z^*$ is a polarized equilibrium with respect to the same partition $(\mathcal{V}_p,\mathcal{V}_n)$.
\end{theorem}
\begin{proof}The proof is reported in Appendix~\ref{app:polarized_convergence_anti}. 
\end{proof}
%%%%%%%======Compared with the polarized equilibrium in the network with coordination game,

\begin{remark}
In~\cite[Theorem 3]{aghbolagh2023coevolutionary} a sufficient condition for existence and convergence to a polarized equilibrium for networks of coordinating agents is reported, paralleling Theorem~\ref{thm:polarized_convergence_anti}. The sufficient condition reported in \cite[Theorem 3]{aghbolagh2023coevolutionary} can be expressed in the notation of this paper as 
\begin{equation}\label{eq:condition_polarized_coo}
    \sum\nolimits_{j\in  \mathcal S}w_{ij}> \max\Big\{\frac{1-2\lambda}{1-\lambda},\frac12\Big(1+\frac{\beta(1-\lambda)}{1-\beta\lambda}\Big)\Big\}, \forall\,i\in \mathcal  S,
\end{equation}
for, separately, $ \mathcal S = \mathcal{V}_p$ and $\mathcal S = \mathcal{V}_n$. The set $S$ in \eqref{eq:condition_polarized_coo} are all $\frac{1}{2}$-cohesive sets since $\max\{\frac{1-2\lambda}{1-\lambda},\frac12(1+\frac{\beta(1-\lambda)}{1-\beta\lambda})\}\geq \frac{1}{2}$.
\end{remark}

