\section{Proof of Theorem~\ref{thm:NE_consesus}}\label{app:thm:NE_consesus}
According to the Definition~\ref{def:best_response} and Lemma~\ref{lemma_Nash_equ}, we need to show that when $\vect{z_{-i}}=[\vect{1}_{n-1},\vect{1}_{n-1}], \forall i \in \mathcal{V}, z_i=[1,1]$ is the best response. That is, $[1,1]\in \mathcal{B}_i(f_i(\cdot,[\vect{1}_{n-1},\vect{1}_{n-1}]))$.
By Assumption~\ref{as:uniform}, we write 
\begin{equation*}\label{eq:th1_eq1}
\begin{split}  & \mathcal{B}_i (f_i(\cdot,[\vect{1}_{n-1},\vect{1}_{n-1}]))=\argmax\nolimits_{z_i} f_i(z_i,[\vect{1}_{n-1},\vect{1}_{n-1}]),  \\
&=\argmax\nolimits_{z_i}\frac{\lambda(1-\beta)}{2}\sum\nolimits_{j\in \mathcal V}a_{ij}(1+\alpha)(1+x_i)\\
&-\frac{1}{2}(1-\lambda)\beta\sum\nolimits_{j \in \mathcal V}w_{ij}(y_i-1)^2-\frac{1}{2}\lambda\beta(y_i-x_i)^2.
\end{split}
\end{equation*}
Since $x_i$ can only take values $-1$ or $1$, the above equation is a discrete optimization problem. We can determine the optimal choice of $x_i$ by substituting these two values into $f_i(z_i, [\vect{1}_{n-1},\vect{1}_{n-1}])$. For $y_i\in[-1,1]$, we need to find the value that maximizes $f_i$ in the interval $[-1, 1]$.

\textbf{Case $x_i=+1$.} We compute
$f_i(z_i,[\vect{1}_{n-1},\vect{1}_{n-1}])=
    \lambda(1-\beta)(1+\alpha)\sum_{j\in \mathcal V}a_{ij}-\frac{1}{2}(1-\lambda)\beta\sum_{j \in \mathcal V}w_{ij}(y_i-1)^2-\frac{1}{2}\lambda\beta(y_i-1)^2$. % 
Taking the partial derivative of $f_i$ with respect to $y_i$ and setting it to zero yields \begin{equation*}
\frac{\partial f_i}{\partial y_i} =- (1 - \lambda) \beta \sum\nolimits_{j \in \mathcal V} w_{ij} (y_i - 1) -\lambda \beta (y_i - 1)  = 0,
\end{equation*}
which is maximized by $y_i = 1$, which yields the claim.

\textbf{Case $x_i=-1$.} We compute  
$
f_i(z_i,[\vect{1}_{n-1},\vect{1}_{n-1}])=-\lambda(1-\beta)\sum_{j\in \mathcal V}a_{ij}-\frac{1}{2}(1-\lambda)\beta\sum_{j \in \mathcal V}w_{ij}(y_i+1)^2-\frac{1}{2}\lambda\beta(y_i+1)^2.
$
%$ f_i(z_i,[\vect{1}_{n-1},\vect{1}_{n-1}])-\frac{1}{2}(1-\lambda)\beta\sum_{j \in \mathcal V}w_{ij}(y_i+1)^2-\frac{1}{2}\lambda\beta(y_i+1)^2.$
