\section{Proof of Theorem~\ref{thm:basins of attraction_vp_vnp}}\label{app:thm:basins of attraction_vp_vnp}
First, our assumption on $\vect z(0)$ implies that $\mathcal V_1^+(0) \cup \mathcal V_{-1}^+(0) = \mathcal V$. Exploiting this, the key argument is to show that the following three statements hold true for all  $t\geq 0$: i) $\delta_i(\vect{z}(t))\geq0$, for all $i\in\mathcal V_1^+(0)$, and $\delta_i(\vect{z}(t))>0$, for all $i\in\mathcal V_{-1}^+(0)$; ii) $\vect x(t+1)\geq \vect x(t)$; and iii) $\vect{y}(t+1)\geq \vect 0_n$. Here, the inequalities are taken entry-wise. We prove the three statements jointly by (strong) induction. We start by proving that the statements hold true for $t=0$. To prove i), we compute $\delta_i$ by splitting each sum into two parts, obtaining
\begin{equation*}\label{eq:delta_t_equation_th1}
 \begin{aligned}
  \delta_i(\vect{z}(0)) &\hspace{-.07cm}=\hspace{-.07cm}  p \sum\nolimits_{j \in \mathcal{V}_{1}^+(0)}\hspace{-.1cm}w_{ij} y_j(0)\hspace{-.07cm}+\hspace{-.07cm}p \sum\nolimits_{k \in \mathcal{V}_{-1}^{+}(0)}\hspace{-.1cm} w_{i k} y_k(0) \\
              &+\frac{q}{4}\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}a_{ij}\left[2x_j(0)+\alpha(1+x_j(0))\right]\\
              &+\frac{q}{4}\sum\nolimits_{k\in \mathcal{V}^{+}_{-1}(0)}a_{ik}\left[2x_k(0)+\alpha(1+x_k(0))\right],\\
 \end{aligned} 
\end{equation*}
where $p=2\lambda\beta(1-\lambda)$ and $q=2\lambda(1-\beta)$ are positive constants. For $i\in \mathcal{V}_{1}^+(0)$, we use the cohesiveness of $\mathcal{V}_{1}^+(0)$ and the fact that $\vect{y}(0)\geq 0_n$, to bound
\begin{equation}\label{eq:delta_t_equation2_th1}
 \begin{aligned}
  \delta_i(\vect{z}(0)) & \geq\frac{q}{2}\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}\hspace{-.1cm}a_{ij}(1+\alpha)\hspace{-.07cm}-\hspace{-.07cm}\frac{q}{2}\sum\nolimits_{k\in \mathcal{V}^{+}_{-1}(0)}\hspace{-.1cm}a_{ik}\\
  & \geq\frac{q}{2}\left[\frac{1}{\alpha+2}(1+\alpha)-\frac{\alpha+1}{\alpha+2}\right]\geq 0.
 \end{aligned} 
\end{equation}
Similarly, for $i\in \mathcal{V}_{-1}^{+}(0)$, we use the diffusiveness of $\mathcal {V}_{-1}^{+}(0)$ and the fact that $\vect{y}(0)\geq 0$, to bound
\begin{equation}\label{eq:delta_t_equation3_th1}
 \begin{aligned}
  \delta_i(\vect{z}(0)) & \geq\frac{q}{2}\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}\hspace{-.07cm}a_{ij}(1+\alpha)\hspace{-.07cm}-\hspace{-.07cm}\frac{q}{2}\sum\nolimits_{k\in \mathcal{V}^{+}_{-1}(0)}\hspace{-.07cm}a_{ik}\\
  & >\frac{q}{2}\left[\frac{1}{\alpha+2}(1+\alpha)-\frac{\alpha+1}{\alpha+2}\right]\geq 0.
 \end{aligned} 
\end{equation}
The strict inequality is obtained due to the $\frac{\alpha+1}{\alpha+2}$-diffusiveness of $\mathcal {V}_{-1}^+(0)$, which implies that $\sum\nolimits_{k\in \mathcal{V}^{+}_{-1}(0)}a_{ik}<\frac{\alpha+1}{\alpha+2}$. To prove ii) and iii), let $i_0$ be the agent active at time $t=0$. For all $i\neq i_0$, no update is performed, hence, it clearly holds true that $x_i(1)=x_i(0)$ and $y_i(1)=y_i(0)\geq 0$. Then, we distinguish two cases. If $i_0\in\mathcal V_1^+(0)$, and because $\delta_i(\vect z(0))\geq 0$ as established above, it follows that $x_i(1)=1$ and $y_i(1)\geq\lambda\geq 0$, according to Proposition~\ref{prop:dyn}. If $i_0\in\mathcal V_{-1}^+(0)$, and because $\delta_i(\vect z(0))> 0$ as established above, it follows that $x_i(1)=1$ and $y_i(1)\geq\lambda\geq 0$, according to Proposition~\ref{prop:dyn}, yielding the claim. This concludes the proof of the induction basis.
% We now proceed to prove the inductive step.
We are now left to prove that, assuming i)--iii) hold up to time $t$, they necessarily hold at $t+1$. The proof of i) follows the same arguments used to prove the induction basis. In fact, due to  strong induction assumption, we have $x_i(t)\geq x_i(0)$, for all $i\in\mathcal V$, implying
\begin{equation}\label{eq:delta_t_equation4}
 \begin{aligned}
  \delta_i(\vect{z}(t))  &\geq \frac{q}{4}\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(t)}a_{ij}\left[2x_j(t)+\alpha(1+x_j(t))\right]\\
              &+\frac{q}{4}\sum\nolimits_{k\in \mathcal{V}^{+}_{-1}(t)}a_{ik}\left[2x_k(t)+\alpha(1+x_k(t))\right],\\
           \geq   & \frac{q}{4}\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}a_{ij}\left[2x_j(0)+\alpha(1+x_j(0))\right]\\
              &+\frac{q}{4}\sum\nolimits_{k\in \mathcal{V}^{+}_{-1}(0)}a_{ik}\left[2x_k(0)+\alpha(1+x_k(0))\right],
 \end{aligned} 
\end{equation}
which is nonnegative (or strictly positive) as per \eqref{eq:delta_t_equation2_th1}
and \eqref{eq:delta_t_equation3_th1}, respectively. Similar, ii) and iii) are obtained as consequences of the positivity of $\delta_i$ from \eqref{eq:delta_t_equation4}.

Finally, if at a generic time $t$, agent $i_t\in\mathcal V_{-1}^{+}(0)$ activates, then $\delta_{i_t}(\vect{z}(t))>0$, implying that $x_{i_t}(t+1)=1$. Due to Assumption~\ref{as:activation} and the monotonicity property proved above in item ii), it necessarily holds true that $\vect{x}(t)=\vect{1}$, for all $t\geq T$. Finally, the fact that $[\vect{1}_n,\vect{1}_n]$ is the only NE with $\vect{x}=\vect{1}_n$ guarantees convergence~\cite[Theorem 1]{raineri2025}. 

\qed
