\sum\nolimits_{j\in\mathcal{V}_{-1}^{-}(0)}w_{ij}  &< \frac{q}{2(p+q)}, && i\in\mathcal{V}_{-1}^{-}(0),\label{eq:xcoo_cond_nn}
\end{align}
\end{subequations}
then i) $\delta_i(\vect{z}(t))\geq0$, for all $i\in\mathcal V_1^+(0)$, and $\delta_i(\vect{z}(t))>0$, for all $i\in\mathcal V_{-1}^{-}(0)$; and ii) the action vector $\vect x(t+1)\geq \vect x(t)$.  Then, we show that if there also holds 
\vspace{-0.1cm}
\begin{subequations}
\begin{align}
 \sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}w_{ij}\geq\frac{1-2\lambda}{1-\lambda} && i\in\mathcal{V}_{1}^{+}(0),\label{eq:ycoo_cond_pp} \\
\sum\nolimits_{j\in\mathcal{V}_{-1}^{-}(0)}w_{ij}< \frac{\lambda}{1-\lambda},&& i\in\mathcal{V}_{-1}^{-}(0),\label{eq:ycoo_cond_nn} 
\end{align}
\end{subequations}
we have iii) the opinion vector $\vect{y}(t+1))\geq \vect 0_n$. 
We start by proving that the statements hold for $t=0$. To prove i), we compute $\delta_i$ by splitting each sum into two parts, obtaining
\vspace{-0.1cm}
\begin{equation*}\label{eq:deltacon_0001_vp_pn}
 \begin{aligned}
  \delta_i&(\vect{z}(0)) \hspace{-.07cm}=\hspace{-.07cm}  p \sum\nolimits_{j \in \mathcal{V}_{1}^+(0)}\hspace{-.1cm}w_{ij} y_j(0)\hspace{-.07cm}+\hspace{-.07cm}p \sum\nolimits_{k \in \mathcal{V}_{-1}^{-}(0)}\hspace{-.1cm} w_{i k} y_k(0) \\
              &+\frac{q}{4}\left[\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}w_{ij}2x_j(0)+\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}2x_k(0)\right].
