 \end{equation*}
For $i\in \mathcal{V}_{1}^+(0)$, we use \eqref{eq:xcoo_cond_pp},  $\sum_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik} = 1-\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}$ because $W$ is stochastic, and $y_k(0)\in[-1,0),\forall k\in\mathcal{V}_{-1}^{-}(0),y_j(0)\in(0,+1],\forall j\in\mathcal{V}_{1}^{+}(0)$ to bound
% \begin{equation}\label{eq:deltacon_02_vp_pn}
%   \delta_i(\vect{z}(0)) \geq -p\hspace{-.2cm}\sum_{k\in \mathcal{V}_{-1}^{-}(0)}\hspace{-.2cm}w_{ik}+\frac{q}{2}\Big(\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij} -\hspace{-.2cm}\sum_{k\in \mathcal{V}_{-1}^{-}(0)}\hspace{-.2cm}w_{ik}\Big),
