 \delta_i(\vect{z}(0)) 
 %&\geq -p\hspace{-.1cm}\sum_{k\in \mathcal{V}_{-1}^{-}(0)}\hspace{-.2cm}w_{ik}+\frac{q}{2}\Big(\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij} -\hspace{-.2cm}\sum_{k\in \mathcal{V}_{-1}^{-}(0)}\hspace{-.2cm}w_{ik}\Big)\\
 &\geq -p(1\hspace{-.07cm}-\hspace{-.07cm}\sum\nolimits_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij})+q\Big[\hspace{-0.05cm}\sum\nolimits_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij} \hspace{-.07cm}-\hspace{-.07cm}\frac12\Big]\\
% &\geq -(p+\frac{q}{2})(1-\hspace{-.3cm}\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij})+\frac{q}{2}\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}\\
 &\geq  -(p+\frac{q}{2})+(p+q)\sum\nolimits_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}\\
 &\geq  -(p+\frac{q}{2})+(p+q)\big(1-\frac{q}{2(p+q)}\big)\geq 0.
  \end{aligned} 
