\section{Proof of Theorem~\ref{thm:polarized_convergence_anti}}\label{app:polarized_convergence_anti}
First, our assumption on polarized $\vect z(0)$ implies that $\mathcal V_1^+(0) \cup \mathcal V_{-1}^{-}(0) = \mathcal V$. 
For the sake of convenience in our proof, we define positive constants $p=2\lambda\beta(1-\lambda)$ and $q=2\lambda(1-\beta)$.
%First, our assumption on $\vect z(0)$ implies that $\mathcal V_1^+(0) \cup \mathcal V_{-1}^{-}(0) = \mathcal V$. 
The proof is by induction. To begin, we show that if the partitions $\mathcal{V}_{1}^{+}(0)$ and $\mathcal{V}_{-1}^{-}(0)$ satisfy \eqref{eq:condition_polarized_anti}, then i) $\vect{x}(1)$ is polarized with respect to the same partition and ii) $\vect{y}(1)$ is polarized with respect to the same partition, i.e., $\mathcal{V}_{1}^{+}(1) = \mathcal{V}_{1}^{+}(0)$ and $\mathcal{V}_{-1}^{-}(1) = \mathcal{V}_{-1}^{-}(0)$
% \vspace{-0.1cm}
% \begin{equation}\label{eq:x_anti_cond}
%     \sum\nolimits_{j\in S}w_{ij}<\frac12\Big(1+\frac{p}{p-q}\Big), \forall i\in S,
% \end{equation}
% with $\mathcal S \in\{\mathcal{V}_{1}^{+}(0), \mathcal{V}_{-1}^{-}(0)\}$, then i) $\delta_i(\vect{z}(t))\geq0$, for all $i\in\mathcal V_1^+(0)$, and $\delta_i(\vect{z}(t))<0$, for all $i\in\mathcal V_{-1}^{-}(0)$; and ii) the action vector $\vect x(t+1)\geq \vect x(t)$.  Then, we show that if there also holds 
% \vspace{-0.1cm}
% \begin{equation}\label{eq:y_anti_cond}
%    \sum\nolimits_{j\in S}w_{ij}> \frac{1-2\lambda}{1-\lambda}, \forall i\in S,
% \end{equation}
% for $\mathcal S \in\{\mathcal{V}_{1}^{+}(0), \mathcal{V}_{-1}^{-}(0)\}$, 
% then the opinion vector $\vect{y}(t+1)$ will also be polarized. Hence, by induction, if $\vect{z}(0)$ is polarized, then $\vect{z}(t)$ will be polarized, for all $t$. 
Then, Theorems~\ref{thm:anti_convergence_all} and~\ref{thm:polarized_anti} are leveraged to guarantee convergence to equilibrium , and that $\mathcal{V}_{1}^{+}(t) = \mathcal{V}_{1}^{+}(0)$ and $\mathcal{V}_{-1}^{-}(t) = \mathcal{V}_{-1}^{-}(0)$ for all $t\geq 0$ (implying the equilibrium is polarized), respectively.

We start from the induction basis. To prove i), we compute $\delta_i(\vect{z}(0))$ by splitting each sum into two parts, obtaining 
\begin{equation}\begin{array}{l}\displaystyle\delta_i(\vect{z}(0)) \hspace{-.07cm}=\hspace{-.07cm}  p\Big[\sum\nolimits_{j \in \mathcal{V}_{1}^+(0)}\hspace{-.1cm}w_{ij} y_j(0)\hspace{-.07cm}+\hspace{-.07cm}\sum\nolimits_{k \in \mathcal{V}_{-1}^{-}(0)}\hspace{-.1cm} w_{i k} y_k(0)\Big]\\ \quad\displaystyle-\frac{q}{2}\Big[\sum\nolimits_{j\in\mathcal{V}_{1}^{+}(0)}w_{ij}x_j(0)+\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}x_k(0)\Big].
\end{array}\end{equation}
For $i\in \mathcal{V}_{1}^+(0)$, we use the following facts: a) the inequalities in \eqref{eq:condition_polarized_anti}, b) $\beta<1/(2-\lambda)$, c) $y_k(0)\in[-1,0),\forall k\in\mathcal{V}_{-1}^{-}(0),y_j(0)\in(0,+1],\forall j\in\mathcal{V}_{1}^{+}(0)$, and d) $\sum_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik} = 1-\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}$ to bound
\vspace{-0.1cm}
\begin{equation}\label{eq:deltacon_03_vp_pn_polar}
 \begin{aligned}
\delta_i&(\vect{z}(0))=p\left[\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij}y_j+\right.
\left.\hspace{-.07cm}\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}y_k\right]\\
  & \quad \ -q\Big( \sum\nolimits_{j\in\mathcal{V}_{+1}^{+}(0)}w_{ij}-\frac12\Big)\\
  &\geq -p\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}-q\sum\nolimits_{j\in\mathcal{V}_{+1}^{+}(0)}w_{ij} +\frac{q}{2}\\
  %&\geq -p(1-\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij})-q\sum\nolimits_{j\in\mathcal{V}_{+1}^{+}(0)}w_{ij} +\frac{q}{2}\\
   &\geq (p-q)\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij}-p+\frac{q}{2}\\
  &\geq (p-q) \frac12\big(1+\frac{p}{p-q}\big)+\big(\frac{q}{2} +p\big)> 0.
\end{aligned}
\end{equation}
For $i\in \mathcal{V}_{-1}^{-}(0)$, we use the inequalities in \eqref{eq:condition_polarized_anti}, the condition $\beta<1/(2-\lambda)$, the fact that $y_k(0)\in[-1,0),\forall k\in\mathcal{V}_{-1}^{-}(0),y_j(0)\in(0,+1],\forall j\in\mathcal{V}_{1}^{+}(0)$, and the equality $\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}=1-\sum_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik}$ to bound
\vspace{-0.1cm}
\begin{equation}\label{eq:deltacon_04_vp_pn_polar}
 \begin{aligned}
\delta_i&(\vect{z}(0))=p\left[\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij}y_j\right.
\left.\hspace{-.07cm}+\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}y_k\right]\\
  & \quad \ -q\Big(\frac12 -\hspace{-.1cm}\sum\nolimits_{j\in\mathcal{V}_{-1}^{-}(0)}w_{ij}\Big)\\
  &\leq p\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij}-q\Big(\frac12 -\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}\Big)\\
  &\leq -(p-q)\sum\nolimits_{k\in \mathcal{V}^{-}_{-1}(0)}w_{ik}+\big(p-\frac{q}{2}\big)\\
  &\leq -(p-q) \frac12\big(1+\frac{p}{p-q}\big)+\big(p-\frac{q}{2}\big)< 0.
\end{aligned}
\end{equation}
Let $i_0$ be the agent active at time $t=0$. For all $i\neq i_0$, no update is performed, so those agents in $\mathcal{V}^-_{-1}(0)$ remain in $\mathcal{V}^-_{-1}(1)$ (and agents in $\mathcal{V}^+_{+1}(0)$ stay in $\mathcal{V}^+_{+1}(1)$ ). Concerning $i_0$, we distinguish two cases. If $i_0\in\mathcal V_{1}^{+}(0)$, being $\delta_i(\vect z(0))\geq 0$, then $x_i(1)=x_i(0)=1$. From \eqref{opinion_update}, we obtain $y_i(1)\geq(1-\lambda)(-\sum\nolimits_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik} )+\lambda>0,$ with the latter due to the left inequality of \eqref{eq:condition_polarized_anti}. If $i_0\in\mathcal V_{-1}^{-}(0)$, being $\delta_i(\vect z(0))< 0$, then $x_i(1)=-1$ and similarly, $y_i(1)\leq(1-\lambda)\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij}-\lambda<0$ according to \eqref{eq:condition_polarized_anti}. This concludes the proof of the induction basis. 
%Following a reasoning similar to the one in the proof of Theorem~\ref{thm:basins of attraction_vp_vnp} implies that $\vect{x}(1)$ is polarized, with respect to the same partition. 
%To prove ii) and iii), let $i_0$ be the agent active at time $t=0$. For all $i\neq i_0$, no update is performed, hence it clearly holds true that $x_i(1)=x_i(0)$ and $y_i(1)=y_i(0)\geq 0,i\in\mathcal{V}$. Then, we distinguish two cases. If $i_0\in\mathcal V_{1}^{+}(0)$, being $\delta_i(\vect z(0))\geq 0$, then $x_i(1)=x_i(0)=1$ and $y_i(1)\geq(1-\lambda)(-\sum_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik} )+\lambda\geq 0$ according to \eqref{eq:y_anti_cond} and $\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}+ \sum_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik} =1$. If $i_0\in\mathcal V_{-1}^{-}(0)$, being $\delta_i(\vect z(0))< 0$, then $x_i(1)=-1$ and $y_i(1)\leq(1-\lambda)\sum\nolimits_{j\in \mathcal{V}_{+1}^{+}(0)}w_{ij}-\lambda<0$ according to \eqref{eq:y_anti_cond} and $\sum_{j\in \mathcal{V}_{1}^{+}(0)}w_{ij}+ \sum_{k\in \mathcal{V}_{-1}^{-}(0)}w_{ik} =1 $, yielding the claim. This concludes the proof of the induction basis. 
By using an induction argument, it can be shown by repeating the arguments used in \eqref{eq:deltacon_03_vp_pn_polar} and \eqref{eq:deltacon_04_vp_pn_polar} that if $\vect{z}(t)$ is polarized with respect to the same partitioning and \eqref{eq:condition_polarized_anti} holds, then also $\vect{z}(t+1)$ is polarized with respect to that partitioning. Hence, the induction principle yields the first claim. 

%Finally, Theorem~\ref{thm:anti_convergence_all} guarantees  convergence based on $\lim_{t\to\infty} \vect{z}(t)\to\vect{z}^*$. Since $\vect z(t)$ is polarized with respect to $(\mathcal{V}_{1}^{+}(t),\mathcal{V}_{-1}^{-}(t))$, and because the inequalities in \eqref{eq:condition_polarized_anti} satisfy the conditions~(\ref{eq:pol_y_cond_anti})--(\ref{eq:pol_xn_cond_anti}) of Theorem~\ref{thm:polarized_anti} (which can be applied since Assumptions~\ref{as:uniform}--\ref{as:polarization} hold), then $\vect z^*(t)$ must be polarized with respect to $(\mathcal{V}_{1}^{+}(t),\mathcal{V}_{-1}^{-}(t))$ for any time $t$.We observe that the elements in the two sets remain unchanged over time. For notational convenience, we denote $\mathcal{V}_{1}^{+}(t)$ and $\mathcal{V}_{-1}^{-}(t)$ as $\mathcal{V}_p$ and $\mathcal{V}_n$, which completes the proof.

%{\color{orange}
Finally, Theorem~\ref{thm:anti_convergence_all} guarantees  convergence to an equilibrium: $\lim_{t\to\infty} \vect{z}(t)\to\vect{z}^*$. Now, $\vect z(0)$ is polarized with respect to $(\mathcal{V}_{1}^{+}(0),\mathcal{V}_{-1}^{-}(0))$ by hypothesis, and the above has established that $\mathcal{V}_{1}^{+}(t) = \mathcal{V}_{1}^{+}(0)$ and $\mathcal{V}_{-1}^{-}(t) = \mathcal{V}_{-1}^{-}(0)$ for all $t\geq 0$. In other words, the elements in the two sets remain unchanged over time. Separately, the inequalities in \eqref{eq:condition_polarized_anti} satisfy the conditions~(\ref{eq:pol_y_cond_anti})--(\ref{eq:pol_xn_cond_anti}) of Theorem~\ref{thm:polarized_anti} (which can be applied since Assumptions~\ref{as:uniform}--\ref{as:polarization} hold), and thus $\vect z^*$ must be polarized with respect to $(\mathcal{V}_{1}^{+}(0),\mathcal{V}_{-1}^{-}(0))$.
% We observe that the elements in the two sets remain unchanged over time. 
For notational convenience, we denote $\mathcal{V}_{1}^{+}(0)$ and $\mathcal{V}_{-1}^{-}(0)$ as $\mathcal{V}_p$ and $\mathcal{V}_n$, which completes the proof.%}
