\begin{lemma} \label{pairs}
The number of descending pairs in $B \cap G$ is $O(x^3\sqrt{n})$.
\end{lemma}
%
\begin{proof}
By construction (due to that $\angle{v_2ov_3}=30^\circ$), 
for each fixed point $u \in B\cap G$, there are $O(x^2)$ points $v$, where $(u,v)$ is a descending pair. 
Summing over all $O(x \sqrt{n})$ points in $B\cap G$, the upper bound follows.  
\end{proof}



We can now finalize the proof of the lower bound. Take a random subset $P$ of
$B\cap{G}$ by retaining each point independently with probability
$p\in(0,1)$. We have that
$\mathbb{E}(\lvert{P}\rvert)=\Omega(x\sqrt{n}p)$. Moreover, letting $D$ and $T$
denote the numbers of descending pairs and collinear triples in $P$,
respectively, by Lemmas~\ref{triples} and~\ref{pairs} it holds that 
\begin{equation}
\mathbb{E}(D)=O(p^2x^3\sqrt{n})\quad\text{and}\quad\mathbb{E}(T)=O(p^3x^{5/2}n^{3/4}\log{n}).
\end{equation}
Setting $x=n^{1/10}(\log{n})^{2/5}$, we have $\mathbb{E}(\lvert{P}\rvert)=\Omega\left(pn^{3/5}(\log{n})^{2/5}\right)$ and
\begin{equation}
\mathbb{E}(D)=O\left(p^2n^{4/5}(\log{n})^{6/5}\right)\quad\text{and}\quad\mathbb{E}(T)=O\left(p^3n\log{n}\right).
\end{equation}
Let $p=\frac{c}{n^{1/5}(\log{n})^{4/5}}$ with a sufficiently small constant $c>0$. Then
%We shall have that
\begin{equation}
\mathbb{E}(\lvert{P}\rvert-D-T)=\mathbb{E}(\lvert{P}\rvert)-\mathbb{E}(D)-\mathbb{E}(T)\geq\frac{1}{3}\mathbb{E}(\lvert{P}\rvert)=\Omega\left(\frac{n^{2/5}}{(\log{n})^{2/5}}\right).
\end{equation}
Since each descending pair and collinear triple can be eliminated by deleting
one point, there exists a monotone general position subset of $B\cap G$ of
size $\Omega\left((n/\log{n})^{2/5}\right)$, proving the lower bound. 

\medskip
\emph{Upper bound.} Let $G$ be a $\sqrt{n} \times \sqrt{n}$ grid of $n$
points. An old result of Pomerance~\cite{Pom80} states that for every $k \geq
3,b >0$, there exists a number $m_0(k,b)$ such that if $m \geq m_0(k,b)$ and
$\mathbf{u_0}, \mathbf{u_1},\ldots, \mathbf{u_m}$ are points in $\ZZ^2$ with
$\sum_{i=1}^m |\mathbf{u_i} -\mathbf{u_{i-1}}| \leq b m$, then $\{\mathbf{u_0},
\mathbf{u_1},\ldots, \mathbf{u_m}\}$ contains a collinear $k$-tuple.
%We will  use this result for $k=3$. 

Assume for contradiction that there exists an absolute constant $c>0$
such that there exists a monotone general position set
$P:=\{\mathbf{u_0}, \mathbf{u_1},\ldots, \mathbf{u_m}\}\subseteq{G}$ with $m
\geq c \sqrt{n}$. Let $k=3$, $b=2/c$ and assume that $n$ is sufficiently large
so that $m \geq c \sqrt{n} \geq m_0(k,b)$. Since the set $P$ is monotone, we
have 
\begin{equation}
\sum_{i=1}^m |\mathbf{u_i} -\mathbf{u_{i-1}}| \leq 2\sqrt{n} \leq \frac{2m}{c} =b m.
\end{equation}

By the above result (with $k=3$ and $b=2/c$), $P$ contains a collinear triple,
a contradiction. This concludes the proof of the upper bound and the theorem.\qed




\section{Selecting a subset with pairwise distinct slopes} \label{sec:slopes}

In this section we prove Theorem~\ref{thm:distinct-slopes}. 
First we need an upper bound on the number of trapezoids (each trapezoid is an obstacle
in achieving the final goal). 


\begin{lemma} \label{lem:T}
Let $P\subseteq{R}^2$ be a set of $n$ points with at most $s$ points collinear. Then the number of trapezoids spanned by $P$ is at most
\begin{equation}
O(n^3 \log{s} + n^2 s^2).
\end{equation}
\end{lemma}
%
\begin{proof}
Let $T$ denote the number of trapezoids spanned by $P$. For every trapezoid $t=abcd$, let $ab \parallel cd$ be a pair of parallel lines. 
Assign every trapezoid to the parallel line that is incident to the largest number of points in $P$,
with ties broken arbitrarily.

For $2 \leq i \leq s$, let $k_i$ be the number of lines containing exactly $i$ points in $P$. A well-known corollary of the Szemer\'edi--Trotter theorem~\cite{ST83} states that
%
\begin{equation} \label{eq:st}
  b_i := \sum_{j \geq i} k_j =O\left( \frac{n^2}{i^3} + \frac{n}{i} \right).
\end{equation}
%

Note that the sequence $(b_i)_{i\geq2}$ is non-increasing. 
For a given line $\ell$ with $|\ell \cap P|=i$, let $m=m(\ell)$ be the number of
lines determined by $P$ that are parallel to $\ell$ and incident to at most $i$
points of $P$. Let $a_1,\ldots,a_m \leq i$ be the number of points contained in
these lines. Then the number of trapezoids assigned to $\ell$ is at most 
\begin{equation}
{i \choose 2} \sum_{j=1}^{m(\ell)} {a_j \choose 2} \leq {i \choose 2} \frac{n}{i} \, {i \choose 2} \leq ni^3.
\end{equation}
Therefore,
%
\begin{equation} 
\label{eq:T}
  T \leq \sum_{i=2}^{s}\sum_{\ell:\,|\ell \cap P|=i} ni^3 = n \sum_{i=2}^{s} i^3 k_i.
\end{equation}
%

Note that $i^3 -(i-1)^3 \leq 3 i^2$, thus by Abel’s partial summation formula we obtain
%
\begin{equation}
\begin{aligned}
\sum_{i=2}^{s} i^3 k_i &= \sum_{i=2}^{s} i^3 \left(b_i - b_{i+1}\right) 
= O\left(\sum_{i=2}^{s} i^2 b_i \right)
= O\left(\sum_{i=2}^{s} i^2 \left(\frac{n^2}{i^3} + \frac{n}{i} \right) \right)\\
&= O\left( n^2 \sum_{i=2}^{s} \frac{1}{i} + n \sum_{i=2}^{s} i \right)
= O\left( n^2 \log{s} + n s^2 \right).
\end{aligned}
\end{equation}
%

Plugging the above estimate into~\eqref{eq:T} yields
\begin{equation}
T \leq  n \sum_{i=2}^{s} i^3 k_i =  O\left( n^3 \log{s} + n^2 s^2 \right).\qedhere
\end{equation}
\end{proof}


\subsection{Proof of Theorem~\ref{thm:distinct-slopes}}
\medskip
\emph{Lower bound.} Let $P\subseteq\mathbb{R}^2$ be an arbitrary set of $n$
points with at most $s$ points collinear,
where $s=O(\sqrt{n})$. We take a random subset $X \subseteq P$ by selecting points
independently with probability $p=k/n$. Note that
$\mathbb{E}(\lvert{X}\rvert)=k$.  

To select a subset with distinct slopes, one needs to avoid two types
of obstacles, collinear triples and trapezoids. Let $L$ and $T$ be the number of collinear triples and trapezoids spanned by $P$.
One obstacle can be eliminated by deleting one point from the subset in the second step. In particular,
it suffices to choose $k$ so that
\begin{equation}
\mathbb{E}(L p^3) \leq k/3 \quad\text{ and }\quad  \mathbb{E}(T p^4) \leq k/3,
\end{equation}
since this implies that the expected number of remaining points after deleting one point from each trapezoid and collinear triple is at least $k-k/3-k/3=k/3$.
Using the upper bounds in Lemma~\ref{low} and  Lemma~\ref{lem:T},
it suffices to choose $k$ so that
\begin{equation}
O(k^2) \leq n/\log{s} \quad\text{ and }\quad  O(k^3) \leq n/\log{s}.
\end{equation}
Setting $k = c(n/\log{s})^{1/3}$ with a sufficiently small constant $c>0$ would satisfy both requirements, proving the lower bound.

\medskip
\emph{Upper bound (i).} Let $P=\{(x,x^2): x\in [n]\}\subseteq \mathbb{R}^2$.
The point set $P$ is of size $n$ and contains no collinear triple.
Let $Q\subseteq P$ be a subset of size $|Q|=2\sqrt{n}+2$. We will show that $Q$ contains a trapezoid. 

A \emph{Sidon set} $S\subseteq [n]$ is a subset of the integers such that
$a+b = c+d$ for $a, b, c, d \in S$ with $a\neq b, c\neq d$ implies $\{a, b\} = \{c, d\}$;
see, \eg,~\cite[Chap.~6]{ES03} or~\cite[Chap.~2]{TV06}. 
Note that the largest size of a Sidon set $S\subseteq[n]$ is at most $2\sqrt{n}+1$,
because $\binom{|S|}{2}\leq 2n$. Let $S=\{x: (x,x^2)\in Q\}$.
Since $|S|=2\sqrt{n}+2$, it is not a Sidon set and thus contains 4 distinct elements $x_1,x_2,x_3,x_4\in S$
such that $x_1+x_2=x_3+x_4$. Then, the 4 points 
$(x_1,x_1^2),  (x_2,x_2^2),  (x_3,x_3^2), (x_4,x_4^2)\in Q $
form a trapezoid. Indeed,
\begin{equation}
\frac{x_2^2-x_1^2}{x_2-x_1}=  
x_1+x_2  = x_3+x_4 = \frac{x_4^2-x_3^2}{x_4-x_3}.
\end{equation}


\medskip
\emph{Upper bound (ii).} The proof is similar to that of Theorem~\ref{law} part~(i).
Consider the 2-dimensional grid $[n]^2$. Let $\mathcal{L}$ be the set of
lines that go through at least two points in $[n]^{2}$. Note that
$\lvert\mathcal{L}\rvert\leq{n^{4}}$ and every line in $\mathcal{L}$ contains at
most $n$ points in $[n]^2$. Moreover, it was shown in~\cite{EGRT92} that every
set of $\Omega(n^{4/5})$ points in $[n]^2$ contains a trapezoid. Let $P$ be a
random subset of $[n]^2$ by retaining each point independently with probability
$n^{\alpha-1}/2$, where $\alpha \in [3/5,1]$. By Chernoff's bound we have that
$|P|=\Theta(n^{1+\alpha})$ with high probability. Furthermore, using the union
bound and Chernoff's bound we have 
\begin{equation}
\begin{aligned}
  & \quad \ \mathbb{P}\left(P\text{ contains no collinear
  $n^{\alpha}$-tuple}\right)=1-\mathbb{P}\left(\exists\,\ell\in\mathcal{L}:\,\lvert{P\cap\ell}\rvert\geq{n^{\alpha}}\right) \\
  &\geq1-\sum_{\ell\in\mathcal{L}}\mathbb{P}\left(\lvert{P\cap\ell}\rvert\geq\left(1+\frac{n^{\alpha}}{2\mathbb{E}(\lvert{P\cap\ell}\rvert)}\right)\mathbb{E}(\lvert{P\cap\ell}\rvert)\right) \geq1-n^{4}\exp(-n^{\alpha}/10),
\end{aligned}
\end{equation}
which tends to $1$ as $n\to\infty$. Namely, there exists a point set $P\subseteq[n]^{2}$
of size $\Theta(n^{1+\alpha})$, so that $P$ contains no collinear $n^{\alpha}$-tuple
and every subset of $P$ of size $\Omega(n^{4/5})$ contains a trapezoid. After scaling we obtain 
\begin{equation} 
h(n,n^{\frac{\alpha}{1+\alpha}}) = O(n^{\frac{4/5}{1+\alpha}}) \quad \text{for}\quad 3/5\leq\alpha\leq1.
\end{equation}
By letting $s=n^{\frac{\alpha}{1+\alpha}}$ we have
\begin{equation}
h(n,s) = O((n/s)^{4/5}) \quad \text{for}\quad n^{3/8}\leq s \leq \sqrt{n}.
\end{equation}

\medskip
Aggregating the bounds in (i) and (ii) yields the bounds in the theorem.
\qed




\section{Further consequences}\label{sec:consequences}

Gowers~\cite{Gow11} introduced the following natural notion. For
$s\in\mathbb{N}$, the \textit{(diagonal) Ramsey number of planar points} $r(s)$
is the smallest integer, such that every set $P\subseteq\mathbb{R}^{2}$ of $r(s)$
points contains either a collinear $s$-tuple or a general position subset of
size $s$. It follows from the definition that $r(s)=s$ when $s\leq3$. With a
simple drawing one can show that $r(4)=5$, but the value of $r(5)$ is already
unknown. For the asymptotic behavior of $r(s)$, Gowers~\cite{Gow11} observed
that 
\begin{equation}
\label{gow}
\Omega(s^{2})=r(s)=O(s^{3}).
\end{equation}
The lower bound construction comes from the grid $[m]^{2}$, where
$m=\lceil{s/2}\rceil-1$. Obviously, $[m]^{2}$ contains at most $s/2$ collinear
points and by the pigeonhole principle at most $s-1$ points in general
position. The upper bound in~\eqref{gow} is derived by a greedy algorithm. Gowers~\cite{Gow11} asked to determine the correct order of $r(s)$ or
at least to show which one of the trivial lower and upper bounds is closer to
the truth. This question has been partially answered by Payne and
Wood~\cite{PW13}, who proved that 
\begin{equation}
\label{pop}
r(s)=O(s^{2}\log{s}),
\end{equation}
and further conjectured that $r(s)$ is quadratic in $s$.
\begin{conjecture}[{Payne-Wood~\cite[Conjecture 4.1]{PW13}}, see also~\cite{Gow13}]
\label{oil}
\begin{equation}
r(s)=\Theta(s^{2}).
\end{equation}
\end{conjecture}
As a consequence of Proposition~\ref{new}, if a set $P\subseteq\mathbb{R}^2$ of
$n$ points contains no collinear $s$-tuple with $s=O(\sqrt{n})$, then it contains
a general position subset of size $\Omega\left(\sqrt{\frac{n\log\log{s}}{\log{s}}}\right)$.
This implies the following better upper bound on $r(s)$ proved by Hajnal and Szemer\'{e}di~\cite{HS18}. 
\begin{corollary}[{Hajnal--Szemer\'{e}di~\cite[Theorem 3]{HS18}}]
\label{log}
\begin{equation}
r(s)=O\left(\frac{s^{2}\log{s}}{\log\log{s}}\right).
\end{equation}
\end{corollary}
Our proof of Proposition~\ref{new} can be regarded as an extension of the arguments presented in~\cite{HS18}.
Payne and Wood~\cite{PW13} proposed the following strengthening of Conjecture~\ref{oil}.
\begin{conjecture}[{Payne-Wood~\cite[Conjecture 4.2]{PW13}}]
\label{conj:PaynWood}
  Every set $P\subseteq\mathbb{R}^{2}$ of $n$ points with at most $\sqrt{n}$ points collinear can be colored with $O(\sqrt{n})$ colors
  such that each color class is in general position.
\end{conjecture}
Conjecture~\ref{conj:PaynWood}, if true, would be sharp since at least $\sqrt{n}/2$ colors are needed to properly color the $\sqrt{n}\times \sqrt{n}$ grid.
Payne and Wood showed that $O(\sqrt{n}(\log{n})^{3/2})$ colors are sufficient to color $P$.
Here we improve this result by a factor of $\sqrt{\log{n}}$. Moreover, note that Theorem~\ref{dog} is a strengthening of Corollary~\ref{log}.
\begin{theorem}
\label{dog}
Every set $P\subseteq\mathbb{R}^{2}$ of $n$ points with at most $\sqrt{n}$
collinear points can be colored with $O(\sqrt{n}\log{n})$ colors such that each
color class is in general position. In particular, one can properly color $n-o(n)$ points of $P$ with $O(\sqrt{n\log{n}/\log\log{n}})$ colors. 
\end{theorem}
\begin{proof}
Assume that $n$ is sufficiently large and let $s=\lfloor\sqrt{n}\rfloor$. Then
$P\subseteq\mathbb{R}^{2}$ is a set of $n$ points with at most $s$ points
collinear. Our process of coloring $P$ consists of two phases.

\smallskip
\textbf{Phase 1:}\\
Let $k=\lfloor\log\log{n}-2C\rfloor$ with some sufficiently large constant
$C>0$. For each $i\in[k]$, we let $P_{i}$ be a subset of
$P\backslash\left(\bigcup_{j<i}P_{j}\right)$ obtained by selecting half of the remaining points,
namely those that are contained in the least number of collinear triples.
% xxx: have revised the wording, please check and/or further revise if needed.
Note that $\lvert{P_{i}}\rvert\geq4^Cn/\log{n}$ holds for all $i\in[k]$, namely,
$s\leq2^{-C}\sqrt{\lvert{P_{i}}\rvert\log{\lvert{P_{i}}\rvert}}$. Let
$\mathcal{H}_{i}=\mathcal{H}(P_{i})$ be a $3$-uniform hypergraph with the vertex
set $P_{i}$, whose edges are the collinear triples in $P_{i}$. Observe that the
least number of colors needed to color $P_{i}$ with each color class being in
general position is equal to $\chi(\mathcal{H}_{i})$. Recall~\eqref{due}, we
have that 
\begin{equation}
\chi(\mathcal{H}_{i})=O\left(\sqrt{\frac{\lvert{P}_{i}\rvert\log{s}}{\log{\frac{\lvert{P}_{i}\rvert\log{s}}{s^{2}}}}}\right)=O\left(\sqrt{\frac{n\log{s}}{2^{i}\log{\frac{n\log{s}}{2^{i}s^{2}}}}}\right)=O\left(\sqrt{\frac{n\log{n}}{2^{i-1}\log\log{n}}}\right).
\end{equation}
Hence, we can properly color each $P_{i}$ using $\chi(\mathcal{H}_{i})$ new colors for
$1\leq i\leq k$. The total number of colors to properly color $\bigcup_{i=1}^{k}P_{i}$ is at most
\begin{equation}
\sum_{i=1}^{k}O\left(\sqrt{\frac{n\log{n}}{2^{i-1}\log\log{n}}}\right)\leq O\left(\sqrt{\frac{n\log{n}}{\log\log{n}}}\right)\sum_{i=1}^{\log\log{n}}\left(\frac{1}{\sqrt{2}}\right)^{i-1}=O\left(\sqrt{\frac{n\log{n}}{\log\log{n}}}\right).
\end{equation}

\smallskip
\textbf{Phase 2:}\\
Let $P'$ be the set of remaining uncolored points. It holds that
$\lvert{P'}\rvert=O\left(n/\log{n}\right)$. We will color $P'$ as
follows. First, select a largest general position subset $I_{1}$ of $P'$ and let
$P'_{1}=P\backslash{I_{1}}$. For $i>1$, as long as $P'_{i-1}\neq\emptyset$, we
select a largest general position subset $I_{i}$ of $P'_{i-1}$ and let
$P'_{i}=P'_{i-1}\backslash{I_{i}}$. Let $m$ be the stopping time of this
process, i.e., $P'_{m}=\emptyset$, equivalently, 
\begin{equation}
P'=\bigcup_{i=1}^{m}I_{i}.
\end{equation}
By assigning a new color to each $I_{i}$, we finish coloring $P'$ with $m$
colors. It remains to bound the value of $m$. Let $P'_{0}=P'$.
By~\eqref{pay} we have that, for each $i\in[m]$,
\begin{equation}
\lvert{I_{i}}\rvert=\Omega\left(\frac{\lvert{P'_{i-1}}\rvert}{s}\right)\geq\frac{\lvert{P'_{i-1}}\rvert}{D\sqrt{n}},
\end{equation}
for some constant $D>0$. Accordingly, for each $i\in[m]$,
\begin{equation}
\lvert{P'_{i}}\rvert\leq\lvert{P'}\rvert\left(1-\frac{1}{D\sqrt{n}}\right)^{i}.
\end{equation}
When $m=\lceil{D\sqrt{n}\log{n}}\rceil$, it holds that
$\lvert{P'_{m-1}}\rvert\leq2$. Then, we can choose $I_{m}$ to be $P'_{m-1}$ and
the process stops, namely, $m=O(\sqrt{n}\log{n})$. Overall, we have properly colored $P$ using 
\begin{equation}
O(\sqrt{n\log{n}/\log\log{n}})+O(\sqrt{n}\log{n})=O(\sqrt{n}\log{n})
\end{equation}
colors.
\end{proof}

Theorem~\ref{dog} guarantees that most of the points from $P$ can be properly colored with \\ $O(\sqrt{n\log{n}/\log\log{n}})$ colors. This suggests that extending the result to all points may be achievable with further refinements in the proof. 


