\subsection{Prompts of Third-Party Punishment Experiments}

\begin{promptbox}{Experimental Rules Description}
{
You are taking part in a multi-round game. In each round, you are matched with two new players. Player~1 decides how to divide \$30 between themselves and Player~2 (e.g., giving \$$x$ to Player~2 and keeping \$$30 - x$). If Player~1 allocates exactly \$15 to Player~2, it may indicate a fair distribution. Other allocations are not absolutely fair. As the judge, you can either accept Player~1's proposal—allowing the split and earning \$10 yourself—or punish Player~1 by paying \$$y$ to reduce Player~1's earnings to \$0. Player~2 keeps their share, and you earn \$$10 - y$.
}
\end{promptbox}

\begin{promptbox}{Round Indicator Prompt}
{
This is round \{\}.\\[-0.5mm]
\tikz{\draw[gray, densely dashed, line width=0.3pt] (0,0) -- (\linewidth,0);}\\[-0.5mm]
\textit{Explain: The round number should fill in the \{\}.}
}
\end{promptbox}

\begin{promptbox}{Scenario Description Prompt}
{
Player~1 gives \${$a$} to Player~2 and keeps \${$b$}. Punishing costs you \${$c$}.
\\[-0.5mm]
\tikz{\draw[gray, densely dashed, line width=0.3pt] (0,0) -- (\linewidth,0);}\\[-0.5mm]
\textit{Explain: $a$ is the amount given to Player~2, $b$ is the amount Player 1 keeps (i.e., \$$30 - a$), and $c$ is the cost for you to punish Player~1.}
}
\end{promptbox}

\begin{promptbox}{Emotion and Decision Input Format}
{
Rate your emotion before the choice (AA valence, AA arousal, range: –0.1 to 0.1; higher scores indicate more positive emotions for valence and stronger emotions for arousal). Then choose: 1 = punish, 0 = accept. After that, rate your emotion again (AC valence, AC arousal). Respond in the following format, for example: 

AA valence = 0.053, AA arousal = –0.027, choice = 1, AC valence = –0.014, AC arousal = 0.062.

Please keep all emotion scores to three decimal places and adhere to the specified format.
}
\end{promptbox}

