\section{Preliminaries}\label{section:preliminaries}
%
%

For a set $X$, we denote its powerset by $\powerset{X}$.
\LongVersion{%
  For a finite set $X$, we denote its size by $|X|$.
}%
For sets $X, Y$,
we denote a partial function $f$ from $X$ to $Y$ by $f \colon X \partfun Y$ and denote its domain by $\domain(f) \subseteq X$.
\LongVersion{For $x \in \setZ$ and $N \in \setN$, we let $x \bmod N \in \{0,1,\dots, N - 1\}$ be such that $x \bmod N + y N = x$ for some $y \in \setZ$.}

\LongVersion{
%
\subsection{Clocks, clock guards, and parameters}
%
}

%

We let $\Time$ be the domain of the time, which will be either non-negative reals $\setRnn$\LongVersion{ (continuous-time semantics)} or naturals $\setN$\LongVersion{ (discrete-time semantics)}.
Let $\Clock = \{ \clock_1, \dots, \clock_\ClockCard \}$ be a set of \emph{clocks}, \ie{} variables that evolve at the same rate.
A clock valuation is a function
$\clockval : \Clock \rightarrow \Time$.
We write $\ClocksZero$ for the clock valuation assigning $0$ to all clocks.
Given $d \in \Time$, $\clockval + d$ 
%
denotes the valuation \st{} $(\clockval + d)(\clock) = \clockval(\clock) + d$, for all $\clock \in \Clock$.
%
Given $\resets \subseteq \Clock$, we define the \emph{reset} of a valuation~$\clockval$, denoted by $\reset{\clockval}{\resets}$, as follows: $\reset{\clockval}{\resets}(\clock) = 0$ if $\clock \in \resets$, and $\reset{\clockval}{\resets}(\clock)=\clockval(\clock)$ otherwise.

We assume a set~$\Param = \{ \param_1, \dots, \param_\ParamCard \} $ of \emph{parameters}, \ie{} unknown constants.
%
A parameter \emph{valuation} $\pval$ is  a function
%
$\pval\colon \Param \rightarrow \setQnn$.%
%
\footnote{%
	\changed{We choose $\setQnn$ by consistency with most of the PTA literature, but also because, for classical PTAs, choosing~$\Rgeqzero$ leads to undecidability~\cite{Miller00}.}
}
%
We assume ${\compOp} \in \{<, \leq, =, \geq, >\}$.
A \emph{(clock) guard}~$\guard$ is a constraint over $\Clock \cup \Param$ defined by a conjunction of inequalities of the form $\clock \compOp \paramOrInt$ with $\paramOrInt \in \Param \cup \setN$.
%
For simplicity, we often use intervals instead of a conjunction of inequalities.
%
Given~$\guard$, we write~$\clockval\models\pval(\guard)$ if %
the expression obtained by replacing each~$\clock$ with~$\clockval(\clock)$ and each~$\param$ with~$\pval(\param)$ in~$\guard$ evaluates to true.
%
%
%
%
%
%
%
\changed{For a finite set $X = \{x_1, x_2, \dots, x_N\}$ of size $N \in \setN$, a \emph{linear term} $\lterm$ (\resp{} \emph{non-negative linear term} $\ltermNN$)
is of the form $\sum_{1 \leq i \leq N} \alpha_i x_i + d$, with
	$\alpha_i, d \in \setZ$ (\resp{} $\alpha_i, d \in \setN$).}
%
%
%
%
%
%
%
%
%
