\LongVersion{
%
\subsection{Parametric timed automata}
%
}

Parametric timed automata (PTAs)~\cite{AHV93} extend timed automata~\cite{AD94} with parameters within guards and invariants in place of integer constants.

%
\begin{definition}[PTA]%
 \label{definition:PTA}
 A \emph{parametric timed automaton (PTA)} $\A$ is an 8-tuple $\A = (\Actions, \Loc, \LocInit, %
 \Clock, \Param, \invariant, \Edges, \Label)$, where:
 \begin{itemize}
  \item $\Actions$ is a finite set of atomic propositions;
  \item $\Loc$ is a finite set of locations;
  \item $\LocInit \subseteq \Loc$ is the set of initial locations,
  %
  \item $\Clock$ is a finite set of clocks;
  \item $\Param$ is a finite set of parameters;
  \item $\invariant$ is the invariant, assigning to every $\loc\in \Loc$ a clock guard $\invariant(\loc)$;
  \item $\Edges$ is a finite set of edges  $\edge = (\loc, \guard, \resets, \loc')$,
		where~$\loc, \loc' \in \Loc$ are the source and target locations, $\resets\subseteq \Clock$ is a set of clocks to be reset, and $\guard$ is the transition guard;
  \item $\Label\colon \Loc \to \powerset{\Actions}$ is the labeling function \changed{assigning the atomic propositions satisfied at each location}.
 \end{itemize}
\end{definition}
%

%
Given a parameter valuation~$\pval$, 
we denote by $\valuate{\A}{\pval}$ the non-parametric structure where all occurrences of a parameter~$\param_i$ have been replaced by~$\pval(\param_i)$.
We refer as a \emph{timed automaton (TA)} to any structure $\valuate{\A}{\pval}$, by assuming a rescaling of the constants: by multiplying all constants in $\valuate{\A}{\pval}$ by the least common multiple of their denominators, we obtain an equivalent (integer-valued) TA%
, as defined in~\cite{AD94}.

%
\begin{example}
	The PTA in \cref{figure:system_running_example} contains 1~clock $\styleclock{\clock}$ and one parameter~$\styleparam{\param_1}$.
	The invariant of $\loc_0$ is ``$\styleclock{\clock} \leq \styleparam{\param_1}$'' and the transition to~$\loc_1$ is guarded by ``$\changed{\styleparam{\param_1} - 1 < }\styleclock{\clock} < \styleparam{\param_1}$'', and resets~$\styleclock{\clock}$.
	Atomic propositions $\styleact{H}$ and $\styleact{L}$ are associated with $\loc_0$ and~$\loc_1$, respectively.
 This PTA models a clock generator with drift: the digital signal switches between high ($\styleact{H}$) and low ($\styleact{L}$) states in a near periodic manner but with some timing deviation, depending on the value of parameter $\styleparam{\param_1}$.
\end{example}
%

%
