Here, we introduce \emph{hyper parametric timed computation tree logic (\HyperPTCTL{})}.
\HyperPTCTL{} is a generalization of PTCTL~\cite{BDR08} with quantifiers over paths to represent hyperproperties.

%
\subsection{Syntax of \ExtOrNotHyperPTCTL{}}
%

%
\begin{definition}
 [Syntax of \HyperPTCTL{}]%
 \label{definition:syntax_hyperptctl}
 For atomic propositions $\Actions$ and parameters $\Param$,
 the syntax of \HyperPTCTL{} formulas of the temporal level~$\fml$ and the top level~$\fullFml$ are defined as follows, where
 $\action \in \Actions$,
 \changed{$\PathVar$ is the set of path variables,}
 $\vrun, \vrun_1, \vrun_2, \dots, \vrun_n \in \PathVar$,
 $\paramOrInt \in \Param \cup \setN$,
 $\param \in \Param$,
 ${\compOp} \in \{<, \leq, =, \geq, >\}$, and 
 $\ltermNN$ is a \changed{non-negative} linear term over $\Param$: %
{%
\begin{align*}
 \fml \Coloneq & \top \mid \action_{\vrun} \mid \neg \fml \mid \fml \lor \fml \mid \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml}{\fml}
 \\
 & \mid \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml}{\fml}\\
 \fullFml \Coloneq & \fml \mid \param \compOp \ltermNN \mid \neg \fullFml \mid \fullFml \lor \fullFml \mid \PExists \param\, \fullFml
 \end{align*}
}
\end{definition}
%

%
As syntax sugar, we utilize the following formulas:
{\ShortVersion{\small}\LongVersion{\scriptsize}
\begin{gather*}
 \bot \equiv \neg \top \quad \fml_1 \land \fml_2 \equiv \neg (\neg \fml_1 \lor \neg \fml_2) \quad \fml_1 \implies \fml_2 \equiv \neg\fml_1 \lor \fml_2\\
 \fml_1 = \fml_2 \equiv (\fml_1 \land \fml_2) \lor ((\neg \fml_1) \land (\neg \fml_2)) \quad
 \fml_1 \neq \fml_2 \equiv \neg (\fml_1 = \fml_2) \\
 \HEReleaseFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2} \equiv \neg \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\neg \fml_1}{\neg \fml_2} \\
 \HAReleaseFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2} \equiv \neg \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\neg \fml_1}{\neg \fml_2} \\
 \LongVersion{\HEWeakUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2} \equiv \HEReleaseFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_2}{(\fml_1 \lor \fml_2)} \\}
 \LongVersion{\HAWeakUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2} \equiv \HAReleaseFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_2}{(\fml_1 \lor \fml_2)} \\}
 \HEDiaFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml} \equiv \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\top}{\fml} \\
 \HADiaFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml} \equiv \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\top}{\fml} \\
 \HEBoxFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml} \equiv \HEReleaseFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\bot}{\fml} \\
 \HABoxFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml} \equiv \HAReleaseFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\bot}{\fml}
\end{gather*}
}

\emph{\ExistsHyperPTCTL{}} is a subclass of \HyperPTCTL{} such that the (top-level) formulas are of the form $\PExists \param_1 \PExists \param_2 \dots \PExists \param_n\, \fullFml$, where $\fullFml$ has no quantifiers over parameters.
%
\emph{PTCTL}~\cite{BDR08} is a subclass of \HyperPTCTL{} with only one path variable~$\vrun$.\footnote{Although the original definition in~\cite{BDR08} does not use path variables, one can easily check that our definition coincides with the one in~\cite{BDR08}.}
%
\emph{\ExistsPTCTL{}}~\cite{BDR08} is defined analogously.

We extend \HyperPTCTL{} with counters and clocks to constrain the number of occurrences of atomic propositions and to compare the time difference between the occurrences of two atomic propositions, respectively.
Intuitively, for each atomic proposition $\action$ and path~$\vrun$,
$\LAST(\action_{\vrun})$ indicates the \changed{time elapsed since the last switching of~$\action$ from false to true} in~$\vrun$, and
$\COUNT(\action_{\vrun})$ indicates the total number of \changed{switches of~$\action$ from false to true} in~$\vrun$.
To ensure decidability, we only allow specific forms of constraints.
We denote the extended logic as \emph{\ExtHyperPTCTL{}}.

%
%
\begin{definition}
 [Syntax of \ExtHyperPTCTL{}]
 %
 We extend the syntax of \HyperPTCTL{} formulas of the temporal level as follows:
 $\action \in \Actions$,
 \changed{$\PathVar$ is the set of path variables,}
 $\vrun \in \PathVar$,
 ${\compOp} \in \{{<}, {\leq}, {=}, {\geq}, {>}\}$,
 $d,N \in \setN$,
 $\lterm$ is a linear term over $\Param$,
 $\CountActions = \{\COUNT(\action_{\vrun}) \mid \action \in \Actions, \vrun \in \PathVar\}$,
 %
 $\ltermCntNN$ is a \emph{non-negative} linear term over $\CountActions$ (\ie{} $\ltermCntNN = \sum_{\action \in \Actions, \vrun \in \PathVar} \alpha_{\action, \vrun} \COUNT(\action_{\vrun})$ for some $\alpha_{\action, \vrun} \in \setN$)\footnote{The restriction of $\ltermCntNN$ is to construct finite observers in \cref{ss:observers}. Our implementation accepts any linear term, which is encoded by variables in \imitator{}~\cite{Andre21}.}, and
 $\ltermCnt$ is a linear term over $\CountActions$ (\ie{} $\ltermCnt = \sum_{\action \in \Actions, \vrun \in \PathVar} \alpha_{\action, \vrun} \COUNT(\action_{\vrun})$ for some $\alpha_{\action, \vrun} \in \setZ$).
 \begin{align*}
  \fml \Coloneq & \top \mid \action_{\vrun} \mid \LAST(\action_{\vrun}) - \LAST(\action_{\vrun}) \compOp \lterm \\
  & \mid \ltermCntNN \compOp d \mid (\ltermCnt \bmod N) \compOp d \mid \cdots
 \end{align*}
\end{definition}
%

%

\changed{We call $\LAST(\action_{\vrun}) - \LAST(\action_{\vrun}) \compOp \lterm$, $\ltermCntNN \compOp d$, and $(\ltermCnt \bmod N) \compOp d$ as \LASTExpr{}, \COUNTNNExpr{}, and \COUNTModExpr{}, respectively.}
We let \emph{\ExtPTCTL{}} be the subclass of \ExtHyperPTCTL{} with only one path variable~$\vrun$.
