\subsection{Semantics of \ExtOrNotHyperPTCTL{}}
%

Before defining the semantics of \HyperPTCTL{}, we formalize the assignments of paths.
In addition to the partial function assigning the paths,
we use a total preorder to fix the order of the discrete transitions at the same time-point.

%
\begin{definition}
 [Path assignments]%
 \label{definition:path_assignment}
 %
 For path variables $\PathVar$ and a TA $\valuate{\A}{\pval}$,
 a \emph{path assignment} $(\runs, \pathOrder)$ is a pair of 
 a partial function $\runs \colon \PathVar \partfun \Traces(\valuate{\A}{\pval})$ from path variables $\PathVar$ to paths $\Traces(\valuate{\A}{\pval})$ of $\valuate{\A}{\pval}$
 and a total preorder $\pathOrder$ on $\domain(\runs) \times \setN$ such that
 for any $\vrun, \vrun' \in \domain(\runs)$ and $i, j \in \setN$,
 $i < j$ implies $(\vrun, i) \pathOrder (\vrun, j)$ and $(\vrun, j) \npathOrder (\vrun, i)$,
 $(\vrun, i) \pathOrder (\vrun', j)$ implies $\sum_{k = 0}^{i} d^{\vrun}_k \leq \sum_{k = 0}^{j} d^{\vrun'}_k$, and
 $\sum_{k = 0}^{i} d^{\vrun}_k < \sum_{k = 0}^{j} d^{\vrun'}_k$ implies $(\vrun, i) \pathOrder (\vrun', j)$,
 where $d^{\vrun}_k$ and $d^{\vrun'}_k$ are the $k$-th delay in $\runs(\vrun)$ and $\runs(\vrun')$, respectively.
\end{definition}
%

 We let $(\emptyruns, \pathOrder[\emptyruns])$ be the empty path assignment,
 \ie{} the path assignment satisfying $\domain(\emptyruns) = \emptyset$.
 %
 For path assignments $(\runs, \pathOrder)$ and $(\runs', \pathOrder[\runs'])$, 
 $(\runs', \pathOrder[\runs'])$ is an \emph{extension} of $(\runs, \pathOrder)$ if we have 
 $\domain(\runs) \subseteq \domain(\runs')$ and
 for any $\vrun, \vrun' \in \domain(\runs)$ and $i,j \in \setN$, we have
 $(\vrun, i) \pathOrder (\vrun', j) \iff (\vrun, i) \pathOrder[\runs'] (\vrun', j)$ and
 $\runs(\vrun) = \runs'(\vrun)$.
 %
 %
 %
 %
 %
 %
 %
 For path assignments~$(\runs, \pathOrder)$ and $(\runs', \pathOrder[\runs'])$, we let $(\runs, \pathOrder) \suffixEqOp (\runs', \pathOrder[\runs'])$ (\resp{} $(\runs, \pathOrder) \suffixOp (\runs', \pathOrder[\runs'])$) if $\domain(\runs) = \domain(\runs')$ and there is $d \in \setRnn$ such that
 for any $\vrun \in \domain(\runs)$, we have $\runs(\vrun) \suffixEqOp \runs'(\vrun)$ (\resp{} $\runs(\vrun) \suffixOp \runs'(\vrun)$) and $\duration(\runs(\vrun) - \runs'(\vrun)) = d$, and
 for any $\vrun, \vrun' \in \domain(\runs)$ and $i, j \in \setN$,
 we have
 $(\vrun, i) \pathOrder[\runs'] (\vrun', j) \iff (\vrun, i + \removedEdges{\runs(\vrun)}{\runs'(\vrun)}) \pathOrder (\vrun', j + \removedEdges{\runs(\vrun')}{\runs'(\vrun')})$,
 and if $\removedEdges{\runs(\vrun)}{\runs'(\vrun)} \geq 1$ holds,
 $(\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)} - 1) \pathOrder (\vrun', \removedEdges{\runs(\vrun')}{\runs'(\vrun')})$ and
 $(\vrun', \removedEdges{\runs(\vrun')}{\runs'(\vrun')}) \npathOrder (\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)} - 1)$ also hold.
 We let $\duration(\runs - \runs') = d$ for such $\runs$, $\runs'$, and $d$.

%
\begin{definition}[Semantics of \HyperPTCTL{}]
 \label{definition:semantics_HyperPTCTL}
Let $\A$ be a PTA over parameters~$\Param_1$;
given a \HyperPTCTL{} formula over~parameters~$\Param_2$,
let $\Param = \Param_1 \cup \Param_2$.
For a parameter valuation $\pval \in \PVal$
a path assignment $(\runs, \pathOrder)$, and 
a concrete state $\state$ of $\valuate{\A}{\pval}$,
the satisfaction relation of the temporal level \HyperPTCTL{} formulas is defined as follows:
\begin{itemize}
  \item $(\runs, \pathOrder), \state \models_{\pval,\A} \action_{\vrun}$ if $\vrun \in \domain(\runs)$ and $\action \in \Label(\Init(\runs(\vrun)))$;
  \item $(\runs, \pathOrder), \state \models_{\pval,\A} \neg \fml$ if we have $(\runs, \pathOrder), \state \not\models_{\pval,\A} \fml$;
  \item $(\runs, \pathOrder), \state \models_{\pval,\A} \fml_1 \lor \fml_2$ if $(\runs, \pathOrder), \state \models_{\pval,\A} \fml_1$ or $(\runs, \pathOrder), \state \models_{\pval,\A} \fml_2$ holds;
  \item $(\runs, \pathOrder), \state \models_{\pval,\A} \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$ if for some extension $(\runs^{1}, \pathOrder[\runs^{1}])$ of $(\runs, \pathOrder)$ satisfying $\domain(\runs^{1}) = \domain(\runs) \disjointUnion \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and $\runs^{1}(\vrun_i) \in \Traces(\valuate{\A}{\pval}, \state)$ for each $i \in \{1,2,\dots,n\}$, there is $(\runs^{2}, \pathOrder[\runs^{2}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$, $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$, $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)) \models_{\pval,\A} \fml_2$, and for any $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)) \models_{\pval,\A} \fml_1$ holds.
  \item $(\runs, \pathOrder), \state \models_{\pval,\A} \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$ if for any extension $(\runs^{1}, \pathOrder[\runs^{1}])$ of $(\runs, \pathOrder)$ satisfying $\domain(\runs^{1}) = \domain(\runs) \disjointUnion \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and $\runs^{1}(\vrun_i) \in \Traces(\valuate{\A}{\pval}, \state)$ for each $i \in \{1,2,\dots,n\}$, there is $(\runs^{2}, \pathOrder[\runs^{2}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$, $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$, $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)) \models_{\pval,\A} \fml_2$, and for any $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)) \models_{\pval,\A} \fml_1$ holds.
%
%
  %
\end{itemize}
For a PTA $\A$, a parameter valuation $\pval \in \PVal$, and a temporal-level \HyperPTCTL{} formula $\fml$,
we write $\A \models_{\pval} \fml$ if
we have $(\emptyruns, \pathOrder[\emptyruns]), \sinit \models_{\pval, \A} \fml$, where $\sinit$ is an initial state of $\valuate{\A}{\pval}$.

For a PTA $\A$ and a parameter valuation $\pval \in \PVal$,
the satisfaction relation of the top-level \HyperPTCTL{} formulas is defined as follows:
\begin{itemize}
  \item $\A \models_{\pval} \param \compOp \ltermNN$ if we have $\valuate{\param}{\pval} \compOp \valuate{\ltermNN}{\pval}$,
\changed{where $\valuate{\ltermNN}{\pval}$ denotes the expression obtained by replacing each~$\param$ with~$\pval(\param)$ in~$\ltermNN$;} %
  \item $\A \models_{\pval} \neg \fullFml$ if we have $\A \not\models_{\pval} \fullFml$;
  \item $\A \models_{\pval} \fullFml_1 \lor \fullFml_2$ if we have $\A \models_{\pval} \fullFml_1$ or $\A \models_{\pval} \fullFml_2$;
  \item $\A \models_{\pval} \PExists \param\, \fullFml$ if there is $\pval' \in \PVal$ satisfying $\pval(\param') = \pval'(\param')$ for any $\param' \in \Param \setminus\{\param\}$ and $\A \models_{\pval'} \fullFml$.
\end{itemize}
\end{definition}
%

%

%
%
\begin{example}
 Consider the formula $\fml : \PExists \param_2 \big( \param_2 > \param_1 \land \HEUntilFml[= \param_2]{\vrun_1,\vrun_2}{(\styleact{L}_{\vrun_1} \implies \styleact{H}_{\vrun_2})}{(\styleact{H}_{\vrun_1} \land \styleact{H}_{\vrun_2})} \big)$.
 Fix $\pval(\parami{1}) = 1.8$.
 For the PTA $\A$ in \cref{figure:system_running_example}, we have
 $\A \models_{\pval} \fml$ with
 $\pval(\parami{2}) = 2.0$ and 
 $\runs^1(\vrun_1)$ and $\runs^1(\vrun_2)$ are as follows:
 in $\vrun_1$, we jump from $\loc_0$ to $\loc_1$ at 1.5 and jump from $\loc_1$ to \changed{$\loc_0$} at 2.0;
 in $\vrun_2$, we jump from $\loc_0$ to $\loc_1$ at 0.5 and jump from $\loc_1$ to \changed{$\loc_0$} at 1.0.
%
%
\end{example}
%

%

%
%
To define the semantics of \ExtHyperPTCTL{}, we introduce valuations of $\COUNT(\action_{\vrun})$ and $\LAST(\action_{\vrun})$.
A counter valuation is a function %
$\countval\colon \Actions \times \PathVar \to \setN$.
A recording valuation is a function %
$\recordval\colon \Actions \times \PathVar \to \setRnn$.
We write $\CountZero$ and $\RecordZero$ for the counter and recording valuations assigning $0$ to all $(\action, \vrun) \in \Actions \times \PathVar$, respectively.
%
%
For a linear term $\ltermCnt$ over $\{\COUNT(\action_{\vrun}) \mid \action \in \Actions, \vrun \in \PathVar\}$,
we let $\countval(\ltermCnt)$ be the inequality obtained by replacing $\COUNT(\action_{\vrun})$ with $\countval(\action, \vrun)$ and 
$\Vars(\ltermCnt) = \{\vrun \in \PathVar \mid \exists \action \in \Actions, \alpha_{\action, \vrun} \neq 0]\}$, with
$\ltermCnt = \sum_{\action \in \Actions, \vrun \in \PathVar} \alpha_{\action, \vrun} \COUNT(\action_{\vrun})$.

%
%
For paths $\trace, \trace'$ satisfying $\trace \suffixEqOp \trace'$, we let $\RISING(\action, \trace - \trace')$ be the set of positions $\state$ in $\trace$ satisfying $\Init(\trace) < \state \leq \Init(\trace')$, $\action \in \Label(\state)$, and there is $\delta \in \Time$ such that for any $\state' < \state$, $\duration(\state) - \duration(\state') < \delta$ implies $\action \not\in \Label(\state)$.
Notice that $\RISING(\action, \trace - \trace')$ is finite because $\duration(\trace - \trace')$ is finite and we have no Zeno behavior.
For a counter valuation $\countval$ and path assignments $\runs, \runs'$ satisfying $\runs \suffixEqOp \runs'$,
$\UpdateCountval{\countval}{\runs}{\runs'}$ is the counter valuation such that for any $(\action, \vrun) \in \Actions \times \PathVar$,
$\UpdateCountval{\countval}{\runs}{\runs'}(\action, \vrun) = \countval(\action, \vrun) + |\RISING(\action, \runs(\vrun) - \runs'(\vrun))|$
if $\vrun \in \domain(\runs)$
and
$\UpdateCountval{\countval}{\runs}{\runs'}(\action, \vrun) = \countval(\action, \vrun)$ otherwise.
For a recording valuation $\recordval$ and path assignments $\runs, \runs'$ satisfying $\runs \suffixEqOp \runs'$,
$\UpdateRecordval{\recordval}{\runs}{\runs'}$ is the recording valuation such that for any $(\action, \vrun) \in \Actions \times \PathVar$,
$\UpdateRecordval{\recordval}{\runs}{\runs'}(\action, \vrun) = \duration(\runs - \runs')$
if $\vrun \not\in \domain(\runs)$ or $\RISING(\action, \runs(\vrun) - \runs'(\vrun)) = \emptyset$
and otherwise,
$\UpdateRecordval{\recordval}{\runs}{\runs'}(\action, \vrun)$ is the duration of $\Init(\runs'(\vrun))$ in the suffix of $\runs(\vrun)$ starting from the last position in $\RISING(\action, \runs(\vrun) - \runs'(\vrun))$.
%

%
\begin{definition}[Semantics of \ExtHyperPTCTL{}]%
 \label{definition:semantics_ext_hyperptctl}
Let $\A$ be a PTA over parameters~$\Param_1$;
given an \ExtHyperPTCTL{} formula over~parameters~$\Param_2$,
let $\Param = \Param_1 \cup \Param_2$.
For a parameter valuation $\pval \in \PVal$,
a path assignment $(\runs, \pathOrder)$,
%
 a concrete state $\state$ of $\valuate{\A}{\pval}$, and
 counter and recording valuations $\countval$ and $\recordval$,
the satisfaction relation of the temporal level \ExtHyperPTCTL{} formulas is defined as follows:
\begin{itemize}
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \action_{\vrun}$ if $\vrun \in \domain(\runs)$ and $\action \in \Label(\Init(\runs(\vrun)))$;
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \LAST(\action_{\vrun}) - \LAST(\action'_{\vrun'}) \compOp \lterm$ if we have $\vrun, \vrun' \in \domain(\runs)$ and $\recordval(\action, \vrun) - \recordval(\action', \vrun') \compOp \pval(\lterm)$;
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \ltermCntNN \compOp d$ if we have $\Vars(\ltermCntNN) \subseteq \domain(\runs)$ and $\countval(\ltermCntNN) \compOp d$;
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} (\ltermCnt \bmod N) \compOp d$ if we have $\Vars(\ltermCnt) \subseteq \domain(\runs)$ and $(\countval(\ltermCnt) \bmod N) \compOp d$;
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \neg \fml$ if we have $(\runs, \pathOrder), \state, \countval, \recordval \not\models_{\pval,\A} \fml$;
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \fml_1 \lor \fml_2$ if we have $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \fml_1$ or $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \fml_2$;
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$ if for some extension $(\runs^{1}, \pathOrder[\runs^{1}])$ of $(\runs, \pathOrder)$ satisfying $\domain(\runs^{1}) = \domain(\runs) \disjointUnion \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and $\runs^{1}(\vrun_i) \in \Traces(\valuate{\A}{\pval}, \state)$ for each $i \in \{1,2,\dots,n\}$, there is $(\runs^{2}, \pathOrder[\runs^{2}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$, $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$, $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)),\UpdateCountval{\countval}{\runs^{1}}{\runs^{2}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{2}} \models_{\pval,\A} \fml_2$, and for any $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, we have $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$.
  \item $(\runs, \pathOrder), \state, \countval, \recordval \models_{\pval,\A} \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$ if for any extension $(\runs^{1}, \pathOrder[\runs^{1}])$ of $(\runs, \pathOrder)$ satisfying $\domain(\runs^{1}) = \domain(\runs) \disjointUnion \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and $\runs^{1}(\vrun_i) \in \Traces(\valuate{\A}{\pval}, \state)$ for each $i \in \{1,2,\dots,n\}$, there is $(\runs^{2}, \pathOrder[\runs^{2}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$, $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$, $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)),\UpdateCountval{\countval}{\runs^{1}}{\runs^{2}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^2} \models_{\pval,\A} \fml_2$, and for any $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, we have $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$.
%
  %
  %
\end{itemize}
For a PTA $\A$, a parameter valuation $\pval \in \PVal$, and a temporal-level \HyperPTCTL{} formula $\fml$,
we write $\A \models_{\pval} \fml$ if
we have $(\emptyruns, \pathOrder[\emptyruns]), \sinit, \CountZero, \RecordZero \models_{\pval, \A} \fml$, where $\sinit$ is an initial state of $\valuate{\A}{\pval}$.
The satisfaction relation of the top-level \ExtHyperPTCTL{} formulas is the same as that of \HyperPTCTL{}.\@
\end{definition}
