\section{Reduction of Nest-Free \ExtHyperPTCTL{} synthesis to PTCTL synthesis}\label{section:reduction}
%
%

%
%
\subsection{Reduction of path variables via self-composition of PTAs}\label{section:self-composition}
%
%
%

We show that model checking and parameter synthesis of nest-free \ExtOrNotHyperPTCTL{} is reducible to ones of (Ext-)PTCTL by self-composition of PTAs.
For a PTA $\A = (\Actions, \Loc, \LocInit, \Clock, \Param, \invariant, \Edges, \Label)$ and $n \in \setNpos$, we let $\A^{n} = \underbrace{\A \composeOp \A \composeOp \dots \composeOp \A}_\text{$n$ times}$, and for each $i \in \{1,2,\dots,n\}$ and $\action \in \Actions$ (\resp{} $\clock \in \Clock$), we denote the corresponding atomic proposition in $\Actions^n$ (\resp{} clock in $\Clock^n$) of the $i$-th component as $\action^{i}$ (\resp{} $\clock^{i}$), where $\Actions^{n}$ and $\Clock^{n}$ are the sets of atomic propositions and clocks in $\A^n$.
%
We generalize the projection of paths to such $n$-compositions, \ie{} for a path $\trace$ of $\A^n$,
we let $\project{\trace}{i}$ be the projection of $\trace$ to the $i$-th component.

%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%

%
%
%
%
%
%
%
%
%
%
%
%

We define an auxiliary function $\reduce^n$ to ``compose'' the atomic propositions in \ExtOrNotHyperPTCTL{} formulas.

%
\begin{definition}
 [$\reduce^n$]
 For $n \in \setNpos$, the function $\reduce^n$ from nest-free temporal-level \ExtHyperPTCTL{} formulas with atomic propositions $\Actions$ to
 nest-free temporal-level \ExtPTCTL{} formulas with atomic propositions $\Actions^n$ is inductively defined as follows, with
 $\reduce^n(\sum_{\action \in \Actions, i \in \{1,2,\dots,n\}} \alpha_{\action, \vrun_i} \COUNT(\action_{\vrun_i})) = \sum_{\action^i \in \Actions^n} \alpha_{\action^i, \vrun} \COUNT(\action_{\vrun}^i)$:
 \begin{itemize}
  \item $\reduce^n(\top) = \top$
  \item $\reduce^n(\action_{\vrun_i}) = \action_{\vrun}^{i}$
  \item $\reduce^n(\LAST(\action_{\vrun_i}) - \LAST(\action_{\vrun_j}) \compOp \lterm) = \LAST(\action_{\vrun}^{i}) - \LAST(\action_{\vrun}^{j}) \compOp \lterm$
  \item $\reduce^n(\ltermCntNN \compOp d) = \reduce^n(\ltermCntNN) \compOp d$
  \item $\reduce^n((\ltermCnt \bmod N) \compOp d) = (\reduce^n(\ltermCnt) \bmod N) \compOp d$
  %
  %
  \item $\reduce^n(\neg \fml) = \neg \reduce^n(\fml)$
  \item $\reduce^n(\fml_1 \lor \fml_2) = \reduce^n(\fml_1) \lor \reduce^n(\fml_2)$
  \item $\reduce^n(\HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}) = \HEUntilFml[\compOp \paramOrInt]{\vrun}{\reduce^n(\fml_1)}{\reduce^n(\fml_2)}$
  \item $\reduce^n(\HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}) = \HAUntilFml[\compOp \paramOrInt]{\vrun}{\reduce^n(\fml_1)}{\reduce^n(\fml_2)}$
  %
  %
  %
  %
 \end{itemize}
We naturally extend $\reduce^n$ to top-level \NFExtHyperPTCTL{} formulas.
\end{definition}
%


%
\SetKwFunction{Fsynthesis}{synthesisExtPTCTL}
\SetKwFunction{Freduce}{reduceSynth}
\SetKwProg{Fn}{def}{\string:}{}
\begin{algorithm}[tbp]
 \caption{Outline of our reduction of \NFExtHyperPTCTL{} synthesis to nest-free \ExtPTCTL{} synthesis.}%
 \label{algorithm:reduction}
 \DontPrintSemicolon{}
 \ShortVersion{\small}
 \newcommand{\myCommentFont}[1]{\texttt{\small{#1}}}
 \SetCommentSty{myCommentFont}
 \KwIn{A PTA $\A$ and a \NFExtHyperPTCTL{} formula $\fullFml$}
 \KwOut{The set $\{\pval \in \PVal \mid \A \models_{\pval} \fullFml\}$}
 \Fn{\Freduce{$\A$, $\fullFml$}}{
 \Switch{$\fullFml$}{%
   \lCase{$\top$}{%
     \Return{$\PVal$}\label{algorithm:reduction:top}
   }
   \Case{$\action_{\vrun_i}$ \KwOr{} $\LAST(\action_{\vrun_i}) - \LAST(\action_{\vrun_j})$ \KwOr{} $\ltermCntNN \compOp d$ \KwOr{} $(\ltermCnt \bmod N) \compOp d$}{%
     \tcp{$\fullFml$ does not hold for empty path assignments}\label{algorithm:reduction:bottom}
     \Return{$\emptyset$}
   }
   \Case{$\neg \fullFml$}{%
     \Return{$(\setQnn)^{\Param} \setminus \Freduce(\A, \fullFml)$}\label{algorithm:reduction:negation}
   }
   \Case{$\fullFml_1 \lor \fullFml_2$}{%
     \Return{$\Freduce(\A, \fullFml_1) \cup \Freduce(\A, \fullFml_2)$}\label{algorithm:reduction:disjunction}
   }
   \Case{$\HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$ \KwOr{} $\HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$}{%
     \tcp{Use nest-free \ExtPTCTL{} synthesis}
     \Return{$\Fsynthesis(\A^n, \reduce^n(\fullFml))$}\label{algorithm:reduction:temporal}
   }
   \Case{$\param \compOp \ltermNN$}{%
     \Return{$\{\pval \in \PVal \mid \valuate{\param}{\pval} \compOp \valuate{\ltermNN}{\pval}\}$}\label{algorithm:reduction:parameter_constraint}
   }
   \Case{$\PExists \param\, \fullFml$}{%
     $\mathrm{pre} \gets \Freduce(\A, \fullFml)$\;
     \Return{$\{\pval \in \PVal \mid \exists \pval' \in \mathrm{pre}. \forall \param' \in \Param \setminus\{\param\}.\, \pval(\param') = \pval'(\param')\}$}\label{algorithm:reduction:parameter_quantifier}
   }
 }}
\end{algorithm}
%

\cref{algorithm:reduction} outlines our reduction of the synthesis problem.
The reduction of model checking is similar.
Our reduction is inductive on the structure of the \ExtHyperPTCTL{} formula~$\fullFml$.
Since the path assignment $(\runs, \pathOrder)$ is empty,
for atomic formulas, $\fullFml$ is satisfied (\cref{algorithm:reduction:top}) or violated (\cref{algorithm:reduction:bottom}) independent of $\A$ and $\pval$.
For Boolean cases,
we obtain the result from the result of the reduction of the immediate subformula(s) (\cref{algorithm:reduction:negation,algorithm:reduction:disjunction}).
For the temporal operators,
we use the result of the synthesis for the composed PTA $\A^n$ and the reduced formula $\reduce^n(\fullFml)$ (\cref{algorithm:reduction:temporal}).
For the remaining cases,
the result is independent of $\A$ (\cref{algorithm:reduction:parameter_constraint}) or
obtained by un-constraining the result for $\param$ (\cref{algorithm:reduction:parameter_quantifier}).

The correctness of \cref{algorithm:reduction} is immediate from the following theorem.

%
\newcommand{\correctnessReductionStatement}{%
 For a PTA $\A$, a temporal-level \NFExtHyperPTCTL{} formulas
 $\fml_{\exists} = \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$ and
 $\fml_{\forall} = \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\fml_1}{\fml_2}$, and
 a parameter valuation $\pval$,
 we have $\A \models_{\pval} \fml_{\exists}$ (\resp{} $\A \models_{\pval} \fml_{\forall}$) if and only if
 we have $\A^n \models_{\pval} \reduce^n(\fml_{\exists})$ (\resp{} $\A^n \models_{\pval} \reduce^n(\fml_{\forall})$).%
}
\begin{theorem}
 %
 \label{theorem:correctness_reduction}
 \correctnessReductionStatement{}
\end{theorem}
%

