\subsection{Observers for extended predicates}\label{ss:observers}
%

We show that the satisfaction of the additional predicates
$\LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$, 
$\ltermCntNN \compOp d$, and 
$(\ltermCnt \bmod N) \compOp d$ in \ExtPTCTL{}
are observable by a PTA, and thus, \ExtPTCTL{} model checking and synthesis are reducible to \PTCTL{} model checking and synthesis, respectively.
Since we consider \ExtPTCTL{} formulas, we assume $\PathVar = \{\vrun\}$ without loss of generality.

For \changed{\LASTExpr{}} $\LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$,
since the truth value of $\LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$ changes only when
the truth value of $\action^1_{\vrun}$ or $\action^2_{\vrun}$ changes from $\bot$ to $\top$,
we can construct an observer by ``re-evaluating'' $\LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$ when $\action^1$ or $\action^2$ changes from false to true.
Additionally, we use invariants so that the initial states depend on the parameter valuations.

For \changed{\COUNTNNExpr{}} $\ltermCntNN \compOp d$,
since $\COUNT(\action_{\vrun})$ is monotonically increasing,
we can abstract the precise value once its value is sufficiently large.
Therefore, we can encode the counted value by finite locations.

For \changed{\COUNTModExpr{}} $(\ltermCnt \bmod N) \compOp d$,
since the value of $\COUNT(\action_{\vrun})$ is cycling back at $N \in \setN$,
we can also encode the counted value modulo $N$ by finite locations.
%
Observers were studied in~\ShortVersion{\cite{ABBL03}}\LongVersion{\cite{ABBL03,Andre13ICECCS}}, and we define them as follows.

 %
 %

%
\begin{definition}%
 [\changed{observers for \LASTExpr{}}]%
 \label{definition:observer_last}
 %
 \newcommand{\isInitialized}{b}
 Let $\action^1, \action^2 \in \Actions$, ${\compOp} \in \{<, \leq, =, \geq, >\}$, and $\lterm$ be a linear term over $\Param$.
 The observer for $\fml = \LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$ is a PTA %
 $\observerof{\fml} = (\Loc, \Loc, \LocInit, \{\clock_{\action^{1}}, \clock_{\action^{2}}\}, \Param, \invariant, \Edges, \Label)$, where:
 $\Loc = \powerset{\{\action^1, \action^2, \fml\}} \times \{\top, \bot\}$,
 $\LocInit$ is $\LocInit = \{ (\props, \isInitialized) \in \Loc \mid \isInitialized = \bot \}$,
 $\invariant$ is such that
 $\invariant(\loc) = \top$ for any $\loc \not\in \LocInit$, and
 for $\loc = (\props, \bot) \in \LocInit$,
 $\invariant(\loc)$ is $0 \compOp \lterm$ if $\fml \in \props$ and otherwise,
 $\invariant(\loc)$ is $\neg (0 \compOp \lterm)$,
 $\Label$ is the identity function, and {%
 \newcommand{\norise}{\ensuremath{\bigl\{((\props, \isInitialized), \top, \emptyset,(\props', \top)) \mid \props' \subsetneq \props, \fml \in \props \cap \props' \text{ or } \fml \not\in \props \cup \props'\bigr\}}}%
 \newcommand{\riseActions}{\Actions_{\mathrm{rise}}}%
 \newcommand{\currentActions}{\{\action^{1}, \action^{2}\}}%
 \newcommand{\currentGuard}{(\clock_{\action^{1}} - \clock_{\action^{2}} \compOp \lterm)[\Clock_{\riseActions} \coloneq 0]}%
 \newcommand{\risetrue}{\ensuremath{\bigl\{((\props, \isInitialized), \currentGuard, \Clock_{\riseActions}, (\props' \cup \{\fml\}, \top)) \mid \props' \subseteq \currentActions, \riseActions = \props' \setminus \props, \riseActions \neq \emptyset\bigr\}}}%
 \newcommand{\risefalse}{\ensuremath{\bigl\{((\props, \isInitialized), \neg\currentGuard, \Clock_{\riseActions}, (\props', \top)) \mid \props' \subseteq \currentActions, \riseActions = \props' \setminus \props, \riseActions \neq \emptyset\bigr\}}}%
 $\Edges = \norise \cup \risetrue \cup \risefalse$, where
 $\Clock_{\riseActions} = \{\clock_{\action^{i}} \mid \action^{i} \in \riseActions\}$ and
 $\currentGuard$ is $-\clock_{\action^{2}} \compOp \lterm$ if $\Clock_{\riseActions} = \{\clock_{\action^1}\}$, $\clock_{\action^{1}} \compOp \lterm$ if $\Clock_{\riseActions} = \{\clock_{\action^2}\}$, and $0 \compOp \lterm$ if $\Clock_{\riseActions} = \{\clock_{\action^{1}}, \clock_{\action^{2}}\}$.
 }%
\end{definition}
%

%
\begin{definition}%
 [\changed{observers for \COUNTNNExpr{}}]%
 \label{definition:observer_count_nn}
 %
 Let $\ltermCntNN = \sum_{\action \in \Actions} \alpha_{\action, \vrun} \COUNT(\action_{\vrun})$ be a non-negative linear term, \ie{} $\alpha_{\action, \vrun} \in \setN$.
 The observer for $\fml = \ltermCntNN \compOp d$ is a PTA
 $\observerof{\fml} = (\powerset{\Actions \cup \{\fml\}}, \powerset{\Actions} \times {\{0,1,\dots, d, d+1\}}^{\Actions}, \LocInit, \emptyset, \emptyset, \invariant, \Edges, \Label)$, where:
 $\LocInit = \powerset{\Actions} \times {\{0\}}^{\Actions}$,
 $\invariant(\loc) = \top$ for any $\loc \in \Loc$, %
 $\Label$ is such that $\Label((\props, \approxcountval)) = \props \cup \{\fml\}$ if $\sum_{\action \in \Actions} \alpha_{\action, \vrun} \approxcountval(\action) \compOp d$ holds and
 $\Label((\props, \approxcountval)) = \props$ otherwise, and
 $\Edges = \{((\props, \approxcountval), \top, \emptyset, (\props', \approxcountval[\props' \setminus \props \pluseq 1])) \mid \props, \props' \subseteq \Actions, \approxcountval \in \{0,1,\dots, d, d+1\}^{\Actions}\}$, where $\approxcountval[\props' \setminus \props \pluseq 1]$ is such that $v[\props' \setminus \props \pluseq 1](\action) = v(\action)$ for $\action \not\in \props' \setminus \props$, $\approxcountval[\props' \setminus \props \pluseq 1](\action) = \approxcountval(\action) + 1$ if $\action \in \props' \setminus \props$ and $\approxcountval(\action) < d$, and $\approxcountval[\props' \setminus \props \pluseq 1](\action) = d + 1$, otherwise.
\end{definition}
%

\ShortVersion{\changed{We omit the definition of the observers for $\fml = (\ltermCnt \bmod N) \compOp d$ since it is similar to \cref{definition:observer_count_nn}. The main difference is to reset the ``counter'' $\approxcountval$ to 0 when the value becomes $N$.}}
%
\LongVersion{\begin{definition}%
 [\changed{observers for \COUNTModExpr{}}]%
 \label{definition:observer_count_mod}
 %
 Let $\ltermCnt = \sum_{\action \in \Actions} \alpha_{\action, \vrun} \COUNT(\action_{\vrun})$ be a linear term.
 The observer for $\fml = (\ltermCnt \bmod N) \compOp d$ is a PTA
 $\observerof{\fml} = (\powerset{\Actions \cup \{\fml\}}, \powerset{\Actions} \times \{0,1,\dots, N -1\}^{\Actions}, \LocInit, \emptyset, \emptyset, \invariant, \Edges, \Label)$, where:
 $\LocInit = \powerset{\Actions} \times \{0\}^{\Actions}$,
 $\invariant(\loc) = \top$ for any $\loc \in \Loc$,
 $\Label$ is such that $\Label((\props, \approxcountval)) = \props \cup \{\fml\}$ if $\sum_{\action \in \Actions} \alpha_{\action, \vrun} \approxcountval(\action) \bmod N \compOp d$ holds and
 $\Label((\props, \approxcountval)) = \props$ otherwise, and
 $\Edges = \{((\props, \approxcountval), \top, \emptyset, (\props', \approxcountval[\props' \setminus \props \pluseq 1])) \mid \props, \props' \subseteq \Actions, \approxcountval \in \{0,1,\dots, N-1\}^{\Actions}\}$, where $\approxcountval[\props' \setminus \props \pluseq 1]$ is such that $\approxcountval[\props' \setminus \props \pluseq 1](\action) = \approxcountval(\action)$ for $\action \not\in \props' \setminus \props$, $\approxcountval[\props' \setminus \props \pluseq 1](\action) = \approxcountval(\action) + 1$ if $\action \in \props' \setminus \props$ and $\approxcountval(\action) < N - 1$, and $\approxcountval[\props' \setminus \props \pluseq 1](\action) = 0$, otherwise.
\end{definition}}
