\begin{lemma}
 [correctness of the observers]%
 \label{lemma:correctness_observers}
 For each $\action \in \Actions$, we let $\alpha_{\action} \in \setN$ and $\alpha'_{\action} \in \setZ$.
 Let $N \in \setN$, $\action^1, \action^2 \in \Actions$, ${\compOp} \in \{<, \leq, =, \geq, >\}$, $d \in \setN$, and $\lterm$ be a linear term over $\Param$.
 Let $\fml$ be one of the following:
 $\LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$,
 $\sum_{\action \in \Actions} \alpha_{\action} \COUNT(\action_{\vrun}) \compOp d$, or
 $(\sum_{\action \in \Actions} \alpha'_{\action} \COUNT(\action_{\vrun}) \bmod N) \compOp d$.
 %
 Let $\pval$ be a valuation over $\Param$, 
 $(\runs, \pathOrder)$ be a path assignment satisfying
 $\domain(\runs) = \{\vrun\}$ and
 $\runs(\vrun) \in \Traces(\valuate{\observerof{\fml}}{\pval})$.
 For any $(\runs', \pathOrder[\runs'])$ satisfying $(\runs, \pathOrder) \suffixEqOp (\runs', \pathOrder[\runs'])$,
 we have
 $\runs', \Init(\runs'(\vrun)), \UpdateCountval{\CountZero}{\runs}{\runs'}, \UpdateRecordval{\RecordZero}{\runs}{\runs'} \models_{\pval,\observerof{\fml}} \fml$ if and only if we have $\fml \in \Label(\Init(\runs'(\vrun)))$.
 \ShortVersion{\qed{}}
\end{lemma}
