%
\newcommand{\correctnessObserversStatement}{%
 For a PTA $\A$, a parameter valuation $\pval \in \PVal$, and a top-level \ExtPTCTL{} formula $\fullFml$,
 we have $\A \models_{\pval} \fullFml$ if and only if $\A \productOp \observerof{\fullFml} \models_{\pval} \rmextfrom{\fullFml}$.%
}
\begin{theorem}
 [correctness of the reduction with $\observerof{\fullFml}$]%
 \label{theorem:correctness_observers}
 \correctnessObserversStatement{}
\end{theorem}
%

%
\begin{proof}
 [Proof (sketch)]
 \changed{Since the other cases are similar,
 we only outline the proof of} $\A \models_{\pval} \fml_{\exists} \implies \A \productOp \observerof{\fullFml} \models_{\pval} \rmextfrom{\fml_{\exists}}$, where
 $\fml_{\exists} = \HEUntilFml[\compOp \paramOrInt]{\vrun}{\fml_1}{\fml_2}$.
 \changed{Moreover, since we have $\PathVar = \{\vrun\}$, we discuss it based on paths rather than path assignments for simplicity.} \LongVersion{See \cref{section:proof:correctness_observers} for a full and more formal proof.}
 Suppose $\A \models_{\pval} \fml_{\exists}$ holds.
 By the semantics of ExtPTCTL, 
 \changed{there is a path $\trace_1$ of $\valuate{\A}{\pval}$ and a suffix $\trace_2$ of $\trace_1$ such that 
 $\duration(\trace_1 - \trace_2) \compOp \valuate{\paramOrInt}{\pval}$, 
 $\fml_2$ holds at $\trace_2$, and
 $\fml_1$ holds at any position between $\trace_1$ and $\trace_2$.
 }
 Since the observer $\observerof{\fullFml}$ is complete, there is a path \changed{$\trace'_{1}$} of \changed{$\valuate{\A \productOp \observerof{\fullFml}}{\pval}$} satisfying
 \changed{$\project{\trace_{1}}{\valuate{\A}{\pval}} = \trace'_1$}.
 Moreover, by taking a suitable suffix of \changed{$\trace'_{1}$}, 
 there is a path \changed{$\trace'_{2}$} of \changed{$\valuate{\A \productOp \observerof{\fullFml}}{\pval}$} satisfying
 \changed{$\project{\trace'_{2}}{\valuate{\A}{\pval}} = \trace_{2}$}.
 \changed{By \cref{lemma:correctness_observers}, $\rmextfrom{\fml_2}$ holds at $\trace'_{2}$.}
 \changed{For any position between $\trace'_1$ and $\trace'_2$, since there is a corresponding position between $\trace_1$ and $\trace_2$,
 $\rmextfrom{\fml_1}$ holds at that position.}
%
 Therefore, we have $\A \productOp \observerof{\fullFml} \models_{\pval} \rmextfrom{\fml_{\exists}}$.
\end{proof}
