\section{Decidable subclasses\LongVersion{ for model checking and synthesis}}\label{section:decidability}
%
%

The model checking problem (and the synthesis counterpart) against general PTAs is trivially undecidable,
even for the nest-free existential fragment.

%
\begin{proposition}
	Model checking PTAs against a \NFExistsHyperPTCTL{} formula is undecidable.
\end{proposition}
%
\begin{proof}
	The \NFExistsHyperPTCTL{} formula ``$\HEDiaFml[\geq 0]{\vrun}{\action}$'' is equivalent to the TCTL formula $\CTLEF{} \action$ denoting reachability.
	Reachability-emptiness is known to be undecidable for PTAs~\cite{AHV93}, which gives the result.
\end{proof}
%

This negative result leads us to exhibit subclasses of either the model or the formula for which decidability can be achieved,
which we do in the following.


%
\subsection{Non-parametric model against parametric formula}
%

%
%
%

%
%


%

%
We consider here non-parametric TAs against a restriction of \NFExtHyperPTCTL{} defined as follows:
\begin{ienumeration}
	\item parameters cannot be used in $\LAST$\LongVersion{, \ie{} their syntax is restricted to %
      $\LAST(\action_{\vrun}) - \LAST(\action_{\vrun}) \compOp n$},
      and
%
	\item parameters are integer-valued.
\end{ienumeration}%
\LongVersion{%
	(See formal definition in \cref{definition:class-BDR08} in \cref{appendix:NFExtHyperPTCTLBDR}.)
}%
Put it differently, parameters cannot be used in the extended syntax (the constructs that are turned into observers during our transformation in \cref{ss:observers}); we insist that parameters can be used anywhere else in the formula.
Let \NFExtHyperPTCTLBDR{} denote this class (with ``RP'' denoting a restricted use of parameters).
%
For instance, the opacity in \cref{example:opacity} is in this class.
%


%
\begin{theorem}[complexity of the model checking problem]\label{theorem:MC:BDR08}
	Model checking timed automata against a \NFExtHyperPTCTLBDR{} formula is in \NEXPTIME{6}.
\end{theorem}
%
\begin{proof}
    \changed{We reduce to model checking a non-parametric TA against PTCTL~\cite{BDR08}.}
	Recall that our general construction (\cref{section:reduction}) reduces model checking a PTA against a \NFExtHyperPTCTL{} formula to model checking a network of PTAs and a set of observers against a PTCTL formula.
	Since the observers are created for the extended syntax, and since they do not contain parameters in \NFExtHyperPTCTLBDR{}, the synchronized product of the multiple TAs\LongVersion{ (by self-composition)} and the observers does not contain parameters.

	Now, model checking a non-parametric TA against PTCTL can be done in \NEXPTIME{5} in the synchronized product of the size\footnote{%
		As in~\cite{BDR08}, by size of a formula~$\fullFml$, we mean the number of symbols used to write it, and we denote it by~$|\fullFml|$.
	} of~$\A$ and~$\fullFml$ from~\cite[Theorem~7.5]{BDR08}.
%
	Therefore, since $|\A^n| \leq |\A|^{|\fullFml|}$
	and due to the fact that the observers are in constant size, and come in number at most linear in~$|\fullFml|$\LongVersion{ (the size of the formula)},
%
	model checking a TA against a \NFExtHyperPTCTLBDR{} formula is in \NEXPTIME{6}.
	%

	%
	Observe that this is only an upper bound because
	\begin{oneenumeration}%
		\item we only provide a one-way reduction, and
		\item the complexity in~\cite[Theorem~7.5]{BDR08} only gives an upper bound anyway.
	\end{oneenumeration}%
\end{proof}
%


%
\begin{remark}
	Following the same reasoning, model checking a TA against a formula expressed in \LongVersion{a restriction of \NFExtHyperPTCTLBDR{} to the case where (top-level) formulas are of the form $\PExists \param_1 \PExists \param_2 \dots \PExists \param_n\, \fullFml$, where $\fullFml$ is a \NFExtHyperPTCTLBDR{} formula with no quantifiers over parameters (which could be called ``}\NFExistsExtHyperPTCTLBDR{}\LongVersion{''),}
	is in \NEXPTIME{4}, reusing the fact that model checking a non-parametric TA against \ExistsPTCTL{} can be done in \NEXPTIME{3}~\cite[Proposition~7.6]{BDR08}.
\end{remark}
%


%
\LongVersion{%
%
\begin{remark}\label{remark:BDR08:discrete}
	Over discrete time ($\Time = \setN$), model checking TAs against a \NFExtHyperPTCTLBDR{} formula (resp.\ \NFExistsExtHyperPTCTLBDR{}) remains in \NEXPTIME{6} (resp.\ \NEXPTIME{4}), following \cite[Corollary~7.3]{BDR08} (resp.\ \cite[Proposition~7.4]{BDR08}).
\end{remark}
%
}

%

%

%
\begin{theorem}[effective parameter synthesis]\label{theorem:NFExtHyperPTCTL:synthesis}
	The solution to the parameter synthesis problem for TAs against a \NFExtHyperPTCTL{} formula can be effectively computed.
\end{theorem}
%
%
\begin{proof}
    \changed{As in the proof of \cref{theorem:MC:BDR08}, we reduce to model checking a non-parametric TA against PTCTL~\cite{BDR08}.}
 %
  %
%
\LongVersion{%
   The solution of the synthesis problem can be effectively computed using the first-order arithmetic over the structure $\tuple{\setR, +, <, \setN, 0, 1}$ of the real numbers, where $\setN$ being the predicate ``is a natural number''.
	%
  This arithmetic has a decidable theory with complexity in \NEXPTIME{3} in the size of the sentence~\cite{Weispfenning99}.
  }%
  %
	From \LongVersion{\cite[Theorem~6.5]{BDR08}}\ShortVersion{\cite{BDR08}}, the solution of the parameter synthesis of a non-parametric TA against PTCTL can be effectively computed.
\end{proof}
