\subsection{L/U-PTAs against \NFExtHyperPTCTL{}}
%

%
\begin{definition}[L/U-PTA~\cite{HRSV02}]\label{def:LUPTA}
	An \emph{L/U-PTA} (lower-bound/upper-bound PTA) is a PTA where the set of parameters is partitioned into lower-bound parameters and upper-bound parameters,
	where each upper-bound (resp.\ lower-bound) parameter~$\parami{i}$ must be such that,
	for every guard or invariant constraint $\clock \compOp \parami{i}$, we have ${\compOp} \in \set{ \leq, < }$ (resp.\ ${\compOp} \in \set{ \geq, > }$).
\end{definition}
%

%
\begin{example}
	The PTA in \cref{figure:system_running_example} is an L/U-PTA with an upper-bound parameter $\parami{1}$.
	\LongVersion{(This is in fact even a U-PTA~\cite{BlT09}.)

	}%
	The \LongVersion{observer fragment }PTA in \cref{figure:system_running_example:observer_last} is not L/U.
\end{example}
%

Because the mere $\forall \Diamond$-emptiness (emptiness of the valuations set for which a \LongVersion{given }location is always eventually reachable) is undecidable for L/U-PTAs~\cite{JLR15}\LongVersion{ and so is the nested TCTL fragment~\cite{ALR18FORMATS}}, we restrict ourselves to the reachability fragment of \NFExtHyperPTCTL{}, \LongVersion{\ie{} }where temporal operators are only~$\CTLEF{}$\LongVersion{ (CTL for reachability)}.
Let \NFExistsExtReachHyperPTCTL{} denote this fragment.


%
%
%
%
%
%
%
%
%
%

%
\begin{theorem}[decidability of non-parametric \NFExistsExtReachHyperPTCTL{} for L/U-PTAs]\label{theorem:MC:LU}
	Model checking L/U-PTAs against a non-parametric \NFExistsExtReachHyperPTCTL{} formula is \PSPACE{}-complete.
	The synthesis is, however, intractable.
\end{theorem}
%
\begin{proof}
	\changed{We reduce to reachability for L/U-PTAs.}
	Our general construction (\cref{section:reduction}) reduces model checking a PTA against a \NFExtHyperPTCTL{} formula to model checking a network of (L/U-)PTAs and a set of non-parametric observers against a TCTL formula.
	Here, we consider the reachability fragment only, leading to a reachability property.
	Reachability-emptiness is \PSPACE{}-complete for L/U-PTAs~\cite{HRSV02}, and therefore model checking L/U-PTAs against a non-parametric \NFExistsExtReachHyperPTCTL{} formula is \PSPACE{}-complete (the hardness \LongVersion{argument }following immediately).

	The non-parametric \NFExistsExtReachHyperPTCTL{} formula ``$\HEDiaFml[]{\vrun}{\action}$'' is equivalent to the (T)CTL formula $\CTLEF{} \action$ denoting reachability.
	Reachability-synthesis is known to be intractable\footnote{%
      More precisely, it cannot be effectively computed: the result cannot be represented in general using a finite union of polyhedra.
	} for L/U-PTAs~\cite{JLR15}, and therefore the synthesis for L/U-PTAs against a non-parametric \NFExistsExtReachHyperPTCTL{} is intractable.
\end{proof}
%

By using as proof argument a result from~\cite{ALR18FORMATS} showing that nest-free TCTL emptiness is decidable for L/U-PTAs with integer-valued parameters and \emph{without invariants}, we can show\LongVersion{ the following result}:

%
\begin{theorem}[decidability of non-parametric \NFExtHyperPTCTL{} for L/U-PTAs]\label{theorem:MC:LUflat}
	Model checking L/U-PTAs with integer-valued parameters without invariants against a non-parametric \NFExtHyperPTCTL{} formula is \PSPACE{}-complete.
	The synthesis is however intractable.
\end{theorem}
\LongVersion{%
	%
	\begin{proof}
		In~\cite{ALR18FORMATS}, we showed that nest-free TCTL emptiness is \PSPACE{}-complete for L/U-PTAs with integer-valued parameters and \emph{without invariants}.
		Again, our general construction reduces model checking a PTA against a \NFExtHyperPTCTL{} formula to model checking a network of (L/U-)PTAs and a set of non-parametric observers against a TCTL formula, which is by definition nest-free.
		Therefore, model checking L/U-PTAs without invariants against a non-parametric \NFExtHyperPTCTL{} formula is \PSPACE{}-complete.

		The intractability of the synthesis comes from \cite[Remark~2]{ALR18FORMATS}.
	\end{proof}
  %
}

