\subsection{$(1, \arbitrarilyMany, 1)$-PTAs against non-parametric formula}\label{ss:1-arbitrarilyMany-1}
%

%

We use here a common notation $(n, \arbitrarilyMany, m)$ to denote $n$ parametric clocks,
arbitrarily many non-parametric clocks and $m$ parameters.
%
%
%
%
%
%
%
%
%
%
%
We finally show decidability in a restrictive setting, by reduction to the decidable setting of~\LongVersion{\cite{BO17,GH21}}\ShortVersion{\cite{GH21}}.

%
\begin{theorem}[Decidability \LongVersion{over discrete time with 1~clock}\ShortVersion{with 1 discrete clock}]\label{theorem:BO:BDR08}
	Model checking a $(1, \arbitrarilyMany, 1)$-PTA is decidable over discrete time against a non-parametric \NFExistsExtReachHyperPTCTL{} with (at most) two path quantifiers for each temporal level formula.
%
%
\end{theorem}
%
\begin{proof}
  %
	\changed{We reduce to reachability for $(2, \arbitrarilyMany{}, 1)$-PTAs.}
    Model checking non-parametric \NFExistsExtReachHyperPTCTL{} reduces to model checking a network of PTAs (including the observers necessary to encode the extended syntax of the formula) against a reachability property.
    Further, the model contains a single parametric clock, and the formula contains 2 paths quantifiers for each temporal level formula, leading the self-composed model to contain 2 parametric clocks.
    Since the (unique) parameter is shared between both\LongVersion{ composed} copies, then the resulting composition is a $(2, \arbitrarilyMany{}, 1)$-PTA.
    Reachability-emptiness is \EXPSPACE{}-complete for $(2, \arbitrarilyMany{}, 1)$-PTAs for $\Time = \setN$~\cite{GH21}.
\end{proof}
%

It remains open whether the \emph{synthesis} problem is tractable in this latter case.

%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%

This result is not tight in the number of clocks, in the sense that it remains open whether model checking a $(2, \arbitrarilyMany, 1)$-PTA against  \NFExistsExtReachHyperPTCTL{} with 2 path quantifiers per temporal level formula is decidable or not.
However, by allowing $\CTLE \CTLU$ instead of $\CTLEF$ in the formula, we can show undecidability.
The proof encodes a $(4, 0, 1)$-PTA (for which \CTLEF{}-emptiness is undecidable~\cite{BBLS15}) into two $(2, 0, 1)$-PTAs, the synchronization of which is enforced thanks to an $\CTLE \CTLU$-based \NFExistsHyperPTCTL{}.

%
\begin{theorem}[Undecidability over discrete time with 2~clocks]\label{theorem:BO:BDR08:undec:EU}
	Model checking a $(2, 0, 1)$-PTA is undecidable over discrete time against a non-parametric \NFExistsHyperPTCTL{} formula using only $\CTLE \CTLU$ and two path quantifiers.
\end{theorem}
%
%
	\begin{proof}[Proof (sketch)]
		We reduce from the reachability for $(3, 0, 1)$-PTAs~\cite{BBLS15}.
		Let $\A$ be a $(4, 0, 1)$-PTA with clocks $t, x, y, z$.
		Let us ``split'' it into two $(2, 0, 1)$-PTAs with the same structure (same locations and edges), such that the first (resp.\ second) PTA only contains clock constraints containing $t$ and~$x$ (resp.\ $y$ and~$z$).
		Add to each location of the first PTA a unique location label with the same name as the location, \ie{} $\Label(\loc_i) = \{ \loc_i \}$, and to the second a primed label \ie{} $\Label(\loc_i) = \{ \loc_i' \}$.
		Fix $\loc$ a target location.
		Then let $\A'$ be the PTA union of these two PTAs, \ie{} starting with an initial non-deterministic choice in 0-time, and then ``choosing'' between either components (we assume that $y$ and~$z$ are renamed into $t$ and~$x$).
		Reaching $\loc$ in $\A$ is equivalent to checking the following \NFExistsHyperPTCTL{} formula in~$\A'$:
		\ShortVersion{$\HEUntilFml{\vrun_1, \vrun_2}{\big(\bigwedge_i (\loc_i)_{\vrun_1} = (\loc_i')_{\vrun_2} \big)}{}{( \loc_{\vrun_1} \land \loc'_{\vrun_2} )}$.}
		\LongVersion{\[ \HEUntilFml{\vrun_1, \vrun_2}{\big(\bigwedge_i (\loc_i)_{\vrun_1} = (\loc_i')_{\vrun_2} \big)}{}{( \loc_{\vrun_1} \land \loc'_{\vrun_2} )} \]}
%

		Since \CTLEF{}-emptiness is undecidable for $(3, 0, 1)$-PTAs~\cite{BBLS15}\LongVersion{ (and therefore for $(4, 0, 1)$-PTAs)}, then model checking this formula against $\A'$ is undecidable.
		$\A'$ contains only two clocks, and the formula is made of a single $\CTLE \CTLU$, with only two path quantifiers.
	\end{proof}
