\LongVersion{
Before proving \cref{theorem:correctness_reduction},
we show a property on path assignments and lemmas between path assignments of the original TAs and the paths of self-composed TAs.
In the remaining part of this section,
we assume that any PTA does not have a self-loop with no guard or reset.
Note that removing such edges does not change the semantics.
For any edge $\edge$ of $\A^n$ and $i \in \{1,2,\dots,n\}$, we let $\project{\edge}{i}$ be the projection of $\edge$ to the $i$-th component.

%
\begin{proposition}
 \label{proposition:path_assignment_equal}
 Let $\A$ be a PTA, $\pval$ be a parameter valuation, and
 $(\runs, \pathOrder)$ be a path assignment of $\valuate{\A}{\pval}$ satisfying
 $\domain(\runs) = \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and
 $\runs(\vrun) \in \Traces(\valuate{\A}{\pval})$
 for any $\vrun \in \domain(\runs)$.
 For any $\vrun, \vrun' \in \domain(\runs)$ and $i, j \in \setN$,
 if we have $(\vrun, i) \pathOrder (\vrun', j)$ and $(\vrun', j) \pathOrder (\vrun, i)$,
 $\sum_{k = 0}^{i} d^{\vrun}_k = \sum_{k = 0}^{j} d^{\vrun'}_k$ holds, where
 $d^{\vrun}_k$ and $d^{\vrun}_k$ are the $k$-th delay in $\runs(\vrun)$ and $\runs(\vrun')$, respectively.
\end{proposition}
%
\begin{proof}
 It is
 immediate from the second requirement on $\pathOrder$ in \cref{definition:path_assignment}.
%
\end{proof}
%

%
\begin{lemma}%
 \label{lemma:composition_lemma}
 Let $\A$ be a PTA, $\pval$ be a parameter valuation, and $n \in \setNpos$.
 For any path assignment $(\runs, \pathOrder)$ of $\valuate{\A}{\pval}$ satisfying
 $\domain(\runs) = \{\vrun_1,\vrun_2,\dots,\vrun_n\}$, if
 for any $\vrun \in \domain(\runs)$, $\runs(\vrun) \in \Traces(\valuate{\A}{\pval})$ holds,
 there is a path $\trace \in \Traces(\valuate{\A^n}{\pval})$ of $\valuate{\A^n}{\pval}$
 satisfying the following conditions, where
 $\pathOrderToN$ is the monotone surjection  from $\domain(\runs) \times \setN$ to $\setN$.
 \begin{itemize}
  \item For any $\vrun_k \in \domain(\runs)$, $\runs(\vrun_k) = \project{\trace}{k}$ holds.
  \item For any $i \in \setN$, the inverse image $\pathOrderToN^{-1}(\{i\})$ satisfies
        $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\}) \iff \project{\edge_i}{k} = \edge^k_j$,
        where $\edge_i$ is the $i$-th edge of $\trace$ and $\edge^k_j$ is the $j$-th edge of $\runs(\vrun_{k})$.
 \end{itemize}
\end{lemma}
%
\begin{proof}
 For the sake of simplicity, we show the case of $n = 2$.
 The proof of the general case is by induction on $n$.
 Let
 $\runs(\vrun_1) = (\loc^1_0, \clockval^1_0), (d^1_0, \edge^1_0), (\loc^1_1, \clockval^1_1), \ldots$ and
 $\runs(\vrun_2) = (\loc^2_0, \clockval^2_0), (d^2_0, \edge^2_0), (\loc^2_1, \clockval^2_1), \ldots$.
 By using the inverse image $\pathOrderToN^{-1}$,
 we inductively define $\trace = (\loc_0, \clockval_0), (d_0, \edge_0), (\loc_1, \clockval_1), \ldots$ as follows:
 \begin{itemize}
  \item $\loc_0 = (\loc^1_0, \loc^2_0)$ and $\clockval_0$ is such that $\clockval_0(\clock) = \clockval^1_0(\clock)$ if $\clock$ is a clock of the first component, and otherwise, $\clockval_0(\clock) = \clockval^2_0(\clock)$.
  \item $d_i = \sum_{l = 0}^{j} d^k_l - \sum_{l = 0}^{i-1} d_l$, where $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\})$.
  \item $\edge_i$ is such that:
        \begin{itemize}
         \item if $\pathOrderToN^{-1}(\{i\}) = \{(\vrun_1, j)\}$, $\edge_i = ( (\loc^1, \loc^2), \guard, \resets, ({\loc^1}', \loc^2))$, with $\loc_i = (\loc^1, \loc^2)$ and $\edge^1_j = (\loc^1, \guard, \resets, {\loc^1}')$;
         \item if $\pathOrderToN^{-1}(\{i\}) = \{(\vrun_2, j)\}$, $\edge_i = ( (\loc^1, \loc^2), \guard, \resets, ({\loc^1}, {\loc^2}'))$, with $\loc_i = (\loc^1, \loc^2)$ and $\edge^2_j = (\loc^2, \guard, \resets, {\loc^2}')$;
         \item if $\pathOrderToN^{-1}(\{i\}) = \{(\vrun_1, j), (\vrun_2, k)\}$, $\edge_i = ((\loc^1, \loc^2), \guard^1 \land \guard^2, \resets^1\cup\resets^2, ({\loc^1}', {\loc^2}'))$, with $\loc_i = (\loc^1, \loc^2)$, $\edge^1_j = (\loc^1, \guard^1, \resets^1, {\loc^1}')$, and $\edge^2_j = (\loc^2, \guard^2, \resets^2, {\loc^2}')$.
        \end{itemize}
  \item For $\edge_{i-1} = (\loc, \guard, \resets, \loc')$, $\loc_i = \loc'$ and $\clockval_i = \reset{\clockval_{i-1} + d_{i-1}}{\resets}$.
 \end{itemize}
 Notice that $d_i$ is irrelevant to the choice of $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\})$ by \cref{proposition:path_assignment_equal}.
 From the definition of the edges of $\valuate{\A^2}{\pval}$,
 such $\trace$ is a path of $\valuate{\A^2}{\pval}$.
 Moreover, we have $\project{\trace}{1} = \runs(\vrun_1)$ and $\project{\trace}{2} = \runs(\vrun_2)$, and $\pathOrderToN^{-1}(\{i\})$ is such that $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\})$ if and only if we have $\project{\edge_i}{k} = \edge^k_j$.
%
\end{proof}
%

%
\begin{lemma}%
 \label{lemma:decomposition_lemma}
 Let $\A$ be a PTA, $\pval$ be a parameter valuation, and $n \in \setNpos$.
 For any path $\trace \in \Traces(\valuate{\A^n}{\pval})$ of $\valuate{\A^n}{\pval}$,
 there is a path assignment $(\runs, \pathOrder)$ of $\valuate{\A}{\pval}$ 
 satisfying the following conditions, where
 $\pathOrderToN$ is the monotone surjection from $\domain(\runs) \times \setN$ to $\setN$.
 \begin{itemize}
  \item $\domain(\runs) = \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ holds.
  \item For any $\vrun_k \in \domain(\runs)$, $\runs(\vrun_k) = \project{\trace}{k}$ holds.
  \item For any $i \in \setN$, the inverse image $\pathOrderToN^{-1}(\{i\})$ satisfies
        $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\}) \iff \project{\edge_i}{k} = \edge^k_j$,
        where $\edge_i$ is the $i$-th edge of $\trace$ and $\edge^k_j$ is the $j$-th edge of $\runs(\vrun_{k})$.
 \end{itemize}
\end{lemma}
%
\begin{proof}
 For the sake of simplicity, we show the case of $n = 2$.
 The proof of the general case is by induction on $n$.
 Let $\trace = (\loc_0, \clockval_0), (d_0, \edge_0), (\loc_1, \clockval_1), \ldots$ and
 let $\runs$ be such that
 $\domain(\runs) = \{\vrun_1, \vrun_2\}$, and
 for each $k \in \{1,2\}$, $\runs(\vrun_k) = \project{\trace}{k}$.
 We let
 $\runs(\vrun_1) = (\loc^1_0, \clockval^1_0), (d^1_0, \edge^1_0), (\loc^1_1, \clockval^1_1), \ldots$ and
 $\runs(\vrun_2) = (\loc^2_0, \clockval^2_0), (d^2_0, \edge^2_0), (\loc^2_1, \clockval^2_1), \ldots$.
 By definition of $\A^2$ and because of $\runs(\vrun_1) = \project{\trace}{1}$ and $\runs(\vrun_2) = \project{\trace}{2}$,
 each $\edge_i$ in $\trace$ satisfies one of the following, where $\Edges$ is the set of edges in $\A$:
 \begin{itemize}
  \item $\edge_i = ( (\loc^1, \loc^2), \guard, \resets, ({\loc^1}', \loc^2))$, with $(\loc^1, \guard, \resets, {\loc^1}') = \edge^1_j \in \Edges$ for some $j \in \setN$;
  \item $\edge_i = ( (\loc^1, \loc^2), \guard, \resets, ({\loc^1}, {\loc^2}'))$, with $(\loc^2, \guard, \resets, {\loc^2}') = \edge^2_j \in \Edges$ for some $j \in \setN$;
  \item $\edge_i = ((\loc^1, \loc^2), \guard^1 \land \guard^2, \resets^1\cup\resets^2, ({\loc^1}', {\loc^2}'))$, with $(\loc^1, \guard^1, \resets^1, {\loc^1}') = \edge^1_j \in \Edges$ and $(\loc^2, \guard^2, \resets^2, {\loc^2}') = \edge^2_l \in \Edges$ for some $j,l \in \setN$.
 \end{itemize}
 We let $\pathOrderToN$ be such that
 $\pathOrderToN^{-1}(i) = \{(\vrun_1, j)\}$ for the first case,
 $\pathOrderToN^{-1}(i) = \{(\vrun_2, j)\}$ for the second case, and
 $\pathOrderToN^{-1}(i) = \{(\vrun_1, j), (\vrun_2, l)\}$ for the third case.
 Since for each $k \in \{1,2\}$, $\runs(\vrun_k) = \project{\trace}{k}$ holds,
 such $\pathOrderToN$ is a surjection from $\domain(\runs) \times \setN$ to $\setN$.
 We let $\pathOrder \subseteq (\domain(\runs) \times \setN) \times (\domain(\runs) \times \setN)$ be such that
 $(\vrun, i) \pathOrder (\vrun', j) \iff \pathOrderToN((\vrun, i)) \leq \pathOrderToN((\vrun', j))$.
 Notice that $\pathOrder$ is a total preorder and $\pathOrderToN$ is monotone.
 By definition of $\pathOrderToN$,
 for any $k, k' \in \{1,2\}$ and $i, j \in \setN$,
 $i < j$ implies $\pathOrderToN((\vrun_k, i)) < \pathOrderToN((\vrun_{k}, j))$,
 $\pathOrderToN((\vrun_k, i)) \leq \pathOrderToN((\vrun_{k'}, j))$ implies $\sum_{l = 0}^{i} d^{k}_l \leq \sum_{l = 0}^{j} d^{k'}_l$, and
 $\sum_{l = 0}^{i} d^{k}_l < \sum_{l = 0}^{j} d^{{k'}}_l$ implies $\pathOrderToN((\vrun_k, i)) \leq \pathOrderToN((\vrun_{k'}, j))$.
 By definition of $\pathOrder$,
 for any $k, k' \in \{1,2\}$ and $i, j \in \setN$,
 $i < j$ implies $(\vrun_k, i) \pathOrder (\vrun_k, j)$ and $(\vrun_k, j) \npathOrder (\vrun_k, i)$,
 $(\vrun_k, i) \pathOrder (\vrun_{k'}, j)$ implies $\sum_{l = 0}^{i} d^{k}_l \leq \sum_{l = 0}^{j} d^{k'}_l$, and
 $\sum_{l = 0}^{i} d^{k}_l < \sum_{l = 0}^{j} d^{{k'}}_l$ implies $(\vrun_k, i) \pathOrder (\vrun_{k'}, j)$.
 Overall, such $(\runs, \pathOrder)$ is a path assignment.
%
\end{proof}
%

%
\begin{lemma}%
 \label{lemma:suffix_lemma}
 Let $\A$ be a PTA, $\pval$ be a parameter valuation, and $n \in \setNpos$.
 Let $(\runs, \pathOrder)$ be a path assignment of $\valuate{\A}{\pval}$ satisfying
 $\domain(\runs) = \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and
 let $\trace \in \Traces(\valuate{\A^n}{\pval})$ be a path of $\valuate{\A^n}{\pval}$.
 Let $\edge_i$ be the $i$-th edge of $\trace$ and $\edge^k_j$ be the $j$-th edge of $\runs(\vrun_{k})$.
 If for any $\vrun_k \in \domain(\runs)$, we have $\runs(\vrun_k) = \project{\trace}{k}$ and
 for any $i \in \setN$, the inverse image $\pathOrderToN^{-1}(\{i\})$ satisfies $(\vrun, j) \in \pathOrderToN^{-1}(\{i\}) \iff \project{\edge_i}{k} = \edge^k_j$,
 we have the following.
 \begin{itemize}
  \item  For any $\trace'$ and $\trace''$ satisfying $\trace \suffixEqOp \trace'' \suffixOp \trace'$,
         there are $(\runs', \pathOrder[\runs'])$ and $(\runs'', \pathOrder[\runs''])$
         such that we have $(\runs, \pathOrder) \suffixEqOp (\runs'', \pathOrder'') \suffixOp (\runs', \pathOrder[\runs'])$ and
         for any $i \in \{1,2,\dots,n\}$,
         we have $\runs'(\vrun_i) = \project{\trace'}{i}$ and $\runs''(\vrun_i) = \project{\trace''}{i}$.
  \item  For any $(\runs', \pathOrder[\runs'])$ and $(\runs'', \pathOrder[\runs''])$
         satisfying $(\runs, \pathOrder) \suffixEqOp (\runs'', \pathOrder[\runs'']) \suffixOp (\runs', \pathOrder[\runs'])$,
         there are $\trace'$ and $\trace''$ such that 
         we have $\trace \suffixEqOp \trace'' \suffixOp \trace'$ and
         for any $i \in \{1,2,\dots,n\}$, we have
         $\runs'(\vrun_i) = \project{\trace'}{i}$ and
         $\runs''(\vrun_i) = \project{\trace''}{i}$.
 \end{itemize}
\end{lemma}
%
\begin{proof}
 For the sake of simplicity, we show the case of $n = 2$.
 The proof of the general case is by induction on $n$.
 Let $\trace = (\loc_0, \clockval_0), (d_0, \edge_0), (\loc_1, \clockval_1), \ldots$.

 For any
 $\trace' = (\loc_i, \clockval_i + d), (d_i - d, \edge_i), (\loc_{i+1}, \clockval_{i+1}), \ldots$ and
 $\trace'' = (\loc_{i'}, \clockval_{i'} + d'), (d_{i'} - d', \edge_{i'}), (\loc_{i'+1}, \clockval_{i'+1}), \ldots$
 satisfying $\trace \suffixEqOp \trace'' \suffixOp \trace'$,
 let $\runs'$, $\runs''$, $\pathOrder[\runs']$, and $\pathOrder[\runs'']$ be such that
 $\runs'(\vrun_1) = \project{\trace'}{1}$, $\runs'(\vrun_2) = \project{\trace'}{2}$,
 $\runs''(\vrun_1) = \project{\trace''}{1}$, $\runs''(\vrun_2) = \project{\trace''}{2}$, and
 for any $\vrun,\vrun' \in \domain(\runs)$ and $l, m \in \setN$, we have
 $(\vrun, l) \pathOrder[\runs''] (\vrun', m) \iff (\vrun, l + \removedEdges{\runs(\vrun)}{\runs''(\vrun)}) \pathOrder (\vrun'', m + \removedEdges{\runs(\vrun')}{\runs''(\vrun')})$ and
 $(\vrun, l) \pathOrder[\runs'] (\vrun', m) \iff (\vrun, l + \removedEdges{\runs''(\vrun)}{\runs'(\vrun)}) \pathOrder[\runs''] (\vrun', m + \removedEdges{\runs''(\vrun')}{\runs'(\vrun')})$.
 By the construction of $\trace'$, $\trace''$, $\runs'$, and $\runs''$, we have the following.
 \begin{itemize}
  \item $\duration(\runs - \runs'') = \duration(\trace - \trace'') (= d' + \sum_{j = 0}^{i' - 1} d_j)$.
  \item $\duration(\runs'' - \runs') = \duration(\trace'' - \trace') (= d + \sum_{j = 0}^{i - 1} d_j - \duration(\runs - \runs''))$.
  \item For any $k \in \{1, 2\}$, $\runs(\vrun_k) = \project{\trace}{k} \suffixEqOp \project{\trace''}{k} = \runs''(\vrun_k)$.
  \item For any $k \in \{1, 2\}$, $\runs''(\vrun_k) = \project{\trace''}{k} \suffixOp \project{\trace'}{k} = \runs'(\vrun_k)$.
  \item For any $\vrun \in \domain(\runs)$ and $j \in \setN$, $\removedEdges{\runs(\vrun)}{\runs'(\vrun)} \leq j \iff i \leq \pathOrderToN((\vrun, j))$.
  \item For any $\vrun \in \domain(\runs)$ and $j \in \setN$, $\removedEdges{\runs(\vrun)}{\runs''(\vrun)} \leq j \iff i' \leq \pathOrderToN((\vrun, j))$.
 \end{itemize}
 Particularly,
 we have $\pathOrderToN((\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)} - 1)) < i \leq \pathOrderToN((\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)}))$ and
 $\pathOrderToN((\vrun, \removedEdges{\runs(\vrun)}{\runs''(\vrun)} - 1)) < i' \leq \pathOrderToN((\vrun, \removedEdges{\runs(\vrun)}{\runs''(\vrun)}))$.
 Since $\pathOrderToN$ is monotone,
 for any $\vrun, \vrun' \in \domain(\runs)$, we have
 $(\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)} - 1) \pathOrder (\vrun', \removedEdges{\runs(\vrun')}{\runs'(\vrun')})$,
 $(\vrun', \removedEdges{\runs(\vrun')}{\runs'(\vrun')}) \npathOrder (\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)} - 1)$,
 $(\vrun, \removedEdges{\runs(\vrun)}{\runs''(\vrun)} - 1) \pathOrder (\vrun', \removedEdges{\runs(\vrun')}{\runs''(\vrun')})$, and
 $(\vrun', \removedEdges{\runs(\vrun')}{\runs''(\vrun')}) \npathOrder (\vrun, \removedEdges{\runs(\vrun)}{\runs''(\vrun)} - 1)$.
 Since $\removedEdges{\runs(\vrun')}{\runs'(\vrun')} = \removedEdges{\runs(\vrun')}{\runs''(\vrun')} + \removedEdges{\runs''(\vrun')}{\runs'(\vrun')}$,
 we have
 $(\vrun, \removedEdges{\runs''(\vrun)}{\runs'(\vrun)} - 1) \pathOrder[\runs''] (\vrun', \removedEdges{\runs''(\vrun')}{\runs'(\vrun')})$ and
 $(\vrun', \removedEdges{\runs''(\vrun')}{\runs'(\vrun')}) \npathOrder[\runs''] (\vrun, \removedEdges{\runs''(\vrun)}{\runs'(\vrun)} - 1)$.
 Overall, we have $(\runs, \pathOrder) \suffixEqOp (\runs'', \pathOrder[\runs'']) \suffixOp (\runs', \pathOrder[\runs'])$.

 For any $(\runs', \pathOrder[\runs'])$ and $(\runs'', \pathOrder[\runs''])$ satisfying $(\runs, \pathOrder) \suffixEqOp (\runs'', \pathOrder[\runs'']) \suffixOp (\runs', \pathOrder[\runs'])$,
 we let
 $\trace' = (\loc_i, \clockval_i + d), (d_i - d, \edge_i), (\loc_{i+1}, \clockval_{i+1}), \ldots$ and
 $\trace'' = (\loc_{i'}, \clockval_{i'} + d'), (d_{i'} - d', \edge_{i'}), (\loc_{i'+1}, \clockval_{i'+1}), \ldots$, where
 $i = \min_{\vrun \in \domain(\runs)} \pathOrderToN((\vrun, \removedEdges{\runs(\vrun)}{\runs'(\vrun)}))$,
 $d = \duration(\runs - \runs') - \sum_{j = 0}^{i-1} d_j$,
 $i' = \min_{\vrun \in \domain(\runs)} \pathOrderToN((\vrun, \removedEdges{\runs(\vrun)}{\runs''(\vrun)}))$, and
 $d' = \duration(\runs - \runs'') - \sum_{j = 0}^{i'-1} d_j$.
 Notice that we have $\trace \suffixEqOp \trace'' \suffixOp \trace'$.
 Since we have $\project{\trace}{1} = \runs(\vrun_1)$, $\project{\trace}{2} = \runs(\vrun_2)$,
 $\duration(\runs - \runs'') = \duration(\trace - \trace'')$, and
 for any $\vrun \in \domain(\runs)$, $j \in \setN$,
 $\removedEdges{\runs(\vrun)}{\runs''(\vrun)} \leq j \iff i' \leq \pathOrderToN((\vrun, j))$ holds,
 we have
 $\project{\trace''}{1} = \runs''(\vrun_1)$ and $\project{\trace''}{2} = \runs''(\vrun_2)$.
 Similarly,
 since we have $\project{\trace}{1} = \runs(\vrun_1)$, $\project{\trace}{2} = \runs(\vrun_2)$,
 $\duration(\runs - \runs') = \duration(\trace - \trace')$, and
 for any $\vrun \in \domain(\runs)$, $j \in \setN$,
 $\removedEdges{\runs(\vrun)}{\runs'(\vrun)} \leq j \iff i \leq \pathOrderToN((\vrun, j))$ holds,
 we have
 $\project{\trace'}{1} = \runs'(\vrun_1)$ and $\project{\trace'}{2} = \runs'(\vrun_2)$.
%
\end{proof}
