Proof of \cref{theorem:correctness_reduction} is as follows.

\recallResult{theorem:correctness_reduction}{\correctnessReductionStatement}

%
\begin{proof}
 [Proof of \cref{theorem:correctness_reduction}]
%
 Suppose $\A \models_{\pval} \fml_{\exists}$ holds.
 By the semantics of \ExtHyperPTCTL{},
 for some extension $(\runs^{1}, \pathOrder[\runs^{1}])$ of $(\emptyruns, \pathOrder[\emptyruns])$
 satisfying $\domain(\runs) = \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ and
 $\runs^{1}(\vrun_i) \in \Traces(\valuate{\A}{\pval})$ for each $i \in \{1,2,\dots,n\}$,
 there is $(\runs^{2}, \pathOrder[\runs^{2}])$ satisfying 
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$,
 $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$,
 $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)),\UpdateCountval{\countval}{\runs^{1}}{\runs^{2}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{2}} \models_{\pval,\A} \fml_2$, and
 for any $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$ holds.
 By \cref{lemma:composition_lemma,lemma:suffix_lemma},
 for any such $\runs^{1}$ and $\runs^{2}$,
 there are paths $\trace$ and $\trace'$ of $\valuate{\A^n}{\pval}$
 such that $\trace \suffixEqOp \trace'$ holds and
 for each $i \in \{1,2,\dots,n\}$, we have
 $\runs^{1}(\vrun_i) = \project{\trace}{i}$ and
 $\runs^{2}(\vrun_i) = \project{\trace'}{i}$.
 Let $\overline{\runs}^{1}$ and $\overline{\runs}^{2}$,
 be such that
 $\domain(\overline{\runs}^{1}) = \domain(\overline{\runs}^{2}) = \{\vrun\}$,
 $\overline{\runs}^{1}(\vrun) = \trace$, $\overline{\runs}^{2}(\vrun) = \trace'$, and
 ${\pathOrder[\overline{\runs}^{1}]} = {\pathOrder[\overline{\runs}^{2}]}$ are such that
 $(\vrun, i) \pathOrder[\overline{\runs}^{1}] (\vrun, j) \iff i \leq j$.
 For such $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}])$ and $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$,
 we have $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$,
 $\duration(\overline{\runs}^{1} - \overline{\runs}^{2}) \compOp \valuate{\paramOrInt}{\pval}$, and
%
 $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}]), \Init(\overline{\runs}^{2}(\vrun)),\UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{2}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{2}} \models_{\pval,\A} \reduce^n(\fml_2)$.
 Let $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$ be a path assignment satisfying $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]) \suffixOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$.
 By \cref{lemma:suffix_lemma},
 for any such $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$,
 there is a path assignment $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, and
 $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$ for each $i \in \{1,2,\dots,n\}$.
 Since we have $\A \models_{\pval} \fml_{\exists}$, for such $(\runs^{3}, \pathOrder[\runs^{3}])$,
 we have $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$.
 Since for each $i \in \{1,2,\dots,n\}$, we have $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$,
 for such $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$,
 we have $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]), \Init(\overline{\runs}^{3}(\vrun)), \UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{3}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{3}} \models_{\pval,\A} \reduce^n(\fml_1)$.
 Therefore, we have $\A^n \models_{\pval} \reduce^n(\fml_{\exists})$.

 Suppose $\A^n \models_{\pval} \reduce^n(\fml_{\exists})$ holds.
 By the semantics of \ExtHyperPTCTL{},
 for some extension $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}])$ of $(\emptyruns, \pathOrder[\emptyruns])$
 satisfying $\domain(\overline{\runs}) = \{\vrun\}$ and $\overline{\runs}^{1}(\vrun) \in \Traces(\valuate{\A^n}{\pval})$,
 there is $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$ satisfying 
 $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$,
 $\duration(\overline{\runs}^{1} - \overline{\runs}^{2}) \compOp \valuate{\paramOrInt}{\pval}$,
 $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}]), \Init(\overline{\runs}^{2}(\vrun)),\UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{2}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{2}} \models_{\pval,{\A}^{n}} \reduce^n(\fml_2)$, and
 for any $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$ satisfying $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]) \suffixOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$, $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]), \Init(\overline{\runs}^{3}(\vrun)), \UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{3}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{3}} \models_{\pval,{\A}^{n}} \reduce^n(\fml_1)$ holds.
 By \cref{lemma:decomposition_lemma,lemma:suffix_lemma},
 for any such $\overline{\runs}^{1}(\vrun)$ and $\overline{\runs}^{2}(\vrun)$,
 there are path assignments $(\runs^{1}, \pathOrder[\runs^{1}])$ and $(\runs^{2}, \pathOrder[\runs^{2}])$
 such that
 $\domain(\runs^{1}) = \domain(\runs^{2}) = \{\vrun_1, \vrun_2, \dots, \vrun_n\}$,
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$, and
 for each $i \in \{1,2,\dots,n\}$, we have
 $\runs^{1}(\vrun_i) = \project{\overline{\runs}^{1}(\vrun)}{i}$ and
 $\runs^{2}(\vrun_i) = \project{\overline{\runs}^{2}(\vrun)}{i}$.
 For such $(\runs^{1}, \pathOrder[\runs^{1}])$ and $(\runs^{2}, \pathOrder[\runs^{2}])$,
 we have $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$ and
%
 $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)),\UpdateCountval{\countval}{\runs^{1}}{\runs^{2}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{2}} \models_{\pval,\A} \fml_2$.
 Let $(\runs^{3}, \pathOrder[\runs^{3}])$ be a path assignment satisfying
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$.
 By \cref{lemma:suffix_lemma},
 for any such $(\runs^{3}, \pathOrder[\runs^{3}])$,
 there is a path assignment $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$ satisfying
 $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]) \suffixOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$, and
 $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$ for each $i \in \{1,2,\dots,n\}$.
 Since we have $\A^n \models_{\pval} \reduce^n(\fml_{\exists})$, for such $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$,
 we have $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]), \Init(\overline{\runs}^{3}(\vrun)), \UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{3}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{3}} \models_{\pval,\A} \reduce^n(\fml_1)$.
 Since for each $i \in \{1,2,\dots,n\}$, we have $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$,
 for such $(\runs^{3}, \pathOrder[\runs^{3}])$, 
 we have $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$.
 Therefore, we have $\A \models_{\pval} \fml_{\exists}$.

 Suppose $\A \models_{\pval} \fml_{\forall}$ holds.
 Let $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^1])$ be a path assignment satisfying
 $\domain(\overline{\runs}^{1}) = \{\vrun\}$ and
 $\overline{\runs}^{1}(\vrun) \in \Traces(\valuate{\A^n}{\pval})$.
 By \cref{lemma:decomposition_lemma},
 there is a path assignment $(\runs^{1}, \pathOrder[\runs^{1}])$ of $\valuate{\A}{\pval}$ 
 satisfying the following conditions, where
 $\pathOrderToN$ is the monotone surjection from $\domain(\runs^{1}) \times \setN$ to $\setN$.
 \begin{itemize}
  \item $\domain(\runs^{1}) = \{\vrun_1,\vrun_2,\dots,\vrun_n\}$ holds.
  \item For any $\vrun_k \in \domain(\runs^{1})$, $\runs^{1}(\vrun_k) = \project{\trace}{k}$ holds.
  \item For any $i \in \setN$, the inverse image $\pathOrderToN^{-1}(\{i\})$ satisfies
        $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\}) \iff \project{\edge_i}{k} = \edge^k_j$,
        where $\edge_i$ is the $i$-th edge of $\trace$ and $\edge^k_j$ is the $j$-th edge of $\runs^{1}(\vrun_{k})$.
 \end{itemize}
 Since we have $\A \models_{\pval} \fml_{\forall}$,
 for any such $(\runs^{1}, \pathOrder[\runs^{1}])$,
 there is $(\runs^{2}, \pathOrder[\runs^{2}])$ satisfying 
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$,
 $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$,
 $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)),\UpdateCountval{\countval}{\runs^{1}}{\runs^{2}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{2}} \models_{\pval,\A} \fml_2$, and
 for any $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$ holds.
 By \cref{lemma:suffix_lemma},
 for any such $\runs^{2}$,
 there is a path $\trace'$ of $\valuate{\A^n}{\pval}$
 such that for each $i \in \{1,2,\dots,n\}$, we have
 $\runs^{2}(\vrun_i) = \project{\trace'}{i}$.
 Let $\overline{\runs}^{2}$ be such that
 $\domain(\overline{\runs}^{2}) = \{\vrun\}$,
 $\overline{\runs}^{2}(\vrun) = \trace'$, and
 ${\pathOrder[\overline{\runs}^{2}]}$ is such that
 $(\vrun, i) \pathOrder[\overline{\runs}^{2}] (\vrun, j) \iff i \leq j$.
 Notice that we have ${\pathOrder[\overline{\runs}^{1}]} = {\pathOrder[\overline{\runs}^{2}]}$
 because of $\domain(\overline{\runs}^{1}) = \domain(\overline{\runs}^{2}) = \{\vrun\}$.
 For such $\overline{\runs}^{2}$,
 we have $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$,
 $\duration(\overline{\runs}^{1} - \overline{\runs}^{2}) \compOp \valuate{\paramOrInt}{\pval}$, and
 $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}]), \Init(\overline{\runs}^{2}(\vrun)),\UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{2}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{2}} \models_{\pval,\A} \reduce^n(\fml_2)$.
 Let $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$ be a path assignment satisfying $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]) \suffixOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$.
 By \cref{lemma:suffix_lemma},
 for any such $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$,
 there is a path assignment $(\runs^{3}, \pathOrder[\runs^{3}])$ satisfying
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$, and
 $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$ for each $i \in \{1,2,\dots,n\}$.
 Since we have $\A \models_{\pval} \fml_{\forall}$, for such $(\runs^{3}, \pathOrder[\runs^{3}])$,
 we have $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$.
 Since for each $i \in \{1,2,\dots,n\}$, we have $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$,
 for such $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$,
 we have $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]), \Init(\overline{\runs}^{3}(\vrun)), \UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{3}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{3}} \models_{\pval,\A} \reduce^n(\fml_1)$.
 Therefore, we have $\A^n \models_{\pval} \reduce^n(\fml_{\forall})$.

 Suppose $\A^n \models_{\pval} \reduce^n(\fml_{\forall})$ holds.
 Let $(\runs^{1}, \pathOrder[\runs^1])$ be a path assignment satisfying
 $\domain(\runs^{1}) = \{\vrun_1, \vrun_2, \dots, \vrun_n\}$ and
 for any $i \in \{1,2,\dots,n\}$,
 $\runs^{1}(\vrun_i) \in \Traces(\valuate{\A}{\pval})$.
 By \cref{lemma:composition_lemma},
 there is a path $\trace \in \Traces(\valuate{\A^n}{\pval})$ of $\valuate{\A^n}{\pval}$
 satisfying the following conditions, where
 $\pathOrderToN$ is the monotone surjection  from $\domain(\runs) \times \setN$ to $\setN$.
 \begin{itemize}
  \item For any $\vrun_k \in \domain(\runs)$, $\runs(\vrun_k) = \project{\trace}{k}$ holds.
  \item For any $i \in \setN$, the inverse image $\pathOrderToN^{-1}(\{i\})$ satisfies
        $(\vrun_k, j) \in \pathOrderToN^{-1}(\{i\}) \iff \project{\edge_i}{k} = \edge^k_j$,
        where $\edge_i$ is the $i$-th edge of $\trace$ and $\edge^k_j$ is the $j$-th edge of $\runs^{1}(\vrun_{k})$.
 \end{itemize}
 Since we have $\A^n \models_{\pval} \reduce^n(\fml_{\forall})$,
 for the extension $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}])$ of $(\emptyruns, \pathOrder[\emptyruns])$
 satisfying $\domain(\runs) = \{\vrun\}$ and $\overline{\runs}^{1}(\vrun) = \trace$,
 there is $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$ satisfying 
 $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$,
 $\duration(\overline{\runs}^{1} - \overline{\runs}^{2}) \compOp \valuate{\paramOrInt}{\pval}$,
 $(\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}]), \Init(\overline{\runs}^{2}(\vrun)),\UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{2}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{2}} \models_{\pval,\A} \fml_2$, and
 for any $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$ satisfying $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]) \suffixOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$,
 $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]), \Init(\overline{\runs}^{3}(\vrun)), \UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{3}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{3}} \models_{\pval,\A} \fml_1$ holds.
 By \cref{lemma:suffix_lemma},
 for any such $\overline{\runs}^{2}(\vrun)$,
 there is a path assignment $(\runs^{2}, \pathOrder[\runs^{2}])$
 such that
 $\domain(\runs^{1}) = \domain(\runs^{2}) = \{\vrun_1, \vrun_2, \dots, \vrun_n\}$,
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{2}, \pathOrder[\runs^{2}])$, and
 for each $i \in \{1,2,\dots,n\}$, we have
 $\runs^{2}(\vrun_i) = \project{\overline{\runs}^{2}(\vrun)}{i}$.
 For such $(\runs^{2}, \pathOrder[\runs^{2}])$,
 we have $\duration(\runs^{1} - \runs^{2}) \compOp \valuate{\paramOrInt}{\pval}$ and
 $(\runs^{2}, \pathOrder[\runs^{2}]), \Init(\runs^{2}(\vrun_n)),\UpdateCountval{\countval}{\runs^{1}}{\runs^{2}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{2}} \models_{\pval,\A} \fml_2$.
 Let $(\runs^{3}, \pathOrder[\runs^{3}])$ be a path assignment satisfying
 $(\runs^{1}, \pathOrder[\runs^{1}]) \suffixEqOp (\runs^{3}, \pathOrder[\runs^{3}]) \suffixOp (\runs^{2}, \pathOrder[\runs^{2}])$.
 By \cref{lemma:suffix_lemma},
 for any such $(\runs^{3}, \pathOrder[\runs^{3}])$,
 there is a path assignment $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$ satisfying
 $(\overline{\runs}^{1}, \pathOrder[\overline{\runs}^{1}]) \suffixEqOp (\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]) \suffixOp (\overline{\runs}^{2}, \pathOrder[\overline{\runs}^{2}])$, and
 $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$ for each $i \in \{1,2,\dots,n\}$.
 Since we have $\A^n \models_{\pval} \reduce^n(\fml_{\forall})$, for such $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}])$,
 we have $(\overline{\runs}^{3}, \pathOrder[\overline{\runs}^{3}]), \Init(\overline{\runs}^{3}(\vrun)), \UpdateCountval{\countval}{\overline{\runs}^{1}}{\overline{\runs}^{3}}, \UpdateRecordval{\recordval}{\overline{\runs}^{1}}{\overline{\runs}^{3}} \models_{\pval,\A} \reduce^n(\fml_1)$.
 Since for each $i \in \{1,2,\dots,n\}$, we have $\runs^{3}(\vrun_i) = \project{\overline{\runs}^{3}(\vrun)}{i}$,
 for such $(\runs^{3}, \pathOrder[\runs^{3}])$, 
 we have $(\runs^{3}, \pathOrder[\runs^{3}]), \Init(\runs^{3}(\vrun_n)), \UpdateCountval{\countval}{\runs^{1}}{\runs^{3}}, \UpdateRecordval{\recordval}{\runs^{1}}{\runs^{3}} \models_{\pval,\A} \fml_1$.
 Therefore, we have $\A \models_{\pval} \fml_{\forall}$.
%
\end{proof}
