\subsection{Detailed proof of \cref{theorem:correctness_observers}}\label{section:proof:correctness_observers}
%

Before proving \cref{theorem:correctness_observers}, we show the completeness of the observers.

%
\begin{lemma}
 [completeness of the observers]%
 \label{lemma:completeness_observers}
 Let $\A$ be a PTA, $\fullFml$ be an \ExtPTCTL{} formula, and $\pval$ be a parameter valuation for the union of the parameters in $\A$ and~$\fullFml$.
 For any path $\trace$ of $\valuate{\A}{\pval}$,
 there is a path $\trace'$ of $\valuate{\A \productOp \observerof{\fullFml}}{\pval}$ satisfying $\project{\trace'}{\valuate{\A}{\pval}} = \trace$, where
 $\project{\trace'}{\valuate{\A}{\pval}}$ is the projection of $\trace'$ to the path of $\valuate{\A}{\pval}$.
\end{lemma}
%
\begin{proof}
 The result of the general case is immediate from the result of the base cases (\ie{} $\fullFml$ is one of
$\LAST(\action^1_{\vrun}) - \LAST(\action^2_{\vrun}) \compOp \lterm$,
$\sum_{\action \in \Actions} \alpha_{\action} \COUNT(\action_{\vrun}) \compOp d$, and
$(\sum_{\action \in \Actions} \alpha'_{\action} \COUNT(\action_{\vrun}) \bmod N) \compOp d$), and we focus on them.

 {%
 \newcommand{\riseActions}{\Actions_{\mathrm{rise}}}%
 \newcommand{\currentGuard}{(\action^{1} - \action^{2} \compOp \lterm)[\riseActions \coloneq 0]}%
 \newcommand{\isInitialized}{b}
 For $\fullFml = \LAST(\action^{1}_{\vrun}) - \LAST(\action^{2}_{\vrun}) \compOp \lterm$,
 since $\Label$ is the identity function,
 it suffices to show that
 for any $\loc = (\props, \isInitialized) \in \Loc = \powerset{\{\action^1, \action^2, \fml\}} \times \{\top, \bot\}$ and
 $\props'_{\Actions} \subseteq \{\action^1, \action^2\}$ with $\props \cap \Actions \neq \props'_{\Actions}$ and
 for any clock valuation $\clockval \colon \{\action^{1}, \action^{2}\} \to \setRnn$,
 there is another clock valuation $\clockval'$ and $\loc' = (\props', \isInitialized') \in \Loc$
 satisfying $\props'_{\Actions} = \props' \cap \Actions$ and
 $(\loc, \clockval) \flecheRel (\loc', \clockval')$.
 Let $\props_{\Actions} = \props \cap \Actions$.
 If $\props'_{\Actions} \subsetneq \props_{\Actions}$,
 we have $(\loc, \top, \emptyset, \loc') \in \Edges$, and
 $(\loc, \clockval) \flecheRel (\loc', \clockval')$ holds
 for $\clockval' = \clockval$ and
 $\loc' = (\props'_{\Actions} \cup (\props \cap \{\fullFml\}), \top)$.
 If $\props'_{\Actions} \not\subsetneq \props_{\Actions}$,
 there are transitions from $\loc$ with guards
 $\currentGuard$ and $\neg\currentGuard$ to appropriate $\loc'$.
 Therefore,
 $(\loc, \clockval) \flecheRel (\loc', \clockval')$ is satisfied
 for appropriately chosen $\loc'$ and $\clockval'$.
 }

 Assume
 $\fullFml = \sum_{\action \in \Actions} \alpha_{\action} \COUNT(\action_{\vrun}) \compOp d$. %
 %
 For any location $(p, \approxcountval) \in \powerset{\Actions} \times \{0,1,\dots, d, d+1\}^{\Actions}$ of $\observerof{\fullFml}$,
 we have $\Label((p, \approxcountval)) \cap \Actions = p$.
 Moreover, since for any transition of $\observerof{\fullFml}$, the guard is $\top$,
 it suffices to show that
 for any $p, p' \in \powerset{\Actions}$ and $\approxcountval \in \{0,1,\dots, d, d+1\}^{\Actions}$ with $p \neq p'$,
 there is $\approxcountval' \in \{0,1,\dots, d, d+1\}^{\Actions}$ such that
 $((p, \approxcountval), \top, \emptyset, (p', \approxcountval')) \in \Edges$, which is straightforward from the definition.
 The proof is similar for $\fullFml = (\sum_{\action \in \Actions} \alpha'_{\action} \COUNT(\action_{\vrun}) \bmod N) \compOp d$.
%
\end{proof}
