\subsection{Syntax of \NFExtHyperPTCTLBDR{}}\label{appendix:NFExtHyperPTCTLBDR}
%

%

%
\begin{definition}[Syntax of \NFExtHyperPTCTLBDR{}]\label{definition:class-BDR08}
 For atomic propositions $\Actions$ and parameters $\Param$,
 the syntax of \NFExtHyperPTCTLBDR{} formulas of the Boolean level~$\Boolean$, the temporal level~$\fml$, and the top level~$\fullFml$ are defined as follows, where
 $\action \in \Actions$,
 $\paramOrInt \in \Param \cup \setN$,
 $n \in \setN$,
 $\param \in \Param$, and
 $\lterm$ is a linear term over~$\Param$:
 \begin{align*}
  \Boolean \Coloneq & \top \mid \action_{\vrun} \mid \COUNT(\action_{\vrun}) \compOp n
  \\
  & \mid \LAST(\action_{\vrun}) - \LAST(\action_{\vrun}) \compOp n \mid \neg \Boolean \mid \Boolean \lor \Boolean
  \\
  \fml \Coloneq & \HEUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\Boolean}{\Boolean}
  \\
  & \mid \HAUntilFml[\compOp \paramOrInt]{\vrun_1,\vrun_2,\dots,\vrun_n}{\Boolean}{\Boolean}
  \\
 \fullFml \Coloneq & \fml \mid \param \compOp \ltermNN \mid \neg \fullFml \mid \fullFml \lor \fullFml \mid \PExists \param\, \fullFml
 \end{align*}
\end{definition}
