\subsection{Outage Probability}
Outage probability is defined as the probability that the instantaneous channel capacity $C\triangleq\log_2\left(1+\gamma\right)$ falls below a target rate $R$, i.e., $P_o \triangleq \Pr\left(C\leq R\right)$. 

\begin{Proposition}
The outage probability for the proposed FRIS system is given by
\begin{align}
P_o  = \frac{1}{\Gamma\left(k\right)}\Upsilon\left(k,\frac{\overline{R}}{ \overline{\gamma}L_fL_u\theta}\right),
\end{align}
where $k$ and $\theta$ are defined in Proposition \ref{pro-1}.
\end{Proposition}

\begin{proof}
By inserting the SNR from \eqref{eq-snr} into the definition of outage probability, yields:
\begin{align}
P_o & = \Pr\left(\log_2\left(1+\overline{\gamma}L_fL_uG\right)\leq R\right)\\
& = \Pr\left(G\leq \frac{\overline{R}}{\overline{\gamma}L_fL_u}\right)=F_G\left(\frac{\overline{R}}{\overline{\gamma}L_fL_u}\right),\label{eq-p1}
\end{align}
where $\overline{R}\triangleq 2^{R}-1$. By inserting \eqref{eq-cdf} into \eqref{eq-p1}, the proof is completed. 
\end{proof}

\begin{corollary}
The asymptotic expression of the outage probability in the high-SNR regime, i.e., when $\gamma\gg 1$, is given by $P_o^\infty = \frac{1}{k\Gamma\left(k\right)}\left(\frac{\overline{R}}{ \overline{\gamma}L_fL_u\theta}\right)^k$.
\end{corollary}

\begin{proof}
In the high SNR regime, the CDF in \eqref{eq-cdf} can be rewritten as $F^\infty_G\left(g\right) \simeq \frac{1}{k\Gamma\left(k\right)}\left(\frac{g}{\theta}\right)^k$. Now, by substituting $F^\infty_G\left(g\right)$ into the outage probability definition, $P_o^\infty$ is obtained. 
\end{proof}

\subsection{Ergodic Capacity}
The ergodic capacity of the considered FRIS-assisted communication system is defined as follows: 
\begin{align}
\overline{C} \triangleq \mathbb{E}\left[C\right]=\int_0^\infty \log_2\left(1+\overline{\gamma}L_fL_uG\right)f_G\left(g\right)\mathrm{d}g,\label{eq-ecdef}
\end{align}
where $f_G\left(g\right)$ has been defined in \eqref{eq-pdf}. By substituting \eqref{eq-pdf} into \eqref{eq-ecdef}, a closed-form expression for the ergodic capacity can be derived in terms of the hypergeometric/Meijer's G-functions~\cite{Meijer}. However, to enhance the analysis further, we apply Jensen's inequality to derive a tight upper bound for $\overline{C}$. 

\begin{Proposition}
The ergodic capacity for the proposed FRIS-assisted communication system is given by 
\begin{align}
\overline{C} \approx \log_2\left(1+\overline{\gamma}L_f L_u \mathrm{tr}\left(\widetilde{\mathbf{J}}^2\right)\right).\label{eq-ec}
\end{align}
\end{Proposition}

\begin{proof}
By applying Jensen's inequality into \eqref{eq-ecdef}, we have
\begin{align}
\overline{C}&=\mathbb{E}\left[\log_2\left(1+\overline{\gamma}L_fL_uG\right)\right]\\
&\leq \log_2\left(1+\overline{\gamma}L_fL_u\mathbb{E}\left[G\right]\right)\\
&= \log_2\left(1+\overline{\gamma}L_fL_u\mathrm{tr}\left(\mathbf{A}\mathbf{A}^H\right)\right).\label{eq-p2}
\end{align}
By inserting $\mathrm{tr}\left(\mathbf{A}\mathbf{A}^H\right)$ from \eqref{eq-trac1} into \eqref{eq-p2}, yields\eqref{eq-ec} which completes the proof.
\end{proof}

\begin{corollary}
The asymptotic expression of the ergodic capacity in the high-SNR regime, i.e., $\gamma\gg 1$, is given by $\overline{C}^\mathrm{\infty} \approx \log_2\left(\overline{\gamma}L_f L_u \mathrm{tr}\left(\widetilde{\mathbf{J}}^2\right)\right)$.
\end{corollary}
