\subsection{No-Regret Property and the Probability of Excess Allocation} \label{sec:NoRegretAndMissingProofs}



In this section, we finish the missing proofs of \Cref{lemma:prob-ea-small} and \Cref{lem:noRegret}. First, we prove the no-regret property in \Cref{lem:noRegret}. Recall, in this online problem we play a price $\accprice_{i, j} \geq 0$ in the $i$-th step and get   revenue $\accprice_{i, j} \cdot r_{i,j} $ from the   $j$-th item where $r_{i,j} \in [-1,1]$; note that $r_{i,j}$  could be negative. We want to lower bound the total revenue of the exponential pricing rule that sets prices as follows.
\[
\textstyle   \accprice_{i, j} \gets \initprice \cdot \exp\left(\delta \cdot \sum_{\ell \, < \, i}  r_{\ell,j} \right).
\]



\begin{proof}[Proof of \Cref{lem:noRegret}.]
We start by observing that
\begin{align*}
    \accprice_{i+1, j} - \accprice_{i, j}~=~ \accprice_{i, j} \cdot\left(\exp \left(\delta \cdot r_{i,j} \right) - 1\right) 
    &~\leq~ \accprice_{i,j} \cdot \left(\delta \cdot r_{i,j} + (\delta)^2 \cdot  r_{i,j}^2\right) \\
    &~\leq~ \accprice_{i,j} \cdot \left(\delta \cdot  r_{i,j} + (\delta)^2   \cdot r_{i,j} \cdot \mathsf{sign}( r_{i,j})\right),
\end{align*}
where the first inequality follows from $e^x - 1 \leq x + x^2$ for $x = \delta \cdot r_{i,j}  \in [-1/2, 1/2]$  and the second inequality uses $|r_{i,j}| \leq 1$. 
On re-arranging this inequality,  we get
\begin{align*}
\accprice_{i, j} \cdot r_{i,j}~&\geq~ \frac{1}{\delta}  \cdot (\accprice_{i+1,j} - \accprice_{i,j}) -  \delta \cdot \accprice_{i,j} \cdot r_{i,j}\cdot \mathsf{sign}(r_{i,j}).
\end{align*}
Subtracting $\delta \cdot \accprice_{i, j} \cdot r_{i,j}$ from both sides of the above inequality, 
\begin{align*}
    (1 - \delta) \cdot \accprice_{i, j} \cdot r_{i,j} ~&\geq~ \frac{1}{\delta}  \cdot  (\accprice_{i+1,j} - \accprice_{i,j}) -  2\delta \cdot \accprice_{i,j} \cdot r_{i,j}^+,
\end{align*}
where we use $1 + \mathsf{sign}(r_{i,j}) = 0$ when $r_{i,j} < 0$.
Summing the above inequality over all $i \in [\stoptime]$ gives
\begin{align*}
(1 - \delta)\cdot \sum_{i \in [\stoptime]} \accprice_{i, j} \cdot r_{i,j} ~&\geq~ \frac{1}{\delta}  \cdot  \sum_{i \in [\stoptime]}(\accprice_{i+1,j} - \accprice_{i,j}) - 2\delta \sum_{i \in [\stoptime] }\accprice_{i,j} \cdot r_{i,j}^+\\
    ~&=~ \frac{1}{\delta} \cdot (\accprice_{\stoptime+1,j} - \accprice_{1,j}) - 2\delta \sum_{i \in [\stoptime] }\accprice_{i,j} \cdot r_{i,j}^+ 
    \quad \geq \quad  -\frac{\initprice}{\delta}  - 2\delta \sum_{i \in [\stoptime] }\accprice_{i,j} \cdot r_{i,j}^+.
\end{align*}
Finally, using $\frac{1}{1 - \delta} \leq 2$ completes the proof of the lemma.
\end{proof}




Finally, we bound the probability of excess allocation and prove \Cref{lemma:prob-ea-small}.

\begin{proof}[Proof of \Cref{lemma:prob-ea-small}.]

We first recall the setting of \Cref{lemma:prob-ea-small}. 
Recall that event $\EA$ corresponds to the situation that
Algorithm~\ref{alg:prsp} terminates for some $i \in [n]$ and $j \in [m]$, 
and our goal is to show that $\pr(\EA) \leq \epsilon$.
Furthermore, since  
$\esopt$ and   $\big\{\widehat{\cons}_{i, j}\big\}$   are \emph{good estimates} of $\opt$ and  $\big\{\cons^*_{i, j}{\supx}\big\}$, we have (by \Cref{def:goodestimates}) that $\pr_{(\gamma_1, \cdots, \gamma_n)}\big[\sum_{i \in [n]} \one \big[\max_{\theta \in \Theta_i} \val_i(\theta) \geq \beta \cdot \esopt\big] > \frac{10}{\epsilon}\big] \leq \epsilon$; i.e.,   the number of high-value requests with respect to $\esopt$ is $O(1/\epsilon)$.
We will argue that under event $\EA$,
we have $\sum_{i \in [n]} \one \left[\max_{\theta \in \Theta_i} \val_i(\theta) \geq \beta \cdot \esopt\right] > \frac{10}{\epsilon}$, 
which, given our assumption occurs with probability  at most $\epsilon$, thus bounding $\pr(\EA)$ by $\epsilon$.
%We prove this statement via a contradiction. 
Towards this end, we say that the $i$-th request
is a \emph{low value} (resp., \emph{high value}) request
if $\max_{\theta \in \Theta_i} \val_i(\theta)$ is less than (resp., at least) $\beta \cdot \esopt$.

Now suppose that event $\EA$ is triggered after request $\stoptime$ for resource $j^*$, and that
$|\{i \in [n]:i \text{ is high value} \}| \leq \frac{10}{\epsilon}$.
We will show that, in this case, the algorithm obtains total value at least $n \cdot \beta \cdot \esopt$ from  the low value requests. 
This is a contradiction since each low value request can contribute at most $\max_\theta \val_i(\theta) < \beta \cdot \esopt$ to the total value.
We first note that we have 
$\sum_{i \in [\stoptime] \, : \, i \text{ is low value} }\calg_{i, j^*}  \,\, \geq \,\, \frac{1}{2}\epsilon\cdot B_j - \frac{10}{\epsilon} \,\, \geq \,\, 2,$
where the final inequality uses $B_j \geq {32 \log (nm\beta/\epsilon)}/{\epsilon^2}$ for all $j \in [m]$.
Next, we define $\widehat \ell$ to be an index such that
$\sum_{i \in [\widehat \ell, \stoptime]\, :\, i \text{ is low value} }\calg_{i, j^*} \in [1, 2]$: such an index always exists since at
most one unit of a resource can be allocated for a given request. Let $\alg_{low}$ be the total value gained from those low value requests.
Conditioned on $\EA$, and using $\val_i(\theta_i) - \langle \bprice_i, a_i(\theta_i) \rangle \geq 0$ since $\phi \in \Theta_i$, we have
\begin{equation}\label{eq:largeEA2}
 \alg_{low} \,\, \geq \,\, \sum_{i \in [\stoptime] \, : \, i \text{ is low value} } \sum_{j=1}^m \price_{i, j} \cdot \calg_{i, j} ~\geq~ \sum_{i \in [\widehat \ell, \stoptime] \, : \, i \text{ is low value} } \price_{i, j^*} \cdot \calg_{i, j^*}.
\end{equation}
Also, for $i \in [\widehat \ell, s]$, 
 \begin{align}
 \sum\limits_{\ell < i } \calg_{\ell, j^*} - \sum\limits_{\ell < i}\widehat{\cons}_{ \ell, j^*}  
~\geq~  \sum\limits_{\ell \leq \stoptime } \calg_{\ell, j^*} - \sum\limits_{\ell \leq s}\widehat{\cons}_{ \ell, j^*} - \sum\limits_{i \leq \ell \leq \stoptime} \calg_{i, j^*}
~\geq~  \frac{\epsilon}{2}   B_j - 2 - \frac{10}{\epsilon}  ~ \geq ~\frac{\epsilon}{4}   B_j,\label{eq:largeEA3}
\end{align}
where the second inequality uses the termination condition, the assumption that there are no more than $\frac{10}{\epsilon}$ high value requests and that $\sum_{i \in [\widehat \ell, \stoptime]\, :\, i \text{ is low value} }\calg_{i, j^*} \leq 2$. 
The final inequality above is true when $B_j \geq 44\epsilon^{-2}$. 
Substituting~\eqref{eq:largeEA3} in the definition of $\price_{i,j^*}$ implies  $\lambda_{i, j^*} \geq \initprice \cdot \big( \delta \cdot \frac{1}{4}\epsilon B_j\big) = \initprice \cdot \frac{n^2 m^2 \beta^2}{\epsilon^2}$ for $i \in [\widehat{\ell}, \stoptime]$. 
Using this in \eqref{eq:largeEA2} gives
\[
\alg_{low} ~\geq~ \initprice \cdot \frac{n^2m^2\beta^2}{\epsilon^2} \cdot \sum_{i \in [\stoptime] \, : \, i \text{ is low value} } \cons_{i, j^*} ~\geq~ \initprice \cdot \frac{n^2m^2\beta^2}{\epsilon^2} \cdot 1 ~\geq~ n \cdot \beta \cdot \esopt,
\]
which is a contradiction, since there must be $\alg_{low} < n \cdot \beta \cdot \esopt$.
\end{proof}




\section{Learning Good Estimates using a Single Sample}\label{sec:single-sample}

In this section, we design a single sample online resource allocation algorithm that achieves value $(1 - O(\epsilon)) \cdot \opt$ and prove \Cref{thm:intro-main} by using \Cref{thm:exp-pricing-estimates} from the previous section.

To apply \Cref{thm:exp-pricing-estimates}, we need two kinds of estimates: $\esopt$ and $\{\esconsx\}_{i \in [n], j \in [m]}$, which  are good (see \Cref{def:goodestimates}) with respect to some feasible solution $x$ to  $\lp\left(\B\cdot(1-\epsilon)\right)$ with a large objective value $\obj(x) \geq (1 - O(\epsilon)) \cdot \opt$.
Here, learning a good $\esopt$ will be relatively straightforward: we will use the value of the $(1/\epsilon)$-th largest value in  the sample as $\esopt$ and argue, via concentration, that it satisfies the desired conditions. 
For details, see \Cref{sec:CompletingSingleSample}. 
Our main challenge will be to learn good estimates $\{\esconsx\}_{i \in [n], j \in [m]}$. 
Recall that for these estimates to be good, we need that for all $i \in[n], j \in [m]$,
    \begin{align} \label{eq:goodEst}
    \textstyle 0 \,\, \leq \,\, \widehat{\cons}_{i, j} \,\, \leq \,\,  1 \quad \text{and} \quad 
        \big|\sum_{\ell \leq i}\widehat \cons_{\ell, j} - \sum_{\ell\leq i}\cons_{\ell, j}^*{\supx}\big| \,\, \leq \,\, \frac{\epsilon^2 \cdot B_j}{16 \log (nm\beta/\epsilon)},
    \end{align}
    where $ \cons_{\ell, j}^*{\supx} := \sum_{k = 1}^K \sum_{\theta \in \Theta_{\ell, k}} \left(a_{\ell, k}(\theta)\right)_j \cdot x_{\ell, k, \theta}$.

We note that our goal is to estimate budget consumptions $\{\esconsx\}_{i \in [n], j \in [m]}$  with respect to some solution $x$ with a large $\obj(x)$, rather than to learn $x$ itself. 
Indeed, estimating such an $x$  from a single sample is impossible  since the number of request types $K$ could be arbitrarily large. 
The following is the main result of this section.

{
\begin{Theorem}
\label{lma:step1}
    There exists an algorithm that,
    given a single sample $\{\tilde \gamma_1, \ldots, \tilde \gamma_n\}$ from an online resource allocation instance and assuming all resource budgets $B_j \geq \Omega\big({\log^4(nm/\epsilon)}\cdot{\epsilon^{-6}}\big)$,
    outputs estimates $\{\esconsx\}_{i \in [n], j \in [m]}$, such that, with probability at least $1-2\epsilon$, 
    there exists a solution $x$ of $\lp((1 - \epsilon) \cdot \B)$ with $\obj(x) \geq (1 - 4\epsilon) \cdot \opt$ and the estimates satisfy 
    \eqref{eq:goodEst} with respect to $x$.
\end{Theorem}
}


\noindent \textbf{Proof Overview.}
We start by observing that the lemma is much easier to prove if we were given $\OTild(\epsilon^{-4})$ independent samples from the underlying distributions. This is because by solving the configuration LP relaxation for each sample,  we obtain an unbiased estimator for $\consx$.  As we only need to learn prefix budget consumptions up to  $\OTild(\epsilon^2 \cdot B_j)$  accuracy,  $\OTild(\epsilon^{-4})$ samples suffice, and we can then union bound over every prefix. However, this argument crucially relies on obtaining independent samples.


Given a single sample, a natural idea is to uniformly partition the single sample into $\OTild(\epsilon^{-4})$ parts, and treat each part as an independent sample. That is,  let $\ptt = \{S_1, \ldots, S_D\}$ be a uniformly at random partition of $[n]$ into $D=\OTild(\epsilon^{-4})$   parts where each part $S_d$ has size $n/D$\footnote{Without loss of generality, we assume $n$ is a multiple of $D$. This assumption is feasible because we can arbitrarily add $0$-value requests into the instance.}. 
 Now we can treat  each part $S_d$  as a ``mini-sample'' for estimating  $\consx$ by solving the configuration LP on $S_d$ with budget $\B/D$. However, two  challenges arise with such an approach.  

The first and primary challenge arises from the correlations among different parts, as they must remain disjoint. While we can interpret random partitioning as ``sampling without replacement,” there is no negative correlation between samples of $\consx$ from different parts, making it difficult to apply standard concentration bounds.
 %
Our key idea is to redefine the learning target. Instead of aiming for the ``global” LP optimal solution that depends on all $n$ requests, we define ``local” LP optimal solutions for each part. This approach effectively bypasses correlations, as separate parts no longer interact, allowing us to leverage concentration results with  $\OTild(\epsilon^{-4})$ independent samples. Additionally, we show that when  $\ptt$ is chosen uniformly at random, with high probability the local solutions can be merged to obtain a near-optimal global solution.



The second challenge comes from the inaccuracy of the budget for each mini-sample. After randomly choosing $\ptt$,  each mini-sample needs $\OTild(\epsilon^4 \cdot \B)$ budget in expectation. 
However, because of the standard deviation, some mini-samples may require  more budget than the expectation, leading to an extra loss when only the expected amount of budget is assigned to this mini-sample. 
{To resolve this   challenge, we relax the assumption on the budget to be $B_j \geq \tilde \Omega(\epsilon^{-6})$, instead of $B_j \geq \tilde \Omega(\epsilon^{-2})$, and argue that under the new budget assumption, with high probability, this leads to at most $O(\epsilon)$ loss in the objective value.}





\subsection{Learning Estimates $\{\esconsx\}$ via Sample Partition: Proof of \Cref{lma:step1}}

    We start by defining, for every fixed partition $\ptt = \{S_1, \cdots, S_D\}$ of $[n]$, a feasible solution $x^\ptt$ for  $\lp((1 - \epsilon) \cdot \B)$. Note that this solution depends only on the partition and not on our single sample. 
    To define this solution, consider the following random process.
    \begin{itemize}
        \item For each $i \in S_d$, draw a random $\gamma_i = (\val_i, a_i, \Theta_i)$ from $\D_i$.
        \item Then, solve  \ref{program:notype} for $\{\gamma_i\}_{i \in S_d}$ and         let  $z^{(d)}$ be the corresponding optimal solution.
        \begin{align}
            \text{maximize } \quad \quad  &  \textstyle  \quad\sum_{i \in S_d}  \sum_{\theta \in \Theta_{i}} \val_{i}(\theta) \cdot z_{i, \theta}, \notag \\
           \text{s.t.} \qquad & \textstyle \quad   \sum_{i \in S_d} \sum_{\theta \in \Theta_{i}}  a_{i}(\theta) \cdot z_{i, \theta}  \leq \frac{1 - \epsilon}{D} \cdot \B \tag{$\text{LP}_{\textsc{Sample}}$} \label{program:notype} \\
            \forall i \in S_d, & \textstyle \quad \sum_{\theta \in \Theta_{i}} z_{i,\theta} \leq 1 \notag \\
            \forall i \in S_d,  \theta \in \Theta_{i, k},& \quad   0 \leq z_{i, k, \theta} \leq 1. \notag
        \end{align}


    \end{itemize}

    For each $d \in [D]$, let $y^{(d)}$ be a solution of $\lp((1 - \epsilon)\cdot\B / D, \{\D_i\}_{i \in S_d})$ that represents the above random process; i.e., we set  $ y^{(d)}_{i, k, \theta} = \E\big[z^{(d)}_{i, \theta} \cdot \one[\type(i) = k]\big]$, where the function $\type(\cdot)$ represents the type of request $i$.
    In other words, we set $\type(i) = k$ if, and only if, the realization of $\gamma_i$ is $\gamma_{i,k}$. 
    We further define $x^\ptt$ to be the combination of all $\{y^{(d)}\}$; formally, let $x^\ptt_{i, k, \theta} = y^{(d)}_{i, k, \theta}$ for $i \in S_d$. 
    The following claim guarantees that $x^\ptt_{i, k, \theta}$ is a feasible for $\lp((1 - \epsilon) \cdot \B)$.


\begin{Claim} \label{claim:xpFeasibility}
    The solution $x^\ptt$ defined above is feasible for  $\lp((1 - \epsilon) \cdot \B)$.
\end{Claim}
\begin{proof}

    To verify the budget constraint, it suffices to check that each mini-solution $y^{(d)}$ uses at most $(1 - \epsilon) \cdot \B/D$ budget, which follows from the fact that
    \begin{align*}
    \textstyle        \sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} a_{i,k}(\theta) \cdot y^{(d)}_{i,k,\theta} ~&=~ \textstyle \E_{\{\gamma_i\}_{i \in S_d}}\left[ \sum_{i \in S_d} \sum_{\theta \in \Theta_i} a_i(\theta) \cdot z^{(d)}_{i, \theta} \cdot \sum_{k \in [K]} \one[\type(i) = k]\right] \\
    ~&=~ \textstyle \E_{\{\gamma_i\}_{i \in S_d}}\left[ \sum_{i \in S_d} \sum_{\theta \in \Theta_i} a_i(\theta) \cdot z^{(d)}_{i, \theta}\right] ~\leq~ (1 - \epsilon) \cdot \B/D.
    \end{align*}
    To check that $x^{\ptt}$ satisfies $\sum_{\theta} x^{\ptt}_{i, k, \theta} \leq p_{i, k}$ for all $i \in [n]$ and $k \in [K]$, it's sufficient to check $\sum_{\theta} y^{(d)}_{i, k, \theta} \leq p_{i, k}$ for every $i \in S_d, k \in [K]$. This follows from the fact that
    \begin{align*}
        \textstyle \sum_{\theta \in \Theta_{i,k}} y^{(d)}_{i, k, \theta} ~=~ \E_{\{\gamma_i\}_{i \in S_d}}\left[\sum_{\theta \in \Theta_i}  z^{(d)}_{i, \theta} \cdot \one[\type(i) = k]\right] ~\leq~ \E_{\{\gamma_i\}_{i \in S_d}}\left[1 \cdot \one[\type(i) = k]\right] ~=~ p_{i,k}.
    \end{align*}
    Therefore, $x^\ptt$ is a solution of $\lp((1 - \epsilon) \cdot \B)$.
\end{proof}

Next, we show that $\obj(x^\ptt)$ is large when $\ptt$ (and consequently $x^\ptt$) is chosen uniformly at random.



\begin{Lemma}
\label{lma:xptt}
    Let $D\geq 1$ be an integer that divides $n$. Suppose that, for every resource $j \in [m]$, the budget $B_j$ satisfies $B_j \geq \Omega(\frac{D\cdot \log (nm/\epsilon)}{\epsilon^{2}})$. 
    Then, with probability at least $1 - \epsilon$, a uniformly random  partition $\ptt$ of $[n]$ into parts of size $n/D$ will yield a solution $x^\ptt$ such that $\obj(x^\ptt) \geq (1 - 4\epsilon) \cdot \opt$.
\end{Lemma}

\begin{proof}
    Let $\tildx$ be an arbitrary but fixed solution of $\lp((1 - 3\epsilon) \cdot \B)$, such that $\obj(\tildx) \geq (1 - 3\epsilon) \cdot \opt$. The existence of $\tildx$ is guaranteed by the observation that it's sufficient to scale down the optimal solution of $\lp(\B)$ by a factor of $1 - 3\epsilon$. Our main idea is to show that $\obj(x^\ptt)$ is comparable to $\obj(\tildx) \geq  (1 - 3\epsilon) \cdot \opt$.
    Towards this end, we call a partition $\ptt$ \emph{average} with respect to $\tildx$ if, for every $S_d \in \ptt$, the following condition holds: 
    \[  \textstyle 
    \sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} a_{i,k}(\theta) \cdot \tildx_{i,k,\theta} \leq \frac{(1 - 2\epsilon)}{D} \cdot \B.
    \] 
    In other words, each part $S_d$ does not significantly exceed its expected budget consumption.
    The following claim shows that a uniformly random partition $\ptt$ of $[n]$ into parts of size $n/D$ is average with high probability.

    \begin{restatable}{Claim}{clmnottoomuch}\label{clm:nottoomuch} Let $\tildx$ be a solution of $\lp((1-3\epsilon) \cdot \B)$. If $\ptt$ is chosen uniformly at random and $B_j \geq \Omega(\frac{\log (nm/\epsilon) \cdot D}{\epsilon^2})$ for all $j$,     
        then with probability at least $1 - \epsilon$, we have 
        \[  \textstyle 
            \sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} a_{i,k}(\theta) \cdot \tildx_{i,k,\theta} \leq \frac{(1 - 2\epsilon)}{D} \cdot \B
        \] 
         for all parts $S_d \in \ptt$; i.e., $\ptt$ is average with respect to $\tildx$. 
    \end{restatable}

      We defer the proof of \Cref{clm:nottoomuch} to \Cref{app:clm-nottoomuch}, as it follows by applying standard concentration inequalities.
     We proceed by assuming that $\ptt$ satisfies \Cref{clm:nottoomuch}, and consider the following random process, which defines a feasible solution $\tildz^{(d)}$ for \ref{program:notype}.
     \begin{itemize}
         \item For each $i \in S_d$, draw $\gamma_i \sim \D_i$.
         \item Check the following condition: 
         \begin{align}  \textstyle 
             \sum_{i \in S_d} \sum_{\theta \in \Theta_i} a_i(\theta) \cdot \sum_{k \in [K]} \one[\type(i) = k] \cdot  \frac{\tildx_{i,k, \theta}}{p_{i,k}} ~\leq~ (1 - \epsilon) \cdot \B/D \label{eq:condition}
         \end{align}
         If Condition \eqref{eq:condition} is satisfied, set $\tildz^{(d)}_{i,\theta} = \frac{\tildx_{i, k, \theta}}{p_{i,k}}$, where $k = \type(i)$; otherwise, set $\tildz^{(d)}_{i,\theta} = 0$.
     \end{itemize}

     The following claim shows that the objective obtained by $\tildz^{(d)}$ is sufficiently high.

     \begin{restatable}{Claim}{clmfollowtildx}
     \label{clm:followtildx}
         Let $\tildx$ be a solution of $\lp((1-3\epsilon) \cdot \B)$, and let $\ptt$ be an average partition with respect to $\tildx$ (per \Cref{clm:nottoomuch}). Then, we have
         \[  \textstyle 
         \E_{\{\gamma_i\}_{i \in S_d}} \left[\sum_{i \in S_d} \sum_{\theta \in \Theta_i} \val_i(\theta) \cdot \tildz^{(d)}_{i, \theta} \right] ~\geq~ (1 - \epsilon) \cdot \sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} \val_{i,k}(\theta) \cdot \tildx_{i,k, \theta}
         \]
         for every $d \in [D]$, provided that $B_j \geq \Omega(\frac{\log (nm/\epsilon) \cdot D}{\epsilon^2})$.
     \end{restatable}
     Note that when \Cref{clm:nottoomuch} is satisfied,
     following solution $\tildx$ implies that, in expectation, the realization of $\{\gamma_i\}_{i \in S_d}$ only consumes $(1 - 2\epsilon) \cdot \B/D$ budget. 
     Then, \Cref{clm:followtildx} essentially suggests that Condition \eqref{eq:condition} is satisfied with probability at least $1 - \epsilon$. 
     In other words, with high probability, the consumption of the realized requests does not exceed the expected consumption by a significant amount.
     This, in turn, allows us to lower bound the expected value in terms of the value obtained by $\tildx$.
     We defer the proof of \Cref{clm:followtildx} to \Cref{app:clm-followtildx}, and proceed to complete the proof of \Cref{lma:xptt}. 


     Recall that in the random process of solving \ref{program:notype} that defines $y^{(d)}$,  each random $z^{(d)}$ is solved optimally. 
     Therefore, the objective value given by $z^{(d)}$ is at least the value of $\tildz^{(d)}$, i.e.,
     \begin{align*} \textstyle 
         \obj(y^{(d)}) ~=~ \E_{\{\gamma_i\}_{i \in S_d}} \left[\sum_{i \in S_d} \sum_{\theta \in \Theta_i} \val_i(\theta) \cdot z^{(d)}_{i, \theta} \right] ~\geq~ \E_{\{\gamma_i\}_{i \in S_d}} \left[\sum_{i \in S_d} \sum_{\theta \in \Theta_i} \val_i(\theta) \cdot \tildz^{(d)}_{i, \theta} \right].
     \end{align*}
     When \Cref{clm:followtildx} holds, we get
     \[  \textstyle 
     \obj(y^{(d)}) ~\geq~ (1 - \epsilon) \cdot \sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} \val_{i,k}(\theta) \cdot \tildx_{i,k, \theta}.
     \]
     Summing the above inequality for all $d \in [D]$ gives
     \[ \textstyle 
     \obj(x^\ptt) ~=~ \sum_{d \in [D]} \obj(y^{(d)}) ~\geq~ (1 - \epsilon) \cdot \obj(\tildx).
     \]
     Therefore, the objective of $x^\ptt$ is at least $(1 - \epsilon) \cdot (1 - 3\epsilon) \cdot \opt \geq (1 - 4\epsilon) \cdot \opt$ when \Cref{clm:nottoomuch} holds, i.e., when $\ptt$ is chosen uniformly at random.
     Thus, with probability at least $1 - \epsilon$, we have $\obj(x^\ptt) \geq (1 - 4\epsilon) \cdot \opt$, which finishes the proof of \Cref{lma:xptt}.
\end{proof}
The final step in proving \Cref{lma:step1} is to show that a single sample from each request distribution is sufficient to concentrate around $x^\ptt$. 
Formally, we give the following lemma.

\begin{Lemma}
    \label{lma:xptt-concentrate}
    Let $D \geq 1$ be an integer that divides $n$. Given a single sample $\{\tilde \gamma_1, \ldots, \tilde \gamma_n\}$ from each of the $n$ request distributions, and a partition $\ptt$ of $[n]$ into parts of size $n/D$, there exists an algorithm that outputs $\{\widehat \cons^{\ptt}_{i, j}\}_{i \in [n], j \in [m]} \in [0, 1]$ such that with probability at least $1 - \epsilon$,   we have for every $i, j$  that
    \[ \textstyle 
    \left|\sum_{\ell \leq i} \widehat \cons^{\ptt}_{\ell, j} - \sum_{\ell \leq i}  \cons^*_{\ell, j}{(x^\ptt)}\right| \leq \epsilon_D \cdot B_j
    \]
    for every $i \in [n]$ and $j \in [m]$, as long as $\epsilon_D \geq \sqrt{\frac{4\log (nm/\epsilon)}{D}}$.
\end{Lemma}

\begin{proof}
We start by considering the following algorithm.
\begin{itemize}
    \item For each $S_d \in \ptt$, solve \ref{program:notype} on requests $\{\tilde \gamma_i\}_{i \in S_d}$, and let $\bar z^{(d)}$ be the corresponding optimal solution. As discussed in \Cref{sec:LPandGoodEstimates}, we can solve this LP in $\poly(n,m)$ time (since $K=1$ here) given demand-oracle access to the $n$ requests.


    \item For each $i \in [n]$ and $j \in [m]$, compute
    \[ \textstyle 
    \widehat \cons^{\ptt}_{i, j} ~:=~ \sum_{d \in [D]} \one[i \in S_d] \cdot \sum_{\theta \in \tilde \Theta_i} \left(\tilde a_{i}(\theta)\right)_j \cdot \bar z^{(d)}_{i, j} \enspace .
    \]
\end{itemize}
We will show that for each $i \in [n], j \in [m]$, we have
\begin{equation}\label{eq:xptt-concentrate-1}
\textstyle 
\pr\left(\left|\sum_{\ell \leq i} \widehat \cons^{\ptt}_{\ell, j} - \sum_{\ell \leq i} \cons^*_{\ell, j}{(x^\ptt)}\right| > \epsilon_D \cdot B_j \right) ~\leq~ \frac{\epsilon}{n  m}  \enspace .
\end{equation} 
Then, applying the union bound over all $i \in [n]$ and $j\in [m]$ finishes the proof.

We now fix $i\in [n]$ and $j \in [m]$, and prove \Cref{eq:xptt-concentrate-1}. First, we define random variables $A^{(d)}_{\leq i, j} := \sum_{\ell \in S_d: \, \ell \leq i} \sum_{\theta \in \tilde \Theta_\ell} \left(\tilde a_{\ell}(\theta)\right)_j \cdot \bar z^{(d)}_{\ell, j}$, where the randomness stems from the realization of requests $\{\tilde \gamma_\ell\}_{\ell \in S_d}$. 
Since $\bar z^{(d)}$ is feasible for \ref{program:notype} for requests  $\{\tilde \gamma_\ell\}_{\ell \in S_d}$, we have
\[ \textstyle 
A^{(d)}_{\leq i, j} ~\leq~ \sum_{\ell \in S_d} \sum_{\theta \in \tilde \Theta_\ell} \left(\tilde a_{\ell}(\theta)\right)_j \cdot \bar z^{(d)}_{\ell, j} ~\leq~ \frac{(1 - \epsilon)}{D} \cdot B_j  \enspace . 
\]
On the other hand, we have
\begin{align*} \textstyle 
    \E\left[A^{(d)}_{\leq i, j}\right] ~&=~ \textstyle   \E_{\{\tilde \gamma_\ell\}_{\ell \in S_d}}\left[\sum_{\ell \in S_d: \, \ell \leq i} \sum_{k \in [K]} \one[\type(\ell) = k] \cdot \sum_{\theta \in \Theta_{i,k}}  \left(\tilde a_{\ell}(\theta)\right)_j \cdot \bar z^{(d)}_{\ell, \theta}\right] \\
    ~&=~  \textstyle \sum_{\ell \in S_d: \, \ell \leq i} \sum_{k \in [K]}  \sum_{\theta \in \Theta_{i,k}}  y^{(d)}_{\ell, k, \theta} \cdot \left(\tilde a_{\ell}(\theta)\right)_j \\
    ~&=~ \textstyle  \sum_{\ell \in S_d: \, \ell \leq i}\sum_{k \in [K]}  \sum_{\theta \in \Theta_{i,k}} x^{\ptt}_{\ell, k, \theta} \cdot \left(\tilde a_{\ell}(\theta)\right)_j,
\end{align*}
where the second equality follows from the observation that $\bar z^{(d)}$ and $z^{(d)}$ (the random solution used to define $y^{(d)}$) are uniformly distributed.
Taking a sum over all $d \in [D]$, we get
\[ \textstyle 
\sum_{d \in [D]} \E\left[A^{(d)}_{\leq i, j}\right] ~=~ \sum_{\ell \leq i} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} x^\ptt_{\ell, k, \theta} \cdot \left(\tilde a_{\ell}(\theta)\right)_j ~=~ \sum_{\ell \leq i} \cons^*_{\ell, j}{(x^\ptt)},
\]
i.e., $\sum_{\ell \leq i} \widehat \cons^{\ptt}_{\ell, j} := \sum_{d \in [D]} A^{(d)}_{\leq i, j}$ is an unbiased estimator of $\sum_{\ell \leq i} \cons^*_{\ell, j}{(x^\ptt)}$. By Hoeffding's Inequality (\Cref{Hoeffding}), we have
\begin{align*} \textstyle 
    \pr\left(\left|\sum_{\ell \leq i} \widehat \cons^{\ptt}_{\ell, j} - \sum_{\ell \leq i} \cons^*_{\ell, j}{(x^\ptt)}\right| > \epsilon_D\cdot B_j\right) ~\leq~ 2\exp\left(-\frac{2\epsilon^2_D B^2_j}{D \cdot (1 -\epsilon)^2 \cdot B^2_j/D^2}\right) ~\leq~ \frac{\epsilon}{nm},
\end{align*}
where the last inequality holds when $\epsilon_D \geq \sqrt{\frac{4\log (nm/\epsilon)}{D}}$.
\end{proof}



We now complete the proof of \Cref{lma:step1} using \Cref{claim:xpFeasibility}, \Cref{lma:xptt}, and \Cref{lma:xptt-concentrate}.

\begin{proof}[Proof of \Cref{lma:step1}]
We first generate a random partition $\ptt$ according to \Cref{lma:xptt}   with $D = {1024 \log^3(nm/\epsilon)}/{\epsilon^4}$. 
This choice of $D$ and $B_j \geq \Omega({\log^4(nm/\epsilon)}/{\epsilon^6})$ ensures that  the condition $B_j \geq \Omega({D\cdot \log (nm/\epsilon)}/{\epsilon^2})$ in \Cref{lma:xptt} is satisfied, so the lemma guarantees that with probability at least  $1-\epsilon$ we have $\obj(x^\ptt) \geq (1 - 4\epsilon) \cdot \opt$. 
Moreover, \Cref{claim:xpFeasibility} implies that $x^\ptt$  is a feasible solution for $\lp((1 - \epsilon) \cdot \B)$. 
Thus, to prove \Cref{lma:step1}, it suffices  learn good estimates  $\{\widehat \cons_{i, j}\}_{i\in [n], j \in [m]}$  (as in \eqref{eq:goodEst}) w.r.t.\,$x^\ptt$. 
Such good estimates can be obtained for partition $\ptt$ with probability at least $1-\epsilon$ using the single sample algorithm in \Cref{lma:xptt-concentrate} with  $\epsilon_D = \sqrt{{4\log (nm/\epsilon)}/{D}} = {\epsilon^2}/{(16 \log (nm/\epsilon))}$. 
Finally, applying the union bound over the guarantees of \Cref{lma:xptt}  and \Cref{lma:xptt-concentrate}, we can conclude that with probability at least $1 - 2\epsilon$, all the conditions in \Cref{lma:step1} hold. 
\end{proof}



\subsection{Learning $\widehat \opt$ and Completing the Proof of \Cref{thm:intro-main}}
\label{sec:CompletingSingleSample}

Now we complete the proof of our main \Cref{thm:intro-main} by combining the  estimated prefix budget consumptions from the last subsection with  Exponential Pricing  from the last section.

\begin{Theorem}[Formal version of \Cref{thm:intro-main}]
     Given a single sample from each of the $n$ request distributions for online resource allocation with \emph{non-identical} distributions, there exists a $\big(1-O(\epsilon)\big)$-approximation posted pricing algorithm, provided that  every resource has $\Omega\big({\log^4(nm/\epsilon)}/{\epsilon^{6}}\big)$ budget.  
\end{Theorem}



\begin{proof}
    We assume $\epsilon \leq 0.1$, otherwise the theorem trivially holds. We  will also need the following claim regarding learning an estimate of the optimal value.

\begin{Claim}
    \label{lma:step2} Given a single sample $\{\tilde \gamma_1, \ldots, \tilde \gamma_n\}$ of the instance and provided that $\epsilon \leq 0.1$, there exists an algorithm that outputs $\esopt$, which satisfies with probability at least $1 - 2\epsilon$ the following:
    \begin{itemize}
        \item $\esopt \leq \opt$.
        \item $\pr_{(\gamma_1, \cdots, \gamma_n)}\left(\sum_{i \in [n]} \one\left[\max_{\theta \in \Theta_i} \val_i(\theta) > \esopt\right] > 10\epsilon^{-1} \right) ~\leq~ \epsilon.$
    \end{itemize}
\end{Claim}

    Before proving the claim, we use it to complete the proof of the theorem.  
    Combining \Cref{lma:step1}  from the last subsection and \Cref{lma:step2} using union bound, we get    with probability at least $1 - 4\epsilon$   good estimates $\esopt$ and $\{\widehat \cons_{i,j}\}_{i \in [n], j\in [m]}$ that satisfy \Cref{def:goodestimates} with $\beta = 1$ w.r.t. solution $x$ of $\lp((1 - \epsilon) \cdot \B)$ which has $\obj(x) \geq (1 - 4\epsilon) \cdot \opt$.  Now applying \Cref{thm:exp-pricing-estimates} from the last section with these estimates gives a posted pricing algorithm with expected value at least 
    \[
    (1 - 4\epsilon) \cdot \big((1-\epsilon)(1 - 4\epsilon)\cdot \opt - 7\epsilon \cdot \opt\big)~\geq~ (1 - 16\epsilon) \cdot \opt. \qedhere
    \]
\end{proof}

Next, we prove the missing claim.
\begin{proof}[Proof of \Cref{lma:step2}]
    We assume that for all $i \neq i'$, we have $\max_{\theta} \val_i(\theta) \neq \max_{\theta} \val_{i'}(\theta)$.
    This assumption is without loss of generality since we can add an arbitrarily small noise to the value functions, or equivalently, we can break ties uniformly at random.

    Given $\{\tilde \gamma_1, \ldots, \tilde \gamma_n\}$, our algorithm outputs $\esopt$ that satisfies $\sum_{i \in [n]} \one[\max_{\theta \in \tilde \Theta_i} \tilde \val_i(\theta) \geq \esopt] = 3/\epsilon$. 
    We prove \Cref{lma:step2} by showing that the two required conditions are both satisfied with probability at least $1 - \epsilon$ for the value of $\esopt$ defined above. At a high-level, we show that with high probability the number of requests with highest value above $\esopt$ is at least $\epsilon^{-1}$ and at most $6\epsilon^{-1}$. Then, the first argument implies $\esopt \leq \opt$, and the second argument directly covers the second condition in \Cref{lma:step2}.


    We first prove that $\esopt \leq \opt$ with  probability at least $1 - \epsilon$. 
    Let $\eta_1$ be a value that satisfies $\E\big[\sum_{i \in [n]} \one[\max_{\theta \in \Theta_i} \val_i(\theta) > \eta_1]\big] = 1/\epsilon$. Note that it suffices to show $\esopt \leq \eta_1$ with high probability. This is because when $\esopt \leq \eta_1$, we have
    \[ \textstyle
    \opt ~\geq~ \eta_1  ~\geq~ \esopt.
    \]
    To see the first inequality, define random variables $X_i = \one[\max_{\theta \in \Theta_i}v_i(\theta) > \eta_1]$, and note that $\sum_{i \in [n]}\E[X_i] = 1/\epsilon$. Then, applying the (one-sided version of) Bernstein's inequality to the mean-zero random variables $\E[X_i] - X_i$ gives
    \[
    \textstyle 
    \pr\left( \sum_{i \in [n]} (\E[X_i] - X_i)  \geq \frac{1}{2\epsilon}\right) ~\leq~ \exp\left( - \frac{1/8\epsilon^2}{\sigma^2 + 1/(3\epsilon)} \right) ~\leq~ 6\epsilon,
    \]
    where the final inequality uses $\sigma^2 = \sum_{i\in[n]}\sigma_i^2 \leq 1/\epsilon$ and $\epsilon \leq 0.1$. Thus, $\opt \geq (1-6\epsilon) \cdot \frac{1}{2\epsilon} \cdot \eta_1 \geq \eta_1$, which again uses $\epsilon \leq 0.1$.
    Further, note that 
    \begin{align*}\textstyle
        \pr\left(\esopt > \eta_1 \right) ~\leq~ \pr\left(\sum_{i \in [n]} (X_i - \E[X_i]) \geq \frac{3}{\epsilon} - \frac{1}{\epsilon}\right) ~\leq~ \exp\left(-\frac{4 /(2\epsilon^2)}{\sigma^2 + 2/(3  \epsilon)} \right) ~\leq~ \epsilon,
    \end{align*}
    which again uses $\sigma^2 = \sum_{i\in[n]}\sigma_i^2 \leq 1/\epsilon$ and $\epsilon \leq 0.1$.
    Therefore, we have $\esopt \leq \opt$ with probability at least $1 - \epsilon$.
    %

    For the second condition, we define $\eta_2$ to be a value that satisfies $\E\big[\sum_{i \in [n]} \one[\max_{\theta \in \Theta_i} \val_i(\theta) > \eta_2]\big] = 6/\epsilon$. 
    Then, we define random variables $Y_i = \one[\max_{\theta \in \Theta_i} \val_i(\theta) > \eta_2]$, and note $\sum_{i \in [n]} \E[Y_i] = 6/\epsilon$. Let $\sigma_2^2 := \E[(Y_i - \E[Y_i])^2]$. 
    Observe that $\sigma_2^2 \leq \sum_{i \in [n]} \E[Y_i] = 6/\epsilon$, and
    that it suffices to show $\esopt \geq \eta_2$ with high probability. 
    This is because when $\esopt \geq \eta_2$, we have
    \begin{align*}\textstyle
        \pr\left(\sum_{i \in [n]} \one\left[\max_{\theta \in \Theta_i} \val_i(\theta) > \esopt\right] > 10\epsilon^{-1} \right) ~&\leq~ \textstyle\pr\left(\sum_{i \in [n]} \one\left[\max_{\theta \in \Theta_i} \val_i(\theta) > \eta_2\right] > 10\epsilon^{-1} \right) \\
        ~&=~\textstyle \pr\left(\sum_{i \in [n]} (Y_i  - \E[Y_i]) > \frac{10}{\epsilon} - \frac{6}{\epsilon}\right) \\
        ~&\leq~ \textstyle \exp \left(-\frac{16/(2\epsilon^2)}{6/\epsilon + 4/(3\epsilon)}\right) ~\leq~ \epsilon,
    \end{align*}
    where the penultimate inequality uses Bernstein's Inequality, and the last inequality holds when $\epsilon \leq 0.1$.
    It remains to show that $\pr(\esopt \geq \eta_2)$ is at least $1 - \epsilon$. This follows by applying  Bernstein's Inequality to variables $Y_{i} - \E[Y_i]$ as follows.
    \begin{align*}\textstyle
        \pr\left(\esopt < \eta_2 \right) ~=~ \pr\left(\sum_{i \in [n]} (Y_i - \E[Y_i]) \leq \frac{3}{\epsilon} - \frac{6}{\epsilon}\right) ~\leq~ \exp\left(-\frac{9 /(2\epsilon^2)}{\sigma_2^2 + 3/(3  \epsilon)} \right) ~\leq~ \epsilon,
    \end{align*}
    where the last inequality holds when $\epsilon \leq 0.1$.

    Finally, combining two statements with union bound proves \Cref{lma:step2}.
\end{proof}







%%%%%%%%%%%% Robustness %%%%%%%%%%

\section{Robustness in the Byzantine Secretary Model } \label{sec:robustness}
In this section, we show that the  
Exponential Pricing algorithm is robust to outliers: it achieves a $(1-\epsilon)$-approximation in the {Byzantine Secretary} model.


\subsection{Byzantine Secretary Model and Proof Overview}
We now formally describe an instance of online resource allocation in the Byzantine Secretary model \cite{BGSZ-ITCS20,AGMS-SODA22}.
There are two sets of requests:  $\numg$ green (stochastic or good) requests and  
$\numr$ red (adversarial or rogue) requests. 
Each green request $i$, represented by $\gamma_i = (\val_i, a_i, \Theta_i)$, arrives at a uniformly random time $t_i \sim U[0, 1]$, while
each red request $i$, represented by  $\gamma^\mathsf{R}_i = (\val^\mathsf{R}_i, a^\mathsf{R}_i, \Theta^\mathsf{R}_i)$, arrives at an adversarially chosen time $t^\mathsf{R}_i \in [0, 1]$. 
We assume that the adversary is oblivious,
so the model dynamics are as follows:
The adversary first decides the set of requests $\gamma _1, \ldots, \gamma _{\numg}$ and $\gamma^\mathsf{R}_1, \ldots, \gamma^\mathsf{R}_{\numr}$, and the arrival times $t^\mathsf{R}_1, \ldots, t^\mathsf{R}_{\numr}$
of the red requests. 
Then each green request is independently assigned a uniformly random arrival time $t _i \sim \text{Unif}[0, 1]$.
When a request arrives, the algorithm does not see the color (green
or red): it just sees the request and the time of arrival.
Our goal is to design a pricing algorithm that makes an irrevocable decision upon receiving a request,  subject to the given budget constraints.


We note that since the red requests are chosen adversarially and have adversarial arrival order, we cannot hope to get the value of the offline optimum on the red requests. 
As mentioned in \Cref{sec:introModel}, the best possible approximation in this case is $\Omega\left(n/B\right)$ 
even for the special case of a single resource.
Consequently, we  compare the performance of 
our algorithm to the expected offline optimum of the green requests. 
Specifically, we define the benchmark for our algorithm to be
\begin{align}
\label{program:ro}
\textstyle
    \opt ~:=~ \max_{\{\theta _i \in \Theta _i\}_{i \in [\numg]}} \sum_{i = 1}^{\numg} \val _i(\theta _i) ~\text{ s.t. } \sum_{i = 1}^{\numg} a _i(\theta _i) \leq \B .
\end{align}
Additionally, 
we assume that an estimate $\widehat{\opt}$ of $\opt$  is provided, with $\esopt \in [\frac{\opt}{\beta}, \opt]$. As argued in \cite{BGSZ-ITCS20}, such an assumption is necessary  since it is impossible to compare to unbounded $\opt$.


The main result of this section is a $(1-\epsilon)$-approximation in the Byzantine Secretary model, greatly improving the $\Omega(1)$-approximation of \cite{AGMS-SODA22} in the same setting.

\begin{Theorem}
\label{thm:romainori}
Given $\epsilon > 0$ and an estimate $\esopt \in \left[\frac{\opt}{\beta}, \opt\right]$, there exists a pricing algorithm for online resource allocation in the Byzantine Secretary model that obtains expected total value at least $\left(1 - O(\epsilon)\right) \cdot \opt$ when the  budget satisfies $B_{j} =  \Omega\left({\log(m\beta/\epsilon)}\cdot {\epsilon^{-2}}\right)$ for every $j \in [m]$. 
\end{Theorem}


\noindent\textbf{Proof Overview.} 
Our idea is to apply  Exponential Pricing to the Byzantine Secretary model. To facilitate this,  in \Cref{sec:disByz} we first transform the original Byzantine Secretary model into a ``discrete" model, converting the continuous time horizon 
$[0,1]$ into a finite number of time slots.

Once the Exponential Pricing algorithm is applied, the proof structure resembles that of  \Cref{thm:exp-pricing-estimates}. A key difference arises in  \eqref{eq:independent}  of that proof, where we rewrote   $\loss$ by moving the expectation inside the dot product. This step is only possible if the price vector  $\bprice_i$ is independent of the realization of request $\gamma_i$. However, 
in the Byzantine Secretary model, since the green requests arrive in random order, the realization of request $\gamma_i$ depends on previous requests, creating correlation with the corresponding price vector. 
To address this, we interpret the randomness in historical data as a ``sampling without replacement'' process and apply concentration inequalities for this type of sampling. Similar to previous work \cite{AGMS-SODA22, GM-MOR16}, we also restart the Exponential Pricing algorithm at the midpoint to further control the effects of dependencies.






\subsection{Discretized Byzantine Secretary Model}
\label{sec:disByz}


To prove \Cref{thm:romainori}, we first  reduce  the problem to solving a ``discretized'' version of the Byzantine Secretary model. 
Then, we show that an algorithm for online resource allocation in the discretized  model can be converted into an algorithm for online resource allocation in the original Byzantine Secretary model with a negligible loss in the value (see Lemma~\ref{lma:oritodisc} for a formal statement).




\medskip
\noindent\textbf{Model.}
The intuition behind discretizing the input is as follows.
Suppose we could 
break the time interval $[0, 1]$ into $T$ smaller intervals where $T \gg \numg + \numr$; 
now the $t$-th interval, or piece, represents the time $\big[(t - 1) \cdot \frac{1}{T}, t \cdot \frac{1}{T}\big)$,
then the intervals
containing green requests should contain 
at most one green request (with probability arbitrarily close to $1$).
Building on this intuition, we formally define an instance of online resource allocation in the discretized Byzantine Secretary model as follows.
Given an $\epsilon > 0$, we have $T > (\numg + \numr) / \epsilon$ time intervals. 
The adversary first decides the set of green requests $\gamma _1, \ldots, \gamma _{\numg}$. 
Then, the adversary selects intervals $R \subseteq [T]$ such that $|R| \leq \numr$, and for each $t \in R$ sets a red request 
$\gamma_t = (\val_t, a_t, \Theta_t)$.
Finally, the set of green requests are permuted uniformly at random amongst the time intervals 
in the set $[T] \setminus R$.
This gives a mapping $\pi : [\numg] \to [T] \setminus R$ which maps each one of the green requests to one of the remaining time intervals.
Without loss of generality, we 
use $\gamma _{i}$ to denote the request 
$\gamma_{\pi(i)} = (\val_{\pi(i)}, a_{\pi(i)}, \Theta_{\pi(i)})$
for $i \in [\numg]$.
For the intervals that are not assigned any request; that is, for $t \in [T] \setminus \left(\{\pi(i): i \in [\numg]\} \cup R\right)$, we set $\gamma_t$ to be 
a dummy request that only contains the null decision $\phi$.




\begin{Lemma}
\label{lma:oritodisc}
Suppose that 
we are given an algorithm for online resource allocation problem in the discretized Byzantine Secretary model
that achieves expected total value at least $\eta \cdot \opt$ when $T > \numg$ (the number of green requests).
Then,  
we can obtain an algorithm for 
online resource allocation problem in the Byzantine Secretary model
that achieves expected total value at least $(1 - \disceps) \cdot \eta\cdot\opt$, where $\opt$ equals the expected offline optimum of the green requests.
\end{Lemma}

\begin{proof}
Let $\A_d$ denote an algorithm for online resource allocation in the discretized Byzantine Secretary model. 
Now, consider an instance of  online resource allocation in the Byzantine Secretary model with $\gamma _1, \cdots, \gamma _{\numg}$ denoting the green requests, and $\opt$ denoting the offline optimum on these green requests.
The main idea is to appropriately select $T$ such that the resulting instance behaves like an instance of the discretized Byzantine Secretary model, and then to run $\A_d$ on this resulting instance. 

\medskip
\noindent{\bf Reduction.} We set $T = n^2/\disceps$ where $n = \numg + \numr$, and consider 
intervals of the form $\big[(t - 1) \cdot \frac{1}{T}, t \cdot \frac{1}{T}\big)$. 
Recall that the adversary first decides the set of requests $\gamma _1, \ldots, \gamma _{\numg}$ 
and 
$\gamma^\mathsf{R}_1, \ldots, \gamma^\mathsf{R}_{\numr}$, 
and the arrivals of the red requests; that is, $t^\mathsf{R}_1, \ldots, t^\mathsf{R}_{\numr}$, where  each $t_i^\mathsf{R} \in [0, 1]$.
Then each green request is independently assigned a uniformly random arrival time $t _i \sim \text{Unif}[0, 1]$.
We say that there is a \emph{conflict} if
a green request 
falls in an interval already containing another request (either red or green).
Note that the probability that a green request results in a conflict is at most $n/T$ (since at most $n$ intervals could contain other requests),
and by the union bound the probability of a conflict is at most $n^2/T$, which equals $\disceps$ by our choice of $T$. 
So, with probability at least $1 - \disceps$, each green request appears by itself in a time interval. 
We note that this is 
equivalent to selecting a random permutation $\pi$ as defined
in the discretized Byzantine Secretary model.
Furthermore, for a time interval that contains more than one red request, we keep only the first red request and discard the remaining. 
Lastly, for any empty interval, we assume that there is a dummy request with only the null decision $\phi$.


\medskip
\noindent{\bf Value.} From the previous discussion, with probability at least $1 - \disceps$, we have an instance of online resource allocation in the discretized Byzantine Secretary model with expected offline optimum of the green requests equal to $\opt$.
Running $\A_d$ gives us \emph{conditional} expected total value at least $\eta \cdot \opt$.
On de-conditioning, we get that the
expected total value is at least $(1 - \disceps)\cdot \eta \cdot \opt$. \end{proof}
%
Thus, our main result involves showing that there exists a nearly optimal pricing algorithm for online resource allocation in the discretized Byzantine secretary model.



\begin{Theorem}
\label{thm:romain}
Given $\epsilon > 0$, $T > {(\numg + \numr)}/{\epsilon}$, and an estimate $\esopt \in \big[\frac{\opt}{\beta}, \opt\big]$, there exists a pricing algorithm for the online resource allocation in the discretized Byzantine Secretary model that obtains expected total value at least $\left(1 - O(\epsilon)\right) \cdot \opt$ when budget satisfies $B_{j} =  \Omega\left(\frac{\log(m\beta/\epsilon)}{\epsilon^2}\right)$ for every $j \in [m]$, where $\opt$ represents the expected offline optimum of the green requests.
\end{Theorem}


Combining \Cref{thm:romain} with  \Cref{lma:oritodisc}  proves \Cref{thm:romainori}.

\subsection{Exponential Pricing for Discretized Byzantine Secretary}\label{sec:discByzantineSec}

In this section, we give the proof of \Cref{thm:romain}.  
As before, the algorithm uses the expected allocation of a given resource for each request. 
In the case of the Random-Order model (without corruptions), the expected allocation of resource $j \in [m]$ at time $t \in [T]$ of an optimal solution would be $B_j / T$.
Motivated by this, we find setting
$(1-\epsilon) \cdot B_j/T$
for every $t \in [T]$ and every $j \in [m]$ suffices, where the expected consumption is scaled down by a factor of $1 - \epsilon$ to avoid exhausting budget.
The prices are set according to~\eqref{eq:ora-ro-prices}. We note that the scaling factor in \eqref{eq:ora-ro-prices} is $\epsilon$, instead of the $\delta = \OTild(1/(\epsilon \cdot B_j))$  used in \Cref{alg:prsp}. Essentially, this change helps us avoid losing a $\log T$ factor in the large budget assumption. However, the corresponding $\log n$ factor in  \Cref{alg:prsp} is unavoidable due to the learning error from the single sample.

Given the prices, the $t$-th decision
involves playing a best-response decision.
Lastly, we set the following termination condition: if, for any $i \in [T/2]$, there exists $j \in [m]: \price_{t+1, j} = \initprice \cdot \exp\left(\epsilon \cdot \left(\sum_{s\leq t}\calg_{s, j} - t \cdot (1-\epsilon) \cdot B_j/T \right)\right) > \initprice \cdot  (m\beta/\epsilon)^8$, the algorithm stops/terminates. 
The algorithm restarts at $t = T/2 + 1$.


\begin{algorithm}
\caption{\textsc{Exponential-Pricing-Byzantine} ($\mathcal{I}, \epsilon, \widehat{\opt}$)}
\label{alg:ropip}
\begin{algorithmic}[1]
\For{$t = 1, \ldots, \frac{T}{2}$}
\State $(\val_t, a_t, \Theta_t) \gets $ $t$-th request 
\State $\bprice_t \gets $ vector denoting resource prices before $t$-th request arrives;
for $j \in [m]$, we set 
\begin{equation}\label{eq:ora-ro-prices}
\textstyle  \price_{t,j} \gets \initprice \cdot \exp\left(\epsilon \cdot \left(\sum_{s < t}\calg_{s, j} - (t-1)\cdot (1-\epsilon) \cdot B_j/T \right)\right)
\end{equation}
\qquad where  $\initprice \gets \epsilon^5 \cdot \esopt / m^4$
\State Take $\theta_t \in \arg \max_{\theta \in \Theta_t} \left(\val_t(\theta) - \langle \bprice_t, a_t(\theta) -  (1-\epsilon) \cdot \B/T \rangle\right)$, and the algorithm gains $\val_t(\theta_t)$.
\State Set vector $(\calg_{t,1}, \cdots, \calg_{t, m}) = a_t(\theta_t)$.
\If{ $\exists j \in [m]: \,$ $\price_{t+1, j} = \initprice \cdot \exp\left(\epsilon \cdot \left(\sum_{s\leq t}\calg_{s, j} - \frac{t \cdot (1-\epsilon)B_j}{T} \right)\right) > \initprice \cdot  (m\beta/\epsilon)^8$}
\State  \textbf{break}
\EndIf
\EndFor
\State Restart the algorithm for $t = \frac{T}{2} + 1, \ldots, T$.
\end{algorithmic}
\end{algorithm}


Now, we prove \Cref{thm:romain} by showing that \Cref{alg:ropip} is the desired algorithm.



\begin{proof}[Proof of \Cref{thm:romain}] In this proof, we assume $\epsilon \in [0,1/2]$ to be a fixed parameter, since the theorem is true for $\epsilon>1/2$.

To simplify notation, we define the vector 
\[
\ba^* ~=~ (a^*_1, \cdots, a^*_m) ~:=~ \frac{(1 - \epsilon) \cdot \B}{T},
\] which corresponds to the scaled expected budget consumption in each round. 
We first verify that \Cref{alg:ropip} is feasible. To do this, we first show that the first half of the algorithm
uses at most ${B_j}/{2}$ budget for any resource $j \in [m]$. Suppose not, then there exists $t \in [T/2]$ and $j \in [m]$ that satisfies 
    \[
    \sum_{s = 1}^t \calg_{s, j} ~>~ \frac{B_j}{2} ~\geq~ t \cdot a^*_j+ \frac{\epsilon \cdot B_j}{2}.
    \]
Then, we have
\begin{align*}
\price_{t, j} ~&=~ \initprice \cdot \exp \left( \textstyle \epsilon \cdot \left(\Big(\sum_{s = 1}^t \calg_{s, j} - t\cdot a^*_j\Big) - \Big(\calg_{t, j} - a^*_j\Big)\right)\right)\\
&>~ \initprice \cdot \exp \left( \textstyle \epsilon \cdot \left(\frac{\epsilon \cdot B_j}{2} - 1\right)\right) ~\geq~ \initprice \cdot  (m\beta/\epsilon)^8,
\end{align*}
where the last inequality holds when $B_j  \geq  {20\log (m\beta/\epsilon)}/{\epsilon^2}$.
Note that the above inequality leads to a contradiction (see the termination condition), and thus the first half of the algorithm uses budget at most $B_j / 2$ for every $j \in [m]$.


This observation implies that we can 
analyze the second half of \Cref{alg:ropip} in the same way as the first half, i.e., the first and second half of \Cref{alg:ropip} are symmetric. 
Let $\alg_{ro}$ be a random variable denoting the value obtained in the first half of \Cref{alg:ropip} (value collected until ${T}/{2}$). 
Then, it's sufficient to show $\E[\alg_{ro}] \geq (1 - O(\epsilon)) \cdot \frac{\opt}{2}$: the expected total value 
obtained by \Cref{alg:ropip} is $2 \cdot \E[\alg_{ro}] \geq (1 - O(\epsilon)) \cdot \opt$.

In order to analyze $\E[\alg_{ro}]$,  we define an event $\bev$ which corresponds to the event that for some $t \in [T/2]$ and $j \in [m]$:
$\price_{t+1, j} = \initprice \cdot \exp\left(\epsilon \cdot \left(\sum_{s\leq t}\calg_{s, j} - t \cdot a^*_j \right)\right) > \initprice \cdot  (m\beta/\epsilon)^8$; that is, termination condition of \Cref{alg:ropip} is satisfied.



We analyze $\E[\alg_{ro}]$ by thresholding $\pr(\bev)$. When $\pr(\bev)$ is large, the following lemma guarantees that our algorithm achieves a good value:

\begin{Lemma}
    \label{lma:bevlarge}
    If $\pr(\bev) \geq \epsilon$, then $\alg_{ro} \geq \opt$.
\end{Lemma}

The proof  of \Cref{lma:bevlarge} is based on the simple idea  that our algorithm gets a  large revenue (more than $\opt /\epsilon$)  when $\bev$ happens, as the price grows extremely high. Hence, we defer the  proof to \Cref{sec:lmabevlarge-proof}.



\Cref{lma:bevlarge} suggests that $\alg_{ro}$ is sufficiently large when $\pr(\bev)$ is large. It remains to discuss the case where $\pr(\bev) < \epsilon$.
In this case, the algorithm reaches the half-time with probability at least $1-\epsilon$. We will show 
that $\E[\alg_{ro}]$ is approximately $\big(1 - O(\epsilon)\big)\cdot \frac{\opt}{2}$. 

Let $\stoptime$ be a random variable denoting
the time that the algorithm stops. 
Under event $\bev$, we set $\stoptime$ to be the request after which the algorithm terminates. 
Otherwise, we set $\stoptime = T/2$ and have $\pr[\stoptime = T/2] = 1 - \pr(\bev)$.
Furthermore, let $\{\widetilde {\theta}_{t}\}_{t \in [T]}$ denote random decisions 
that follow the offline optimum decision with probability $1-4\epsilon$, i.e.,  we define 
\begin{align*}
    \widetilde \theta_t ~:=~ \left\{ 
    \begin{aligned}
        & \theta^{*}_i & \qquad & \text{with probability } ~1-4\epsilon~ \text{ when } \pi(i) = t,\\
        & \phi &\qquad  &\text{ if } t \notin G\text{ or } \text { or w.p. } 4\epsilon \text{ when } t \in G
    \end{aligned}
    \right.
\end{align*}
where $\{\theta^*_i\}$ denotes the optimal decisions made by the offline optimum on the green requests; that is, $\opt ~=~ \sum_{i = 1}^{\numg} \val _i(\theta^{*}_i).$

We start from decomposing $\alg_{ro}$ into utility and revenue:
\begin{align*} 
 \alg_{ro} ~=~ \textstyle\sum_{t = 1}^\stoptime \val_t(\theta_t) \, &= \,\, \underbrace{\textstyle\sum_{t = 1}^\stoptime \Big( \val_t(\theta_t) - \langle\bprice_t, a_t(\theta_t)\rangle \Big)}_{\mathsf{Utility}} \,\, + \,\, \underbrace{\textstyle\sum_{t = 1}^\stoptime \langle\bprice_t, a_t(\theta_t)\rangle}_{\mathsf{Revenue}} \\
 &\textstyle\geq~ \sum_{t = 1}^\stoptime \Big( \val_t(\widetilde{\theta}_{t}) - \langle\bprice_t, a_t(\widetilde{\theta}_{t})\rangle \Big) +  \sum_{i = 1}^\stoptime \langle\bprice_t, a_t(\theta_t)\rangle, \notag 
\end{align*}
where the inequality follows from the fact that decisions $\{\theta_t\}_t$ are performing best response. Taking the expectations for both sides of the above inequality and rearrange the terms, we have
\begin{align*}
   \textstyle  \E[\alg_{ro}] ~\geq~ \E\left[\sum_{t = 1}^\stoptime  \val_t(\widetilde{\theta}_{t})   \right] -  \E\left[\sum_{i = 1}^\stoptime \langle\bprice_t, a_t(\widetilde{\theta}_t) - a_t({\theta}_{t})\rangle \right] \enspace .
\end{align*}
The first term on the right hand side can be lower bound as
\[
 \E\Big[ \sum_{t = 1}^\stoptime \val_t(\widetilde{\theta}_t)\Big] ~=~ \sum_{t = 1}^{T/2} \E\Big[\val_t(\widetilde{\theta}_t) \cdot \one[\stoptime \geq t] \Big]
    ~=~\sum_{t =  1}^{T/2} \E\Big[\val_t(\widetilde{\theta}_t)\Big] \cdot \pr[\stoptime \geq t] \enspace ,
\]
where we use independence to obtain the second equality
since $\stoptime$ only depends on the history from $1$ to $t - 1$ and $\val_t(\widetilde{\theta}_t)$ depends only on the type of $t$-th request since it depends on the offline solution $\widetilde \theta_t$. This can be further simplified to obtain
\begin{align}
    \sum_{t =  1}^{T/2} \E\left[\val_t(\widetilde{\theta}_t)\right] \cdot \pr[\stoptime \geq t]&\geq~ \sum_{t =  1}^{T/2} (1 - \pr(\bev)) \cdot \E\left[\val_t(\widetilde{\theta}_t)\right] \notag \\
    &\geq~ (1 - \pr(\bev))\cdot (1 - 4\epsilon)\cdot\sum_{t =  1}^{T/2} \E\left[\val_t({\theta}^*_t)\right] \enspace . \label{eq:ro-case2-p1-1} 
 \end{align}

Finally, in order to bound $\sum_{t =  1}^{T/2} \E\left[\val_t({\theta}^*_t)\right]$ in terms of $\opt$, we bound the probability that a green request, say $\gamma_i $, contributes to the sum.
Towards this end, fix a green request $\gamma_i $, and note that
by the definition of $\widetilde \theta_t$,
this request contributes to the sum when $\pi(i) \leq T/2$. Note that
\[
\pr\left(\pi(i) ~>~ \frac{T}{2}\right) ~\leq~ \frac{{T}/{2}}{T - \numr} ~\leq~ \frac{1}{2\cdot(1-\epsilon)} \leq \frac{1}{2} + \epsilon,
\]
since there are $\numr$ red requests, and in the worst-case, they all occur in the first $T/2$ time intervals. The second inequality above uses $T \geq \numr/\epsilon$. So, we have
\begin{align}
   \sum_{t =  1}^{T/2} \E\left[\val_t({\theta}^*_t)\right] ~&=~ \sum_{i \in \numg} \val_i (\theta_i^{*}) \cdot \pr\left(\pi(i) \leq T/2\right) \geq~ \sum_{i \in \numg} \val_i (\theta_i^{*}) \cdot \left(\frac{1}{2} - \epsilon\right) ~=~ \left(\frac{1}{2} - \epsilon\right) \cdot \opt. \label{eq:ro-case2-p1-2}
\end{align}
%
Combining \eqref{eq:ro-case2-p1-1} and \eqref{eq:ro-case2-p1-2}, we get 
\[
\E\left[ \sum_{t = 1}^\stoptime \val_t(\widetilde{\theta}_t)\right] \geq  (1 - \pr(\bev))\cdot (1 - 4\epsilon)\cdot \left(\frac{1}{2} - \epsilon\right) \cdot \opt ~\geq~ (1 - 7\epsilon) \cdot \frac{\opt}{2},
\]
where the last inequality uses the assumption that $\pr(\bev) < \epsilon$.

So far, we have shown
\begin{equation}\label{eq:ro-part1}
    \E[\alg_{ro}] ~\geq~ (1 - 7\epsilon) \cdot \frac{\opt}{2} - {\E\Big[\sum_{t =  1}^{\stoptime} \langle \bprice_t,  a_t(\widetilde{\theta}_t) - a_t(\theta_t)   \rangle \Big]}. %_{\loss},
\end{equation}

As in the previous proofs, we interpret the last term in the above expression as the ``loss in revenue'' that arises from making the best-response decisions. 

\paragraph{Bounding the Loss in Revenue.}  We start by  splitting $\loss$ into two terms:
\[
\loss ~:=~ \E\Big[\sum_{t =  1}^{\stoptime} \langle \bprice_t,  a_t(\widetilde{\theta}_t) - a_t(\theta_t)   \rangle \Big]~=~ \E\Big[\sum_{t =  1}^{\stoptime} \langle \bprice_t,  a_t(\widetilde{\theta}_t) - \ba^*  \rangle \Big] + \E\Big[\sum_{t = 1}^{\stoptime} \langle \bprice_t, \ba^* - a_t(\theta_t) \rangle \Big],
\]
where we recall $\ba^* = \frac{1-\epsilon}{T} \cdot \B$ is the expected budget consumption per time step.

For the first term, note that we have $\E[a_t(\widetilde \theta_t)] \leq (1-4\epsilon) \cdot \B/(T - \numr) \leq 1 - 3\epsilon$, which is further upper-bounded by $\ba^*$. Therefore, ideally we wish to move the expectation into the dot product, and upper bound the first term by $0$. If we are in the stochastic Online Resource allocation model or if the green requests are i.i.d., the decision $\widetilde{\theta}_t$ can be made to depend only on the type of request $\gamma_t$, and is therefore independent of the price vector $\bprice_t$. However, when the green requests arrive in a random order, this random-order process brings an extra correlation between $\bprice_t$ and $\gamma_t$, preventing us from moving the expectation into the dot product. To fix this issue, we view the randomness of $\gamma_t$ as a sampling without replacement process, and further bound the first term as follows:

\begin{Lemma}
\label{lma:s-wo-r}
    We have 
    \[
    \E\Big[\sum_{t =  1}^{\stoptime} \langle \bprice_t,  a_t(\widetilde{\theta}_t) - \ba^*  \rangle \Big] ~\leq~ \epsilon \cdot \opt.
    \]
\end{Lemma}

The proof of  \Cref{lma:s-wo-r} requires concentration inequalities for sampling-without-replacement and is deferred   to \Cref{sec:lmaswor-proof}. To complete the proof of the theorem, it remains to bound
\[
\E\Big[\sum_{t = 1}^{\stoptime} \langle \bprice_t, \ba^* - a_t(\theta_t) \rangle \Big] ~=~ \sum_{j \in [m]} \E\Big[\sum_{t = 1}^\tau \lambda_{t, j} \cdot (a^*_j - \calg_{t, j})\Big] \enspace .
\]
We apply the no-regret property (\Cref{lem:noRegret}) of  Exponential Pricing  to every $j \in [m]$, which gives
\[
\sum_{t=1}^\stoptime \lambda_{t, j} \cdot (a^*_j - \calg_{t, j}) ~\leq~ \frac{2 \initprice}{\epsilon} + 4\epsilon \cdot \sum_{t = 1}^\stoptime \lambda_{t, j} \cdot \calg_{t,j}
\]
for every realization of the instance (note the change in sign). Taking the expectation and summing over all $j \in [m]$, we have 
\begin{align*}
    \E\Big[\sum_{t = 1}^{\stoptime} \langle \bprice_t, \ba^* - a_t(\theta_t) \rangle \Big] ~&\leq~ \frac{2m \initprice}{\epsilon} + 4\epsilon \cdot \E\Big[\sum_{t = 1}^\stoptime \sum_{j = 1}^m \lambda_{t,j} \cdot \calg_{t, j} \Big] ~\leq~ \epsilon \cdot \opt + 4\epsilon \cdot \E[\alg_{ro}] \enspace ,
\end{align*}
where the second inequality uses the fact that $2m \initprice/\epsilon \leq \epsilon \cdot \esopt \leq \epsilon \cdot \opt$ and that $\alg_{ro} \geq \sum_{t \in [\stoptime]} v_t(\theta_t) \geq \sum_{t \in [\stoptime]} \sum_{j \in [m]} \lambda_{t,j} \cdot \calg_{t, j}$ since the utility is always non-negative.

Finally, applying the above inequality and \Cref{lma:s-wo-r} to \eqref{eq:ro-part1} and rearranging, we have
\[
\E[\alg_{ro}] ~\geq~ \frac{1-11\epsilon}{1+4\epsilon} \cdot \frac{\opt}{2} ~\geq~ (1 - 15\epsilon) \cdot \frac{\opt}{2} \enspace ,
\]
which completes the proof of \Cref{thm:romain}.
\end{proof}

\subsection{Proof of Lemma~\ref{lma:s-wo-r} via Sampling Without Replacement}
\label{sec:lmaswor-proof}

In this subsection, we show $\E\left[\sum_{t =  1}^{\stoptime} \langle \bprice_t,  a_t(\widetilde{\theta}_t) - \ba^*  \rangle \right] \leq \epsilon \cdot \opt$. For simplicity of notation, we define vector $(\widetilde a_{t, 1}, \cdots, \widetilde a_{t, m}) = a_t(\widetilde \theta_t)$. This simplifies our target expression as
\[
\E\Big[\sum_{t =  1}^{\stoptime} \langle \bprice_t,  a_t(\widetilde{\theta}_t) - \ba^*  \rangle \Big] ~=~ \sum_{t \in [\stoptime] \setminus R} \sum_{j = 1}^m \E\left[\lambda_{t, j} \cdot \Big(\widetilde{a}_{t,j} - a^*_j \right)\Big].
\]


Now, we fix $t \in [\stoptime] \setminus R$ and $j\in [m]$, 
and give an upper bound for $\E\left[\lambda_{t, j} \cdot \left(\widetilde{a}_{t,j} - a^*_j \right)\right]$. 
To analyze this term, we \emph{condition} on the history, say $\calH$, until (and including) time $t-1$.
This includes the random realizations and decisions made until time $t-1$.
Given history $\calH$ until time $t-1$, the price vector $\bprice_t$ is deterministic, and we get:
\[
\E\left[\lambda_{t, j} \cdot \left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH\right] ~=~ \price_{t, j} \cdot \E\left[\left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH \right]
\]
It would be more accurate to denote the price as $\bprice_t(\calH)$ to make the dependence on $\calH$ explicit: we drop this when $\calH$ is clear from context. 
We crucially prove:
\begin{equation}\label{eq:ro-key-eq}
     \sum_{\calH} \pr(\calH) \cdot \E\left[\left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH \right] ~\leq~ \frac{4}{T } \cdot \left(\frac{\epsilon}{m\beta}\right)^{10},
\end{equation}
where $\pr(\calH)$ denotes the probability that history $\calH$ occurs.

Using conditional expectations, we can write
\begin{align}
    \E\left[\price_{t, j} \cdot \left(\widetilde{a}_{t,j} - a^*_j \right)\right] ~&=~ \sum_{\calH} \pr(\calH)\cdot  \E\left[\price_{t, j}(\calH) \cdot \left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH \right] \notag \\
    ~&=~ \sum_{\calH} \pr(\calH) \cdot \price_{t, j}(\calH) \cdot \E\left[\left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH \right]. \notag
\end{align}
Moreover, since $t \leq \stoptime$, it must be the case that $\price_{t, j} \leq \initprice\cdot (m\beta/\epsilon)^8$. Using this and \eqref{eq:ro-key-eq}, we get
\begin{align}
    \E\left[\price_{t, j} \cdot \left(\widetilde{a}_{t,j} - a^*_j \right)\right] ~\leq~  \initprice \cdot \left(\frac{m\beta}{\epsilon}\right)^8 \cdot \frac{4}{T} \cdot \left(\frac{\epsilon}{m\beta}\right)^{10} ~\leq~ \frac{4\initprice}{T}\cdot \left(\frac{\epsilon}{m\beta}\right)^2.\label{eq:ro-key-term-bd}
\end{align}

Summing \eqref{eq:ro-key-term-bd} over all $t \in [\stoptime]\setminus R$ and $j \in [m]$ gives:
\begin{align*}
\E\left[\sum_{t = 1}^{\stoptime} \langle \bprice_t, a_t(\widetilde{\theta}_t) - \ba^* \rangle \right] ~=~  \sum_{t\in [\stoptime] \setminus R}~ \sum_{j = 1}^m \E\left[\price_{t, j} \cdot \left(\widetilde{a}_{t,j} - a^*_j \right) \right] ~\leq~ T\cdot m \cdot \frac{4\initprice}{T}\cdot \left(\frac{\epsilon}{m\beta}\right)^2 ~\leq~ \epsilon \cdot \opt,
\end{align*}
where the last inequality uses that $\esopt \leq \opt$.


We complete the proof of Lemma~\ref{lma:s-wo-r} by proving~\eqref{eq:ro-key-eq}.


\paragraph{Proving Equation~\eqref{eq:ro-key-eq}.}
Recall the setting of Equation~\eqref{eq:ro-key-eq}. We fix $t \in [\stoptime] \setminus R$ and $j\in [m]$, 
and condition on the history $\calH$ until (and including) time $t-1$.
We want to show:
\[
    \sum_{\calH} \pr(\calH) \cdot \E\left[\left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH \right] ~\leq~ \frac{4}{T } \cdot \left(\frac{\epsilon}{m\beta}\right)^{10}.
\]

First, we decompose the LHS as follows.
\begin{align*}
\sum_{\calH}\pr(\calH)\cdot \E\left[\left(\widetilde{a}_{t,j} - a^*_j \right) \mid \calH \right] ~&=~ \sum_{\calH}\pr(\calH) \cdot \Big(\E[\widetilde{a}_{t,j}\mid \calH] -  a^*_{j} \Big) \\
&\leq~ \sum_{\calH}\pr(\calH)\cdot\Big(\E[\widetilde{a}_{t,j}\mid \calH]\Big)\cdot \one\Big[ \E[\widetilde{a}_{t,j}\mid \calH] \geq a^*_{j} \Big] \enspace .
\end{align*}


Let $A_{\overline \calH}$ be a set denoting the remaining green 
and dummy requests the do not appear in history $\calH$ (but excluding the red requests); so, $|A_{\overline \calH}| \geq T - (t-1) - \numr \geq T/4$ since $\numr < T/\epsilon$ and $\stoptime \leq T/2$. 
Since $t \in [\stoptime] \setminus R$,  the request $\gamma_t$ is chosen uniformly at random from $A_{\overline \calH}$: for any dummy request $\widetilde{a}_{t,j}= 0$, while for any green request $i \in A_{\overline \calH}$, we have $\widehat{a}_{t, j}  = \left(a_i(\theta^*_i) \right)_j \cdot (1 - 4\epsilon) \leq \left(a_i(\theta^*_i) \right)_j$. Since the sum of $\left(a_i(\theta^*_i) \right)_j$ for all $i \in [\numg]$ is at most $B_j$, while $|A_{\overline \calH}|$ is at least $T/4$, we have
\[
\E[\widetilde{a}_{t,j}\mid \calH] ~\leq~ \frac{4B_j}{T}.
\]
for any history $\calH$. This simplifies the bound above: we obtain
\begin{align*}
\sum_{\calH}\pr(\calH)\cdot \E\left[\left( \widetilde{a}_{t,j} -   a^*_{j} \right) \mid \calH \right] 
~&\leq~ \frac{4B_j}{T}\cdot \sum_{\calH}\pr(\calH)\cdot \one\Big[ \E[\widetilde{a}_{t,j}\mid \calH] \geq a^*_{j} \Big] \\
&=~ \frac{4B_j}{T}\cdot \pr_{\calH}\Big( \E[\widetilde{a}_{t,j}\mid \calH] \geq a^*_{j} \Big).
\end{align*}
We now show that $\pr_{\calH}\Big(\E[\widetilde{a}_{t,j}\mid \calH] \geq a^*_{j} \Big) ~\leq~ \left(\frac{\epsilon}{m\beta}\right)^{10} \cdot \frac{1}{B_j}$ to finish the proof. 
We demonstrate this bound by employing concentration bounds for the sample-without-replacement process.
{Indeed, observe that we can view $A_{\overline \calH}$ being generated as follows: from the set of all green and dummy requests, pick all but $|[t-1] \setminus R |$ requests uniformly at random, without replacement. The selected requests constitute $A_{\overline \calH}$ while the remaining requests appear (uniformly at random) in the first $t-1$ slots that do not contain any red requests. }%
Formally, we first define set $A_{\phi}$ to be the set containing all green and dummy requests, and let $u = |A_{\phi}| = T - \numr \geq (1-\epsilon)\cdot T$, $v = |A_{\overline \calH}| \geq T/4$, and $\mu = (1 - 4\epsilon) \cdot \frac{1}{u} \cdot \sum_{i \in [\numg]} \left(a_i(\theta^*_i)\right)_j$ denotes the \emph{unconditional} expected allocation, where the factor $1 - 4\epsilon$ is applied because the action $\widehat \theta_t$ is set to be null with probability $4\epsilon$ even if a green request arrives.
Using $u \geq (1-\epsilon)\cdot T$ and $\sum_{i \in [\numg]} \left(a_i(\theta^*_i)\right)_j \leq B_j$, we have 
\[
\mu ~\leq~ (1-4\epsilon) \cdot \frac{B_j}{(1 - \epsilon)\cdot T} ~\leq~ (1-3\epsilon)\cdot\frac{B_j}{T}.
\]
On simplifying, we obtain:
\begin{align}
\label{eq:ro-swor-mid}
    \pr_{\calH}\Big( \E[\widetilde{a}_{t,j}\mid \calH] ~\geq~ a^*_{j} \Big)  ~&=~ \pr_{\calH}\left( \E[\widetilde{a}_{t,j}\mid \calH] ~\geq~ (1 - \epsilon)\cdot\frac{B_j}{T} \right)\notag \\
    &\leq~ \pr_{\calH}\left( \E[\widetilde{a}_{t,j}\mid \calH] - (1-3\epsilon)\cdot\frac{B_j}{T} ~>~ \frac{\epsilon\cdot B_j}{T} \right)\notag\\
    ~&\leq~ \pr_{\calH}\left(\Big| \E[\widetilde{a}_{t,j}\mid \calH] - \mu\Big| > \frac{\epsilon \cdot B_j}{T}\right).
\end{align}

{Now, we use the following corollary of Bernstein's inequality for a sampling-without-replacement process (it is obtained by replacing sums with averages in \Cref{Bernstein}) to further bound \eqref{eq:ro-swor-mid}.

\begin{Corollary}
\label{cor:swor}
    Let $Y = \{y_1, \cdots, y_u\}$ be a set of real numbers in the interval $[0, M]$. Let $S$ be a random subset of $Y$ of size $v$ and let $\bar S = \frac{1}{v}\sum_{i \in S} y_i$ be the average of $S$. Setting $\mu = \frac{1}{u} \sum_{i} y_i$, we have for every $\disceps > 0$,
    \[
    \pr\left[\left|\bar S - \mu \right| \geq \disceps \right] ~\leq~ 2\cdot\exp \left(-\frac{v\disceps^2}{M(4\mu + \disceps)} \right).
    \]
\end{Corollary}
}


Applying \Cref{cor:swor} with $M = 1$ and $\disceps = \frac{\epsilon B_j}{T}$ implies
\begin{align}
\label{eq:ro-swor-mid2}
   \pr_{\calH}\left(\Big| \E[\widetilde{a}_{t,j}\mid \calH] - \mu\Big| > \frac{\epsilon \cdot B_j}{T}\right) ~&\leq~ 2\cdot\exp \left(-\frac{v \cdot \frac{\epsilon^2 B_j^2}{T^2}}{4 \mu + \frac{\epsilon B_j}{T}}\right) \notag \\
    ~&\leq~ 2\cdot\exp \left(- \frac{\epsilon^2 B_j^2}{16 \mu T + 4 \epsilon B_j} \right) ~\leq~ 2 \cdot \exp \left( - \frac{\epsilon^2 B_j}{40} \right),
\end{align}
where the second inequality uses $v \geq T/4$, and the third inequality uses $\mu \leq (1 + 2\epsilon) \cdot \frac{B_j}{T} \leq \frac{2B_j}{T}$.
To further simplify $2 \cdot\exp \left( - \frac{\epsilon^2 B_j}{40} \right)$, we define $q_j = B_j \cdot \frac{\epsilon^2}{400 \log (m\beta/\epsilon)} \geq 3$, which holds when $B_j \geq \frac{1200 \log (m\beta/\epsilon)}{\epsilon^2}$. Then, we have  
\begin{align*}
    2 \cdot\exp \left( - \frac{\epsilon^2 B_j}{40} \right) ~\leq~  \left(\frac{\epsilon}{m\beta}\right)^{10}   \cdot 2\cdot \left(\frac{\epsilon}{m\beta}\right)^{10q_j - 10} ~&\leq~
     \left( \frac{\epsilon}{m\beta}\right)^{10} \cdot 2\cdot \left( \frac{\epsilon}{m\beta}\right)^{10q_j - 13} \cdot \frac{\epsilon^2}{\log(m/\epsilon)}\\
    &\leq~ \frac{1}{\beta} \cdot \left( \frac{\epsilon}{m\beta}\right)^{10} \cdot 2\cdot \frac{1}{800q_j} \cdot \frac{\epsilon^2}{\log(m/\epsilon)} \\
    ~&=~  \left( \frac{\epsilon}{m\beta}\right)^{10} \cdot \frac{1}{B_j} \enspace ,
\end{align*}
where the second inequality uses $q_j \geq 3$ and $\epsilon \leq 0.5$ to conclude 
$(m\beta/\epsilon)^{10 q_j - 13} \geq  (1/0.5)^{5q_j} \geq 800 q_j$.
Finally, combining the above inequality with \eqref{eq:ro-swor-mid} and \eqref{eq:ro-swor-mid2} gives
\[
\pr_{\calH}\Big( \E[\widetilde{a}_{t,j}\mid \calH] ~\geq~ a^*_{j} \Big) ~\leq~ \left(\frac{\epsilon}{m\beta}\right)^{10} \cdot \frac{1}{B_j } \enspace , 
\]
which completes the proof.





\subsection{Proof of \Cref{lma:bevlarge}}
\label{sec:lmabevlarge-proof}

We finish the section by proving \Cref{lma:bevlarge} that the algorithm has total value at least $\opt$ when $\pr(\bev)$ is at least $\epsilon$.

Note that
when event $\bev$ occurs, say after request $\stoptime$ for resource $j^*$, the resulting price $\price_{\stoptime+1, j^*} > \initprice \cdot    (m\beta /\epsilon)^8$.
Similar to the analysis of \Cref{lemma:prob-ea-small}, we lower bound the revenue obtained from the {last one unit of resource $j^*$}. 
Specifically, we first note that $\sum_{\ell \leq \stoptime}\calg_{\ell, j^*} - \stoptime \cdot a^*_{j^*} \geq {8\log(m/\epsilon)}/{\epsilon}$, which is at least $1$. 
We define $\widehat{\ell}$ to be an index such that
$\sum_{\widehat{\ell} \leq i \leq \stoptime} \calg_{i, j^*} \in [1, 2]$: such an index always exists since at most one unit of a resource can be allocated for a given request.

Conditioned on $\bev$, and using $ \val_{\ell}(\theta_{\ell}) - \langle\price_\ell, a_\ell\rangle  \geq 0$ since $\phi \in \Theta_\ell$, 
we have
\begin{align*}
\textstyle\alg_{ro} &~=~ \sum_{\ell = 1}^\stoptime \val_\ell(\theta_\ell) ~\geq~  \sum_{\ell = 1}^\stoptime\sum_{j=1}^m \price_{\ell,j} \cdot \calg_{\ell, j} 
~\geq~ \sum_{\ell = \widehat{\ell}}^\stoptime\price_{\ell,j^*} \cdot \calg_{\ell, j^*} \enspace.  \\
\intertext{Substituting $\price_{\ell,j^*}$,  this can be simplified to}
\alg_{ro} &~\geq ~ \sum_{\ell=\widehat{\ell}}^\stoptime \initprice \cdot \exp\Bigg( \epsilon \Big( \sum_{i < \ell } \calg_{i, j^*} - (\ell-1)\cdot a^*_{j^*} \Big) \Bigg) \cdot \calg_{\ell, j^*}\\
&~\geq \sum_{\ell=\widehat{\ell}}^\stoptime \initprice \cdot \exp\Bigg( \epsilon \Big( \sum_{i \leq \stoptime } \calg_{i, j^*} - \stoptime\cdot a^*_{j^*} - \sum_{\ell \leq i \leq \stoptime} \calg_{i, j^*} \Big) \Bigg) \cdot \calg_{\ell, j^*} \enspace .
\end{align*}
Now using the termination condition and the fact that $1 \leq \sum_{\widehat{\ell} \leq i \leq \stoptime} \calg_{i, j^*} \leq 2$, we get
\begin{align*}
\alg_{ro}  
&~\geq~ \sum_{\ell=\widehat{\ell}}^{\stoptime}  \initprice \cdot \exp\Bigg( \epsilon \Big( \frac{8\log(m\beta/\epsilon)}{\epsilon} - 2 \Big) \Bigg) \cdot \calg_{\ell, j^*} ~\geq~ \initprice\cdot\left(\frac{m\beta}{\epsilon}\right)^6. 
\end{align*}
%where the final inequality follows holds when $B_j \geq \frac{12\log(m/\epsilon)}{\epsilon^2}$.
Hence, if $\pr(\bev) \geq \epsilon$ then
\begin{equation*}
    \E[\alg_{ro}] ~\geq~ \pr(\bev) \cdot \E[\alg_{ro} \mid \bev] ~\geq~ \epsilon \cdot\initprice\cdot\left(\frac{m\beta}{\epsilon}\right)^6 ~\geq~ \opt \enspace ,
\end{equation*}
where in the last inequality we use the fact that $\beta \cdot \esopt \geq \opt$.

\section{Robustness in the Prophet-with-Augmentations Model}
\label{sec:sub-augmentation}


In this section, we show that the Exponential Pricing algorithm 
is robust to augmentations,
and obtains a $(1-\epsilon)$ approximation in the 
Prophet-with-Augmentations model of \cite{immorlica2020prophet,AGMS-SODA22}.


\medskip
\noindent{\bf Prophet-with-Augmentations Model.} We are given a base instance of 
the general online resource allocation problem in the stochastic model from \Cref{sec:introModel} with \emph{known} distributions.
That is,  $n$ requests  arrive sequentially, where the $i$-th request $\gamma_i = (\val_i, a_i, \Theta_i)$ is independently drawn from a known distribution $\calD_i$.
The distribution $\calD_i$ is a distribution over $K$ request tuples
$\gamma_{i,1}, \ldots, \gamma_{i,K}$, where the $i$-th request is $\gamma_{i,k} = (\val_{i,k}, a_{i,k}, \Theta_{i,k})$ with probability $p_{i, k}$.
An \emph{oblivious} adversary fixes 
perturbation functions $\{r_{i, k}\}_{i \in [n], k \in [K]}$ such that 
$r_{i,k}: \Theta_{i,k} \to \R_{\geq 0}$. When request $i$ arrives with type $k$, the algorithm observes a perturbed request $(\val_{i, k} + r_{i, k}, a_{i,k}, \Theta_{i,k})$. 


To simplify notation, let the $i$-th request be $(\val_i+r_i, a_i, \Theta_i)$. After our posted pricing algorithm observes the perturbed request, it makes a best-response decision $\theta_i \in \Theta_{i}$. 
The algorithm receives the augmented value $\val_{i}(\theta_i) + r_{i}(\theta_i)$, and the
goal is to maximize total value, $\sum_{i = 1}^n \big( \val_i(\theta_i)+r_i(\theta_i) \big)$, subject to the budget constraints.
Crucially, the algorithm competes against the expected offline optimum of the base instance; that is, when there are no perturbations. 

The following is the main result of this section.

\begin{Theorem}\label{thm:onlineRA-aug}
    Given an $\epsilon > 0$, there exists a pricing algorithm  for online resource allocation in the Prophet-with-Augmentations model that obtains
    expected total value at least $\left(1 - O(\epsilon)\right)$ times the expected hindsight optimum with no perturbations, provided that $B_{j} = \Omega\left(\frac{\log(nm/\epsilon)}{\epsilon^2}\right) \, \forall j \in [m]$.
\end{Theorem}

\begin{proof} We assume $\epsilon \in [0,1/2]$ to be a fixed  parameter, since the theorem is true for $\epsilon>1/2$.

%[Proof of \Cref{thm:onlineRA-aug}]
 Our main idea is to run \Cref{alg:prsp} for the base instance. Since we know the base instance distributions, it's sufficient to run \Cref{alg:prsp} with the accurate value of $\opt$ and the optimal solution $x^*$ of $\lp((1 - \epsilon) \cdot \B)$, i.e., the estimates $\esopt$ and $\{\widehat a_{i,j}\}$ become $\opt$ and $\{a^*_{i,j}(x^*)\}$ respectively.


The proof is almost identical to the proof of \Cref{thm:exp-pricing-estimates}. We now describe the small changes needed to handle the adversarial augmentations. 
The only change to Algorithm~\ref{alg:prsp} is that the decision $\theta_i$ is computed as 
\begin{equation*}
\theta_i = \arg\max_{\theta \in \Theta_i} \Big( \val_i(\theta) + r_i(\theta) - \langle\bprice_i, a_i(\theta)\rangle \Big) \enspace.
\end{equation*}

In the proof, we still define $\EA$ to be the event that the budget constraint $ \sum_{\ell \leq i} \calg_{\ell, j} \,\, \geq \,\, \sum_{\ell \leq i}\cons^*_{\ell, j}(x) + \frac{1}{2}\epsilon\cdot B_j$ is violated. Since the adversary is oblivious, the probability $\pr(\EA)$ is still well defined. However, instead of bounding $\pr(\EA)$, we need to slightly change the argument by showing that our algorithm gains a value of at least $10\opt$ when $\pr(\EA) \geq \epsilon$. This is true because the proof of \Cref{lemma:prob-ea-small} implies that our algorithm gains a value of at least $\frac{10}{\epsilon} \cdot \opt$ when $\EA$ happens. 


For the case that $\pr(\EA) < \epsilon$, the changes in the analysis are mainly regarding the best response decision: since our algorithm picks $\theta_i$ that maximizes $\val_i(\theta) + r_i(\theta) - \langle \bprice_i, a_i(\theta) \rangle$, we have
\[
\val_i(\theta_i) + r_i(\theta_i) - \langle \bprice_i, a_i(\theta_i) \rangle ~\geq~ \val_i(\theta_i^*) + r_i(\theta_i^*) - \langle \bprice_i, a_i(\theta_i^*) \rangle ~\geq~ \val_i(\theta_i^*)  - \langle \bprice_i, a_i(\theta_i^*) \rangle,
\]
where the inequality uses the fact that $r_i$'s are non-negative. 
By summing over all $i \in [\tau]$, where random variable $\tau$ denotes after which the algorithm stops, and taking expectations, we get
\[
\E[\alg] ~=~ \E\Big[\sum_{i = 1}^\tau (\val_i(\theta_i) + r_i(\theta_i))\Big] ~\geq~ \E\Big[ \sum_{i = 1}^\tau \val_i(\theta^*_i)\Big] + \E\Big[\sum_{i = 1}^{\tau} \langle \bprice_i, a_i(\theta_i) - a_i(\theta^*_i)  \rangle \Big].
\]
Note that the above inequality is identical to \eqref{eq:for-augmentation}, and so is the remainder of the analysis.

Combining the two cases that $\pr(\EA) \geq \epsilon$ and $\pr(\EA) < \epsilon$ proves \Cref{thm:onlineRA-aug}. 
\end{proof}

