\section{Basic Probabilistic Inequalities}

\begin{Theorem}[Hoeffding's Inequality]
\label{Hoeffding}
Let $X_1,\ldots,X_N$ be independent random variables such that $a_i \leq X_i \leq b_i$. Let $S_N = \sum_{i \in [N]} X_i$. Then, for all $t > 0$, we have
$  \Pr{|S_N - \Ex{S_n}| \geq t} \leq 2\exp\big(-\frac{2t^2}{\sum_{i \in [n]} (b_i - a_i)^2}\big).$
This implies, that if $X_i$ are i.i.d.\,samples of random variable $X$, and $a = a_i, b = b_i$ for all $i \in [N]$, let  $\hat X := \frac{1}{N} \sum_{i \in [N]} X_i$, then for any $\varepsilon > 0$, we have
\[
    \pr\left(|\hat{X} - \Ex{X}| \geq \varepsilon\right) \leq 2 \exp \left(-\frac{2N\varepsilon^2}{(b-a)^2}\right).
\]
\end{Theorem}


\begin{Theorem}[Bernstein's Inequality for Bounded Variables]
\label{Bernstein-bounded}
Let $X_1, \ldots, X_N$ be independent mean-zero random variables such that $|X_i| \leq M$ for all $i$ and $\sigma^2 := \sum_{i \in [N]} \E[X^2_i]$. Then, for any $\varepsilon \geq 0$, % we have
\[
\pr \left(\sum_{i = 1}^N X_i \geq \varepsilon \right) \leq \exp\left(- \frac{\varepsilon^2/2}{\sigma^2 + M\varepsilon/3}\right) \quad \text{and} \quad \pr \left(\sum_{i = 1}^N X_i \leq -\varepsilon \right) \leq \exp\left(- \frac{\varepsilon^2/2}{\sigma^2 + M\varepsilon/3}\right) \enspace .
\]
\end{Theorem}

We also require the following Bernstein’s inequality for sampling-without-replacement:
\begin{Theorem}[see Corollary 2.4.2 in \cite{GM-MOR16} and Theorem 2.14.19 in \cite{weakConvergence}]
\label{Bernstein}
    Let $Y = \{y_1, \cdots, y_u\}$ be a set of real numbers in the interval $[0, M]$. Let $S$ be a random subset of $Y$ of size $v$ and let $Y_S = \sum_{i \in S} y_i$. Setting $\mu = \frac{1}{u} \sum_{i} y_i$, 
    %and $\sigma^2 = \frac{1}{u} \sum_i (y_i - \mu)^2$, 
    we have that for every $\tau > 0$,
    \[
    \pr\left[\left|Y_s - v \cdot \mu \right| \geq \tau \right] ~\leq~ 2\exp \left(-\frac{\tau^2}{M(4v\mu + \tau)} \right).
    \]
\end{Theorem}



\section{Missing Proofs from \Cref{sec:single-sample}}


\subsection{Proof of \Cref{clm:nottoomuch}}\label{app:clm-nottoomuch}

\clmnottoomuch*

\begin{proof}
Let $\ptt = \{S_1, \cdots, S_D\}$ be a partition chosen uniformly at random. 
To prove the claim, it suffices to show that for each group $S_d \in \ptt$, 
\[
\textstyle \sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} a_{i,k}(\theta) \cdot \tildx_{i,k,\theta} ~\leq~ (1 - 2\epsilon) \cdot \B/D 
\]
holds with probability $1 - \epsilon/D$. Applying the union bound over all groups completes the proof.

Fix $j \in [m]$. Let variable $X_{i, j} = \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} \left(a_{i,k}(\theta)\right)_j \cdot \tildx_{i,k, \theta}$. 
Then, we have $\sum_{i \in [n]} X_{i,j} \leq (1 - 3\epsilon) \cdot B_j$, which is guaranteed by the fact that $\tildx$ is a feasible solution for $\lp((1 - 3\epsilon) \cdot \B)$, and $X_{i,j} \in [0, 1]$, which follows from the fact that each request uses at most one unit of resource $j$. 
Note that the sum $\sum_{i \in S_d} \sum_{k \in [K]} \sum_{\theta \in \Theta_{i,k}} \left(a_{i,k}(\theta)\right)_j \cdot \tildx_{i,k, \theta}$ can be viewed as uniformly choosing $|S_d| = n/D$ samples from the pool $\{X_{i,j}\}_{i \in [n]}$ without replacement. Applying \Cref{Bernstein}, we get 
\begin{align}\textstyle
    \pr \Big(\sum_{i \in S_d} X_{i, j} - (1-3\epsilon) \cdot B_j/D \geq \epsilon \cdot B_j/D \Big) ~\leq~ \exp \left(-\frac{\epsilon^2 B^2_j/D^2}{1 \cdot (4B_j/D + \epsilon \cdot B_j/D)}\right) ~\leq~ \frac{\epsilon}{mD}, \label{eq:partitioncond}
\end{align}
where the last inequality holds when $B_j \geq \frac{10\log (mD/\epsilon) \cdot D}{\epsilon^2} \geq \frac{10\log (mn/\epsilon) \cdot D}{\epsilon^2}$, as there must be $D \leq n$.
Applying the above inequality to every $j \in [m]$ and combining them via union bound implies that \eqref{eq:partitioncond} holds simultaneously for every $j \in [m]$ with probability at least $1 - \epsilon/D$, as desired.
\end{proof}

\subsection{Proof of \Cref{clm:followtildx}}\label{app:clm-followtildx}

\clmfollowtildx*

\begin{proof}
Fix $S_d \in \ptt$, and let
$\{\gamma_i\}_{i \in S_d}$ denote the requests. 
Recall that $\tildz_{i, \theta}^{(d)} =\frac{\tildx_{i,k, \theta}}{p_{i,k}} \cdot \one[\type(i)=k]$, if Condition~\eqref{eq:condition} is satisfied, which requires:
\begin{align*}
\textstyle
    \sum_{i \in S_d} \sum_{\theta \in \Theta_i} a_i(\theta) \cdot \sum_{k \in [K]} \one[\type(i) = k] \cdot  \frac{\tildx_{i,k, \theta}}{p_{i,k}} \leq (1 - \epsilon) \cdot \B/D .%\label{eq:condition}
\end{align*}
Therefore, we have
\begin{align*}
\textstyle
\E_{\{\gamma_i\}} \Big[\sum\limits_{i \in S_d} \sum\limits_{\theta \in \Theta_i} v_i(\theta) \cdot \tildz^{(d)}_{i, \theta} \Big]
&=~ \textstyle{ \E_{\{\gamma_i\}}\Big[\sum\limits_{i \in S_d} \sum\limits_{k \in [K]} \sum\limits_{\theta \in \Theta_{i,k}} v_{i,k}(\theta) \cdot \frac{\tildx_{i, k, \theta}}{p_{i,k}} \cdot \one[\type(i) = k] \cdot \one[\eqref{eq:condition} \text{ holds}] \Big]} \\
~& \textstyle =~ \sum\limits_{i \in S_d}\sum\limits_{k \in [K]} \sum\limits_{\theta \in \Theta_{i,k}} v_{i,k}(\theta) \cdot\frac{\tildx_{i, k, \theta}}{p_{i,k}} \cdot \E_{\{\gamma_i\}}\big[  \one[\type(i) = k] \cdot    \one[\eqref{eq:condition} \text{ holds}]\big]
\end{align*}

We note that the events $\one[\type(i) = k]$ and $\one[\eqref{eq:condition} \text{ holds}]$ can be correlated, which prevents us from further decomposing the expectation above. 
To address this, we introduce the following condition for every $i \in S_d$.
\begin{align}
\textstyle
    \sum_{\ell \in S_d \setminus \{i\}} \sum_{k \in [K]} \sum_{\theta \in \Theta_\ell} \one[\type(\ell) = k] \cdot a_\ell(\theta) \cdot \frac{\tildx_{i, k, \theta}}{p_{\ell,k}} ~\leq~  (1 - 1.5\epsilon) \cdot \B/D. \label{eq:conditionnew}
\end{align}
Crucially, we note Condition \eqref{eq:conditionnew} implies  Condition \eqref{eq:condition}. 
This is because request $i$ can consume at most one unit of each resource, and we have $0.5 \epsilon \cdot B_j/D \geq 1$, which is true as long as $B_j \geq 2D/\epsilon$. 
Using the fact that Condition \eqref{eq:conditionnew} implies  Condition \eqref{eq:condition} and that the event $\one[\type(i) = k]$ and $\one[\eqref{eq:conditionnew} \text{ holds}]$ are independent, we get
\begin{align*}
\textstyle
    \E_{\{\gamma_i\}} \Big[\sum\limits_{i \in S_d} \sum\limits_{\theta \in \Theta_i} v_i(\theta) \cdot \tildz^{(d)}_{i, \theta} \Big]
    ~& \textstyle \geq~ \sum\limits_{i \in S_d} \sum\limits_{k \in [K]} \sum\limits_{\theta \in \Theta_{i,k}} v_{i,k}(\theta) \cdot \frac{\tildx_{i, k, \theta}}{p_{i,k}} \cdot \pr\left(\type(i) = k\right) \cdot \pr(\eqref{eq:conditionnew} \text{ holds}) \\
    & \textstyle =~\sum\limits_{i \in S_d}\sum\limits_{k \in [K]} \sum\limits_{\theta \in \Theta_{i,k}} v_{i,k}(\theta) \cdot \tildx_{i, k, \theta} \cdot \pr(\eqref{eq:conditionnew} \text{ holds}).
\end{align*}
Thus, it suffices to show that Condition~\eqref{eq:conditionnew} holds with probability at least $1-\epsilon$ to complete the proof of \Cref{clm:followtildx}.


Towards this end, we fix $j \in [m]$ and let random variable $X^{(d)}_{i, j}$ denote the amount of resource $j$ consumed by request $i \in S_d$, assuming request $i$ follows solution $\tildx$. 
That is, $X^{(d)}_{i, j}$ equals $\sum_{\theta \in \Theta_{i, k}} \left(a_{i,k}(\theta) \right)_j \cdot {\tildx_{i, k, \theta}}/{p_{i, k}}$ with probability $p_{i, k}$. 
Furthermore, let $\mu^{(d)}_{i,j}$ denote the expectation of $X^{(d)}_{i,j}$. 
Since $a_{i, k}(\theta) \in [0, 1]^m$ and $\ptt$ is an average partition with respect to $\tildx$, we have $X^{(d)}_{i, j} \in [0, 1]$ and $\sum_{i \in S_d} \mu^{(d)}_{i,j} \leq (1- 2\epsilon) \cdot B_j/D$.
We will apply Bernstein's inequality (\Cref{Bernstein-bounded}) to the mean-zero random variables $\{X^{(d)}_{i,j} - \mu^{(d)}_{i,j}\}_{i \in S_d}$. 
Let $\sigma^2 = \sum_{i \in S_d} \E[(X^{(d)}_{i,j} - \mu^{(d)}_{i,j})^2]$, and note that
\[\textstyle
\sigma^2 ~=~ \sum_{i \in S_d} \E[(X^{(d)}_{i,j})^2] - \sum_{i \in S_d} (\mu^{(d)}_{i,j})^2 ~\leq~ \sum_{i \in S_d} \E[X^{(d)}_{i,j} \cdot 1] - 0 ~\leq~ \sum_{i \in S_d} \mu^{(d)}_{i, j}.
\]
Then, Bernstein's inequality together with the fact that $\sum_{i \in S_d} \mu^{(d)}_{i, j} \leq (1 - 2\epsilon) \cdot B_j/D$ gives
\[\textstyle
\pr\Big(\sum_{\ell \in S_d \setminus \{i\}} X^{(d)}_{\ell, j} - (1-2\epsilon) \cdot \frac{B_j}{D} > 0.5\epsilon \cdot \frac{B_j}{D} \Big) ~\leq~ \exp\Big(-\frac{\epsilon^2 B_j^2/(4D^2)}{\sigma^2 + 1\cdot 0.5\epsilon B_j/(3D)}\Big) ~\leq~ \frac{\epsilon}{m},
\]
where the last inequality uses $\sigma^2 \leq \sum_{i \in S_d} \mu^{(d)}_{i, j} \leq B_j/D$, and it holds when $B_j \geq \frac{4 \log(m/\epsilon) \cdot D}{\epsilon^2}$. 

Finally, by applying the union bound over all $j \in [m]$, we can conclude that Condition \eqref{eq:conditionnew} holds with probability at least $1 - \epsilon$.
\end{proof}



\section{Lower Bound for Prophet Model}
\label{sec:hardnessExample}

We prove our lower bound on the budgets needed to obtain a $(1-\epsilon)$-approximation for online resource allocation  with \emph{known} input distributions (prophet model), as claimed in \Cref{sec:results-single-sample}.

\begin{Theorem}
\label{thm:lower}
    In online resource allocation  with known input distributions, there exist instances with
    $B_j  = (\log m)/\epsilon^2$ for all resources $j \in [m]$, for which no online algorithm can achieve a competitive ratio better than $(1 - \Omega( \epsilon))$.
\end{Theorem}





\medskip \noindent \textbf{The hard instance.} The instance follows the instance given in \cite{AWY-OR14} for the random-order model.
We consider the setting of online combinatorial auctions, a special case of online resource allocation, where a sequence of $n$ buyers arrive for $m$ kinds of items/resources. 
For simplicity in describing the hard instance, we assume that $m = 2^z$, and number items from $0$ to $m - 1$. % instead of from $1$ to $m$. 
Each item has $B = \log m/\epsilon^2$ copies, implying $\epsilon = \sqrt{z/B}$.

In our hard instance, each buyer is \emph{single-minded}: buyer $i$ has a valuation function given by $f_i(S) = c_i \cdot \mathbf{1}[S_i \subseteq S]$, where $S_i$ is a fixed and $c_i \in \R_{\geq 0}$ could be random (i.e., they have value $c_i$ if they receive a superset of $S_i$). Each buyer belongs to one of the following \emph{types}, indexed by $l \in [z]$:
\begin{itemize}
    \item Type $A_l$: interested in the $m/2$ items $j \in \{0, \dots, m - 1\}$ whose $l$-th bit is $1$.
    \item Type $B_l$: interested in the $m/2$ items $j \in \{0, \dots, m - 1\}$ whose $l$-th bit is $0$.
\end{itemize}
Exactly $3B + \sqrt{Bz}$  buyers arrive sequentially, divided into 3 groups (with lower-numbered groups arriving earlier; the intra-group order is irrelevant for the hardness).

\begin{itemize}
    \item Group 1: $\sqrt{B/z}$ buyers of type $A_l$ arrive, for each $l \in [z]$, each with $c_i = 2$.
    \item Group 2: $2B/z$ buyers of type $A_l$ arrive, for each $l \in [z]$; the valuation $c_i$ is randomly chosen to be either $1$ or $3$, each with a probability of $0.5$.
    \item Group 3: $B/z$ buyers of type $B_l$ arrive, for each $l \in [z]$, each with $c_i = 4$.
\end{itemize}

Let $\opt$ denote the expected value achieved by the optimal offline algorithm for this instance.
We begin with a couple of observations.

\begin{Observation}\label{fac:opt-range}
    We have $5B \leq \opt \leq 7B$.
\end{Observation}
\begin{proof}

    First, note that for each $l \in [z]$, buyers of type $A_l$ and $B_l$ are interested in disjoint sets of items.
    Thus, for every realization of the instance, we can allocate items to all $B/z$ buyers of type $B_l$ and to any $B/z$ buyers of type $A_l$, for all $l \in [z]$.  
    This results in an allocation with $B$ buyers receiving value $4$ and another $B$ buyers receiving value  at least $1$, implying that  $\opt \geq 5B$.



    For the upper bound, note that the instance has a total of $B \cdot m$ items, and each buyer is interested in exactly $m/2$ items. 
    Therefore, any allocation can serve at most $2B$ buyers. Since at most $B$ of these can have value $4$ and the rest have  value at most $3$, it follows that $\opt \leq 7B$.
\end{proof}

\begin{Observation} \label{fac:common}
    For every subset $Y \subseteq [z]$, there is an item that is of interest to every buyer of type $A_l$ with $l \in Y$ and every buyer of type $B_{l'}$ with $l' \notin Y$.
\end{Observation}
\begin{proof}
    Consider item $j$ such that the $l$-th bit of $j$ is $1$ and the $l'$-th bit is 0, where $l \in Y$ and $l' \notin Y$. Then, by the definition of buyer types, \Cref{fac:common} follows.
\end{proof}

\smallskip \noindent \textbf{Online algorithms with more power.}  To prove \Cref{thm:lower}, we show that no online algorithm can achieve an expected reward greater than $(1 - 10^{-3} \cdot \epsilon) \cdot \opt$ for the above instance, even if we give the online algorithm more power.
Specifically, we assume that the online algorithm is able to make decisions based on the following \emph{two-stage arrival}:
\begin{itemize}
    \item Stage 1: All buyers in Group 1 arrive simultaneously. The algorithm needs to immediately decide how many buyers of type $A_l$ and value $2$ to pick. Let $q_l$ denote the number of type $A_l$ buyers the algorithm picks in this stage.

    \item Stage 2: All buyers in Groups 2 and 3 arrive simultaneously. After fixing $\{q_l\}_{l \in [z]}$ and the randomness in Group 2, the optimal allocation can be solved offline. Let $r_l$ be the number of type $A_l$ buyers the algorithm picks in this stage.
\end{itemize}

\noindent Note that Stage~1 is deterministic. We first show that the optimal allocation for Stage~2 must satisfy the following property.
\begin{Claim}
\label{clm:lower-equal}
    Fix $\{q_l\}_{l \in [z]}$ and the randomness in Group 2. Then, the optimal allocation $\{r_l\}_{l \in [z]}$ in Stage~2 must satisfy $q_l + r_l = B/z$ for each $l \in [z]$.
\end{Claim}

\begin{proof}
    We first show that $q_l + r_l \leq B/z$ for each $l \in [z]$.  
    Towards a contradiction, let $Y \subseteq [z]$ such that $Y = \{l \in [z] : q_l + r_l > B/z \}$. 
    Without loss of generality, assume that $Y \neq \emptyset$.
    We begin by giving an upper bound on the number of buyers from Group 3 (i.e., buyer of type $B_l$ for $l \in [z]$) that can be served. 
    As a consequence of \Cref{fac:common}, there exists an item $j_Y$ that is of interest to every buyer of type $A_l$ and every buyer of type $B_{l'}$ where $l \in Y$ and $l' \notin Y$. Since $\sum_{l \in Y}(q_l + r_l)$ copies of $j_Y$ have already been allocated, the algorithm can serve at most $B - \sum_{l \in Y}(q_l + r_l)$ buyers of type $B_{l'}$ where $l' \notin Y$. Since there are exactly $B/z$ buyers of type $B_l$ for each $l \in [z]$, the total number of buyers from Group 3 that can be served is at most $\sum_{l \in Y}B/z + B - \sum_{l \in Y}(q_l + r_l) = B - \sum_{l \in Y}(q_l + r_l - B/z)$.


    We now modify the solution $\{r_l\}_{l \in [z]}$ as follows: we set $\hat{r}_l = B/z-q_l$ if $l \in Y$, else, $\hat{r}_l = r_l$.
    Then, the total loss (resulting from dropped buyers of type $A_l$) is at most $3 \cdot \sum_{l \in Y} (q_l + r_l - B/z)$.
    However, note that after the modification, we have $q_l + \widehat{r}_l \leq B/z$ for each $l \in [z]$. 
    This implies that buyers from Groups 1 and 2 use at most $B/2$ copies of each item. Consequently, all buyers from Group 3 (with value 4) can be served, resulting in a gain of at least $4 \cdot\sum_{l \in Y} (q_l + r_l - B/z)$. This leads to a gain of at least  $\sum_{l \in Y} (q_l + r_l - B/z) > 0$, which contradicts the optimality of $\{r_l\}_{l \in [z]}$.


    Finally, we show that in any optimal allocation, it must hold that $q_l + r_l = B/z$ for each $l \in [z]$. 
    This follows from the observation that if $q_l + r_l \leq B/z$ for each $l \in [z]$,
    then even after serving $B/z$ buyers of type $A_l$ (note Group 2 contains $2B/z$ buyers of type $A_l$) and all $B/z$ buyers of type $B_l$, the algorithm uses at most $B$ copies of each item.
    %even if we satisfies $B/z$ buyers with type $B_l$ and $B/z$ buyers with type $A_l$. 
    Therefore, the greedy principle guarantees that the optimal allocation must fully utilize this capacity, implying $q_l + r_l = B/z$ for each $l \in [z]$.
\end{proof}

\paragraph{Proving \Cref{thm:lower}.} 
With \Cref{clm:lower-equal}, the optimal strategy of the two-stage online algorithm is clear: allocate to all type $B_l$ buyers with value $4$ and to $B/z$ type $A_l$ buyers, for every $l \in [z]$. 
However, since buyers in Group 1 arrives first, the online algorithm cannot predict the number of type $A_l$ buyers with value $3$. 
Consequently, the algorithm is unable to select the top $B/z$ type $A_l$ buyers, incurring a loss relative to the offline optimum. To formalize this, we state the following claim, which follows from standard anti-concentration properties of the binomial distribution.

\begin{Claim}
    \label{clm:lower-anticon}
    For every $l \in [z]$, with probability at least $0.2$, there are at least $B/z + 0.2 \sqrt{B/z}$ type $A_l$ buyers with value $3$. Symmetrically, with probability at least $0.2$, there are at most $B/z - 0.2 \sqrt{B/z}$ type $A_l$ buyers with value $3$.
\end{Claim}
\begin{proof}
    For simplicity of the notation, we define $N = B/z$ and assume $N$ is an integer. Then, the distribution of type $A_l$ buyers in Group 2 with value $3$ follows from a Binomial distribution $Bin(2N, 0.5)$.  Since $Bin(2N, 0.5)$ is symmetric, to prove \Cref{clm:lower-anticon}, it's sufficient to prove that
    \begin{align}
        \mathop{\pr}\limits_{x \sim Bin(2N, 0.5)}\left[N - 0.2\sqrt{N} \leq x \leq N + 0.2 \sqrt{N}\right] ~\leq~ 0.6 \label{eq:lower-tmp}
    \end{align}
    Since the binomial coefficient of $Bin(2N, 0.5)$ is maximized when $x = N$, we have
    \begin{align}
        \mathop{\pr}\limits_{x \sim Bin(2N, 0.5)}\left[N - 0.2\sqrt{N} \leq x \leq N + 0.2 \sqrt{N}\right] ~&\leq~ \mathop{\pr}\limits_{x \sim Bin(2N, 0.5)}\left[x = N\right] \cdot (0.4\cdot \sqrt{N} + 1) \notag \\
        ~&\leq~ \frac{\binom{2N}{N}}{2^{2N}} \cdot 0.5\sqrt{N}, \label{eq:binom-coeff}
    \end{align}
    where the last inequality holds when $N$ is sufficiently large. 
    Thus, it suffices to show that
    $\binom{2N}{N} \cdot \sqrt{N} ~\leq~ 1.2 \cdot 2^{2N}$.
    We proceed by using Stirling's approximation (see \cite{stirling}) to bound $\binom{2N}{N}$. For every positive integer $N$, we have
    \[
\sqrt{2\pi N} \cdot \left(\frac{N}{e}\right)^N \cdot e^{\frac{1}{12N + 1}} ~<~ N! ~<~ \sqrt{2\pi N} \cdot \left(\frac{N}{e}\right)^m \cdot e^{\frac{1}{12N}}.
\]
Plugging the above inequalities in the equation $\binom{2N}{N} = \frac{(2N)!}{(N!)^2}$, we get
\[
\binom{2N}{N} ~<~ \frac{4^N}{\sqrt{\pi \cdot N}} \cdot \frac{e^\frac{1}{24N + 1}}{e^\frac{1}{6N}} ~\leq~ \frac{4^N}{\sqrt{\pi \cdot N}},
\]
which when plugged into \eqref{eq:binom-coeff} completes the proof of the claim. \qedhere 
\end{proof}


Now, we can complete the proof of  \Cref{thm:lower}. 
\begin{proof}[Proof of \Cref{thm:lower}]
Fix an online algorithm that has more power to make decisions based on the two-stage arrival process and satisfies \Cref{clm:lower-equal}. 
We define $X \subseteq [z]$ to be the subset of types such that $q_l  \geq 0.1 \cdot \sqrt{B/z}$. Then, either $|X| > z/2$, or $|X| \leq z/2$. 

When $|X| > z/2$, \Cref{clm:lower-anticon} implies that for every $l \in X$, with probability at least $0.2$, there are at least $B/z + 0.2 \sqrt{B/z} > B/z$ type $A_l$ buyers with value $3$. 
The optimal offline algorithm can allocate to $B/z$ buyers of type $A_l$ and value $3$, by foregoing type $A_l$ buyers from Group 1.
Consequently, the optimal offline allocation gains at least $(3 - 2) \cdot 0.1 \sqrt{B/z} = 0.1 \sqrt{B/z}$ more than the online algorithm from type $A_l$ buyers. Therefore, when $|X| > z/2$, the value of the online algorithm is at least $0.2 \cdot \frac{z}{2} \cdot 0.1\sqrt{B/z} = 0.01 \sqrt{Bz}$  less than $\opt$.

When $|X| \leq z/2$, \Cref{clm:lower-anticon} implies that for every $l \in [z] \setminus X$, with probability at least $0.2$, there are at most $B/z - 0.2 \sqrt{B/z}$ type $A_l$ buyers with value $3$. Since \Cref{clm:lower-equal} guarantees that the online algorithm allocates to $B/z$ buyers of type $A_l$, for $l \in [z] \setminus X$, the online algorithm picks at least $B/z - (B/z - 0.2 \sqrt{B/z}) - 0.1\sqrt{B/z} = 0.1\sqrt{B/z}$ type $A_l$ buyers with value $1$. 
However, the optimal offline allocation can replace each value $1$ buyer with a  buyer with value $2$, and obtain at least $(2 - 1) \cdot 0.1 \sqrt{B/z} = 0.1 \sqrt{B/z}$ more value  than the online algorithm from type $A_l$ buyers. 
Therefore, when $|X| \leq z/2$, the value of the online algorithm is also at least $0.2 \cdot \frac{z}{2} \cdot 0.1\sqrt{B/z} = 0.01 \sqrt{Bz}$  less than $\opt$.

To conclude, we show that no online algorithm can achieve an expected value more than $\opt - 0.01 \sqrt{Bz}$, even the online algorithm is equipped with more power to make decisions. 
Recall that \Cref{fac:opt-range} gives $5B \leq \opt \leq 7B$ and $\epsilon$ is defined as $\sqrt{z/B}$, which implies,
\[
\opt - 0.01\sqrt{Bz} ~\leq~ (1 - 10^{-3} \cdot \epsilon) \cdot \opt \enspace . \qedhere
\]
\end{proof}




