  \begin{minipage}{\linewidth}
      \centering
      \subfloat[BLE 4 operational mode.]{
          \includegraphics[width=0.65\linewidth]{BLE4operation.pdf}
          \label{fig:legacyoperation}
      }\vspace{-2mm}
      \vfill
