\section{Proofs of Theorems} \label{appendix_proof}
%%%%%%%% Theorem 1
\begin{theorem}
With the iterative LIF model and tdBN method, assuming normalized pre-synaptic input $I \sim N(0, (V_{th})^2)$, we have $\Bar{I} \sim N(\Bar{\beta}, (\Bar{\gamma} V_{th})^2)$ after affine transformation, where $\Bar{\beta} = \frac{1}{C} \sum_{c=1}^C \beta_c$ and $\Bar{\gamma} = \frac{1}{C} \sum_{c=1}^C\gamma_c$, $C$ is the channel size of tdBN layer.
\end{theorem}

\begin{proof}
Perform an affine transformation of pre-synaptic inputs $I$, which gives
\begin{equation}
    \Bar{I} \sim
    \begin{cases}
    x_1 = N(\beta_1, (\gamma_1 V_{th})^2) \\
    x_2 = N(\beta_2, (\gamma_2 V_{th})^2) \\
    \quad \quad \quad \quad \vdots \\
    x_C = N(\beta_C, (\gamma_C V_{th})^2), 
    \end{cases}
\end{equation}
where $x_c \in \mathbb{R}^{N\times T\times H\times W}$ represents the pre-synaptic inputs at channel $c$ with $N$: batch axis, $T$: timestep axis, $(H, W)$: spatial axis. The expectation and variance of $\Bar{I}$, as follows \cite{duan2022temporal}:
\begin{align}
    \mathbb{E}[\Bar{I}] &= \frac{1}{C}(\beta_1 + \beta_2 + \cdots + \beta_C) = \frac{1}{C} \sum_{c=1}^C \beta_c, \\
    \mathbb{VAR}[\Bar{I}] &= \frac{1}{C}(\gamma_1^2 + \gamma_2^2 + \cdots + \gamma_C^2) (V_{th})^2.
\end{align}
According to the Cauchy-Schwarz Inequality, we have
\begin{equation}
    \frac{1}{C}(\gamma_1^2 + \gamma_2^2 + \cdots + \gamma_C^2) \ge (\frac{\gamma_1 + \gamma_2 + \cdots + \gamma_C}{C})^2 = (\frac{1}{C} \sum_{c=1}^C \gamma_c)^2.
\end{equation}
Finally, by initializing the pair of parameters $\gamma$ and $\beta$ with 1 and 0, we can get $\mathbb{E}[\Bar{I}] = \Bar{\beta}$ and $\mathbb{VAR}[\Bar{I}] \approx (\Bar{\gamma} V_{th})^2$, i.e., $\Bar{I} \sim N(\Bar{\beta}, (\Bar{\gamma} V_{th})^2)$, where $\Bar{\beta} = \frac{1}{C} \sum_{c=1}^C \beta_c$ and $\Bar{\gamma} = \frac{1}{C} \sum_{c=1}^C\gamma_c$, $C$ is the channel size of tdBN layer.
\end{proof}


%%%%%%%% Theorem 2
\begin{theorem}
Consider an SNN with $T$ timesteps, the pre-synaptic input of neurons injected into the tdBN layer with affine transformation is normalized to satisfy $\Bar{I} \sim N(\Bar{\beta}, (\Bar{\gamma} V_{th})^2)$, we have the membrane potential $\Bar{V} \sim N(\Bar{\beta}, (\Bar{\gamma} V_{th})^2)$ when $t=1$, and $\Bar{V} \sim N((1+\tau)\Bar{\beta}, (1+\tau^2)(\Bar{\gamma} V_{th})^2)$ when $t>1$, where $t \in T$.
\end{theorem}

\begin{proof} 
Assuming the last firing time of $t'$, the membrane potential of iterative LIF model at $t$-th timestep can be expressed by
\begin{equation}
    \Bar{V}(t)=\sum_{k=t'}^t\tau^{t-k}\Bar{I}(k),
\end{equation}
where $\Bar{I}$ denotes the pre-synaptic input after affine transformation. $\tau$ is the decay factor of LIF models. In our SNN model, we set all $\tau$ to 0.2. When $t=1$, neurons are in the resting state, $\Bar{V}$ equals the pre-synaptic input at the initial moment. When $t>1$, $\Bar{V}$ equals the residual membrane potential of the previous moment plus the pre-synaptic input at the current moment. Then, we have

\begin{equation}\label{equation25}
    \Bar{V}(t) \approx \begin{cases}\Bar{I}(t),  &t=1\\ 
    \tau \Bar{I}(t-1)+\Bar{I}(t), &t >1\end{cases}
\end{equation}

According to \textbf{Theorem 1}, $\Bar{I}$ can be assumed as $i.i.d$ sample from $N(\Bar{\beta}, (\Bar{\gamma} V_{th})^2)$ \cite{zheng2021going}. Based on Eq. \ref{equation25}, we can express the mean and variance of $\Bar{V}$ as
\begin{equation}
\begin{aligned}
    \mathbb{E}[\Bar{V}] &\approx \begin{cases}\mathbb{E}[\Bar{I}] = \Bar{\beta},  &t=1\\ (1+\tau)\mathbb{E}[\Bar{I}] = ( 1+\tau) \Bar{\beta}, &t>1\end{cases}
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
    \mathbb{VAR}[\Bar{V}] &\approx \begin{cases}\mathbb{VAR}[\Bar{I}] = (\Bar{\gamma} V_{th})^2, &t=1\\ (1 + \tau^2)\mathbb{VAR}[\Bar{I}] = (1+\tau^2)(\Bar{\gamma} V_{th})^2, &t>1\end{cases}
\end{aligned}
\end{equation}
Finally, we can get the membrane potential $\Bar{V} \sim N(\Bar{\beta}, (\Bar{\gamma} V_{th})^2)$ when $t=1$, and $\Bar{V} \sim N((1+\tau)\Bar{\beta}, (1+\tau^2)(\Bar{\gamma} V_{th})^2)$ when $t>1$, where $t \in T$.
\end{proof}


\section{Experiment}
\subsection{Time Efficiency}
To evaluate the time overhead introduced by our method, we conducted experiments using ResNet19 on the CIFAR10 dataset. Table~\ref{Tab::time_efficiency} compares the running time of one epoch at 2 timesteps and shows that MPD-AGL does not introduce excessive extra overhead. As the inference process does not need gradient estimation, MPD-AGL mainly performs the adaptive SG width adjustment based on the MPD of different timesteps during the training process. In one iteration, the SG width adjustment consists of only $T$ sum-average operations ($\bar{\gamma}$) and $T$ multiplication operations (Eq. 7). For training time, MPD-AGL takes 3s more than STBP-tdBN, and this time overhead is mainly consumed in computing the affine transform parameters of normalization layers and the adaptive update of SG width. MPD-AGL takes 1s more than LSG, since LSG uses the same SG width for all timesteps, whereas our method needs to calculate and update the SG widths for different timesteps. As for inference time, MPD-AGL does not increase the time overhead.

