\begin{algorithm}[H]
\caption{Constant Factor Approximation for $\OPT$.\\
\textbf{Input:} Set of agents $N$, project success functions $f_1, \dots, f_m$, and agent costs $c_{ij}$ for every $i \in N,j \in M$\\
\textbf{Output:} Allocation $S^-$ that approximates $\OPT$
}\label{alg:appx-opt}
\begin{algorithmic}[1]
\State Run \cref{alg:appx-opt-minus} to compute an allocation $S^-$ that approximates $\OPT^-$ by a constant factor\label{state:apply-appx-opt-minus}
\State Formulate the linear program~\eqref{lp:lp1}
\State Run \cref{alg:solve-lp1} with $\epsilon<\delta \min_{j,i}f_j(\{i\})$ to compute an approximately optimal fractional solution $y$ to \eqref{lp:lp1}\label{state:apply-solve-lp1}
\State Construct distributions $\{F_j\}_{j\in M}$ over subsets of $N$ from $y$ as described in \cref{obs:frac-to-dist} \label{state:dist}
\State Run \cref{alg:rounding} to convert the random allocation defined by $\{F_j\}_{j\in M}$ into a deterministic allocation $T$ \label{state:derandomize}
\State Apply \cref{claim:apply-scaling} to $T$ to obtain an allocation $S^+$ that approximates $\OPT^+$ by a constant factor \label{state:do-scaling}
\State \Return $\arg\max_{S\in \{S^-,S^+\}}\rev(S)$ \label{state:return-best}
\end{algorithmic}
\end{algorithm}
%We are now ready to prove \cref{thm:const-diff-projects}.

\begin{proof}[Proof of Theorem~\ref{thm:const-diff-projects}]
By \cref{lem:opt-minus}, running Alg.~\ref{alg:appx-opt-minus} in line~\ref{state:apply-appx-opt-minus} computes an allocation $S^-$ s.t. $$\rev(S^-)\geq \delta \cdot \OPT^-$$
As established in \cref{claim:solve-lp1} and \cref{claim:opt-sol-to-opt}, running \cref{alg:solve-lp1} in line~\ref{state:apply-solve-lp1} with $\epsilon<\delta \min_{j,i}f_j(\{i\})$ computes in polynomial time a solution $y$ to \eqref{lp:lp1} with the following properties.
\begin{enumerate}
    \item[(1.1)] The number of positive variables $y_{j,x,S}$ is polynomially bounded. 
    \item[(1.2)] For every $y_{j,x,S}>0$, $f_j(S)\leq (1+\delta) x$, $f_j(\{i\})\leq \delta x$ and $f_j(i\mid S_j\setminus \{i\})\geq \frac{\sqrt{xc_{ij}}}{2\sqrt{2}}$ $\forall i\in S.$
    \item[(1.3)] The weighted reward according to $y$ is at least a constant fraction of the reward of $S^{\star \star}$. I.e., 
    \begin{eqnarray}
    \frac{1}{5}\sum_{j \in M}f_j(S^{\star \star}_j)\leq \sum_{j \in M} \sum_{x \in D_j} \sum_{S \subseteq A_{j,x}}y_{j,x,S}  {f_j(S)}. \label{eq:final-lp-sol}    
    \end{eqnarray}
\end{enumerate}
Since the number of positive variables $y_{j,x,S}$ is polynomially bounded, we can construct in polynomial time, in line~\ref{state:dist}, the distributions $\{F_j\}_{j\in M}$ as described in \cref{obs:frac-to-dist}. These distributions satisfy the following properties.
\begin{enumerate}
\item[(2.1)] For every agent $i \in N$,  the total probability of being selected across all projects is bounded by $1$, i.e., $\sum_{j\in [m]} \Pr_{\tilde{S}_j \sim F_j}[i \in \tilde{S}_j] \leq 1.$
\item[(2.2)] For every project $j \in M$, the expected function value under $F_j$ is equal to the weighted sum over the fractional solution 
\begin{eqnarray}\label{eq:final-dist}
\sum_{x\in D_j}\sum_{S\subseteq A_{j,x}} y_{j,x,S} f_j(S) = \mathbb{E}_{\tilde{S} \sim F_j}[f_j(\tilde{S})].
\end{eqnarray} 
\item[(2.3)] Every set $S\neq \emptyset$ in the support of $F_j$ corresponds to some $x \in D_j$ with $y_{j,x,S} > 0$.
\label{item:every-set}
\end{enumerate}
Next, in line~\ref{state:derandomize}, we apply \cref{alg:rounding} on $\{F_j\}_{j\in M}$, by \cref{lemma:rounding}, it runs in polynomial time in $M,N$ and the size of the (polynomial) support. Since the distributions satisfy the conditions of \cref{lemma:rounding}, we obtain an allocation $T=(T_1,\ldots,T_m)$ such that for all $j \in M$, there exists $S_j$ in the support of $F_j$ such that $T_j \subseteq S_j$. This implies, by properties (2.3) and (1.2), that for every project $j\in M$, there exists $x_j$ such that $f_j(S)\leq (1+\delta) x_j$, $f_j(\{i\})\leq \delta x_j$ and $f_j(i\mid S_j\setminus \{i\})\geq \frac{\sqrt{x_jc_{ij}}}{2\sqrt{2}}$ $\forall i\in S$. Furthermore, we have $\sum_{j\in M} f_j(T_j) 
\geq \frac{1}{2}\sum_{j\in M}\E_{S_j \sim F_j}[f_j(S_j)].$   
Combining this with Inequality~\eqref{eq:final-lp-sol} and Equality~\eqref{eq:final-dist}, we have an allocation $T$ that satisfy
\begin{eqnarray}
\sum_{j\in M} f_j(T_j) 
\geq \frac{1}{10}f_j(S^{\star \star}_j).    
\end{eqnarray} 
Let $\kappa=\frac{1}{10}$. We can apply \cref{claim:apply-scaling} in line~\ref{state:do-scaling} since all the conditions of the claim are satisfied. As a result, we obtain an allocation $S^+$ such that $\rev(S^+)\geq \frac{1}{512}\frac{1}{10}\rev(S^{\star \star})=OPT^+.$
By picking the best of these two solutions in line~\ref{state:return-best}, the expected revenue of the returned allocation satisfies
$$
\max_{S\in \{S^+,S^-\}}\rev(S) \geq \frac{\rev(S^+)+\rev(S^-)}{2}=\Theta(1) \cdot (\OPT^+ +\OPT^-)=\Theta(1) \cdot \OPT.
$$
This completes the proof.
