\smallskip
\noindent
\textbf{Disk hulls for a point set w.r.t.\ disks and its properties.} 
The unit disk hull of a point set was introduced by Dumitrescu et al.~\cite{DumitrescuGT22} as an analogue of the convex hull. Recall that the convex hull $\conv(P)$ of a point set $P\subset\mathbb{R}^2$ is the smallest convex set in the plane that contains $P$. Equivalently, it is the intersection of all closed half-planes that contain $P$; it can be computed by the classical ``rotating calipers'' algorithm, where we continuously rotate a line $\ell$ around $P$ while $P$ remains in one closed half-plane bounded by $\ell$. Intuitively, we obtain the unit disk hull of $P$ by rolling a unit disk, with center on or below the $x$-axis, around $P$. We generalize this notion to disks of any fixed radius $t>0$.

\begin{figure}[htbp]
 \centering
 \includegraphics[width=.95\textwidth]{hull1.pdf}
 \caption{A point set $P$ (red) and region $\hull_3(P)$ (pink). The boundary $\partial \hull_3(P)$ is composed of horizontal lines and circular arcs.}
    \label{fig:hull1}
\end{figure}

\begin{definition}
Let $P \subset \RR^2$ be a finite set of points above the $x$-axis and let $t>0$. Let $\mathcal{D}_t$ be the set of all disks of radius $t$ with centers on or below the $x$-axis. 
Let $M_t(P)$ be the union of all disks $D \in \mathcal{D}_t$ such that $P \cap \mathrm{int}(D) = \emptyset$. Now, we define the \emph{$t$-hull} of $P$ as $\hull_t(P) = \RR^2 \setminus \mathrm{int}(M_t(P))$. The boundary of $\hull_t(P)$ is denoted by $\partial \hull_t(P)$; for an illustration see \Cref{fig:hull1}. 
\end{definition}

% \todoin{SS: Define what is $x$-monotone.}

Dumitrescu et al.~\cite[Lemma~4]{DumitrescuGT22} proved that $\partial \hull_t(P)$ is $x$-monotone\footnote{A curve in the plane is $x$-monotone if every vertical line intersects it at most once.} for any $t>0$, and established other properties, which were used by Conroy and T\'oth~\cite{ConroyT23}, as well.

\begin{lemma}[Dumitrescu et al.~\cite{DumitrescuGT22}]%[\blue{Dumitrescu, Ghosh and T\'oth}~\cite{DumitrescuGT22}]
\label{lem:hull}
For a finite set $P \subset \RR^2$ above the $x$-axis and $t>0$, the following holds:
\begin{enumerate}\itemsep0pt
\item $\partial \hull_t(P)$ lies above the $x$-axis;
\item every vertical line intersects $\partial \hull_t(P)$ in one
  point, thus $\partial \hull_t(P)$ is an $x$-monotone curve;
\item for every disk $D\in \mathcal{D}_t$, the intersection $D\cap (\partial \hull_t(P))$ is connected (possibly empty);
\item for every disk $D\in \mathcal{D}_t$, if $P\cap D\neq \emptyset$,
  then $P\cap D$ contains a point in $\partial \hull_t(P)$.
\end{enumerate}
\end{lemma}

\begin{figure}[htbp]
 \centering
 \includegraphics[width=.95\textwidth]{hull2.pdf}
 \caption{A point set $P$ (red), $\hull_3(P)$ (pink), and $\hull_1(P)$ (light blue or pink).
 A disk $D\in \mathcal{D}_3$ of radius 3 (dotted blue), where the intersection $D\cap (\partial \hull_1(P))$ has two components.}
    \label{fig:hull2}
\end{figure}

Since we consider the case of disks with bounded radii, for our purposes, we need to compare two disk hulls for the same point set $P$ w.r.t.\ different radii; see \Cref{fig:hull2}. We start with an easy observation. 

\begin{lemma}\label{lem:circles}
%\red{Suppose that points $p_1,p_2\in \mathbb{R}^2$ are connected by two Jordan arcs,  $\gamma_1$ and $\gamma_2$, such that both arcs lie entirely above the $x$-axis. Furthermore $\gamma_1$ and $\gamma_2$ are arcs of circles $C_1$ and $C_2$, resp., of radii $r_1$ and $r_2$, with centers on or below the $x$-axis.}
Let $\gamma_1$ and $\gamma_2$ be Jordan arcs lying entirely above the $x$-axis,
such that $\gamma_1$ and $\gamma_2$ are arcs of circles $C_1$ and $C_2$, resp.,
of radii $r_1$ and $r_2$, with centers on or below the $x$-axis.
\begin{enumerate}
    \item Then both $\gamma_1$ and $\gamma_2$ are $x$-monotone and concave curves.
    \item Furthermore, if points $p_1,p_2\in \mathbb{R}^2$ are contained in both $\gamma_1$ and $\gamma_2$, and $r_1<r_2$, then $\gamma_1$ lies above $\gamma_2$ (i.e., for every vertical line $L$ that separates $p_1$ and $p_2$, point $\gamma_1\cap L$ lies above point $\gamma_2\cap L$).
\end{enumerate}
\end{lemma}
\begin{proof}
\noindent\textbf{(1)} For every $i\in \{1,2\}$, the center of $C_i$ is below the $x$-axis, and so the leftmost and rightmost points of $C_1$ are also below the $x$-axis. The leftmost and rightmost points partition $C_i$ into two halfcircles, one above the center and one below the center. Both halfcircles are $x$-monotone: The lower halfcircle is convex curve and the upper halfcircle is concave. Since $\gamma_i$ lies entirely above the $x$-axis, it is contained in the upper halfcirlce, which is $x$-monotone and concave. 

\noindent\textbf{(2)} The locus of centers of circles that contain both $p_1$ and $p_2$ is the orthogonal bisector of the line segment $p_1p_2$, that we denote by $(p_1p_2)^\perp$.  
Note that $p_1p_2$ is not vertical (or else $(p_1p_2)^\perp$ would be a horizontal line above the $x$-axis, and the centers of $C_1$ and $C_2$ would also be above the $x$-axis). As the center a circle containing $p_1$ and $p_2$ continuously moves from the center of $C_1$ down to $y=-\infty$, the circular arc between $p_1$ and $p_2$ deforms continuously from $\gamma_1$ to the line segment $p_1p_2$. 
Since $\gamma_1$ concave, it lies above the segment $p_1p_2$. Since $r_1<r_2$, the arc $\gamma_2$ lies between the arc $\gamma_1$ and the segment $p_1$ and $p_2$. Consequently, 
then $\gamma_2$ lies below $\gamma_1$, as claimed.
\end{proof}


\begin{lemma}\label{lem:hulls}
    For every finite set $P \subset \RR^2$ above the $x$-axis, the following holds:
\begin{enumerate}\itemsep0pt
\item If $0<s<t$, then for every disk $D\in \mathcal{D}_s$ of radius $s$, the intersection $D\cap (\partial \hull_t(P))$ is connected (possibly empty).
\item Suppose that $p\in P$ lies on the curve $\partial \hull_t(P)$ for some $t>0$. Then  there is a radius $r_p\in (0,t)$ such that $p$ is also on $\partial \hull_s(P)$ for all $s\in [r_p,t]$, but $p$ is below $\partial \hull_s(P)$ for all $s\in [0,r_p)$.
\end{enumerate}
\end{lemma}
\begin{proof}
\noindent\textbf{(1)} Let $D\in \mathcal{D}_s$. Suppose, to the contrary, that the
intersection $D\cap (\partial \hull_t(P))$ has two or more components. 
By \Cref{lem:hull}(2), the $x$-coordinates of the components form
disjoint intervals, and the components have a natural left-to-right ordering.
Let $q_1$ be the rightmost point in the first component, and
let $q_2$ be the leftmost point in the second component. Clearly
$q_1,q_2\in \partial D$. Let $q'$ be an arbitrary point in $\partial
\text{hull}(A)$ between $q_1$ and $q_2$. Then $q'$ lies on the boundary
of some disk $D'$ of radius $t$ whose center is below the $x$-axis,
and whose interior is disjoint from $P$. In particular, neither $q_1$
nor $q_2$ is in the interior of $D'$. Since the center of $D'$ is
below the $x$-axis, $\partial D'$ contains two interior-disjoint
circular arcs between $q$ and the $x$-axis; and both arcs must cross
$\partial D$. We have found two intersection points $p_1,p_2\in \partial D\cap
\partial D'$ above the $x$-axis. Furthermore, between $p_1$ and $p_2$, 
the circular arc $\partial D$ lies above the circular arc $\partial D'$, contradicting
\Cref{lem:circles}(2). This completes the proof of Property~1.

\noindent\textbf{(2)} Consider a point $p\in P$ that lies on the curve $\partial \hull_t(P)$ for some $t>0$. Then there exists a disk $D\in\mathcal{D}_t$ of radius $t$ centered at some point $c$ below the $x$-axis such that $p\in \partial D$. 
Let $c_1$ be the intersection point of the $x$-axis the line $cp$, and $c_2$ the orthogonal projection of $p$ to the $x$-axis. We describe two continuous motions, where the disk $D$ continuously changes while $p$ is in the circle $\partial D$ and there is no point in $P$ in the interior of $D$: First, a central dilation from center $p$ continuously moves $D$ to a disk $D_1$ centered at $c_1$. Second, the center of $D$ moves from $c_1$ towards $c_2$ continuously until its center reaches $c_2$ or a point $c_3$ where $\partial D$ contains both $p$ and another point $p'\in P$. Let $r_p$ be radius of $D$ at that time. 
The continuous motion shows that $p\in \partial \hull_s(P)$ for all $s\in [r_p,t]$, 
but it is not in $\partial \hull_s(P)$ for all $s<r_p$.
\end{proof}
Note that \Cref{lem:hulls}(1) is not symmetric for $s<t$: For a disk $D\in \mathcal{D}_t$ of radius $t$, the intersection $D\cap(\partial\hull_s(P))$ is not necessarily connected; see \Cref{fig:hull2} for an example.

\smallskip\noindent
\textbf{Reduction.}  
We can reduce the \textsl{Online Hitting Set} problem for a finite set $P\subset \mathbb{R}^2$ and disks of bounded radii in the separated setting, to the \textsl{Online Hitting Set} problem for a finite subset of integer points and objects with the lowest-point property. We achieve the reduction in two steps:

\noindent
(1) We choose a subset $Q\subseteq P$ of points that are relevant for a hitting set (\Cref{lem:reduction1}); and (2)  we map the points in $P$ into a set of integer points $P'\subset [0,n]^2\cap \mathbb{Z}^2$ (\Cref{lem:reduction2}).
% we transform $n$ points in $Q$ into a set of $n$ integer points $P'\subset [0,n]^2\cap \mathbb{Z}^2$


For a finite point set $P$ in the plane above the $x$-axis, let $Q=Q(P)$ be the set of points $p\in P$ such that $p\in \partial \hull_t(P)$ for some $t>0$.

\begin{lemma}\label{lem:reduction1}
For a finite point set $P$ in the plane above the $x$-axis, $Q=Q(P)$ has the following property: For every disk $D$ centered below the $x$-axis, if $D\cap P\neq \emptyset$, then $D\cap Q\neq \emptyset$.
\end{lemma}
\begin{proof}
Let $D$ be a disk of radius $t>0$ centered below the $x$-axis. By \Cref{lem:hull}(4), $D\cap P$ contains a point in $\partial\hull_t(P)$. By the definition of $Q$, this point is in $Q$.
\end{proof}

% By definition, the points in $Q$ have distinct $x$-coordinates. 
We may assume that the points in $P$ have distinct $x$-coordinates (if two or more points in $P$ have the same $x$-coordinate, w.l.o.g.\ a minimum hitting set would contain only the point with the smallest $y$-coordinate).
%Sort $Q$ by increasing $x$-coordinates such that $Q=\{q_0,\ldots , q_{|Q|-1}\}$. 
Sort $P$ by increasing $x$-coordinates such that $P=\{p_0,\ldots , p_{n-1}\}$. 
