\begin{lemma}\label{lem:reduction2}
For a set $P$ of $n$ points in the plane above the $x$-axis and for every disk $D$ centered below the $x$-axis, the set $\pi(D\cap P)$ has the lowest-point property.
\end{lemma}
\begin{proof}
Let $D$ be a disk centered below the $x$-axis. We rephrase the lowest-point property in terms of $D\cap P$. Recall that the points in $P$ are sorted by $x$-coordinates. 
Suppose that $s=(s_x,s_y)$ is in $D\cap P$ and $s_x\in I\subset \spn(D\cap P)$.  Consider the point sets $P(I):=\{p=(p_x,p_y) \in D\cap P: p_x\in I\}$. By \Cref{lem:reduction1}, we know that $D\cap Q\neq\ \emptyset$; let $t$ be the largest radius in $T$ such that $Q(I)\cap \partial \hull_t(P)\neq \emptyset$. We need to show that $D$ contains all points in $P(I)\cap \partial \hull_t(P)$. 

Let $q_{\rm left}$ and $q_{\rm right}\in P(I)$, resp., be the leftmost and rightmost points in $P(I)\cap Q$; and let $L_{\rm left}$ and $L_{\rm right}$ be the vertical lines through
$q_{\rm left}$ and $q_{\rm right}$. By the definition of $Q$, we have $q_{\rm left}\in \partial \hull_{t(q_{\rm left})}(P)$ and $q_{\rm right}\in \partial \hull_{t(q_{\rm right})}(P)$, and $t\geq \max\{t(q_{\rm left}),t(q_{\rm right})\}$ by the definition of $t$.
Consequently, the intersection point $\ell:=L_{\rm left}\cap \partial \hull_t(P)$ lies at or below $q_{\rm left}$, the intersection point $r:=L_{\rm right}\cap \partial \hull_t(P)$ lies at or below $q_{\rm right}$. Since $q_{\rm left},q_{\rm right}\in D$, then $D$ contains both $\ell$ and $r$. We know that $\partial\hull_t(P)$ is an $x$-monotone curve by \Cref{lem:hull}(2), and $D\cap \partial\hull_t(P)$ is connected by \Cref{lem:hulls}(2). Since $D$ contains both $\ell$ and $r$, then $D$ contains the sub-curve of $\partial \hull_t(P)$ between $r$ and $\ell$. Since all points in $P(I)$ are between the vertical lines $L_{\rm left}$ and $L_{\rm right}$, then $D$ contains all points in $P(I)\cap \partial \hull_t(P)$, as required. 
\end{proof}


\smallskip\noindent
\textbf{Online algorithm for disks in the separated setting.} We can now complete the reduction.
\begin{theorem}\label{thm:gbottomless}
For the \textsl{Online Hitting Set} problem for a set $P\subset \mathbb{R}^2$ of $n$ points above the $x$-axis and disks centered below the $x$-axis, there is an 
$O(\log n)$-competitive algorithm. 
%algorithm with competitive ratio $O(\log n)$.
\end{theorem}
\begin{proof}
We are given a set $P\subset \mathbb{R}^2$ of $n$ points above the $x$-axis, and we receive a sequence $\mathcal{C}=(D_1,\ldots, D_m)$ of disks centered on or below the $x$-axis in an online fashion. Let $\opt\subseteq P$ be a minimum hitting set for $\mathcal{C}$. 

Initially, we compute the set $P'\subset [0,n]^2\cap \mathbb{Z}^2$ as defined above  \Cref{lem:reduction2}.
When a disk $D_i$ arrives, we compute the set $S_i=\pi(D_i\cap P)$, which has the lowest-point property by \Cref{lem:reduction2}. The bijection $\pi$ maps $\opt$ to a set $\opt'=\pi(\opt)\subseteq P'$, where $|\opt|=|\opt'|$. Here, $\opt'$ is a hitting set for the sets $\mathcal{C}'=(S_1,\ldots , S_m)$. 

We run the online algorithm $\alg_0$ described in \Cref{ssec_lowestpoint} for the point set $P'$ and the sequence $\mathcal{C}'$ of sets.
By \Cref{thm:bottomless}, $\alg$ returns a hitting set $H'\subseteq P'$ of size $|\opt'|\cdot O(\log n)$.  By \Cref{lem:reduction1}, $H=\pi^{-1}(H')\subset P$ is a hitting set for $\mathcal{C}$, and its size is bounded by $|H|=|H'|\leq |\opt'|\cdot O(\log n)=|\opt|\cdot O(\log n)$, as required.
\end{proof}




\section{Disks of Bounded Radii: General Setting}
\label{sec:disks}

% \todoin{The blue things in this section are the suggested changes over the red things.}
In this section, we consider the \textsl{Online Hitting Set} problem, where $P$ is a finite set (given in advance) in the plane; and the objects are disks with radii in the interval $[1, M)$, where $M>1$ is a constant.

\smallskip\noindent
\textbf{Distinguishing layers of disks, according to their radii.}
We partition the disks of radii in the interval $[1,M)$ into $\lfloor \log M\rfloor+1$ layers as follows: for each $j\in\{0,1,\ldots ,\lfloor \log M\rfloor\}$, let \emph{layer} $L_j$ be the set of disks of radii in the interval $[2^j,2^{j+1})$.
The index of each layer $L_j$ is denoted by $j$.


\smallskip\noindent
\textbf{Tiling of the plane for each layer index $\mathbf{j}$.}
For every $j\in\{0,1,\ldots ,\lfloor \log M\rfloor\}$, let $\Lambda_j=\{\alpha_1 \mathbf{v}_1+\alpha_2 \mathbf{v}_2: (\alpha_1,\alpha_2)$ $\in \mathbb{Z}^2\}$ be a two-dimensional lattice spanned by vectors $\mathbf{v}_1=2^{j-1/2}\mathbf{e}_1$ and $\mathbf{v}_2=2^{j-1/2}\mathbf{e}_2$, where $\mathbf{e}_1=(1,0)$ and $\mathbf{e}_2=(0,1)$ are the standard basis vectors. 
Let $\tau_j=\left[0,2^{j-1/2}\right]^2$ be a square of side length $2^{j-1/2}$ with lower-left corner at the origin. Translates of $\tau_j$ (\emph{tiles}), with translation vectors in the lattice $\Lambda_j$, form the \emph{tiling} $\mathcal{T}_j$. Let $\mathcal{L}_j$ denote the set of axis-parallel lines spanned by the sides of the tiles in $\mathcal{T}_j$. 

\begin{figure}[htbp]
         \centering
    \includegraphics[width=75 mm]{tilingj.pdf}
   \caption{A section of the tiling $\mathcal{T}_j$, the tile $\tau_j$ of side length $2^{j-1/2}$, and a disk $D$ of radius $2^{j+2}$.}
    \label{fig:disk}
\end{figure}

We observe two key properties of the construction of layers and the tilings. 
\begin{observation}\label{obs_1}
    For every $j\in\{0,1,\ldots ,\lfloor \log M\rfloor\}$, if $\sigma\in L_j$ and the center of $\sigma$ is in a tile $\tau\in \mathcal{T}_j$, then $\tau\subset \sigma$; see \Cref{fig:disk}. 
\end{observation}
\begin{proof}
Since $\sigma \in L_j$, the radius of the disk $\sigma$ is in at least $2^j$.
The tile $\tau$ is a translate of $\tau_j=[0,2^{j-1/2}]^2$, and so its diameter is $\sqrt{2}\cdot 2^{j-1/2}=2^j$. If the center $c$ of $\sigma$ is in $S$, then every $p\in \tau$ is within distance $2^j$ from $c$, which implies that $\tau\subset \sigma$.
\end{proof}

\begin{observation}\label{obs_2}
    For every $j\in\{0,1,\ldots ,\lfloor \log M\rfloor\}$, every disk $D$ of radius at most $2^{j+2}$ intersects at most 24 lines in $\mathcal{L}_j$: at most 12 horizontal lines and at most 12 vertical lines. 
\end{observation}
\begin{proof}
Let $D$ be a disk of radius $2^{j+2}$; see \Cref{fig:disk}. The orthogonal projection of $D$ to the $x$-axis (resp., $y$-axis) is an interval of length at most $2^{j+3}$. Since the distance between any two consecutive vertical (resp., horizontal) lines in $\mathcal{L}_j$ is $2^{j-1/2}$, then 
$D$ intersects at most $\lceil 2^{j+3} / 2^{j-1/2}\rceil = \lceil 2^{7/2}\rceil = 12$ horizontal and at most 12 vertical lines in $\mathcal{L}_j$. 
%Assume w.l.o.g.\ that the center $c$ of $D$ lies in the square tile $\tau_j=\left[0,2^{j-1/2}\right]^2$; see \Cref{fig:disk}. Then $D$ is contained in the square $\left(-2^{j+1},2^{j+1}+2^{j-1/2}\right]^2$. This square intersects the lines spanned by the four sides of $\tau_j$, and $\lceil 2^{j+1}/(2^{j-1/2})\rceil = \lceil 2^{3/2}\rceil = 3$ additional lines spanned by the tiles on the left, right, above, and below $\tau_j$. This gives $2+6=8$ horizontal lines and $2+6=8$ vertical lines: Overall, 16 lines spanned by the sides of the tiles in $\mathcal{T}_j$. 
\end{proof}

\smallskip\noindent
\textbf{Subproblem for a directed line $\mathbf{L}$.} For a directed line $L$, we denote by $L^-$ and $L^+$ the closed half-plane on the left and right of $L$, respectively. Given a directed line $L$ and the input $(P,\mathcal{C}$) of the \textsl{Online Hitting Set} problem, where $P$ is a set of points, and $\mathcal{C}$ is a sequence of disks in the plane, we define a subproblem $(P_L,\mathcal{C}_L)$ as follows: 
Let $P_L=P\cap L^-$, and let $\mathcal{C}_L$ be the subsequence of disks $\sigma_i\in \mathcal{C}$ such that the center of $\sigma_i$ is in $L^+$ and $\sigma_i$ contains at least one point in $P_L$. Now for each subproblem $(P_L,\mathcal{C}_L)$, we can run the online algorithm $\alg_0$ described in \Cref{thm:gbottomless}, which was developed for the separated setting in \Cref{sec:separated}. 
Let $\alg_0(L)$ denote the online algorithm, where we run the online algorithm $\alg_0$ on the subproblem $(P_L,\mathcal{C}_L)$. 

\smallskip\noindent
\textbf{Online algorithm.} We can now present our online algorithm \alg.
% Let $\alg_0(L)$ be the online algorithm for disks in the separated settings (\Cref{sec:separated}). 
In the current algorithm, we use the online algorithm $\alg_0(L)$ as a subroutine. For each $j\in\mathbb{N}\cup\{0\}$, let layer $L_j$ be the set of disks of radii in the interval $[2^j,2^{j+1})$. 
The algorithm maintains a hitting set $H\subseteq P$ for the disks presented so far. Upon the arrival of a new disk $\sigma$ with radius $r$, if it is already hit by a point in $H$, then do nothing. Otherwise, proceed as follows.
\begin{itemize}
    \item First, find the layer $L_j$, where $j=\lfloor \log r\rfloor$, in which $\sigma$ belongs. %It is easy to observe that the layer can be determined in $O(1)$ time.
    \item Find the tile $\tau\in \mathcal{T}_j$ that contains the center of~$\sigma$. % (see \Cref{lemma_determine_cell}).
    \begin{itemize}
        \item If $P\cap \tau\neq \emptyset$, then choose an arbitrary point $p\in P\cap \tau$ and add it to $H$.
        % Here, by \textit{representative point} of $C$, we mean a point $p\in P\cap C$ such that $d(p,x)\leq d(p',x)$, where $p'\in P\cap C$ and $x$ is the center of $C$. In case of ties we choose 
        \item Otherwise, for every line $L\in \mathcal{L}_j$ that intersects $\sigma$, direct $L$ such that $L^+$ contains the center of $\sigma$, feed the disk $\sigma$ to the online algorithm $\alg_0(L)$, and add any new hitting point chosen by $\alg_0(L)$ to $H$.
    \end{itemize}
\end{itemize}

\smallskip\noindent
\textbf{Competitive analysis.} We now prove that $\alg$ is $O(\log M\log n)$-competitive.

\begin{theorem}\label{thm:disks}
    For the \textsl{Online Hitting Set} problem for a set $P$ of $n$ points in the plane and a sequence $\mathcal{C}=(\sigma_1,\ldots, \sigma_m)$ of disks of radii in the interval $[1, M]$, the online algorithm $\alg$ has competitive ratio $O(\log M\log n)$.
\end{theorem}
\begin{proof}
Let $\mathcal{C}$ be a sequence of disks.
For each $j\in\{0,1,\ldots,\lfloor \log M\rfloor\}$, let $\mathcal{C}^j$ be the collection of disks in $\mathcal{C}$ with radii in the interval $\left[2^j, 2^{j+1}\right)$. Let $H$ and $\opt$, resp., be the hitting set returned by the online algorithm $\alg$ and an (offline) minimum hitting set for $\mathcal{C}$. For every point $p\in \opt$, let $\mathcal{C}_p$ be the set of disks in $\mathcal{C}$ containing $p$. For each $j\in\{0,1,\ldots,\lfloor \log M\rfloor\}$, let $\mathcal{C}^j_p$ be the set of disks in $\mathcal{C}^j$ containing $p$, i.e., $\mathcal{C}^j_p=\mathcal{C}^j\cap \mathcal{C}_p$. 
Let $H^j_p\subseteq H$ be the set of points that $\alg$ adds to $H$ in response to hit objects in $\mathcal{C}^j_p$. It is enough to show that for every $j\in\{0,1,\ldots,\lfloor \log M\rfloor\}$ and $p\in \opt$, we have $|H^j_p|\leq O(\log n)$. 

Let $\tau$ be the tile in $\mathcal{T}_j$ that contains $p$, and let $\mathcal{C'}_p^j \subseteq \mathcal{C}^j_p$ be the subset of disks whose centers are located in $\tau$. To hit the first disk $\sigma\in \mathcal{C'}_p^j$, our algorithm adds a point from $P\cap \tau$ to $H$. By \Cref{obs_1}, any point in $P\cap \tau$ hits $\sigma$, as well as any subsequent disks in $\mathcal{C'}_p^j$. Our algorithm adds at most 1 point to $H$ to hit all the disks in $\mathcal{C'}_p^j$.

It remains to bound the number of points our algorithm adds for disks in $\mathcal{C}_p^j \setminus\mathcal{C'}_p^j$.
Notice that a disk $D_0$ centered at $p$ of radius $2^{j+1}$ contains all the centers of the disks in $\mathcal{C}_p^j \setminus\mathcal{C'}_p^j$. By the triangle inequality, a disk $D$ centered at $p$ of radius $2^{j+2}$ contains all disks in $\mathcal{C}_p^j \setminus\mathcal{C'}_p^j$.
For any disk $\sigma\in \mathcal{C}_p^j \setminus\mathcal{C'}_p^j$, our algorithm uses algorithm $\alg_0(L)$ for a line $L\in \mathcal{L}_j$, directed such that $L^+$ contains the center of $\sigma$. 
According to \Cref{obs_2}, the disk $D$ intersects at most 24 lines in $\mathcal{L}_j$. However, depending on the location of the center of $\sigma$,
each line may be used in either direction for $\alg_0(L)$.
As a result, for all disks in $\mathcal{C}_p^j \setminus\mathcal{C'}_p^j$, 
algorithm $\alg_0(L)$ is called with at most 48 directed lines $L$. 
% \begin{figure}[htbp]
%     \centering
%     \includegraphics[width=0.5\linewidth]{disk_cap_tiles.pdf}
%     \caption{Caption}
%     \label{fig_new}
% \end{figure}


For each directed line $L$, the online algorithm $\alg_0(L)$ maintains a hitting set $H(L)$ for the disks fed into this algorithm. For the point $p$, let $H_p^j(L)$ denote the set of points that algorithm $\alg_0(L)$ adds to $H(L)$ in response to a disk in $\mathcal{C}_p^j \setminus\mathcal{C'}_p^j$ that it receives as input. By \Cref{thm:gbottomless}, we have $|H_p^j(L)|\leq 
O(\log |\mathcal{C}_p^j \setminus\mathcal{C'}_p^j|)\leq O(\log n)$ for every directed line $L$. This yields 
$|H^j_p| \leq 1+ 48 \cdot O(\log n) =O(\log n)$, as required.

By construction, we have $H=\bigcup_{j=0}^{\lfloor\log M\rfloor}\bigcup_{p\in\opt}H^j_p$.
We have shown that $|H^j_p|  =O(\log n)$, for all $j\in\{0,1,\ldots,\lfloor \log M\rfloor\}$ and $p\in \opt$. Consequently, we obtain $|H|\leq \sum_{j=0}^{\lfloor\log M\rfloor}\sum_{p\in\opt} O(\log n) =(\lfloor\log M\rfloor+1)\cdot |\opt|\cdot O(\log n) =O(\log M\log n)|\opt|$, as claimed.
\end{proof}

Due to \Cref{thm:disks}, for disks of radii in the interval $[1, 1 + \eps]$, where $\eps>0$ is a constant, we have the following corollary.
\begin{corollary}\label{corollary:disk}
    For the \textsl{Online Hitting Set} problem for a set $P$ of $n$ points in the plane and a sequence $\mathcal{C}=(\sigma_1,\ldots, \sigma_m)$ of disks of radii in the interval $[1, 1+\eps]$, where $\eps>0$ is a constant, the online algorithm $\alg$ is $O(\log n)$-competitive.
\end{corollary}


\section{Generalization to Positive Homothets of a Convex Body}
\label{sec:homothet}

In this section, we generalize \Cref{thm:disks} for positive homothets of an arbitrary convex body $C$ in the plane. A set $C\subset \mathbb{R}^2$ is a \emph{convex body} if it is convex and has a nonempty interior; and it is \emph{centrally symmetric} (w.r.t.\ the origin) if $C=-C$, where $-C=\{-p: p\in C\}$.
% \blue{A convex body $C$ is said to be \emph{centrally symmetric} if there exists a point $c\in \IR^d$ (center of symmetry) such that for every point $x\in C$, the reflected point $x'=c-(x-c)=2c-x$ is also in $C$.}
% \todoin{I think in the previous definition, we need to say something about origin...}% is the reflection of $C$ in the origin.  

The key components of our $O(\log n)$-competitive algorithm for disks of comparable sizes were an $O(\log n)$-competitive online algorithm in the line-separated setting and a grid tiling that allowed a reduction to the line-separated setting. Specifically, \Cref{obs_1} and \Cref{obs_2} formulate the two essential properties of a tiling: If a center of disk $\sigma$ lies in a tile $\tau$, then $\tau\subset \sigma$ (\Cref{obs_1}); and every disk intersects $O(1)$ grid lines (\Cref{obs_2}). 

We discuss the requirements for generalizing the line-separated setting from disks to other convex bodies (\Cref{ssec_separated}). Then we show how to handle centrally symmetric convex bodies (\Cref{ssec_symmetry}). It is not difficult to generalize these properties from a disk to a centrally symmetric body $C$. However, a further generalization to an arbitrary convex body $C$ is more challenging and requires new geometric insights. For arbitrary convex bodies, we establish a new geometric structure property (\Cref{thm:body} in \Cref{ssec_key}). Finally, we use this key property to generalize our \textsl{Online Hitting Set} algorithm from disks to positive homothets of an arbitrary convex body (\Cref{thm:homothets} in \Cref{ssec_tiling}).


\subsection{Separated Setting for Convex Bodies}
\label{ssec_separated}

In \Cref{sec:separated}, we considered the \textsl{Online Hitting Set} problem with a point set $P$ above the $x$-axis, and disks with centers below the $x$-axis. We reduced this problem to the \textsl{Online Hitting Set} problem with integer points and objects with the lowest-point property, for which we gave an $O(\log n)$-competitive algorithm in \Cref{sec:bottomless}. The reduction readily generalizes (with the same proof) from disks to a broader family of objects. In this section, we formulate sufficient conditions for a generalization. 

When we replace disks with a convex body $C$, we use a \emph{reference point} $r(C)\in C$ instead of the center; and use an arbitrary line $L$ instead of the $x$-axis. Specifically, we work with the following setting: Let $C$ be a convex body in the plane with a reference point $r(C)\in C$, and let $L$ be a directed line. We consider the \textsl{Online Hitting Set} problem for a set $P$ of $n$ points on the left of $L$, and a sequence $\mathcal{C}$ of homothets $\sigma_i=a_iC+b_i$, $a_i\geq 1$, where the reference point $r(\sigma_i)=r(C)+b_i$ is on the right of $L$. 

An arc $\gamma:[0,1]\to \mathbb{R}^2$ is \emph{$L$-monotone} if every line perpendicular to $L$ intersects the arc in a connected set (i.e., the intersection is empty, a single point, or a vertical segment). In particular, an arc is $x$-monotone if it is $L$-monotone when the line $L$ is the $x$-axis.
The intersection of $C$ with the line $L'$ parallel to $L$ that contains the reference point $r(C)$ is a line segment that we denote by $pq$. Points $p$ and $q$ decompose the boundary $\partial C$ into two arcs: Let $\gamma_L^+(C)$ and $\gamma_L^-(C)$, resp., lying in the left and right half-plane bounded by $L'$. The machinery in \Cref{sec:separated} generalizes to this setting if $\gamma_L(C)$ is $L$-monotone. In this case, Conroy and T\'oth~\cite{ConroyT23} shows that the concept of $\hull_t(P)$ generalizes, and the boundary $\partial \hull_t(P)$ is $L$-monotone (cf.~\Cref{lem:hull}). It is easy to see that \Cref{lem:circles}--\Cref{lem:reduction2} also generalize with identical proofs. 

\begin{corollary}\label{cor:general}
    Let $C$ be a convex body with reference point $r(C)\in C$, and let $L$ be a directed line. If $\gamma_L^+(C)$ is $L$-monotone, then there is an $O(\log n)$-competitive algorithm for the \textsl{Online Hitting Set} problem for a set $P$ of $n$ points on the left of $L$, and a sequence $\mathcal{C}$ of positive homothets of $C$ with reference points on the right of $L$. 
\end{corollary}

Importantly, our online algorithm in Section~\ref{sec:disks} uses the line-separated setting for the same grid lines with \emph{both} directions. Therefore, we look for reference points $r(C)$ and lines $L$ such that \emph{both} $\gamma_L^+(C)$ and $\gamma_L^-(C)$ are $L$-monotone. 

\smallskip\noindent
\textbf{Choosing reference points.}
Given a convex body $V$ and a line $L$, it is not difficult to choose a reference point $r(C)\in C$
such that $\gamma_L^+(C)$ and $\gamma_L^-(C)$ are $L$-monotone. 

Let $p,q\in \partial C$ be points on two tangent lines of $C$ orthogonal to $L$, and let the reference point $r(C)$ be any point in the line segment $pq$; see \Cref{fig_pq_partition}. 

