% \begin{restatable}{theorem}{theorembody} ($\star$)
\begin{theorem}\label{thm:body}
    Let $C$ be a convex body in the plane such that its maximum-area inscribed triangle is an equilateral triangle $T_{\rm in}$, and the inscribed circle of $T_{\rm in}$ is a circle of unit radius. Then there exists a good pair of lines.
\end{theorem}
\begin{proof}
    For every $\varepsilon>0$, we can approximate $C$ with a strictly convex body $C_\varepsilon$ such that the Hausdorff distance between the bodies is bounded by $d_H(C,C_{\varepsilon})<\varepsilon$. For every $\eps=\frac{1}{n}$, $n\in \mathbb{N}$, there is a good pair $(L_{1,n}, L_{2,n})$. As $n$ tends to infinity, $C_{1/n}$ converges to $C$ (in Hausdorff metric). By compactness, the sequence $\{(L_{1,n}, L_{2,n})\}_{n\in \mathbb{N}}$ has a convergent subsequence; assume w.l.o.g.\ that it converges to the pair of lines $(L_1,L_2)$. Since $\angle(L_{1,n},L_{2,n})\geq \pi/15$ for all $n\in \mathbb{N}$, then $\angle (L_1,L_2)\geq \pi/15$; and since $B(L_{1,n}\cap L_{2,n},\frac{1}{50})\subset C_{1/n}$ for all 
    $n\in \mathbb{N}$, then  $B(L_1\cap L_2,\frac{1}{50})\subset C$. We conclude that $(L_1,L_2)$ is a good pair of lines for $C$, as required. 
\end{proof}
